		public void AddOption(EncodeOptions key, object value)
		{
			if (!EncodingOptions.ContainsKey(key))
			{
				EncodingOptions.Add(key, value);
			}
			else
			{
				EncodingOptions[key] = value;
			}
		}

		public void RemoveOption(EncodeOptions key)
		{
			if (!EncodingOptions.ContainsKey(key))
			{
				EncodingOptions.Remove(key);
			}
		}

		public void ClearAllOptions()
		{
			EncodingOptions.Clear();
		}

		public T Generate<T>(BarcodeFormat format, string content, Dictionary<EncodeOptions, object> encodingOptions, IOutputProvider<T> provider)
		{
			try
			{
				this.content = content;
				barcodeFormat = format;
				if (encodingOptions != null)
				{
					EncodingOptions = encodingOptions;
				}
				IEncoder encoder = new DefaultEncoder();
				DateTime now = DateTime.Now;
				if (string.IsNullOrEmpty(content))
				{
					throw new Exception("Input data not allowed to be blank.");
				}
				if (EncodedBarcodeFormat == BarcodeFormat.Unknown)
				{
					throw new Exception("Barcode type is not specified.");
				}
				encodedValue = string.Empty;
				countryAssigningManufacturerCode = "N/A";
				switch (barcodeFormat)
				{
				case BarcodeFormat.QRCode:
					encoder = new QRCodeEncoder();
					break;
				case BarcodeFormat.PDF417:
					encoder = new Pdf417Encoder();
					break;
				case BarcodeFormat.DataMatrix:
					encoder = new DataMatrixNewEncoder();
					break;
				case BarcodeFormat.EAN8:
					encoder = new EAN8Encoder();
					break;
				case BarcodeFormat.Codabar:
					encoder = new CodaBarEncoder();
					break;
				case BarcodeFormat.Code39Extended:
					encoder = new Code39Encoder();
					break;
				case BarcodeFormat.Code39:
				case BarcodeFormat.LOGMARS:
					encoder = new Code39Encoder();
					break;
				case BarcodeFormat.EAN13:
				case BarcodeFormat.UCC13:
					encoder = new EAN13Encoder();
					break;
				case BarcodeFormat.UPCA:
				case BarcodeFormat.UCC12:
					encoder = new UPCAEncoder();
					break;
				case BarcodeFormat.ITF14:
					encoder = new ITFEncoder();
					break;
				case BarcodeFormat.Code128:
					encoder = new Code128Encoder();
					break;
				case BarcodeFormat.Code128A:
					encoder = new Code128Encoder();
					break;
				case BarcodeFormat.Code128B:
					encoder = new Code128Encoder();
					break;
				case BarcodeFormat.Code128C:
					encoder = new Code128Encoder();
					break;
				case BarcodeFormat.Aztec:
					encoder = new AztecEncoder();
					break;
				default:
					throw new Exception("Unsupported encoding type specified.");
				}
				Dictionary<EncodeOptions, object> dictionary = new Dictionary<EncodeOptions, object>(EncodingOptions);
				if (!dictionary.ContainsKey(EncodeOptions.CharacterSet) && !string.IsNullOrEmpty(CharacterSet))
				{
					dictionary.Add(EncodeOptions.CharacterSet, CharacterSet);
				}
				if (!dictionary.ContainsKey(EncodeOptions.Margin) && Margin >= 0)
				{
					dictionary.Add(EncodeOptions.Margin, Margin);
				}
				if (barcodeFormat == BarcodeFormat.QRCode)
				{
					if (!dictionary.ContainsKey(EncodeOptions.ErrorCorrection))
					{
						dictionary.Add(EncodeOptions.ErrorCorrection, ErrorCorrectionLevel);
					}
					BitMatrix = encoder.Encode(this.content, barcodeFormat, Width, Height, dictionary);
				}
				else if (barcodeFormat == BarcodeFormat.DataMatrix)
				{
					BitMatrix = encoder.Encode(this.content, barcodeFormat, Width, Height, dictionary);
				}
				else if (barcodeFormat == BarcodeFormat.PDF417)
				{
					if (!dictionary.ContainsKey(EncodeOptions.Pdf417Compaction))
					{
						dictionary.Add(EncodeOptions.Pdf417Compaction, Pdf417Compaction);
					}
					BitMatrix = encoder.Encode(this.content, barcodeFormat, Width, Height, dictionary);
				}
				else if (barcodeFormat == BarcodeFormat.Aztec)
				{
					BitMatrix = encoder.Encode(this.content, barcodeFormat, Width, Height, dictionary);
				}
				else
				{
					BitMatrix = encoder.Encode(this.content, barcodeFormat, Width, Height, dictionary);
				}
				encodedValue = BitMatrix.ToString();
				encodingTime = (DateTime.Now - now).TotalMilliseconds;
				return provider.Generate(BitMatrix, barcodeFormat, content, EncodingOptions);
			}
			finally
			{
				this.content = string.Empty;
				ClearAllOptions();
			}
		}

		public T Generate<T>(BarcodeFormat format, string content, IOutputProvider<T> provider)
		{
			return Generate(format, content, null, provider);
		}

		public Image Encode(BarcodeFormat format, string content)
		{
			this.content = content;
			return Encode(format);
		}

		public Image Encode(BarcodeFormat format, string content, Dictionary<EncodeOptions, object> encodingOptions)
		{
			try
			{
				this.content = content;
				if (encodingOptions != null)
				{
					EncodingOptions = encodingOptions;
				}
				return Encode(format);
			}
			finally
			{
				this.content = string.Empty;
				ClearAllOptions();
			}
		}

		internal Image Encode(BarcodeFormat barcodeFormat)
		{
			this.barcodeFormat = barcodeFormat;
			return Encode();
		}

		internal Image Encode()
		{
			//IL_075c: Unknown result type (might be due to invalid IL or missing references)
			//IL_04a6: Unknown result type (might be due to invalid IL or missing references)
			//IL_04ad: Expected O, but got Unknown
			iOneDEncoder = new Blank();
			iOneDEncoder.Errors.Clear();
			iQRCodeEncoder = new DefaultEncoder();
			iDataMatrixEncoder = new DefaultEncoder();
			iAztecEncoder = new DefaultEncoder();
			DateTime now = DateTime.Now;
			if (string.IsNullOrEmpty(content))
			{
				throw new Exception("Input data not allowed to be blank.");
			}
			if (EncodedBarcodeFormat == BarcodeFormat.Unknown)
			{
				throw new Exception("Symbology type not allowed to be unspecified.");
			}
			encodedValue = string.Empty;
			countryAssigningManufacturerCode = "N/A";
			switch (barcodeFormat)
			{
			case BarcodeFormat.QRCode:
				iQRCodeEncoder = new QRCodeEncoder();
				break;
			case BarcodeFormat.PDF417:
				iPdf417Encoder = new Pdf417Encoder();
				break;
			case BarcodeFormat.Aztec:
				iAztecEncoder = new AztecEncoder();
				break;
			case BarcodeFormat.DataMatrix:
				iDataMatrixEncoder = new DataMatrixEncoder();
				break;
			case BarcodeFormat.Code11:
			case BarcodeFormat.USD8:
				iOneDEncoder = new Code11(content);
				break;
			case BarcodeFormat.EAN8:
				iOneDEncoder = new EAN8(content);
				break;
			case BarcodeFormat.PostNet:
				iOneDEncoder = new Postnet(content);
				break;
			case BarcodeFormat.Bookland:
			case BarcodeFormat.ISBN:
				iOneDEncoder = new ISBN(content);
				break;
			case BarcodeFormat.JAN13:
				iOneDEncoder = new JAN13(content);
				break;
			case BarcodeFormat.UPCSupplemental2Digit:
				iOneDEncoder = new UPCSupplement2(content);
				break;
			case BarcodeFormat.Codabar:
				iOneDEncoder = new Codabar(content);
				break;
			case BarcodeFormat.Code39Extended:
				iOneDEncoder = new Code39(content, AllowExtended: true);
				break;
			case BarcodeFormat.Code39:
			case BarcodeFormat.LOGMARS:
				iOneDEncoder = new Code39(content);
				break;
			case BarcodeFormat.Interleaved2of5:
				iOneDEncoder = new Interleaved2of5(content);
				break;
			case BarcodeFormat.Standard2of5:
			case BarcodeFormat.Industrial2of5:
				iOneDEncoder = new Standard2of5(content);
				break;
			case BarcodeFormat.EAN13:
			case BarcodeFormat.UCC13:
				iOneDEncoder = new EAN13(content);
				break;
			case BarcodeFormat.UPCA:
			case BarcodeFormat.UCC12:
				iOneDEncoder = new UPCA(content);
				break;
			case BarcodeFormat.MSIMod10:
			case BarcodeFormat.MSI2Mod10:
			case BarcodeFormat.MSIMod11:
			case BarcodeFormat.MSIMod11Mod10:
			case BarcodeFormat.ModifiedPlessey:
				iOneDEncoder = new MSI(content, barcodeFormat);
				break;
			case BarcodeFormat.UPCSupplemental5Digit:
				iOneDEncoder = new UPCSupplement5(content);
				break;
			case BarcodeFormat.UPCE:
				iOneDEncoder = new UPCE(content);
				break;
			case BarcodeFormat.ITF14:
				iOneDEncoder = new ITF14(content);
				break;
			case BarcodeFormat.Code93:
				iOneDEncoder = new Code93(content);
				break;
			case BarcodeFormat.Telepen:
				iOneDEncoder = new Telepen(content);
				break;
			case BarcodeFormat.FIM:
				iOneDEncoder = new FIM(content);
				break;
			case BarcodeFormat.Code128:
				iOneDEncoder = new Code128(content);
				break;
			case BarcodeFormat.Code128A:
				iOneDEncoder = new Code128(content, Code128.Types.A);
				break;
			case BarcodeFormat.Code128B:
				iOneDEncoder = new Code128(content, Code128.Types.B);
				break;
			case BarcodeFormat.Code128C:
				iOneDEncoder = new Code128(content, Code128.Types.C);
				break;
			default:
				throw new Exception("Unsupported encoding type specified.");
			}
			Dictionary<EncodeOptions, object> dictionary = new Dictionary<EncodeOptions, object>(EncodingOptions);
			if (!dictionary.ContainsKey(EncodeOptions.CharacterSet) && !string.IsNullOrEmpty(CharacterSet))
			{
				dictionary.Add(EncodeOptions.CharacterSet, CharacterSet);
			}
			if (!dictionary.ContainsKey(EncodeOptions.Margin) && Margin >= 0)
			{
				dictionary.Add(EncodeOptions.Margin, Margin);
			}
			if ((object)iOneDEncoder.GetType() != typeof(Blank))
			{
				encodedValue = iOneDEncoder.EncodedValue;
				content = iOneDEncoder.RawData;
				encodedImage = (Image)(object)GenerateImage();
			}
			else if ((object)iQRCodeEncoder.GetType() != typeof(DefaultEncoder))
			{
				if (!dictionary.ContainsKey(EncodeOptions.ErrorCorrection))
				{
					dictionary.Add(EncodeOptions.ErrorCorrection, ErrorCorrectionLevel);
				}
				BitMatrix = iQRCodeEncoder.Encode(content, barcodeFormat, Width, Height, dictionary);
				encodedImage = MatrixToImageHelper.ToBitmap(BitMatrix, ForeColor, BackColor);
				object encodeOptionType = BarcodeHelper.GetEncodeOptionType(dictionary, EncodeOptions.QRCodeLogo);
				if (encodeOptionType != null)
				{
					try
					{
						Image val = (Image)encodeOptionType;
						int x = encodedImage.Width / 2 - val.Width / 2;
						int y = encodedImage.Height / 2 - val.Height / 2;
						Graphics.FromImage(encodedImage).DrawImage(val, new Point(x, y));
					}
					catch (Exception)
					{
					}
				}
				encodedValue = BitMatrix.ToString();
			}
			else if ((object)iDataMatrixEncoder.GetType() != typeof(DefaultEncoder))
			{
				if ((object)iDataMatrixEncoder.GetType() == typeof(DataMatrixEncoder))
				{
					DataMatrixEncoder dataMatrixEncoder = iDataMatrixEncoder as DataMatrixEncoder;
					DataMatrixImageEncoderOptions dataMatrixImageEncoderOptions = new DataMatrixImageEncoderOptions();
					dataMatrixImageEncoderOptions.BackColor = BackColor;
					dataMatrixImageEncoderOptions.ForeColor = ForeColor;
					dataMatrixImageEncoderOptions.MarginSize = MarginSize;
					dataMatrixImageEncoderOptions.ModuleSize = ModuleSize;
					dataMatrixImageEncoderOptions.Scheme = DataMatrixScheme;
					dataMatrixImageEncoderOptions.SizeIdx = DataMatrixSymbolSize;
					if (!string.IsNullOrEmpty(CharacterSet))
					{
						dataMatrixImageEncoderOptions.CharacterSet = CharacterSet;
					}
					encodedImage = (Image)(object)dataMatrixEncoder.EncodeImage(content, dataMatrixImageEncoderOptions);
				}
				else
				{
					DataMatrixNewEncoder dataMatrixNewEncoder = iDataMatrixEncoder as DataMatrixNewEncoder;
					BitMatrix = dataMatrixNewEncoder.Encode(content, barcodeFormat, Width, Height, dictionary);
					encodedImage = MatrixToImageHelper.ToBitmap(BitMatrix, ForeColor, BackColor);
					encodedValue = BitMatrix.ToString();
				}
			}
			else if ((object)iAztecEncoder.GetType() != typeof(DefaultEncoder))
			{
				AztecEncoder aztecEncoder = iAztecEncoder as AztecEncoder;
				BitMatrix = aztecEncoder.Encode(content, barcodeFormat, Width, Height, dictionary);
				encodedImage = MatrixToImageHelper.ToBitmap(BitMatrix, ForeColor, BackColor);
				encodedValue = BitMatrix.ToString();
			}
			else if ((object)iPdf417Encoder.GetType() != typeof(DefaultEncoder))
			{
				Pdf417Encoder pdf417Encoder = iPdf417Encoder as Pdf417Encoder;
				if (!dictionary.ContainsKey(EncodeOptions.Pdf417Compaction))
				{
					dictionary.Add(EncodeOptions.Pdf417Compaction, Pdf417Compaction);
