	public class QRCodeDecoder : IDecoder
	{
		private static readonly ResultPoint[] NO_POINTS = new ResultPoint[0];

		private readonly MessagingToolkit.Barcode.QRCode.Decoder.Decoder decoder;

		public QRCodeDecoder()
		{
			decoder = new MessagingToolkit.Barcode.QRCode.Decoder.Decoder();
		}

		protected internal MessagingToolkit.Barcode.QRCode.Decoder.Decoder GetDecoder()
		{
			return decoder;
		}

		public virtual Result Decode(BinaryBitmap image)
		{
			return Decode(image, null);
		}

		public virtual Result Decode(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions)
		{
			DecoderResult decoderResult;
			ResultPoint[] array;
			if (decodingOptions != null && decodingOptions.ContainsKey(DecodeOptions.PureBarcode))
			{
				BitMatrix bits = ExtractPureBits(image.BlackMatrix);
				decoderResult = decoder.Decode(bits, decodingOptions);
				array = NO_POINTS;
			}
			else
			{
				DetectorResult detectorResult = new MessagingToolkit.Barcode.QRCode.Detector.Detector(image.BlackMatrix).Detect(decodingOptions);
				decoderResult = decoder.Decode(detectorResult.Bits, decodingOptions);
				array = detectorResult.Points;
			}
			if (decoderResult.Other is QRCodeDecoderMetaData)
			{
				((QRCodeDecoderMetaData)decoderResult.Other).ApplyMirroredCorrection(array);
			}
			Result result = new Result(decoderResult.Text, decoderResult.RawBytes, array, BarcodeFormat.QRCode);
			IList<byte[]> byteSegments = decoderResult.ByteSegments;
			if (byteSegments != null)
			{
				result.PutMetadata(ResultMetadataType.ByteSegments, byteSegments);
			}
			string eCLevel = decoderResult.ECLevel;
			if (eCLevel != null)
			{
				result.PutMetadata(ResultMetadataType.ErrorCorrectionLevel, eCLevel);
			}
			return result;
		}

		public virtual void Reset()
		{
		}

		private static BitMatrix ExtractPureBits(BitMatrix image)
		{
			int[] topLeftOnBit = image.GetTopLeftOnBit();
			int[] bottomRightOnBit = image.GetBottomRightOnBit();
			if (topLeftOnBit == null || bottomRightOnBit == null)
			{
				throw NotFoundException.Instance;
			}
			float num = ModuleSize(topLeftOnBit, image);
			int num2 = topLeftOnBit[1];
			int num3 = bottomRightOnBit[1];
			int num4 = topLeftOnBit[0];
			int num5 = bottomRightOnBit[0];
			if (num4 >= num5 || num2 >= num3)
			{
				throw NotFoundException.Instance;
			}
			if (num3 - num2 != num5 - num4)
			{
				num5 = num4 + (num3 - num2);
			}
			int num6 = (int)Math.Round((float)(num5 - num4 + 1) / num);
			int num7 = (int)Math.Round((float)(num3 - num2 + 1) / num);
			if (num6 <= 0 || num7 <= 0)
			{
				throw NotFoundException.Instance;
			}
			if (num7 != num6)
			{
				throw NotFoundException.Instance;
			}
			int num8 = (int)(num / 2f);
			num2 += num8;
			num4 += num8;
			int num9 = num4 + (int)((float)(num6 - 1) * num) - (num5 - 1);
			if (num9 > 0)
			{
				if (num9 > num8)
				{
					throw NotFoundException.Instance;
				}
				num4 -= num9;
			}
			int num10 = num2 + (int)((float)(num7 - 1) * num) - (num3 - 1);
			if (num10 > 0)
			{
				if (num10 > num8)
				{
					throw NotFoundException.Instance;
				}
				num2 -= num10;
			}
			BitMatrix bitMatrix = new BitMatrix(num6, num7);
			for (int i = 0; i < num7; i++)
			{
				int y = num2 + (int)((float)i * num);
				for (int j = 0; j < num6; j++)
				{
					if (image.Get(num4 + (int)((float)j * num), y))
					{
						bitMatrix.Set(j, i);
					}
				}
			}
			return bitMatrix;
		}

		private static float ModuleSize(int[] leftTopBlack, BitMatrix image)
		{
			int height = image.GetHeight();
			int width = image.GetWidth();
			int num = leftTopBlack[0];
			int num2 = leftTopBlack[1];
			bool flag = true;
			int num3 = 0;
			while (num < width && num2 < height)
			{
				if (flag != image.Get(num, num2))
				{
					if (++num3 == 5)
					{
						break;
					}
					flag = !flag;
				}
				num++;
				num2++;
			}
			if (num == width || num2 == height)
			{
				throw NotFoundException.Instance;
			}
			return (float)(num - leftTopBlack[0]) / 7f;
		}
	}
	public sealed class QRCodeEncoder : IEncoder
	{
		private const int QUIET_ZONE_SIZE = 4;

		public BitMatrix Encode(string contents, BarcodeFormat format, int width, int height)
		{
			return Encode(contents, format, width, height, null);
		}

		public BitMatrix Encode(string contents, BarcodeFormat format, int width, int height, Dictionary<EncodeOptions, object> encodingOptions)
		{
			if (string.IsNullOrEmpty(contents))
			{
				throw new ArgumentException("Found empty contents");
			}
			if (format != BarcodeFormat.QRCode)
			{
				throw new ArgumentException("Can only Encode QR_CODE, but got " + format);
			}
			if (width < 0 || height < 0)
			{
				throw new ArgumentException("Requested dimensions are too small: " + width + "x" + height);
			}
			ErrorCorrectionLevel ecLevel = ErrorCorrectionLevel.L;
			int quietZone = 4;
			if (encodingOptions != null)
			{
				ErrorCorrectionLevel errorCorrectionLevel = (ErrorCorrectionLevel)BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.ErrorCorrection);
				if (errorCorrectionLevel != null)
				{
					ecLevel = errorCorrectionLevel;
				}
				object encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.Margin);
				if (encodeOptionType != null)
				{
					quietZone = Convert.ToInt32(encodeOptionType);
				}
			}
			return RenderResult(MessagingToolkit.Barcode.QRCode.Encoder.Encoder.Encode(contents, ecLevel, encodingOptions), width, height, quietZone);
		}

		private static BitMatrix RenderResult(MessagingToolkit.Barcode.QRCode.Encoder.QRCode code, int width, int height, int quietZone)
		{
			ByteMatrix matrix = code.Matrix;
			if (matrix == null)
			{
				throw new InvalidOperationException();
			}
			int width2 = matrix.Width;
			int height2 = matrix.Height;
			int num = width2 + (quietZone << 1);
			int num2 = height2 + (quietZone << 1);
			int num3 = Math.Max(width, num);
			int num4 = Math.Max(height, num2);
			int num5 = Math.Min(num3 / num, num4 / num2);
			int num6 = (num3 - width2 * num5) / 2;
			int num7 = (num4 - height2 * num5) / 2;
			BitMatrix bitMatrix = new BitMatrix(num3, num4);
			bitMatrix.LeftPadding = num6;
			bitMatrix.TopPadding = num7;
			bitMatrix.ActualHeight = num5 * height2;
			bitMatrix.ActualWidth = num5 * width2;
			int num8 = 0;
			int num9 = num7;
			while (num8 < height2)
			{
				int num10 = 0;
				int num11 = num6;
				while (num10 < width2)
				{
					if (matrix.Get(num10, num8) == 1)
					{
						bitMatrix.SetRegion(num11, num9, num5, num5);
					}
					num10++;
					num11 += num5;
				}
				num8++;
				num9 += num5;
			}
			return bitMatrix;
		}
	}
