		internal static void ClearMatrix(ByteMatrix matrix)
		{
			matrix.Clear(byte.MaxValue);
		}

		internal static void BuildMatrix(MessagingToolkit.Barcode.Common.BitArray dataBits, ErrorCorrectionLevel ecLevel, MessagingToolkit.Barcode.QRCode.Decoder.Version version, int maskPattern, ByteMatrix matrix)
		{
			ClearMatrix(matrix);
			EmbedBasicPatterns(version, matrix);
			EmbedTypeInfo(ecLevel, maskPattern, matrix);
			MaybeEmbedVersionInfo(version, matrix);
			EmbedDataBits(dataBits, maskPattern, matrix);
		}

		internal static void EmbedBasicPatterns(MessagingToolkit.Barcode.QRCode.Decoder.Version version, ByteMatrix matrix)
		{
			EmbedPositionDetectionPatternsAndSeparators(matrix);
			EmbedDarkDotAtLeftBottomCorner(matrix);
			MaybeEmbedPositionAdjustmentPatterns(version, matrix);
			EmbedTimingPatterns(matrix);
		}

		internal static void EmbedTypeInfo(ErrorCorrectionLevel ecLevel, int maskPattern, ByteMatrix matrix)
		{
			MessagingToolkit.Barcode.Common.BitArray bitArray = new MessagingToolkit.Barcode.Common.BitArray();
			MakeTypeInfoBits(ecLevel, maskPattern, bitArray);
			for (int i = 0; i < bitArray.Size; i++)
			{
				bool val = bitArray.Get(bitArray.Size - 1 - i);
				int x = TYPE_INFO_COORDINATES[i][0];
				int y = TYPE_INFO_COORDINATES[i][1];
				matrix.Set(x, y, val);
				if (i < 8)
				{
					int x2 = matrix.Width - i - 1;
					int y2 = 8;
					matrix.Set(x2, y2, val);
				}
				else
				{
					int x3 = 8;
					int y3 = matrix.Height - 7 + (i - 8);
					matrix.Set(x3, y3, val);
				}
			}
		}

		internal static void MaybeEmbedVersionInfo(MessagingToolkit.Barcode.QRCode.Decoder.Version version, ByteMatrix matrix)
		{
			if (version.VersionNumber < 7)
			{
				return;
			}
			MessagingToolkit.Barcode.Common.BitArray bitArray = new MessagingToolkit.Barcode.Common.BitArray();
			MakeVersionInfoBits(version, bitArray);
			int num = 17;
			for (int i = 0; i < 6; i++)
			{
				for (int j = 0; j < 3; j++)
				{
					bool val = bitArray.Get(num);
					num--;
					matrix.Set(i, matrix.Height - 11 + j, val);
					matrix.Set(matrix.Height - 11 + j, i, val);
				}
			}
		}

		internal static void EmbedDataBits(MessagingToolkit.Barcode.Common.BitArray dataBits, int maskPattern, ByteMatrix matrix)
		{
			int num = 0;
			int num2 = -1;
			int num3 = matrix.Width - 1;
			int i = matrix.Height - 1;
			while (num3 > 0)
			{
				if (num3 == 6)
				{
					num3--;
				}
				for (; i >= 0 && i < matrix.Height; i += num2)
				{
					for (int j = 0; j < 2; j++)
					{
						int x = num3 - j;
						if (IsEmpty(matrix.Get(x, i)))
						{
							bool flag;
							if (num < dataBits.Size)
							{
								flag = dataBits.Get(num);
								num++;
							}
							else
							{
								flag = false;
							}
							if (maskPattern != -1 && MaskUtil.GetDataMaskBit(maskPattern, x, i))
							{
								flag = !flag;
							}
							matrix.Set(x, i, flag);
						}
					}
				}
				num2 = -num2;
				i += num2;
				num3 -= 2;
			}
			if (num != dataBits.Size)
			{
				throw new BarcodeEncoderException("Not all bits consumed: " + num + "/" + dataBits.Size);
			}
		}

		internal static int FindMSBSet(int value)
		{
			int num = 0;
			while (value != 0)
			{
				value >>>= 1;
				num++;
			}
			return num;
		}

		internal static int CalculateBCHCode(int val, int poly)
		{
			int num = FindMSBSet(poly);
			val <<= num - 1;
			while (FindMSBSet(val) >= num)
			{
				val ^= poly << FindMSBSet(val) - num;
			}
			return val;
		}

		internal static void MakeTypeInfoBits(ErrorCorrectionLevel ecLevel, int maskPattern, MessagingToolkit.Barcode.Common.BitArray bits)
		{
			if (!QRCode.IsValidMaskPattern(maskPattern))
			{
				throw new BarcodeEncoderException("Invalid mask pattern");
			}
			int val = (ecLevel.Bits << 3) | maskPattern;
			bits.AppendBits(val, 5);
			int val2 = CalculateBCHCode(val, 1335);
			bits.AppendBits(val2, 10);
			MessagingToolkit.Barcode.Common.BitArray bitArray = new MessagingToolkit.Barcode.Common.BitArray();
			bitArray.AppendBits(21522, 15);
			bits.Xor(bitArray);
			if (bits.Size != 15)
			{
				throw new BarcodeEncoderException("should not happen but we got: " + bits.GetSize());
			}
		}

		internal static void MakeVersionInfoBits(MessagingToolkit.Barcode.QRCode.Decoder.Version version, MessagingToolkit.Barcode.Common.BitArray bits)
		{
			bits.AppendBits(version.VersionNumber, 6);
			int val = CalculateBCHCode(version.VersionNumber, 7973);
			bits.AppendBits(val, 12);
			if (bits.Size != 18)
			{
				throw new BarcodeEncoderException("should not happen but we got: " + bits.GetSize());
			}
		}

		private static bool IsEmpty(int value)
		{
			return value == 255;
		}

		private static void EmbedTimingPatterns(ByteMatrix matrix)
		{
			for (int i = 8; i < matrix.Width - 8; i++)
			{
				int val = (i + 1) % 2;
				if (IsEmpty(matrix.Get(i, 6)))
				{
					matrix.Set(i, 6, val);
				}
				if (IsEmpty(matrix.Get(6, i)))
				{
					matrix.Set(6, i, val);
				}
			}
		}

		private static void EmbedDarkDotAtLeftBottomCorner(ByteMatrix matrix)
		{
			if (matrix.Get(8, matrix.Height - 8) == 0)
			{
				throw new BarcodeEncoderException();
			}
			matrix.Set(8, matrix.Height - 8, 1);
		}

		private static void EmbedHorizontalSeparationPattern(int xStart, int yStart, ByteMatrix matrix)
		{
			for (int i = 0; i < 8; i++)
			{
				if (!IsEmpty(matrix.Get(xStart + i, yStart)))
				{
					throw new BarcodeEncoderException();
				}
				matrix.Set(xStart + i, yStart, 0);
			}
		}

		private static void EmbedVerticalSeparationPattern(int xStart, int yStart, ByteMatrix matrix)
		{
			for (int i = 0; i < 7; i++)
			{
				if (!IsEmpty(matrix.Get(xStart, yStart + i)))
				{
					throw new BarcodeEncoderException();
				}
				matrix.Set(xStart, yStart + i, 0);
			}
		}

		private static void EmbedPositionAdjustmentPattern(int xStart, int yStart, ByteMatrix matrix)
		{
			for (int i = 0; i < 5; i++)
			{
				for (int j = 0; j < 5; j++)
				{
					matrix.Set(xStart + j, yStart + i, POSITION_ADJUSTMENT_PATTERN[i][j]);
				}
			}
		}

		private static void EmbedPositionDetectionPattern(int xStart, int yStart, ByteMatrix matrix)
		{
			if (POSITION_DETECTION_PATTERN[0].Length != 7 || POSITION_DETECTION_PATTERN.Length != 7)
			{
				throw new BarcodeEncoderException("Bad position detection pattern");
			}
			for (int i = 0; i < 7; i++)
			{
				for (int j = 0; j < 7; j++)
				{
					matrix.Set(xStart + j, yStart + i, POSITION_DETECTION_PATTERN[i][j]);
				}
			}
		}

		private static void EmbedPositionDetectionPatternsAndSeparators(ByteMatrix matrix)
		{
			int num = POSITION_DETECTION_PATTERN[0].Length;
			EmbedPositionDetectionPattern(0, 0, matrix);
			EmbedPositionDetectionPattern(matrix.Width - num, 0, matrix);
			EmbedPositionDetectionPattern(0, matrix.Width - num, matrix);
			int num2 = 8;
			EmbedHorizontalSeparationPattern(0, num2 - 1, matrix);
			EmbedHorizontalSeparationPattern(matrix.Width - num2, num2 - 1, matrix);
			EmbedHorizontalSeparationPattern(0, matrix.Width - num2, matrix);
			int num3 = 7;
			EmbedVerticalSeparationPattern(num3, 0, matrix);
			EmbedVerticalSeparationPattern(matrix.Height - num3 - 1, 0, matrix);
			EmbedVerticalSeparationPattern(num3, matrix.Height - num3, matrix);
		}

		private static void MaybeEmbedPositionAdjustmentPatterns(MessagingToolkit.Barcode.QRCode.Decoder.Version version, ByteMatrix matrix)
		{
			if (version.VersionNumber < 2)
			{
				return;
			}
			int num = version.VersionNumber - 1;
			int[] array = POSITION_ADJUSTMENT_PATTERN_COORDINATE_TABLE[num];
			int num2 = POSITION_ADJUSTMENT_PATTERN_COORDINATE_TABLE[num].Length;
			for (int i = 0; i < num2; i++)
			{
				for (int j = 0; j < num2; j++)
				{
					int num3 = array[i];
					int num4 = array[j];
					if (num4 != -1 && num3 != -1 && IsEmpty(matrix.Get(num4, num3)))
					{
						EmbedPositionAdjustmentPattern(num4 - 2, num3 - 2, matrix);
					}
				}
			}
		}
	}
	public sealed class QRCode
	{
		public const int NUM_MASK_PATTERNS = 8;

		private Mode mode;

		private ErrorCorrectionLevel ecLevel;

		private MessagingToolkit.Barcode.QRCode.Decoder.Version version;

		private int maskPattern;

		private ByteMatrix matrix;

		public Mode Mode
		{
			get
			{
				return mode;
			}
			set
			{
				mode = value;
			}
		}

		public ErrorCorrectionLevel ECLevel
		{
			get
			{
				return ecLevel;
			}
			set
			{
				ecLevel = value;
			}
		}

		public MessagingToolkit.Barcode.QRCode.Decoder.Version Version
		{
			get
			{
				return version;
			}
			set
			{
				version = value;
			}
		}

		public int MaskPattern
		{
			get
			{
				return maskPattern;
			}
			set
			{
				maskPattern = value;
			}
		}

		public ByteMatrix Matrix
		{
			get
			{
				return matrix;
			}
			set
			{
				matrix = value;
			}
		}

		public QRCode()
		{
			maskPattern = -1;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(200);
			stringBuilder.Append("<<\n");
			stringBuilder.Append(" mode: ");
			stringBuilder.Append(mode);
			stringBuilder.Append("\n ecLevel: ");
			stringBuilder.Append(ecLevel);
			stringBuilder.Append("\n version: ");
			stringBuilder.Append(version);
			stringBuilder.Append("\n maskPattern: ");
			stringBuilder.Append(maskPattern);
			stringBuilder.Append("\n numDataBytes: ");
			if (matrix == null)
			{
				stringBuilder.Append("\n matrix: null\n");
			}
			else
			{
				stringBuilder.Append("\n matrix:\n");
				stringBuilder.Append(matrix.ToString());
			}
			stringBuilder.Append(">>\n");
			return stringBuilder.ToString();
		}

		public static bool IsValidMaskPattern(int maskPattern)
		{
			if (maskPattern >= 0)
			{
				return maskPattern < 8;
			}
			return false;
		}
	}
