	public sealed class AlignmentPattern : ResultPoint
	{
		private readonly float estimatedModuleSize;

		internal AlignmentPattern(float posX, float posY, float estimatedModuleSize)
			: base(posX, posY)
		{
			this.estimatedModuleSize = estimatedModuleSize;
		}

		internal bool AboutEquals(float moduleSize, float i, float j)
		{
			if (Math.Abs(i - Y) <= moduleSize && Math.Abs(j - X) <= moduleSize)
			{
				float num = Math.Abs(moduleSize - estimatedModuleSize);
				if (!(num <= 1f))
				{
					return num <= estimatedModuleSize;
				}
				return true;
			}
			return false;
		}

		internal AlignmentPattern CombineEstimate(float i, float j, float newModuleSize)
		{
			float posX = (X + j) / 2f;
			float posY = (Y + i) / 2f;
			float num = (estimatedModuleSize + newModuleSize) / 2f;
			return new AlignmentPattern(posX, posY, num);
		}
	}
	internal sealed class AlignmentPatternFinder
	{
		private readonly BitMatrix image;

		private List<object> possibleCenters;

		private readonly int startX;

		private readonly int startY;

		private readonly int width;

		private readonly int height;

		private readonly float moduleSize;

		private readonly int[] crossCheckStateCount;

		private readonly ResultPointCallback resultPointCallback;

		internal AlignmentPatternFinder(BitMatrix image, int startX, int startY, int width, int height, float moduleSize, ResultPointCallback resultPointCallback)
		{
			this.image = image;
			possibleCenters = new List<object>(5);
			this.startX = startX;
			this.startY = startY;
			this.width = width;
			this.height = height;
			this.moduleSize = moduleSize;
			crossCheckStateCount = new int[3];
			this.resultPointCallback = resultPointCallback;
		}

		internal AlignmentPattern Find()
		{
			int num = startX;
			int num2 = height;
			int num3 = num + width;
			int num4 = startY + (num2 >> 1);
			int[] array = new int[3];
			for (int i = 0; i < num2; i++)
			{
				int num5 = num4 + (((i & 1) == 0) ? (i + 1 >> 1) : (-(i + 1 >> 1)));
				array[0] = 0;
				array[1] = 0;
				array[2] = 0;
				int j;
				for (j = num; j < num3 && !image.Get(j, num5); j++)
				{
				}
				int num6 = 0;
				for (; j < num3; j++)
				{
					if (image.Get(j, num5))
					{
						switch (num6)
						{
						case 1:
							array[num6]++;
							break;
						case 2:
							if (FoundPatternCross(array))
							{
								AlignmentPattern alignmentPattern = HandlePossibleCenter(array, num5, j);
								if (alignmentPattern != null)
								{
									return alignmentPattern;
								}
							}
							array[0] = array[2];
							array[1] = 1;
							array[2] = 0;
							num6 = 1;
							break;
						default:
							array[++num6]++;
							break;
						}
					}
					else
					{
						if (num6 == 1)
						{
							num6++;
						}
						array[num6]++;
					}
				}
				if (FoundPatternCross(array))
				{
					AlignmentPattern alignmentPattern2 = HandlePossibleCenter(array, num5, num3);
					if (alignmentPattern2 != null)
					{
						return alignmentPattern2;
					}
				}
			}
			if (possibleCenters.Count != 0)
			{
				return (AlignmentPattern)possibleCenters[0];
			}
			throw NotFoundException.Instance;
		}

		private static float CenterFromEnd(int[] stateCount, int end)
		{
			return (float)(end - stateCount[2]) - (float)stateCount[1] / 2f;
		}

		private bool FoundPatternCross(int[] stateCount)
		{
			float num = moduleSize;
			float num2 = num / 2f;
			for (int i = 0; i < 3; i++)
			{
				if (Math.Abs(num - (float)stateCount[i]) >= num2)
				{
					return false;
				}
			}
			return true;
		}

		private float CrossCheckVertical(int startI, int centerJ, int maxCount, int originalStateCountTotal)
		{
			BitMatrix bitMatrix = image;
			int num = bitMatrix.GetHeight();
			int[] array = crossCheckStateCount;
			array[0] = 0;
			array[1] = 0;
			array[2] = 0;
			int num2 = startI;
			while (num2 >= 0 && bitMatrix.Get(centerJ, num2) && array[1] <= maxCount)
			{
				array[1]++;
				num2--;
			}
			if (num2 < 0 || array[1] > maxCount)
			{
				return float.NaN;
			}
			while (num2 >= 0 && !bitMatrix.Get(centerJ, num2) && array[0] <= maxCount)
			{
				array[0]++;
				num2--;
			}
			if (array[0] > maxCount)
			{
				return float.NaN;
			}
			for (num2 = startI + 1; num2 < num && bitMatrix.Get(centerJ, num2); num2++)
			{
				if (array[1] > maxCount)
				{
					break;
				}
				array[1]++;
			}
			if (num2 == num || array[1] > maxCount)
			{
				return float.NaN;
			}
			for (; num2 < num && !bitMatrix.Get(centerJ, num2); num2++)
			{
				if (array[2] > maxCount)
				{
					break;
				}
				array[2]++;
			}
			if (array[2] > maxCount)
			{
				return float.NaN;
			}
			int num3 = array[0] + array[1] + array[2];
			if (5 * Math.Abs(num3 - originalStateCountTotal) >= 2 * originalStateCountTotal)
			{
				return float.NaN;
			}
			if (!FoundPatternCross(array))
			{
				return float.NaN;
			}
			return CenterFromEnd(array, num2);
		}

		private AlignmentPattern HandlePossibleCenter(int[] stateCount, int i, int j)
		{
			int originalStateCountTotal = stateCount[0] + stateCount[1] + stateCount[2];
			float num = CenterFromEnd(stateCount, j);
			float num2 = CrossCheckVertical(i, (int)num, 2 * stateCount[1], originalStateCountTotal);
			if (!float.IsNaN(num2))
			{
				float num3 = (float)(stateCount[0] + stateCount[1] + stateCount[2]) / 3f;
				foreach (AlignmentPattern possibleCenter in possibleCenters)
				{
					if (possibleCenter.AboutEquals(num3, num2, num))
					{
						return possibleCenter.CombineEstimate(num2, num, num3);
					}
				}
				AlignmentPattern alignmentPattern2 = new AlignmentPattern(num, num2, num3);
				possibleCenters.Add(alignmentPattern2);
				if (resultPointCallback != null)
				{
					resultPointCallback.FoundPossibleResultPoint(alignmentPattern2);
				}
			}
			return null;
		}
	}
	public class Detector
	{
		private readonly BitMatrix image;

		private ResultPointCallback resultPointCallback;

		protected internal BitMatrix Image => image;

		protected internal ResultPointCallback ResultPointCallback => resultPointCallback;

		public Detector(BitMatrix image)
		{
			this.image = image;
		}

		public DetectorResult Detect()
		{
			return Detect(null);
		}

		public DetectorResult Detect(Dictionary<DecodeOptions, object> decodingOptions)
		{
			resultPointCallback = ((decodingOptions == null) ? null : ((ResultPointCallback)BarcodeHelper.GetDecodeOptionType(decodingOptions, DecodeOptions.NeedResultPointCallback)));
			FinderPatternInfo info = new FinderPatternFinder(image, resultPointCallback).Find(decodingOptions);
			return ProcessFinderPatternInfo(info);
		}

		protected internal DetectorResult ProcessFinderPatternInfo(FinderPatternInfo info)
		{
			FinderPattern topLeft = info.TopLeft;
			FinderPattern topRight = info.TopRight;
			FinderPattern bottomLeft = info.BottomLeft;
			float num = CalculateModuleSize(topLeft, topRight, bottomLeft);
			if (num < 1f)
			{
				throw NotFoundException.Instance;
			}
			int dimension = ComputeDimension(topLeft, topRight, bottomLeft, num);
			MessagingToolkit.Barcode.QRCode.Decoder.Version provisionalVersionForDimension = MessagingToolkit.Barcode.QRCode.Decoder.Version.GetProvisionalVersionForDimension(dimension);
			int num2 = provisionalVersionForDimension.DimensionForVersion - 7;
			AlignmentPattern alignmentPattern = null;
			if (provisionalVersionForDimension.AlignmentPatternCenters.Length != 0)
			{
				float num3 = topRight.X - topLeft.X + bottomLeft.X;
				float num4 = topRight.Y - topLeft.Y + bottomLeft.Y;
				float num5 = 1f - 3f / (float)num2;
				int estAlignmentX = (int)(topLeft.X + num5 * (num3 - topLeft.X));
				int estAlignmentY = (int)(topLeft.Y + num5 * (num4 - topLeft.Y));
				for (int num6 = 4; num6 <= 16; num6 <<= 1)
				{
					try
					{
						alignmentPattern = FindAlignmentInRegion(num, estAlignmentX, estAlignmentY, num6);
					}
					catch (NotFoundException)
					{
						continue;
					}
					break;
				}
			}
			PerspectiveTransform transform = CreateTransform(topLeft, topRight, bottomLeft, alignmentPattern, dimension);
			BitMatrix bits = SampleGrid(image, transform, dimension);
			ResultPoint[] points = ((alignmentPattern != null) ? new ResultPoint[4] { bottomLeft, topLeft, topRight, alignmentPattern } : new ResultPoint[3] { bottomLeft, topLeft, topRight });
			return new DetectorResult(bits, points);
		}

		public static PerspectiveTransform CreateTransform(ResultPoint topLeft, ResultPoint topRight, ResultPoint bottomLeft, ResultPoint alignmentPattern, int dimension)
		{
			float num = (float)dimension - 3.5f;
			float x2p;
			float y2p;
			float num2;
			float y;
			if (alignmentPattern != null)
			{
				x2p = alignmentPattern.X;
				y2p = alignmentPattern.Y;
				num2 = num - 3f;
				y = num2;
			}
			else
			{
				x2p = topRight.X - topLeft.X + bottomLeft.X;
				y2p = topRight.Y - topLeft.Y + bottomLeft.Y;
				num2 = num;
				y = num;
			}
			return PerspectiveTransform.QuadrilateralToQuadrilateral(3.5f, 3.5f, num, 3.5f, num2, y, 3.5f, num, topLeft.X, topLeft.Y, topRight.X, topRight.Y, x2p, y2p, bottomLeft.X, bottomLeft.Y);
		}

		private static BitMatrix SampleGrid(BitMatrix image, PerspectiveTransform transform, int dimension)
		{
			return GridSampler.GetInstance().SampleGrid(image, dimension, dimension, transform);
		}

		protected internal static int ComputeDimension(ResultPoint topLeft, ResultPoint topRight, ResultPoint bottomLeft, float moduleSize)
		{
			int num = MathUtils.Round(ResultPoint.Distance(topLeft, topRight) / moduleSize);
			int num2 = MathUtils.Round(ResultPoint.Distance(topLeft, bottomLeft) / moduleSize);
			int num3 = (num + num2 >> 1) + 7;
			switch (num3 & 3)
			{
			case 0:
				num3++;
				break;
			case 2:
				num3--;
				break;
			case 3:
				throw NotFoundException.Instance;
			}
			return num3;
		}

		protected internal float CalculateModuleSize(ResultPoint topLeft, ResultPoint topRight, ResultPoint bottomLeft)
		{
			return (CalculateModuleSizeOneWay(topLeft, topRight) + CalculateModuleSizeOneWay(topLeft, bottomLeft)) / 2f;
		}

		private float CalculateModuleSizeOneWay(ResultPoint pattern, ResultPoint otherPattern)
		{
			float num = SizeOfBlackWhiteBlackRunBothWays((int)pattern.X, (int)pattern.Y, (int)otherPattern.X, (int)otherPattern.Y);
			float num2 = SizeOfBlackWhiteBlackRunBothWays((int)otherPattern.X, (int)otherPattern.Y, (int)pattern.X, (int)pattern.Y);
			if (float.IsNaN(num))
			{
				return num2 / 7f;
			}
			if (float.IsNaN(num2))
			{
				return num / 7f;
			}
			return (num + num2) / 14f;
		}

		private float SizeOfBlackWhiteBlackRunBothWays(int fromX, int fromY, int toX, int toY)
		{
			float num = SizeOfBlackWhiteBlackRun(fromX, fromY, toX, toY);
			float num2 = 1f;
			int num3 = fromX - (toX - fromX);
			if (num3 < 0)
			{
				num2 = (float)fromX / (float)(fromX - num3);
				num3 = 0;
			}
			else if (num3 >= image.GetWidth())
			{
				num2 = (float)(image.GetWidth() - 1 - fromX) / (float)(num3 - fromX);
				num3 = image.GetWidth() - 1;
			}
			int num4 = (int)((float)fromY - (float)(toY - fromY) * num2);
			num2 = 1f;
			if (num4 < 0)
			{
				num2 = (float)fromY / (float)(fromY - num4);
				num4 = 0;
			}
			else if (num4 >= image.GetHeight())
			{
				num2 = (float)(image.GetHeight() - 1 - fromY) / (float)(num4 - fromY);
				num4 = image.GetHeight() - 1;
			}
			num3 = (int)((float)fromX + (float)(num3 - fromX) * num2);
			return num + SizeOfBlackWhiteBlackRun(fromX, fromY, num3, num4) - 1f;
		}

		private float SizeOfBlackWhiteBlackRun(int fromX, int fromY, int toX, int toY)
		{
			bool flag = Math.Abs(toY - fromY) > Math.Abs(toX - fromX);
			if (flag)
			{
				int num = fromX;
				fromX = fromY;
				fromY = num;
				int num2 = toX;
				toX = toY;
				toY = num2;
			}
			int num3 = Math.Abs(toX - fromX);
			int num4 = Math.Abs(toY - fromY);
			int num5 = -num3 >> 1;
			int num6 = ((fromX < toX) ? 1 : (-1));
			int num7 = ((fromY < toY) ? 1 : (-1));
			int num8 = 0;
			int num9 = toX + num6;
			int i = fromX;
			int num10 = fromY;
			for (; i != num9; i += num6)
			{
				int x = (flag ? num10 : i);
				int y = (flag ? i : num10);
				if (num8 == 1 == image.Get(x, y))
				{
					if (num8 == 2)
					{
						return MathUtils.Distance(i, num10, fromX, fromY);
					}
					num8++;
				}
				num5 += num4;
				if (num5 > 0)
				{
					if (num10 == toY)
					{
						break;
					}
					num10 += num7;
					num5 -= num3;
				}
			}
			if (num8 == 2)
			{
				return MathUtils.Distance(toX + num6, toY, fromX, fromY);
			}
			return float.NaN;
		}

		protected internal AlignmentPattern FindAlignmentInRegion(float overallEstModuleSize, int estAlignmentX, int estAlignmentY, float allowanceFactor)
		{
			int num = (int)(allowanceFactor * overallEstModuleSize);
			int num2 = Math.Max(0, estAlignmentX - num);
			int num3 = Math.Min(image.GetWidth() - 1, estAlignmentX + num);
			if ((float)(num3 - num2) < overallEstModuleSize * 3f)
			{
				throw NotFoundException.Instance;
			}
			int num4 = Math.Max(0, estAlignmentY - num);
			int num5 = Math.Min(image.GetHeight() - 1, estAlignmentY + num);
			if ((float)(num5 - num4) < overallEstModuleSize * 3f)
			{
				throw NotFoundException.Instance;
			}
			return new AlignmentPatternFinder(image, num2, num4, num3 - num2, num5 - num4, overallEstModuleSize, resultPointCallback).Find();
		}
	}
	public sealed class FinderPattern : ResultPoint
	{
		private readonly float estimatedModuleSize;

		private int count;

		public float EstimatedModuleSize => estimatedModuleSize;

		internal int Count => count;

		internal FinderPattern(float posX, float posY, float estimatedModuleSize)
			: this(posX, posY, estimatedModuleSize, 1)
		{
		}

		private FinderPattern(float posX, float posY, float estimatedModuleSize, int count)
			: base(posX, posY)
		{
			this.estimatedModuleSize = estimatedModuleSize;
			this.count = count;
		}

		internal void IncrementCount()
		{
			count++;
		}

		internal bool AboutEquals(float moduleSize, float i, float j)
		{
			if (Math.Abs(i - Y) <= moduleSize && Math.Abs(j - X) <= moduleSize)
			{
				float num = Math.Abs(moduleSize - estimatedModuleSize);
				if (!(num <= 1f))
				{
					return num <= estimatedModuleSize;
				}
				return true;
			}
			return false;
		}

		internal FinderPattern CombineEstimate(float i, float j, float newModuleSize)
		{
			int num = count + 1;
			float posX = ((float)count * X + j) / (float)num;
			float posY = ((float)count * Y + i) / (float)num;
			float num2 = ((float)count * estimatedModuleSize + newModuleSize) / (float)num;
			return new FinderPattern(posX, posY, num2, num);
		}
	}
	public class FinderPatternFinder
	{
		[Serializable]
		private class FurthestFromAverageComparator : Comparator
		{
			private readonly float average;

			public FurthestFromAverageComparator(float f)
			{
				average = f;
			}

			public virtual int Compare(object center1, object center2)
			{
				float num = Math.Abs(((FinderPattern)center2).EstimatedModuleSize - average);
				float num2 = Math.Abs(((FinderPattern)center1).EstimatedModuleSize - average);
				if (!(num < num2))
				{
					if (num != num2)
					{
						return 1;
					}
					return 0;
				}
				return -1;
			}
		}

		[Serializable]
		private class CenterComparator : Comparator
		{
			private readonly float average;

			public CenterComparator(float f)
			{
				average = f;
			}

			public virtual int Compare(object center1, object center2)
			{
				if (((FinderPattern)center2).Count == ((FinderPattern)center1).Count)
				{
					float num = Math.Abs(((FinderPattern)center2).EstimatedModuleSize - average);
					float num2 = Math.Abs(((FinderPattern)center1).EstimatedModuleSize - average);
					if (!(num < num2))
					{
						if (num != num2)
						{
							return -1;
						}
						return 0;
					}
					return 1;
				}
				return ((FinderPattern)center2).Count - ((FinderPattern)center1).Count;
			}
		}

		private const int CENTER_QUORUM = 6;

		protected internal const int MIN_SKIP = 3;

		protected internal const int MAX_MODULES = 57;

		private const int INTEGER_MATH_SHIFT = 8;

		private readonly BitMatrix image;

		private readonly List<object> possibleCenters;

		private bool hasSkipped;

		private readonly int[] crossCheckStateCount;

		private readonly ResultPointCallback resultPointCallback;

		public FinderPatternFinder(BitMatrix image)
			: this(image, null)
		{
		}

		public FinderPatternFinder(BitMatrix image, ResultPointCallback resultPointCallback)
		{
			this.image = image;
			possibleCenters = new List<object>();
			crossCheckStateCount = new int[5];
			this.resultPointCallback = resultPointCallback;
		}

		protected internal BitMatrix GetImage()
		{
			return image;
		}

		protected internal List<object> GetPossibleCenters()
		{
			return possibleCenters;
		}

		internal FinderPatternInfo Find(Dictionary<DecodeOptions, object> decodingOptions)
		{
			bool flag = decodingOptions?.ContainsKey(DecodeOptions.TryHarder) ?? false;
			int height = image.GetHeight();
			int width = image.GetWidth();
			int num = 3 * height / 228;
			if (num < 3 || flag)
			{
				num = 3;
			}
			bool flag2 = false;
			int[] array = new int[5];
			for (int i = num - 1; i < height; i += num)
			{
				if (flag2)
				{
					break;
				}
				array[0] = 0;
				array[1] = 0;
				array[2] = 0;
				array[3] = 0;
				array[4] = 0;
				int num2 = 0;
				for (int j = 0; j < width; j++)
				{
					if (image.Get(j, i))
					{
						if ((num2 & 1) == 1)
						{
							num2++;
						}
						array[num2]++;
					}
					else if ((num2 & 1) == 0)
					{
						if (num2 == 4)
						{
							if (FoundPatternCross(array))
							{
								if (HandlePossibleCenter(array, i, j))
								{
									num = 2;
									if (hasSkipped)
									{
										flag2 = HaveMultiplyConfirmedCenters();
									}
									else
									{
										int num3 = FindRowSkip();
										if (num3 > array[2])
										{
											i += num3 - array[2] - num;
											j = width - 1;
										}
									}
									num2 = 0;
									array[0] = 0;
									array[1] = 0;
									array[2] = 0;
									array[3] = 0;
									array[4] = 0;
								}
								else
								{
									array[0] = array[2];
									array[1] = array[3];
									array[2] = array[4];
									array[3] = 1;
									array[4] = 0;
									num2 = 3;
								}
							}
							else
							{
								array[0] = array[2];
								array[1] = array[3];
								array[2] = array[4];
								array[3] = 1;
								array[4] = 0;
								num2 = 3;
							}
						}
						else
						{
							array[++num2]++;
						}
					}
					else
					{
						array[num2]++;
					}
				}
				if (FoundPatternCross(array) && HandlePossibleCenter(array, i, width))
				{
					num = array[0];
					if (hasSkipped)
					{
						flag2 = HaveMultiplyConfirmedCenters();
					}
				}
			}
			FinderPattern[] array2 = SelectBestPatterns();
			ResultPoint.OrderBestPatterns(array2);
			return new FinderPatternInfo(array2);
		}

		private static float CenterFromEnd(int[] stateCount, int end)
		{
			return (float)(end - stateCount[4] - stateCount[3]) - (float)stateCount[2] / 2f;
		}

		protected internal static bool FoundPatternCross(int[] stateCount)
		{
			int num = 0;
			for (int i = 0; i < 5; i++)
			{
				int num2 = stateCount[i];
				if (num2 == 0)
				{
					return false;
				}
				num += num2;
			}
			if (num < 7)
			{
				return false;
			}
			int num3 = (num << 8) / 7;
			int num4 = num3 / 2;
			if (Math.Abs(num3 - (stateCount[0] << 8)) < num4 && Math.Abs(num3 - (stateCount[1] << 8)) < num4 && Math.Abs(3 * num3 - (stateCount[2] << 8)) < 3 * num4 && Math.Abs(num3 - (stateCount[3] << 8)) < num4)
			{
				return Math.Abs(num3 - (stateCount[4] << 8)) < num4;
			}
			return false;
		}

		private int[] GetCrossCheckStateCount()
		{
			crossCheckStateCount[0] = 0;
			crossCheckStateCount[1] = 0;
			crossCheckStateCount[2] = 0;
			crossCheckStateCount[3] = 0;
			crossCheckStateCount[4] = 0;
			return crossCheckStateCount;
		}

		private float CrossCheckVertical(int startI, int centerJ, int maxCount, int originalStateCountTotal)
		{
			BitMatrix bitMatrix = image;
			int height = bitMatrix.GetHeight();
			int[] array = GetCrossCheckStateCount();
			int num = startI;
			while (num >= 0 && bitMatrix.Get(centerJ, num))
			{
				array[2]++;
				num--;
			}
			if (num < 0)
			{
				return float.NaN;
			}
			while (num >= 0 && !bitMatrix.Get(centerJ, num) && array[1] <= maxCount)
			{
				array[1]++;
				num--;
			}
			if (num < 0 || array[1] > maxCount)
			{
				return float.NaN;
			}
			while (num >= 0 && bitMatrix.Get(centerJ, num) && array[0] <= maxCount)
			{
				array[0]++;
				num--;
			}
			if (array[0] > maxCount)
			{
				return float.NaN;
			}
			for (num = startI + 1; num < height && bitMatrix.Get(centerJ, num); num++)
			{
				array[2]++;
			}
			if (num == height)
			{
				return float.NaN;
			}
			for (; num < height && !bitMatrix.Get(centerJ, num); num++)
			{
				if (array[3] >= maxCount)
				{
					break;
				}
				array[3]++;
			}
			if (num == height || array[3] >= maxCount)
			{
				return float.NaN;
			}
			for (; num < height && bitMatrix.Get(centerJ, num); num++)
			{
				if (array[4] >= maxCount)
				{
					break;
				}
				array[4]++;
			}
			if (array[4] >= maxCount)
			{
				return float.NaN;
			}
			int num2 = array[0] + array[1] + array[2] + array[3] + array[4];
			if (5 * Math.Abs(num2 - originalStateCountTotal) >= 2 * originalStateCountTotal)
			{
				return float.NaN;
			}
			if (!FoundPatternCross(array))
			{
				return float.NaN;
			}
			return CenterFromEnd(array, num);
		}

		private float CrossCheckHorizontal(int startJ, int centerI, int maxCount, int originalStateCountTotal)
		{
			BitMatrix bitMatrix = image;
			int width = bitMatrix.GetWidth();
			int[] array = GetCrossCheckStateCount();
			int num = startJ;
			while (num >= 0 && bitMatrix.Get(num, centerI))
			{
				array[2]++;
				num--;
			}
			if (num < 0)
			{
				return float.NaN;
			}
			while (num >= 0 && !bitMatrix.Get(num, centerI) && array[1] <= maxCount)
			{
				array[1]++;
				num--;
			}
			if (num < 0 || array[1] > maxCount)
			{
				return float.NaN;
			}
			while (num >= 0 && bitMatrix.Get(num, centerI) && array[0] <= maxCount)
			{
				array[0]++;
				num--;
			}
			if (array[0] > maxCount)
			{
				return float.NaN;
			}
			for (num = startJ + 1; num < width && bitMatrix.Get(num, centerI); num++)
			{
				array[2]++;
			}
			if (num == width)
			{
				return float.NaN;
			}
			for (; num < width && !bitMatrix.Get(num, centerI); num++)
			{
				if (array[3] >= maxCount)
				{
					break;
				}
				array[3]++;
			}
			if (num == width || array[3] >= maxCount)
			{
				return float.NaN;
			}
			for (; num < width && bitMatrix.Get(num, centerI); num++)
			{
				if (array[4] >= maxCount)
				{
					break;
				}
				array[4]++;
			}
			if (array[4] >= maxCount)
			{
				return float.NaN;
			}
			int num2 = array[0] + array[1] + array[2] + array[3] + array[4];
			if (5 * Math.Abs(num2 - originalStateCountTotal) >= originalStateCountTotal)
			{
				return float.NaN;
			}
			if (!FoundPatternCross(array))
			{
				return float.NaN;
			}
			return CenterFromEnd(array, num);
		}

		protected internal bool HandlePossibleCenter(int[] stateCount, int i, int j)
		{
			int num = stateCount[0] + stateCount[1] + stateCount[2] + stateCount[3] + stateCount[4];
			float num2 = CenterFromEnd(stateCount, j);
			float num3 = CrossCheckVertical(i, (int)num2, stateCount[2], num);
			if (!float.IsNaN(num3))
			{
				num2 = CrossCheckHorizontal((int)num2, (int)num3, stateCount[2], num);
				if (!float.IsNaN(num2))
				{
					float num4 = (float)num / 7f;
					bool flag = false;
					for (int k = 0; k < possibleCenters.Count; k++)
					{
						FinderPattern finderPattern = (FinderPattern)possibleCenters[k];
						if (finderPattern.AboutEquals(num4, num3, num2))
						{
							possibleCenters[k] = finderPattern.CombineEstimate(num3, num2, num4);
							flag = true;
							break;
						}
					}
					if (!flag)
					{
						FinderPattern finderPattern2 = new FinderPattern(num2, num3, num4);
						possibleCenters.Add(finderPattern2);
						if (resultPointCallback != null)
						{
							resultPointCallback.FoundPossibleResultPoint(finderPattern2);
						}
					}
					return true;
				}
			}
			return false;
		}

		private int FindRowSkip()
		{
			if (possibleCenters.Count <= 1)
			{
				return 0;
			}
			FinderPattern finderPattern = null;
			foreach (FinderPattern possibleCenter in possibleCenters)
			{
				if (possibleCenter.Count >= 6)
				{
					if (finderPattern != null)
					{
						hasSkipped = true;
						return (int)(Math.Abs(finderPattern.X - possibleCenter.X) - Math.Abs(finderPattern.Y - possibleCenter.Y)) / 2;
					}
					finderPattern = possibleCenter;
				}
			}
			return 0;
		}

		private bool HaveMultiplyConfirmedCenters()
		{
			int num = 0;
			float num2 = 0f;
			int count = possibleCenters.Count;
			foreach (FinderPattern possibleCenter in possibleCenters)
			{
				if (possibleCenter.Count >= 6)
				{
					num++;
					num2 += possibleCenter.EstimatedModuleSize;
				}
			}
			if (num < 3)
			{
				return false;
			}
			float num3 = num2 / (float)count;
			float num4 = 0f;
			foreach (FinderPattern possibleCenter2 in possibleCenters)
			{
				num4 += Math.Abs(possibleCenter2.EstimatedModuleSize - num3);
			}
			return num4 <= 0.05f * num2;
		}

		private FinderPattern[] SelectBestPatterns()
		{
			int count = possibleCenters.Count;
			if (count < 3)
			{
				throw NotFoundException.Instance;
			}
			if (count > 3)
			{
				float num = 0f;
				float num2 = 0f;
				foreach (FinderPattern possibleCenter in possibleCenters)
				{
					float estimatedModuleSize = possibleCenter.EstimatedModuleSize;
					num += estimatedModuleSize;
					num2 += estimatedModuleSize * estimatedModuleSize;
				}
				float num3 = num / (float)count;
				float val = (float)Math.Sqrt(num2 / (float)count - num3 * num3);
				Collections.InsertionSort(possibleCenters, new FurthestFromAverageComparator(num3));
				float num4 = Math.Max(0.2f * num3, val);
				for (int i = 0; i < possibleCenters.Count; i++)
				{
					if (possibleCenters.Count <= 3)
					{
						break;
					}
					if (Math.Abs(((FinderPattern)possibleCenters[i]).EstimatedModuleSize - num3) > num4)
					{
						possibleCenters.RemoveAt(i);
						i--;
					}
				}
			}
			if (possibleCenters.Count > 3)
			{
				float num5 = 0f;
				foreach (FinderPattern possibleCenter2 in possibleCenters)
				{
					num5 += possibleCenter2.EstimatedModuleSize;
				}
				float f = num5 / (float)possibleCenters.Count;
				Collections.InsertionSort(possibleCenters, new CenterComparator(f));
				possibleCenters.RemoveRange(3, possibleCenters.Count - 3);
			}
			return new FinderPattern[3]
			{
				(FinderPattern)possibleCenters[0],
				(FinderPattern)possibleCenters[1],
				(FinderPattern)possibleCenters[2]
			};
		}
	}
