	public sealed class ByQuadrantDecoder : IDecoder
	{
		private readonly IDecoder decoder;

		public ByQuadrantDecoder(IDecoder delegat0)
		{
			decoder = delegat0;
		}

		public Result Decode(BinaryBitmap image)
		{
			return Decode(image, null);
		}

		public Result Decode(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions)
		{
			int width = image.Width;
			int height = image.Height;
			int num = width / 2;
			int num2 = height / 2;
			BinaryBitmap binaryBitmap = image.Crop(0, 0, num, num2);
			try
			{
				return decoder.Decode(binaryBitmap, decodingOptions);
			}
			catch (NotFoundException)
			{
			}
			BinaryBitmap binaryBitmap2 = image.Crop(num, 0, num, num2);
			try
			{
				return decoder.Decode(binaryBitmap2, decodingOptions);
			}
			catch (NotFoundException)
			{
			}
			BinaryBitmap binaryBitmap3 = image.Crop(0, num2, num, num2);
			try
			{
				return decoder.Decode(binaryBitmap3, decodingOptions);
			}
			catch (NotFoundException)
			{
			}
			BinaryBitmap binaryBitmap4 = image.Crop(num, num2, num, num2);
			try
			{
				return decoder.Decode(binaryBitmap4, decodingOptions);
			}
			catch (NotFoundException)
			{
			}
			int left = num / 2;
			int top = num2 / 2;
			BinaryBitmap binaryBitmap5 = image.Crop(left, top, num, num2);
			return decoder.Decode(binaryBitmap5, decodingOptions);
		}

		public void Reset()
		{
			decoder.Reset();
		}
	}
	public class GenericMultipleBarcodeDecoder : MultipleBarcodeDecoder
	{
		private const int MIN_DIMENSION_TO_RECUR = 100;

		private const int MAX_DEPTH = 4;

		private readonly IDecoder decoder;

		public GenericMultipleBarcodeDecoder(IDecoder decoder)
		{
			this.decoder = decoder;
		}

		public Result[] DecodeMultiple(BinaryBitmap image)
		{
			return DecodeMultiple(image, null);
		}

		public Result[] DecodeMultiple(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions)
		{
			IList<Result> list = new List<Result>();
			DoDecodeMultiple(image, decodingOptions, list, 0, 0, 0);
			if (list.Count == 0)
			{
				throw NotFoundException.Instance;
			}
			int count = list.Count;
			Result[] array = new Result[count];
			for (int i = 0; i < count; i++)
			{
				array[i] = list[i];
			}
			return array;
		}

		private void DoDecodeMultiple(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions, IList<Result> results, int xOffset, int yOffset, int currentDepth)
		{
			if (currentDepth > 4)
			{
				return;
			}
			Result result;
			try
			{
				result = decoder.Decode(image, decodingOptions);
			}
			catch (BarcodeDecoderException)
			{
				return;
			}
			bool flag = false;
			foreach (Result result2 in results)
			{
				if (result2.Text.Equals(result.Text))
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				results.Add(TranslateResultPoints(result, xOffset, yOffset));
			}
			ResultPoint[] resultPoints = result.ResultPoints;
			if (resultPoints == null || resultPoints.Length == 0)
			{
				return;
			}
			int width = image.Width;
			int height = image.Height;
			float num = width;
			float num2 = height;
			float num3 = 0f;
			float num4 = 0f;
			ResultPoint[] array = resultPoints;
			foreach (ResultPoint obj in array)
			{
				float x = obj.X;
				float y = obj.Y;
				if (x < num)
				{
					num = x;
				}
				if (y < num2)
				{
					num2 = y;
				}
				if (x > num3)
				{
					num3 = x;
				}
				if (y > num4)
				{
					num4 = y;
				}
			}
			if (num > 100f)
			{
				DoDecodeMultiple(image.Crop(0, 0, (int)num, height), decodingOptions, results, xOffset, yOffset, currentDepth + 1);
			}
			if (num2 > 100f)
			{
				DoDecodeMultiple(image.Crop(0, 0, width, (int)num2), decodingOptions, results, xOffset, yOffset, currentDepth + 1);
			}
			if (num3 < (float)(width - 100))
			{
				DoDecodeMultiple(image.Crop((int)num3, 0, width - (int)num3, height), decodingOptions, results, xOffset + (int)num3, yOffset, currentDepth + 1);
			}
			if (num4 < (float)(height - 100))
			{
				DoDecodeMultiple(image.Crop(0, (int)num4, width, height - (int)num4), decodingOptions, results, xOffset, yOffset + (int)num4, currentDepth + 1);
			}
		}

		private static Result TranslateResultPoints(Result result, int xOffset, int yOffset)
		{
			ResultPoint[] resultPoints = result.ResultPoints;
			if (resultPoints == null)
			{
				return result;
			}
			ResultPoint[] array = new ResultPoint[resultPoints.Length];
			for (int i = 0; i < resultPoints.Length; i++)
			{
				ResultPoint resultPoint = resultPoints[i];
				array[i] = new ResultPoint(resultPoint.X + (float)xOffset, resultPoint.Y + (float)yOffset);
			}
			Result result2 = new Result(result.Text, result.RawBytes, array, result.BarcodeFormat);
			result2.PutAllMetadata(result.ResultMetadata);
			return result2;
		}
	}
