	internal sealed class MultiFinderPatternFinder : FinderPatternFinder
	{
		[Serializable]
		private class ModuleSizeComparator : Comparator
		{
			public virtual int Compare(object center1, object center2)
			{
				float num = ((MessagingToolkit.Barcode.QRCode.Detector.FinderPattern)center2).EstimatedModuleSize - ((MessagingToolkit.Barcode.QRCode.Detector.FinderPattern)center1).EstimatedModuleSize;
				if (!((double)num < 0.0))
				{
					if (!((double)num > 0.0))
					{
						return 0;
					}
					return 1;
				}
				return -1;
			}
		}

		private static readonly FinderPatternInfo[] EMPTY_RESULT_ARRAY = new FinderPatternInfo[0];

		private const float MAX_MODULE_COUNT_PER_EDGE = 180f;

		private const float MIN_MODULE_COUNT_PER_EDGE = 9f;

		private const float DIFF_MODSIZE_CUTOFF_PERCENT = 0.05f;

		private const float DIFF_MODSIZE_CUTOFF = 0.5f;

		internal MultiFinderPatternFinder(BitMatrix image)
			: base(image)
		{
		}

		internal MultiFinderPatternFinder(BitMatrix image, ResultPointCallback resultPointCallback)
			: base(image, resultPointCallback)
		{
		}

		private MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[][] SelectMutipleBestPatterns()
		{
			List<object> list = GetPossibleCenters();
			int count = list.Count;
			if (count < 3)
			{
				throw NotFoundException.Instance;
			}
			if (count == 3)
			{
				return new MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[1][] { new MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[3]
				{
					(MessagingToolkit.Barcode.QRCode.Detector.FinderPattern)list[0],
					(MessagingToolkit.Barcode.QRCode.Detector.FinderPattern)list[1],
					(MessagingToolkit.Barcode.QRCode.Detector.FinderPattern)list[2]
				} };
			}
			Collections.InsertionSort(list, new ModuleSizeComparator());
			List<MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[]> list2 = new List<MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[]>(10);
			for (int i = 0; i < count - 2; i++)
			{
				MessagingToolkit.Barcode.QRCode.Detector.FinderPattern finderPattern = (MessagingToolkit.Barcode.QRCode.Detector.FinderPattern)list[i];
				if (finderPattern == null)
				{
					continue;
				}
				for (int j = i + 1; j < count - 1; j++)
				{
					MessagingToolkit.Barcode.QRCode.Detector.FinderPattern finderPattern2 = (MessagingToolkit.Barcode.QRCode.Detector.FinderPattern)list[j];
					if (finderPattern2 == null)
					{
						continue;
					}
					float num = (finderPattern.EstimatedModuleSize - finderPattern2.EstimatedModuleSize) / Math.Min(finderPattern.EstimatedModuleSize, finderPattern2.EstimatedModuleSize);
					if (Math.Abs(finderPattern.EstimatedModuleSize - finderPattern2.EstimatedModuleSize) > 0.5f && num >= 0.05f)
					{
						break;
					}
					for (int k = j + 1; k < count; k++)
					{
						MessagingToolkit.Barcode.QRCode.Detector.FinderPattern finderPattern3 = (MessagingToolkit.Barcode.QRCode.Detector.FinderPattern)list[k];
						if (finderPattern3 == null)
						{
							continue;
						}
						float num2 = (finderPattern2.EstimatedModuleSize - finderPattern3.EstimatedModuleSize) / Math.Min(finderPattern2.EstimatedModuleSize, finderPattern3.EstimatedModuleSize);
						if (Math.Abs(finderPattern2.EstimatedModuleSize - finderPattern3.EstimatedModuleSize) > 0.5f && num2 >= 0.05f)
						{
							break;
						}
						MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[] array = new MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[3] { finderPattern, finderPattern2, finderPattern3 };
						ResultPoint.OrderBestPatterns(array);
						FinderPatternInfo finderPatternInfo = new FinderPatternInfo(array);
						float num3 = ResultPoint.Distance(finderPatternInfo.TopLeft, finderPatternInfo.BottomLeft);
						float num4 = ResultPoint.Distance(finderPatternInfo.TopRight, finderPatternInfo.BottomLeft);
						float num5 = ResultPoint.Distance(finderPatternInfo.TopLeft, finderPatternInfo.TopRight);
						float num6 = (num3 + num5) / (finderPattern.EstimatedModuleSize * 2f);
						if (!(num6 > 180f) && !(num6 < 9f) && !(Math.Abs((num3 - num5) / Math.Min(num3, num5)) >= 0.1f))
						{
							float num7 = (float)Math.Sqrt(num3 * num3 + num5 * num5);
							if (!(Math.Abs((num4 - num7) / Math.Min(num4, num7)) >= 0.1f))
							{
								list2.Add(array);
							}
						}
					}
				}
			}
			if (list2.Count != 0)
			{
				MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[][] array2 = new MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[list2.Count][];
				for (int l = 0; l < list2.Count; l++)
				{
					array2[l] = list2[l];
				}
				return array2;
			}
			throw NotFoundException.Instance;
		}

		public FinderPatternInfo[] FindMulti(Dictionary<DecodeOptions, object> decodingOptions)
		{
			bool flag = decodingOptions?.ContainsKey(DecodeOptions.TryHarder) ?? false;
			BitMatrix bitMatrix = GetImage();
			int height = bitMatrix.Height;
			int width = bitMatrix.Width;
			int num = (int)((float)height / 228f * 3f);
			if (num < 3 || flag)
			{
				num = 3;
			}
			int[] array = new int[5];
			for (int i = num - 1; i < height; i += num)
			{
				array[0] = 0;
				array[1] = 0;
				array[2] = 0;
				array[3] = 0;
				array[4] = 0;
				int num2 = 0;
				for (int j = 0; j < width; j++)
				{
					if (bitMatrix.Get(j, i))
					{
						if ((num2 & 1) == 1)
						{
							num2++;
						}
						array[num2]++;
					}
					else if ((num2 & 1) == 0)
					{
						if (num2 == 4)
						{
							if (FinderPatternFinder.FoundPatternCross(array) && HandlePossibleCenter(array, i, j))
							{
								num2 = 0;
								array[0] = 0;
								array[1] = 0;
								array[2] = 0;
								array[3] = 0;
								array[4] = 0;
							}
							else
							{
								array[0] = array[2];
								array[1] = array[3];
								array[2] = array[4];
								array[3] = 1;
								array[4] = 0;
								num2 = 3;
							}
						}
						else
						{
							array[++num2]++;
						}
					}
					else
					{
						array[num2]++;
					}
				}
				if (FinderPatternFinder.FoundPatternCross(array))
				{
					HandlePossibleCenter(array, i, width);
				}
			}
			MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[][] array2 = SelectMutipleBestPatterns();
			List<FinderPatternInfo> list = new List<FinderPatternInfo>();
			MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[][] array3 = array2;
			foreach (MessagingToolkit.Barcode.QRCode.Detector.FinderPattern[] array4 in array3)
			{
				ResultPoint.OrderBestPatterns(array4);
				list.Add(new FinderPatternInfo(array4));
			}
			if (list.Count == 0)
			{
				return EMPTY_RESULT_ARRAY;
			}
			FinderPatternInfo[] array5 = new FinderPatternInfo[list.Count];
			for (int l = 0; l < list.Count; l++)
			{
				array5[l] = list[l];
			}
			return array5;
		}
	}
