namespace MessagingToolkit.Barcode.MaxiCode
{
	public sealed class MaxiCodeDecoder : IDecoder
	{
		private static readonly ResultPoint[] NO_POINTS = new ResultPoint[0];

		private const int MATRIX_WIDTH = 30;

		private const int MATRIX_HEIGHT = 33;

		private readonly MessagingToolkit.Barcode.MaxiCode.Decoder.Decoder decoder = new MessagingToolkit.Barcode.MaxiCode.Decoder.Decoder();

		internal MessagingToolkit.Barcode.MaxiCode.Decoder.Decoder GetDecoder()
		{
			return decoder;
		}

		public Result Decode(BinaryBitmap image)
		{
			return Decode(image, null);
		}

		public Result Decode(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions)
		{
			if (decodingOptions != null && decodingOptions.ContainsKey(DecodeOptions.PureBarcode))
			{
				BitMatrix bits = ExtractPureBits(image.BlackMatrix);
				DecoderResult decoderResult = decoder.Decode(bits, decodingOptions);
				ResultPoint[] nO_POINTS = NO_POINTS;
				Result result = new Result(decoderResult.Text, decoderResult.RawBytes, nO_POINTS, BarcodeFormat.MaxiCode);
				string eCLevel = decoderResult.ECLevel;
				if (eCLevel != null)
				{
					result.PutMetadata(ResultMetadataType.ErrorCorrectionLevel, eCLevel);
				}
				return result;
			}
			throw NotFoundException.Instance;
		}

		public void Reset()
		{
		}

		private static BitMatrix ExtractPureBits(BitMatrix image)
		{
			int[] obj = image.GetEnclosingRectangle() ?? throw NotFoundException.Instance;
			int num = obj[0];
			int num2 = obj[1];
			int num3 = obj[2];
			int num4 = obj[3];
			BitMatrix bitMatrix = new BitMatrix(30, 33);
			for (int i = 0; i < 33; i++)
			{
				int y = num2 + (i * num4 + num4 / 2) / 33;
				for (int j = 0; j < 30; j++)
				{
					int x = num + (j * num3 + num3 / 2 + (i & 1) * num3 / 2) / 30;
					if (image.Get(x, y))
					{
						bitMatrix.Set(j, i);
					}
				}
			}
			return bitMatrix;
		}
	}
