			int height = bitMatrix.Height;
			int width = bitMatrix.Width;
			for (int i = 0; i < height; i++)
			{
				int[] array2 = BITNR[i];
				for (int j = 0; j < width; j++)
				{
					int num = array2[j];
					if (num >= 0 && bitMatrix.Get(j, i))
					{
						array[num / 6] |= (byte)(1 << 5 - num % 6);
					}
				}
			}
			return array;
		}
