				}
				else
				{
					stringBuilder.Insert(0, text + "\u001d" + text2 + "\u001d" + text3 + "\u001d");
				}
				break;
			}
			return new DecoderResult(bytes, stringBuilder.ToString(), null, mode.ToString());
