		private static string GetPostCode3(byte[] bytes)
		{
			return new char[6]
			{
				SETS[0][GetInt(bytes, new byte[6] { 39, 40, 41, 42, 31, 32 })],
				SETS[0][GetInt(bytes, new byte[6] { 33, 34, 35, 36, 25, 26 })],
				SETS[0][GetInt(bytes, new byte[6] { 27, 28, 29, 30, 19, 20 })],
				SETS[0][GetInt(bytes, new byte[6] { 21, 22, 23, 24, 13, 14 })],
				SETS[0][GetInt(bytes, new byte[6] { 15, 16, 17, 18, 7, 8 })],
				SETS[0][GetInt(bytes, new byte[6] { 9, 10, 11, 12, 1, 2 })]
			}.ToString();
		}

		private static string GetMessage(byte[] bytes, int start, int len)
		{
			StringBuilder stringBuilder = new StringBuilder();
			int num = -1;
			int num2 = 0;
			int num3 = 0;
			for (int i = start; i < start + len; i++)
			{
				char c = SETS[num2][bytes[i]];
				switch (c)
				{
				case '\ufff7':
					num2 = 0;
					num = -1;
					break;
				case '\ufff8':
					num2 = 1;
					num = -1;
					break;
				case '\ufff0':
				case '\ufff1':
				case '\ufff2':
				case '\ufff3':
				case '\ufff4':
					num3 = num2;
					num2 = c - 65520;
					num = 1;
					break;
				case '\ufff5':
					num3 = num2;
					num2 = 0;
					num = 2;
					break;
				case '\ufff6':
					num3 = num2;
					num2 = 0;
					num = 3;
					break;
				case '\ufffb':
					((bytes[++i] << 24) + (bytes[++i] << 18) + (bytes[++i] << 12) + (bytes[++i] << 6) + bytes[++i]).ToString("000000000");
					break;
				case '\ufff9':
					num = -1;
					break;
				default:
					stringBuilder.Append(c);
					break;
				}
				if (num-- == 0)
				{
					num2 = num3;
				}
			}
			while (stringBuilder.Length > 0 && stringBuilder[stringBuilder.Length - 1] == '￼')
			{
				stringBuilder.Length--;
			}
			return stringBuilder.ToString();
		}
	}
	public sealed class Decoder
	{
		private const int ALL = 0;

		private const int EVEN = 1;

		private const int ODD = 2;

		private readonly ReedSolomonDecoder rsDecoder;

		public Decoder()
		{
			rsDecoder = new ReedSolomonDecoder(GenericGF.MaxicodeField64);
		}

		public DecoderResult Decode(BitMatrix bits)
		{
			return Decode(bits, null);
		}

		public DecoderResult Decode(BitMatrix bits, Dictionary<DecodeOptions, object> decodingOptions)
		{
			byte[] array = new BitMatrixParser(bits).ReadCodeWords();
			CorrectErrors(array, 0, 10, 10, 0);
			int num = array[0] & 0xF;
			byte[] array2;
			switch (num)
			{
			case 2:
			case 3:
			case 4:
				CorrectErrors(array, 20, 84, 40, 1);
				CorrectErrors(array, 20, 84, 40, 2);
				array2 = new byte[94];
				break;
			case 5:
				CorrectErrors(array, 20, 68, 56, 1);
				CorrectErrors(array, 20, 68, 56, 2);
				array2 = new byte[78];
				break;
			default:
				throw FormatException.Instance;
			}
			Array.Copy(array, 0, array2, 0, 10);
			Array.Copy(array, 20, array2, 10, array2.Length - 10);
			return DecodedBitStreamParser.decode(array2, num);
		}

		private void CorrectErrors(byte[] codewordBytes, int start, int dataCodewords, int ecCodewords, int mode)
		{
			int num = dataCodewords + ecCodewords;
			int num2 = ((mode == 0) ? 1 : 2);
			int[] array = new int[num / num2];
			for (int i = 0; i < num; i++)
			{
				if (mode == 0 || i % 2 == mode - 1)
				{
					array[i / num2] = codewordBytes[i + start] & 0xFF;
				}
			}
			try
			{
				rsDecoder.Decode(array, ecCodewords / num2);
			}
			catch (ReedSolomonException)
			{
				throw ChecksumException.Instance;
			}
			for (int j = 0; j < dataCodewords; j++)
			{
				if (mode == 0 || j % 2 == mode - 1)
				{
					codewordBytes[j + start] = (byte)array[j / num2];
				}
			}
		}
	}
