		public static string ToBinaryString(int x)
		{
			char[] array = new char[32];
			int length = 0;
			while (x != 0)
			{
				array[length++] = (((x & 1) == 1) ? '1' : '0');
				x >>= 1;
			}
			Array.Reverse((Array)array, 0, length);
			return new string(array);
		}

