		private Pdf417Common()
		{
		}

		public static int GetBitCountSum(int[] moduleBitCount)
		{
			int num = 0;
			foreach (int num2 in moduleBitCount)
			{
				num += num2;
			}
			return num;
		}

		public static int[] ToIntArray(IList<int?> list)
		{
			if (list == null || list.Count == 0)
			{
				return EMPTY_INT_ARRAY;
			}
			int[] array = new int[list.Count];
			int num = 0;
			foreach (int? item in list)
			{
				int value = item.Value;
				array[num++] = value;
			}
			return array;
		}

		public static int[] ToIntArray(IList<int> list)
		{
			if (list == null || list.Count == 0)
			{
				return EMPTY_INT_ARRAY;
			}
			int[] array = new int[list.Count];
			int num = 0;
			foreach (int item in list)
			{
				array[num++] = item;
			}
			return array;
		}

		public static int GetCodeword(long symbol)
		{
			int num = FindCodewordIndex(symbol & 0x3FFFF);
			if (num == -1)
			{
				return -1;
			}
			return (CODEWORD_TABLE[num] - 1) % 929;
		}

		private static int FindCodewordIndex(long symbol)
		{
			int num = 0;
			int num2 = SYMBOL_TABLE.Length;
			while (num < num2)
			{
				int num3 = num + num2 >>> 1;
				if (symbol < SYMBOL_TABLE[num3])
				{
					num2 = num3;
					continue;
				}
				if (symbol > SYMBOL_TABLE[num3])
				{
					num = num3 + 1;
					continue;
				}
				return num3;
			}
			return -1;
		}
	}
