	public sealed class Pdf417Encoder : IEncoder
	{
		private const int QUIET_ZONE_SIZE = 4;

		public BitMatrix Encode(string contents, BarcodeFormat format, int width, int height, Dictionary<EncodeOptions, object> encodingOptions)
		{
			if (format != BarcodeFormat.PDF417)
			{
				throw new ArgumentException("Can only encode PDF417, but got " + format);
			}
			MessagingToolkit.Barcode.Pdf417.Encoder.Pdf417 pdf = new MessagingToolkit.Barcode.Pdf417.Encoder.Pdf417();
			int quietZone = 4;
			if (encodingOptions != null)
			{
				if (encodingOptions.ContainsKey(EncodeOptions.Pdf417Compact))
				{
					object encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.Pdf417Compact);
					pdf.SetCompact((bool)encodeOptionType);
				}
				if (encodingOptions.ContainsKey(EncodeOptions.Pdf417Compaction))
				{
					object encodeOptionType2 = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.Pdf417Compaction);
					pdf.SetCompaction((Compaction)encodeOptionType2);
				}
				if (encodingOptions.ContainsKey(EncodeOptions.Pdf417Dimensions))
				{
					Dimensions dimensions = (Dimensions)BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.Pdf417Dimensions);
					pdf.SetDimensions(dimensions.MaxCols, dimensions.MinCols, dimensions.MaxRows, dimensions.MinRows);
				}
				if (encodingOptions.ContainsKey(EncodeOptions.Margin))
				{
					quietZone = Convert.ToInt32(BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.Margin));
				}
			}
			return BitMatrixFromEncoder(pdf, contents, width, height, quietZone);
		}

		public BitMatrix Encode(string contents, BarcodeFormat format, int width, int height)
		{
			return Encode(contents, format, width, height, null);
		}

		private static BitMatrix BitMatrixFromEncoder(MessagingToolkit.Barcode.Pdf417.Encoder.Pdf417 encoder, string contents, int width, int height, int quietZone)
		{
			int errorCorrectionLevel = 2;
			encoder.GenerateBarcodeLogic(contents, errorCorrectionLevel);
			int num = 2;
			int num2 = 4;
			byte[][] array = encoder.GetBarcodeMatrix().GetScaledMatrix(num, num2 * num);
			bool flag = false;
			if ((height > width) ^ (array[0].Length < array.Length))
			{
				array = RotateArray(array);
				flag = true;
			}
			int num3 = width / array[0].Length;
			int num4 = height / array.Length;
			int num5 = ((num3 >= num4) ? num4 : num3);
			if (num5 > 1)
			{
				byte[][] array2 = encoder.GetBarcodeMatrix().GetScaledMatrix(num5 * num, num5 * num2 * num);
				if (flag)
				{
					array2 = RotateArray(array2);
				}
				return RenderResult(new ByteMatrix(array2[0].Length, array2.Length, array2), contents, width, height, quietZone);
			}
			return RenderResult(new ByteMatrix(array[0].Length, array.Length, array), contents, width, height, quietZone);
		}

		private static BitMatrix RenderResult(ByteMatrix input, string contents, int width, int height, int quietZone)
		{
			int width2 = input.Width;
			int height2 = input.Height;
			int num = width2 + (quietZone << 1);
			int num2 = height2 + (quietZone << 1);
			int num3 = Math.Max(width, num);
			int num4 = Math.Max(height, num2);
			int num5 = Math.Min(num3 / num, num4 / num2);
			int num6 = (num3 - width2 * num5) / 2;
			int num7 = (num4 - height2 * num5) / 2;
			BitMatrix bitMatrix = new BitMatrix(num3, num4);
			bitMatrix.LeftPadding = num6;
			bitMatrix.TopPadding = num7;
			bitMatrix.ActualHeight = num5 * height2;
			bitMatrix.ActualWidth = num5 * width2;
			int num8 = 0;
			int num9 = num7;
			while (num8 < height2)
			{
				int num10 = 0;
				int num11 = num6;
				while (num10 < width2)
				{
					if (input.Get(num10, num8) == 1)
					{
						bitMatrix.SetRegion(num11, num9, num5, num5);
					}
					num10++;
					num11 += num5;
				}
				num8++;
				num9 += num5;
			}
			return bitMatrix;
		}

		private static byte[][] RotateArray(byte[][] bitarray)
		{
			byte[][] array = new byte[bitarray[0].Length][];
			for (int i = 0; i < bitarray[0].Length; i++)
			{
				array[i] = new byte[bitarray.Length];
			}
			for (int j = 0; j < bitarray.Length; j++)
			{
				int num = bitarray.Length - j - 1;
				for (int k = 0; k < bitarray[0].Length; k++)
				{
					array[k][num] = bitarray[j][k];
				}
			}
			return array;
		}
	}
	internal sealed class Pdf417Decoder : IDecoder, MultipleBarcodeDecoder
	{
		public Result Decode(BinaryBitmap image)
		{
			return Decode(image, null);
		}

		public Result Decode(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions)
		{
			Result[] array = Decode(image, decodingOptions, multiple: false);
			if (array == null || array.Length == 0 || array[0] == null)
			{
				throw NotFoundException.Instance;
			}
			return array[0];
		}

		public Result[] DecodeMultiple(BinaryBitmap image)
		{
			return DecodeMultiple(image, null);
		}

		public Result[] DecodeMultiple(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions)
		{
			try
			{
				return Decode(image, decodingOptions, multiple: true);
			}
			catch (FormatException)
			{
				throw NotFoundException.Instance;
			}
			catch (ChecksumException)
			{
				throw NotFoundException.Instance;
			}
		}

		private static Result[] Decode(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions, bool multiple)
		{
			List<Result> list = new List<Result>();
			Pdf417DetectorResult pdf417DetectorResult = MessagingToolkit.Barcode.Pdf417.Detector.Detector.Detect(image, decodingOptions, multiple);
			foreach (ResultPoint[] point in pdf417DetectorResult.Points)
			{
				DecoderResult decoderResult = Pdf417ScanningDecoder.Decode(pdf417DetectorResult.Bits, point[4], point[5], point[6], point[7], GetMinCodewordWidth(point), GetMaxCodewordWidth(point));
				if (decoderResult == null)
				{
					throw NotFoundException.Instance;
				}
				Result result = new Result(decoderResult.Text, decoderResult.RawBytes, point, BarcodeFormat.PDF417);
				result.PutMetadata(ResultMetadataType.ErrorCorrectionLevel, decoderResult.ECLevel);
				Pdf417ResultMetadata pdf417ResultMetadata = (Pdf417ResultMetadata)decoderResult.Other;
				if (pdf417ResultMetadata != null)
				{
					result.PutMetadata(ResultMetadataType.PDF417ExtraMetadata, pdf417ResultMetadata);
				}
				list.Add(result);
			}
			return list.ToArray();
		}

		private static int GetMaxWidth(ResultPoint p1, ResultPoint p2)
		{
			if (p1 == null || p2 == null)
			{
				return 0;
			}
			return (int)Math.Abs(p1.X - p2.X);
		}

		private static int GetMinWidth(ResultPoint p1, ResultPoint p2)
		{
			if (p1 == null || p2 == null)
			{
				return int.MaxValue;
			}
			return (int)Math.Abs(p1.X - p2.X);
		}

		private static int GetMaxCodewordWidth(ResultPoint[] p)
		{
			return Math.Max(Math.Max(GetMaxWidth(p[0], p[4]), GetMaxWidth(p[6], p[2]) * 17 / 18), Math.Max(GetMaxWidth(p[1], p[5]), GetMaxWidth(p[7], p[3]) * 17 / 18));
		}

		private static int GetMinCodewordWidth(ResultPoint[] p)
		{
			return Math.Min(Math.Min(GetMinWidth(p[0], p[4]), GetMinWidth(p[6], p[2]) * 17 / 18), Math.Min(GetMinWidth(p[1], p[5]), GetMinWidth(p[7], p[3]) * 17 / 18));
		}

		public void Reset()
		{
		}
	}
