namespace MessagingToolkit.Barcode.Pdf417.Encoder
{
	public sealed class BarcodeMatrix
	{
		private readonly BarcodeRow[] matrix;

		private int currentRow;

		private readonly int height;

		private readonly int width;

		public int Width => width;

		public int Height => height;

		internal BarcodeMatrix(int height, int width)
		{
			matrix = new BarcodeRow[height + 2];
			int i = 0;
			for (int num = matrix.Length; i < num; i++)
			{
				matrix[i] = new BarcodeRow((width + 4) * 17 + 1);
			}
			this.width = width * 17;
			this.height = height + 2;
			currentRow = 0;
		}

		internal void Set(int x, int y, byte val)
		{
			matrix[y].Set(x, val);
		}

		internal void SetMatrix(int x, int y, bool black)
		{
			Set(x, y, (byte)(black ? 1u : 0u));
		}

		internal void StartRow()
		{
			currentRow++;
		}

		internal BarcodeRow GetCurrentRow()
		{
			return matrix[currentRow];
		}

		public byte[][] GetMatrix()
		{
			return GetScaledMatrix(1, 1);
		}

		public byte[][] GetScaledMatrix(int scale)
		{
			return GetScaledMatrix(scale, scale);
		}

		public byte[][] GetScaledMatrix(int xScale, int yScale)
		{
			byte[][] array = new byte[height * yScale][];
			for (int i = 0; i < height * yScale; i++)
			{
				array[i] = new byte[width * xScale];
			}
			int num = height * yScale;
			for (int j = 0; j < num; j++)
			{
				array[num - j - 1] = matrix[j / yScale].GetScaledRow(xScale);
			}
			return array;
		}
	}
	internal sealed class BarcodeRow
	{
		private readonly byte[] row;

		private int currentLocation;

		internal BarcodeRow(int width)
		{
			row = new byte[width];
			currentLocation = 0;
		}

		internal void Set(int x, byte value)
		{
			row[x] = value;
		}

		internal void Set(int x, bool black)
		{
			row[x] = (byte)(black ? 1u : 0u);
		}

		internal void AddBar(bool black, int width)
		{
			for (int i = 0; i < width; i++)
			{
				Set(currentLocation++, black);
			}
		}

		internal byte[] GetRow()
		{
			return row;
		}

		internal byte[] GetScaledRow(int scale)
		{
			byte[] array = new byte[row.Length * scale];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = row[i / scale];
			}
			return array;
		}
	}
