		public const float PreferredRatio = 3f;

		private const float DefaultModuleWidth = 0.357f;

		private const float Height = 2f;

		private BarcodeMatrix barcodeMatrix;

		private bool compact;

		private Compaction compaction;

		private int minCols;

		private int maxCols;

		private int maxRows;

		private int minRows;

		public Pdf417()
			: this(compact: false)
		{
		}

		public Pdf417(bool compact)
		{
			this.compact = compact;
			compaction = Compaction.Auto;
			minCols = 2;
			maxCols = 30;
			maxRows = 30;
			minRows = 2;
		}

		public BarcodeMatrix GetBarcodeMatrix()
		{
			return barcodeMatrix;
		}

		private static int CalculateNumberOfRows(int m, int k, int c)
		{
			int num = (m + 1 + k) / c + 1;
			if (c * num >= m + 1 + k + c)
			{
				num--;
			}
			return num;
		}

		private static int GetNumberOfPadCodewords(int m, int k, int c, int r)
		{
			int num = c * r - k;
			if (num <= m + 1)
			{
				return 0;
			}
			return num - m - 1;
		}

		private static void EncodeChar(int pattern, int len, BarcodeRow logic)
		{
			int num = 1 << len - 1;
			bool flag = (pattern & num) != 0;
			int num2 = 0;
			for (int i = 0; i < len; i++)
			{
				bool flag2 = (pattern & num) != 0;
				if (flag == flag2)
				{
					num2++;
				}
				else
				{
					logic.AddBar(flag, num2);
					flag = flag2;
					num2 = 1;
				}
				num >>= 1;
			}
			logic.AddBar(flag, num2);
		}

		private void EncodeLowLevel(string fullCodewords, int c, int r, int errorCorrectionLevel, BarcodeMatrix logic)
		{
			int num = 0;
			for (int i = 0; i < r; i++)
			{
				int num2 = i % 3;
				logic.StartRow();
				EncodeChar(130728, 17, logic.GetCurrentRow());
				int num3;
				int num4;
				switch (num2)
				{
				case 0:
					num3 = 30 * (i / 3) + (r - 1) / 3;
					num4 = 30 * (i / 3) + (c - 1);
					break;
				case 1:
					num3 = 30 * (i / 3) + errorCorrectionLevel * 3 + (r - 1) % 3;
					num4 = 30 * (i / 3) + (r - 1) / 3;
					break;
				default:
					num3 = 30 * (i / 3) + (c - 1);
					num4 = 30 * (i / 3) + errorCorrectionLevel * 3 + (r - 1) % 3;
					break;
				}
				EncodeChar(CodeWordTable[num2][num3], 17, logic.GetCurrentRow());
				for (int j = 0; j < c; j++)
				{
					EncodeChar(CodeWordTable[num2][(uint)fullCodewords[num]], 17, logic.GetCurrentRow());
					num++;
				}
				if (compact)
				{
					EncodeChar(260649, 1, logic.GetCurrentRow());
					continue;
				}
				EncodeChar(CodeWordTable[num2][num4], 17, logic.GetCurrentRow());
				EncodeChar(260649, 18, logic.GetCurrentRow());
			}
		}

		public void GenerateBarcodeLogic(string msg, int errorCorrectionLevel)
		{
			int errorCorrectionCodewordCount = Pdf417ErrorCorrection.GetErrorCorrectionCodewordCount(errorCorrectionLevel);
			string text = Pdf417HighLevelEncoder.EncodeHighLevel(msg, compaction);
			int length = text.Length;
			int[] array = DetermineDimensions(length, errorCorrectionCodewordCount);
			int num = array[0];
			int num2 = array[1];
			int numberOfPadCodewords = GetNumberOfPadCodewords(length, errorCorrectionCodewordCount, num, num2);
			if (length + errorCorrectionCodewordCount + 1 > 929)
			{
				throw new BarcodeEncoderException("Encoded message contains to many code words, message to big (" + msg.Length + " bytes)");
			}
			int num3 = length + numberOfPadCodewords + 1;
			StringBuilder stringBuilder = new StringBuilder(num3);
			stringBuilder.Append((char)num3);
			stringBuilder.Append(text);
			for (int i = 0; i < numberOfPadCodewords; i++)
			{
				stringBuilder.Append('\u0384');
			}
			string text2 = stringBuilder.ToString();
			string text3 = Pdf417ErrorCorrection.GenerateErrorCorrection(text2, errorCorrectionLevel);
			string fullCodewords = text2 + text3;
			barcodeMatrix = new BarcodeMatrix(num2, num);
			EncodeLowLevel(fullCodewords, num, num2, errorCorrectionLevel, barcodeMatrix);
		}

		private int[] DetermineDimensions(int sourceCodeWords, int errorCorrectionCodeWords)
		{
			float num = 0f;
			int[] array = null;
			for (int i = minCols; i <= maxCols; i++)
			{
				int num2 = CalculateNumberOfRows(sourceCodeWords, errorCorrectionCodeWords, i);
				if (num2 < minRows)
				{
					break;
				}
				if (num2 <= maxRows)
				{
					float num3 = (float)(17 * i + 69) * 0.357f / ((float)num2 * 2f);
					if (array == null || !(Math.Abs(num3 - 3f) > Math.Abs(num - 3f)))
					{
						num = num3;
						array = new int[2] { i, num2 };
					}
				}
			}
			if (array == null && CalculateNumberOfRows(sourceCodeWords, errorCorrectionCodeWords, minCols) < minRows)
			{
				array = new int[2] { minCols, minRows };
			}
			if (array == null)
			{
				throw new BarcodeEncoderException("Unable to fit message in columns");
			}
			return array;
		}

		public void SetDimensions(int maxCols, int minCols, int maxRows, int minRows)
		{
			this.maxCols = maxCols;
			this.minCols = minCols;
			this.maxRows = maxRows;
			this.minRows = minRows;
		}

		public void SetCompaction(Compaction compaction)
		{
			this.compaction = compaction;
		}

		public void SetCompact(bool compact)
		{
			this.compact = compact;
		}
	}
