			129692, 129720, 129730, 129732, 129736, 129744, 129758, 129766, 129772, 129814,
			129830, 129836, 129850, 129862, 129868, 129880, 129902, 129906, 129908, 129930,
			129938, 129940, 129954, 129956, 129960, 129974, 130010
		};

		private int k0lc;

		private int k3lc;

		private int k6lc;

		private int numOfRows;

		private int errorCorrection;

		private int numOfColumns;

		private BitMatrix image;

		public Detector2(BitMatrix image)
		{
			this.image = image;
			numOfRows = 0;
			errorCorrection = 0;
			numOfColumns = 0;
		}

		public DecoderResult Detect()
		{
			k0lc = -1;
			k3lc = -1;
			k6lc = -1;
			bool flag = false;
			for (int i = 0; i < image.GetHeight(); i++)
			{
				Pdf417Line line = new Pdf417Line();
				ScanLineInitial(i, ref line);
				if (line.LeftColumnIndicator != null)
				{
					ExtractColumnIndicator(line.LeftColumnIndicator, left: true);
				}
				if (line.RightColumnIndicator != null)
				{
					ExtractColumnIndicator(line.RightColumnIndicator, left: false);
				}
				if (k0lc >= 0 && k3lc >= 0 && k6lc >= 0)
				{
					numOfRows = k0lc % 30 * 3 + k3lc % 3 + 1;
					errorCorrection = k3lc % 30 / 3;
					numOfColumns = k6lc % 30 + 1;
					flag = true;
					break;
				}
			}
			if (flag)
			{
				Pdf417Barcode barcode = new Pdf417Barcode(numOfRows, numOfColumns, errorCorrection);
				Scan(ref barcode);
				int num = (2 << errorCorrection + 1) - 3;
				if (barcode.GetErasures() <= num)
				{
					int[] codewords = barcode.GetCodewords();
					if (barcode.CorrectErrors(codewords))
					{
						string text = MessagingToolkit.Barcode.Pdf417.Decoder.DecodedBitStreamParser.Decode2(codewords);
						return new DecoderResult(new byte[1], text, null, null);
					}
					throw FormatException.Instance;
				}
				throw FormatException.Instance;
			}
			throw FormatException.Instance;
		}

		private bool ScanLineInitial(int y, ref Pdf417Line line)
		{
			int[] blocks = new int[image.Width];
			ScanBlocks(y, blocks);
			int where = 0;
			int num = -1;
			if ((num = FindStartStopPattern(blocks, ref where)) != -1)
			{
				switch (num)
				{
				case 1:
				{
					int K2 = 0;
					int codeword2 = 0;
					if (ReadSymbol(blocks, where + 8, ref K2, ref codeword2))
					{
						line.LeftColumnIndicator = new Pdf417Symbol(K2, codeword2);
						return true;
					}
					break;
				}
				case 2:
				{
					int K = 0;
					int codeword = 0;
					if (ReadSymbol(blocks, where - 8, ref K, ref codeword))
					{
						line.RightColumnIndicator = new Pdf417Symbol(K, codeword);
						return true;
					}
					break;
				}
				}
			}
			return false;
		}

		private void Scan(ref Pdf417Barcode barcode)
		{
			int width = image.Width;
			for (int i = 0; i < image.Height; i++)
			{
				int[] blocks = new int[width];
				ScanBlocks(i, blocks);
				int where = 0;
				int num = -1;
				if ((num = FindStartStopPattern(blocks, ref where)) == -1)
				{
					continue;
				}
				switch (num)
				{
				case 1:
				{
					int K3 = 0;
					int codeword3 = 0;
					if (!ReadSymbol(blocks, where + 8, ref K3, ref codeword3))
					{
						break;
					}
					int num12 = codeword3 / 30 * 3 + 1 + K3 / 3;
					int[] array3 = new int[barcode.GetColumns()];
					int[] array4 = new int[barcode.GetColumns()];
					for (int num13 = 0; num13 < barcode.GetColumns(); num13++)
					{
						array3[num13] = -1;
						array4[num13] = -1;
						ReadSymbol(blocks, where + 16 + num13 * 8, ref array4[num13], ref array3[num13]);
					}
					int K4 = 0;
					int codeword4 = 0;
					if (ReadSymbol(blocks, where + 16 + barcode.GetColumns() * 8, ref K4, ref codeword4))
					{
						int num14 = codeword4 / 30 * 3 + 1 + K4 / 3;
						if (num12 == num14)
						{
							for (int num15 = 0; num15 < barcode.GetColumns(); num15++)
							{
								if (array3[num15] >= 0)
								{
									barcode.Set(num15, num12 - 1, array3[num15]);
								}
							}
							break;
						}
						if (num14 - num12 > 0)
						{
							int num16 = num12;
							int num17 = K3;
							for (int num18 = 0; num18 < barcode.GetColumns(); num18++)
							{
								if (array4[num18] == num17)
								{
									barcode.Set(num18, num16 - 1, array3[num18]);
									continue;
								}
								num16 += GetLineDifference(num17, array4[num18]);
								num17 = array4[num18];
								barcode.Set(num18, num16 - 1, array3[num18]);
							}
						}
						if (num14 - num12 >= 0)
						{
							break;
						}
						int num19 = num12;
						int num20 = K3;
						for (int num21 = 0; num21 < barcode.GetColumns(); num21++)
						{
							if (array4[num21] == num20)
							{
								barcode.Set(num21, num19 - 1, array3[num21]);
								continue;
							}
							num19 -= GetLineDifference(array4[num21], num20);
							num20 = array4[num21];
							barcode.Set(num21, num19 - 1, array3[num21]);
						}
						break;
					}
					for (int num22 = 0; num22 < barcode.GetColumns(); num22++)
					{
						int num23 = num12;
						int num24 = K3;
						if (array4[num22] == num24)
						{
							barcode.SetGuess(num22, num23 - 1, array3[num22]);
							continue;
						}
						num23 += GetLineDifferenceSigned(num24, array4[num22]);
						num24 = array4[num22];
						barcode.SetGuess(num22, num23 - 1, array3[num22]);
					}
					break;
				}
				case 2:
				{
					int K = 0;
					int codeword = 0;
					if (!ReadSymbol(blocks, where - 8, ref K, ref codeword))
					{
						break;
					}
					int num2 = codeword / 30 * 3 + 1 + K / 3;
					int[] array = new int[barcode.GetColumns()];
					int[] array2 = new int[barcode.GetColumns()];
					for (int j = 0; j < barcode.GetColumns(); j++)
					{
						array[j] = -1;
						array2[j] = -1;
						int num3 = barcode.GetColumns() - j - 1;
						ReadSymbol(blocks, where - 16 - j * 8, ref array2[num3], ref array[num3]);
					}
					int K2 = 0;
					int codeword2 = 0;
					if (ReadSymbol(blocks, where - 16 - barcode.GetColumns() * 8, ref K2, ref codeword2))
					{
						int num4 = codeword2 / 30 * 3 + 1 + K2 / 3;
						if (num4 == num2)
						{
							for (int k = 0; k < barcode.GetColumns(); k++)
							{
								if (array[k] >= 0)
								{
									barcode.Set(k, num4 - 1, array[k]);
								}
							}
							break;
						}
						if (num2 - num4 > 0)
						{
							int num5 = num4;
							int num6 = K2;
							for (int l = 0; l < barcode.GetColumns(); l++)
							{
								if (array2[l] == num6)
								{
									barcode.Set(l, num5 - 1, array[l]);
									continue;
								}
								num5 += GetLineDifference(num6, array2[l]);
								num6 = array2[l];
								barcode.Set(l, num5 - 1, array[l]);
							}
						}
						if (num2 - num4 >= 0)
						{
							break;
						}
						int num7 = num4;
						int num8 = K2;
						for (int m = 0; m < barcode.GetColumns(); m++)
						{
							if (array2[m] == num8)
							{
								barcode.Set(m, num7 - 1, array[m]);
								continue;
							}
							num7 -= GetLineDifference(array2[m], num8);
							num8 = array2[m];
							barcode.Set(m, num7 - 1, array[m]);
						}
						break;
					}
					for (int n = 0; n < barcode.GetColumns(); n++)
					{
						int num9 = barcode.GetColumns() - n - 1;
						int num10 = num2;
						int num11 = K;
						if (array2[num9] == num11)
						{
							barcode.SetGuess(n, num10 - 1, array[num9]);
							continue;
						}
						num10 += GetLineDifferenceSigned(num11, array2[num9]);
						num11 = array2[num9];
						barcode.SetGuess(n, num10 - 1, array[num9]);
					}
					break;
				}
				}
			}
		}

		public int GetLineDifference(int k1, int k2)
		{
			int num = k2 - k1;
			if (num < 0)
			{
				num += 9;
			}
			return num / 3;
		}

		public int GetLineDifferenceSigned(int k1, int k2)
		{
			int num = k1 - k2;
			if (num < 0)
			{
				num += 9;
			}
			int num2 = num / 3;
			if (num2 == 2)
			{
				return -1;
			}
			return num2;
		}

		public void ScanBlocks(int y, int[] blocks)
		{
			for (int i = 0; i < image.GetWidth(); i++)
			{
				blocks[i] = 0;
			}
			int width = image.GetWidth();
			bool flag = false;
			int num = 0;
			int j;
			for (j = 0; !image.Get(j, y) && j < width; j++)
			{
			}
			for (int k = j; k < width; k++)
			{
				if (flag ^ image.Get(k, y))
				{
					blocks[num]++;
					continue;
				}
				num++;
				blocks[num] = 1;
				flag = !flag;
			}
		}

		public int FindStartStopPattern(int[] blocks, ref int where)
		{
			int width = image.GetWidth();
			int num = 0;
			int[] array = blocks;
			while (num + 8 < width && Pdf417Symbol.CheckPatternBlockLengths(array))
			{
				if (Pdf417Symbol.CheckPatternIsStartLocator(array))
				{
					where = num;
					return 1;
				}
				if (Pdf417Symbol.CheckPatternIsEndLocator(array))
				{
					where = num;
					return 2;
				}
				num++;
				array = new int[blocks.Length - num];
				for (int i = 0; i < array.Length; i++)
				{
					array[i] = blocks[i + num];
				}
			}
			return -1;
		}

		public bool ReadSymbol(int[] blocks, int from, ref int K, ref int codeword)
		{
			try
			{
				int width = image.Width;
				int[] array = new int[blocks.Length - from];
				for (int i = 0; i < array.Length; i++)
				{
					array[i] = blocks[i + from];
				}
				if (from + 8 < width && Pdf417Symbol.CheckPatternBlockLengths(array))
				{
					int[] edges = new int[6];
					if (Pdf417Symbol.GetPatternEdges(array, edges))
					{
						K = Pdf417Symbol.GetCluster(edges);
						if (K > -1)
						{
							codeword = FindCodewordByEdges(edges);
							if (codeword >= 0)
							{
								return true;
							}
						}
					}
				}
				return false;
			}
			catch (Exception)
			{
				return false;
			}
		}

		public void ExtractColumnIndicator(Pdf417Symbol symbol, bool left)
		{
			int k = symbol.K;
			if (k == -1)
			{
				return;
			}
			int codeword = symbol.codeword;
			if (codeword >= 0)
			{
				if ((left && k == 0) || (!left && k == 3))
				{
					k0lc = codeword;
				}
				else if ((left && k == 3) || (!left && k == 6))
				{
					k3lc = codeword;
				}
				else if ((left && k == 6) || (!left && k == 0))
				{
					k6lc = codeword;
				}
			}
		}

		private int FindCodewordByEdges(int[] edges)
		{
			string ed = string.Concat(edges[0], edges[1], edges[2], edges[3], edges[4], edges[5]);
			int num = FindCwIndexByEdgeDistance(ed);
			if (num >= 0)
			{
				return MessagingToolkit.Barcode.Pdf417.Decoder.BitMatrixParser.GetCodewordByIndex(num);
			}
			return -1;
		}

		private int FindCwIndexByEdgeDistance(string ed)
		{
			for (int i = 0; i < SYMBOL_TABLE.Length; i++)
			{
				if (EDGE_DISTANCE_TABLE[i].Equals(ed, StringComparison.OrdinalIgnoreCase))
				{
					return i;
				}
			}
			return -1;
		}

		public void ConvertSymbol(int pattern, int[] edges)
		{
			int num = 0;
			int num2 = 1;
			for (int i = 0; i < 8; i++)
			{
				edges[i] = 0;
			}
			for (int j = 0; j < 17; j++)
			{
				if ((((uint)pattern & (true ? 1u : 0u)) ^ (uint)num2) != 0)
				{
					edges[num]++;
					pattern >>= 1;
					continue;
				}
				num++;
				edges[num] = 1;
				pattern >>= 1;
				num2 = ((num2 != 1) ? 1 : 0);
			}
		}
	}
	public sealed class Detector
	{
		private static readonly int[] INDEXES_START_PATTERN = new int[4] { 0, 4, 1, 5 };

		private static readonly int[] INDEXES_STOP_PATTERN = new int[4] { 6, 2, 7, 3 };

		private const int INTEGER_MATH_SHIFT = 8;

		private static readonly int PATTERN_MATCH_RESULT_SCALE_FACTOR = 256;

		private static readonly int MAX_AVG_VARIANCE = (int)((float)PATTERN_MATCH_RESULT_SCALE_FACTOR * 0.42f);

		private static readonly int MAX_INDIVIDUAL_VARIANCE = (int)((float)PATTERN_MATCH_RESULT_SCALE_FACTOR * 0.8f);

		private static readonly int[] START_PATTERN = new int[8] { 8, 1, 1, 1, 1, 1, 1, 3 };

		private static readonly int[] STOP_PATTERN = new int[9] { 7, 1, 1, 3, 1, 1, 1, 2, 1 };

		private const int MAX_PIXEL_DRIFT = 3;

		private const int MAX_PATTERN_DRIFT = 5;

		private const int SKIPPED_ROW_COUNT_MAX = 25;

		private const int ROW_STEP = 5;

		private const int BARCODE_MIN_HEIGHT = 10;

		public static Pdf417DetectorResult Detect(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions, bool multiple)
		{
			BitMatrix blackMatrix = image.BlackMatrix;
			IList<ResultPoint[]> list = Detect(multiple, blackMatrix);
			if (list.Count == 0)
			{
				Rotate180(blackMatrix);
				list = Detect(multiple, blackMatrix);
			}
			return new Pdf417DetectorResult(blackMatrix, list);
		}

		private static IList<ResultPoint[]> Detect(bool multiple, BitMatrix bitMatrix)
		{
			IList<ResultPoint[]> list = new List<ResultPoint[]>();
			int num = 0;
			int startColumn = 0;
			bool flag = false;
			while (num < bitMatrix.Height)
			{
				ResultPoint[] array = FindVertices(bitMatrix, num, startColumn);
				if (array[0] == null && array[3] == null)
				{
					if (!flag)
					{
						break;
					}
					flag = false;
					startColumn = 0;
					foreach (ResultPoint[] item in list)
					{
						if (item[1] != null)
						{
							num = (int)Math.Max(num, item[1].Y);
						}
						if (item[3] != null)
						{
							num = Math.Max(num, (int)item[3].Y);
						}
					}
					num += 5;
				}
				else
				{
					flag = true;
					list.Add(array);
					if (!multiple)
					{
						break;
					}
					if (array[2] != null)
					{
						startColumn = (int)array[2].X;
						num = (int)array[2].Y;
					}
					else
					{
						startColumn = (int)array[4].X;
						num = (int)array[4].Y;
					}
				}
			}
			return list;
		}

		internal static void Rotate180(BitMatrix bitMatrix)
		{
			int width = bitMatrix.Width;
			int height = bitMatrix.Height;
			MessagingToolkit.Barcode.Common.BitArray bitArray = new MessagingToolkit.Barcode.Common.BitArray(width);
			MessagingToolkit.Barcode.Common.BitArray row = new MessagingToolkit.Barcode.Common.BitArray(width);
			MessagingToolkit.Barcode.Common.BitArray result = new MessagingToolkit.Barcode.Common.BitArray(width);
			for (int i = 0; i < height + 1 >> 1; i++)
			{
				bitArray = bitMatrix.GetRow(i, bitArray);
				bitMatrix.SetRow(i, Mirror(bitMatrix.GetRow(height - 1 - i, row), result));
				bitMatrix.SetRow(height - 1 - i, Mirror(bitArray, result));
			}
		}

		internal static MessagingToolkit.Barcode.Common.BitArray Mirror(MessagingToolkit.Barcode.Common.BitArray input, MessagingToolkit.Barcode.Common.BitArray result)
		{
			result.Clear();
			int size = input.Size;
			for (int i = 0; i < size; i++)
			{
				if (input.Get(i))
				{
					result.Set(size - 1 - i);
				}
			}
			return result;
		}

		private static ResultPoint[] FindVertices(BitMatrix matrix, int startRow, int startColumn)
		{
			int height = matrix.Height;
			int width = matrix.Width;
			ResultPoint[] array = new ResultPoint[8];
			CopyToResult(array, FindRowsWithPattern(matrix, height, width, startRow, startColumn, START_PATTERN), INDEXES_START_PATTERN);
			if (array[4] != null)
			{
				startColumn = (int)array[4].X;
				startRow = (int)array[4].Y;
			}
			CopyToResult(array, FindRowsWithPattern(matrix, height, width, startRow, startColumn, STOP_PATTERN), INDEXES_STOP_PATTERN);
			return array;
		}

		private static void CopyToResult(ResultPoint[] result, ResultPoint[] tmpResult, int[] destinationIndexes)
		{
			for (int i = 0; i < destinationIndexes.Length; i++)
			{
				result[destinationIndexes[i]] = tmpResult[i];
			}
		}

		private static ResultPoint[] FindRowsWithPattern(BitMatrix matrix, int height, int width, int startRow, int startColumn, int[] pattern)
		{
			ResultPoint[] array = new ResultPoint[4];
			bool flag = false;
			int[] counters = new int[pattern.Length];
			while (startRow < height)
			{
				int[] array2 = FindGuardPattern(matrix, startColumn, startRow, width, whiteFirst: false, pattern, counters);
				if (array2 != null)
				{
					while (startRow > 0)
					{
						int[] array3 = FindGuardPattern(matrix, startColumn, --startRow, width, whiteFirst: false, pattern, counters);
						if (array3 != null)
						{
							array2 = array3;
							continue;
						}
						startRow++;
						break;
					}
					array[0] = new ResultPoint(array2[0], startRow);
					array[1] = new ResultPoint(array2[1], startRow);
					flag = true;
					break;
				}
				startRow += 5;
			}
			int i = startRow + 1;
			if (flag)
			{
				int num = 0;
				int[] array4 = new int[2]
				{
					(int)array[0].X,
					(int)array[1].X
				};
				for (; i < height; i++)
				{
					int[] array5 = FindGuardPattern(matrix, array4[0], i, width, whiteFirst: false, pattern, counters);
					if (array5 != null && Math.Abs(array4[0] - array5[0]) < 5 && Math.Abs(array4[1] - array5[1]) < 5)
					{
						array4 = array5;
						num = 0;
						continue;
					}
					if (num > 25)
					{
						break;
					}
					num++;
				}
				i -= num + 1;
				array[2] = new ResultPoint(array4[0], i);
				array[3] = new ResultPoint(array4[1], i);
			}
			if (i - startRow < 10)
			{
				for (int j = 0; j < array.Length; j++)
				{
					array[j] = null;
				}
			}
			return array;
		}

		private static int[] FindGuardPattern(BitMatrix matrix, int column, int row, int width, bool whiteFirst, int[] pattern, int[] counters)
		{
			for (int i = 0; i < counters.Length; i++)
			{
				counters[i] = 0;
			}
			int num = pattern.Length;
			bool flag = whiteFirst;
			int num2 = column;
			int num3 = 0;
			while (matrix.Get(num2, row) && num2 > 0 && num3++ < 3)
			{
				num2--;
			}
			int j = num2;
			int num4 = 0;
			for (; j < width; j++)
			{
				if (matrix.Get(j, row) ^ flag)
				{
					counters[num4]++;
					continue;
				}
				if (num4 == num - 1)
				{
					if (PatternMatchVariance(counters, pattern, MAX_INDIVIDUAL_VARIANCE) < MAX_AVG_VARIANCE)
					{
						return new int[2] { num2, j };
					}
					num2 += counters[0] + counters[1];
					Array.Copy(counters, 2, counters, 0, num - 2);
					counters[num - 2] = 0;
					counters[num - 1] = 0;
					num4--;
				}
				else
				{
					num4++;
				}
				counters[num4] = 1;
				flag = !flag;
			}
			if (num4 == num - 1 && PatternMatchVariance(counters, pattern, MAX_INDIVIDUAL_VARIANCE) < MAX_AVG_VARIANCE)
			{
				return new int[2]
				{
					num2,
					j - 1
				};
			}
			return null;
		}

		private static int PatternMatchVariance(int[] counters, int[] pattern, int maxIndividualVariance)
		{
			int num = counters.Length;
			int num2 = 0;
			int num3 = 0;
			for (int i = 0; i < num; i++)
			{
				num2 += counters[i];
				num3 += pattern[i];
			}
			if (num2 < num3)
			{
				return int.MaxValue;
			}
			int num4 = (num2 << 8) / num3;
			maxIndividualVariance = maxIndividualVariance * num4 >> 8;
			int num5 = 0;
			for (int j = 0; j < num; j++)
			{
				int num6 = counters[j] << 8;
				int num7 = pattern[j] * num4;
				int num8 = ((num6 > num7) ? (num6 - num7) : (num7 - num6));
				if (num8 > maxIndividualVariance)
				{
					return int.MaxValue;
				}
				num5 += num8;
			}
			return num5 / num2;
		}
	}
	public sealed class Pdf417Barcode
	{
		private int[][] matrix;

		private int rows;

		private int columns;

		private int ecLevel;

		private int erasures;

		public Pdf417Barcode(int r, int c, int ec)
		{
			rows = r;
			columns = c;
			ecLevel = ec;
			matrix = new int[columns][];
			for (int i = 0; i < columns; i++)
			{
				matrix[i] = new int[rows];
			}
			for (int j = 0; j < columns; j++)
			{
				for (int k = 0; k < rows; k++)
				{
					matrix[j][k] = -1;
				}
			}
			erasures = rows * columns;
		}

		public void Set(int x, int y, int codeword)
		{
			if (x >= 0 && x < columns && y >= 0 && y < rows && codeword >= 0)
			{
				if (matrix[x][y] == -1)
				{
					erasures--;
				}
				matrix[x][y] = codeword;
			}
		}

		public void SetGuess(int x, int y, int codeword)
		{
			if (x >= 0 && x < columns && y >= 0 && y < rows && codeword >= 0 && matrix[x][y] == -1)
			{
				matrix[x][y] = codeword;
				erasures--;
			}
		}

		public int Get(int x, int y)
		{
			return matrix[x][y];
		}

		public int GetRows()
		{
			return rows;
		}

		public int GetColumns()
		{
			return columns;
		}

		public int GetECLevel()
		{
			return ecLevel;
		}

		public int GetErasures()
		{
			return erasures;
		}

		public int[] GetCodewords()
		{
			int[] array = new int[rows * columns];
			for (int i = 0; i < rows; i++)
			{
				for (int j = 0; j < columns; j++)
				{
					int num = i * columns + j;
					if (matrix[j][i] != -1)
					{
						array[num] = matrix[j][i];
					}
					else
					{
						array[num] = 0;
					}
				}
			}
			return array;
		}

		public bool CorrectErrors(int[] codewords)
		{
			int num = 2 << ecLevel + 1;
			if (codewords.Length < 4)
			{
				throw ChecksumException.Instance;
			}
			int num2 = codewords[0];
			if (num2 > codewords.Count() || num2 < 0)
			{
				throw ChecksumException.Instance;
			}
			if (num2 == 0)
			{
				if (num >= codewords.Count())
				{
					throw ChecksumException.Instance;
				}
				codewords[0] = codewords.Count() - num;
			}
			int num3 = new Pdf417RsDecoder().CorrectErrors(codewords, null, 0, rows * columns, rows * columns - codewords[0]);
			if (num3 < 0)
			{
				return false;
			}
			_ = 0;
			return true;
		}
	}
