	internal sealed class BoundingBox
	{
		private BitMatrix image;

		private ResultPoint topLeft;

		private ResultPoint bottomLeft;

		private ResultPoint topRight;

		private ResultPoint bottomRight;

		private int minX;

		private int maxX;

		private int minY;

		private int maxY;

		internal ResultPoint TopRight
		{
			get
			{
				return topRight;
			}
			set
			{
				topRight = value;
				CalculateMinMaxValues();
			}
		}

		internal ResultPoint BottomRight
		{
			get
			{
				return bottomRight;
			}
			set
			{
				bottomRight = value;
				CalculateMinMaxValues();
			}
		}

		internal int MinX => minX;

		internal int MaxX => maxX;

		internal int MinY => minY;

		internal int MaxY => maxY;

		internal ResultPoint TopLeft => topLeft;

		internal ResultPoint BottomLeft => bottomLeft;

		internal BoundingBox(BitMatrix image, ResultPoint topLeft, ResultPoint bottomLeft, ResultPoint topRight, ResultPoint bottomRight)
		{
			if ((topLeft == null && topRight == null) || (bottomLeft == null && bottomRight == null) || (topLeft != null && bottomLeft == null) || (topRight != null && bottomRight == null))
			{
				throw NotFoundException.Instance;
			}
			Init(image, topLeft, bottomLeft, topRight, bottomRight);
		}

		internal BoundingBox(BoundingBox boundingBox)
		{
			Init(boundingBox.image, boundingBox.topLeft, boundingBox.bottomLeft, boundingBox.topRight, boundingBox.bottomRight);
		}

		private void Init(BitMatrix image, ResultPoint topLeft, ResultPoint bottomLeft, ResultPoint topRight, ResultPoint bottomRight)
		{
			this.image = image;
			this.topLeft = topLeft;
			this.bottomLeft = bottomLeft;
			this.topRight = topRight;
			this.bottomRight = bottomRight;
			CalculateMinMaxValues();
		}

		internal static BoundingBox Merge(BoundingBox leftBox, BoundingBox rightBox)
		{
			if (leftBox == null)
			{
				return rightBox;
			}
			if (rightBox == null)
			{
				return leftBox;
			}
			return new BoundingBox(leftBox.image, leftBox.topLeft, leftBox.bottomLeft, rightBox.topRight, rightBox.bottomRight);
		}

		internal BoundingBox AddMissingRows(int missingStartRows, int missingEndRows, bool isLeft)
		{
			ResultPoint resultPoint = topLeft;
			ResultPoint resultPoint2 = bottomLeft;
			ResultPoint resultPoint3 = topRight;
			ResultPoint resultPoint4 = bottomRight;
			if (missingStartRows > 0)
			{
				ResultPoint obj = (isLeft ? topLeft : topRight);
				int num = (int)obj.Y - missingStartRows;
				if (num < 0)
				{
					num = 0;
				}
				ResultPoint resultPoint5 = new ResultPoint(obj.X, num);
				if (isLeft)
				{
					resultPoint = resultPoint5;
				}
				else
				{
					resultPoint3 = resultPoint5;
				}
			}
			if (missingEndRows > 0)
			{
				ResultPoint obj2 = (isLeft ? bottomLeft : bottomRight);
				int num2 = (int)obj2.Y + missingEndRows;
				if (num2 >= image.Height)
				{
					num2 = image.Height - 1;
				}
				ResultPoint resultPoint6 = new ResultPoint(obj2.X, num2);
				if (isLeft)
				{
					resultPoint2 = resultPoint6;
				}
				else
				{
					resultPoint4 = resultPoint6;
				}
			}
			CalculateMinMaxValues();
			return new BoundingBox(image, resultPoint, resultPoint2, resultPoint3, resultPoint4);
		}

		private void CalculateMinMaxValues()
		{
			if (topLeft == null)
			{
				topLeft = new ResultPoint(0f, topRight.Y);
				bottomLeft = new ResultPoint(0f, bottomRight.Y);
			}
			else if (topRight == null)
			{
				topRight = new ResultPoint(image.Width - 1, topLeft.Y);
				bottomRight = new ResultPoint(image.Width - 1, bottomLeft.Y);
			}
			minX = (int)Math.Min(topLeft.X, bottomLeft.X);
			maxX = (int)Math.Max(topRight.X, bottomRight.X);
			minY = (int)Math.Min(topLeft.Y, topRight.Y);
			maxY = (int)Math.Max(bottomLeft.Y, bottomRight.Y);
		}
	}
	internal sealed class Codeword
