			}
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < detectionResultColumn.Codewords.Length; i++)
			{
				stringBuilder.Append(string.Format("CW %3d:", i));
				for (int j = 0; j < barcodeColumnCount + 2; j++)
				{
					if (detectionResultColumns[j] == null)
					{
						stringBuilder.Append("    |   ");
						continue;
					}
					Codeword codeword = detectionResultColumns[j].Codewords[i];
					if (codeword == null)
					{
						stringBuilder.Append("    |   ");
					}
					else
					{
						stringBuilder.Append(string.Format(" %3d|%3d", codeword.RowNumber, codeword.Value));
