	internal sealed class Pdf417CodewordDecoder
	{
		private static readonly float[][] RATIOS_TABLE;

		static Pdf417CodewordDecoder()
		{
			RATIOS_TABLE = BarcodeHelper.CreateRectangularFloatArray(Pdf417Common.SYMBOL_TABLE.Length, 8);
			for (int i = 0; i < Pdf417Common.SYMBOL_TABLE.Length; i++)
			{
				int num = Pdf417Common.SYMBOL_TABLE[i];
				int num2 = num & 1;
				for (int j = 0; j < 8; j++)
				{
					float num3 = 0f;
					while ((num & 1) == num2)
					{
						num3 += 1f;
						num >>= 1;
					}
					num2 = num & 1;
					RATIOS_TABLE[i][8 - j - 1] = num3 / 17f;
				}
			}
		}

		private Pdf417CodewordDecoder()
		{
		}

		internal static int GetDecodedValue(int[] moduleBitCount)
		{
			int decodedCodewordValue = GetDecodedCodewordValue(SampleBitCounts(moduleBitCount));
			if (decodedCodewordValue != -1)
			{
				return decodedCodewordValue;
			}
			return GetClosestDecodedValue(moduleBitCount);
		}

		private static int[] SampleBitCounts(int[] moduleBitCount)
		{
			float num = Pdf417Common.GetBitCountSum(moduleBitCount);
			int[] array = new int[8];
			int num2 = 0;
			int num3 = 0;
			for (int i = 0; i < 17; i++)
			{
				float num4 = num / 34f + (float)i * num / 17f;
				if ((float)(num3 + moduleBitCount[num2]) <= num4)
				{
					num3 += moduleBitCount[num2];
					num2++;
				}
				array[num2]++;
			}
			return array;
		}

		private static int GetDecodedCodewordValue(int[] moduleBitCount)
		{
			int bitValue = GetBitValue(moduleBitCount);
			if (Pdf417Common.GetCodeword(bitValue) != -1)
			{
				return bitValue;
			}
			return -1;
		}

		private static int GetBitValue(int[] moduleBitCount)
		{
			long num = 0L;
			for (int i = 0; i < moduleBitCount.Length; i++)
			{
				for (int j = 0; j < moduleBitCount[i]; j++)
				{
					num = (num << 1) | ((i % 2 == 0) ? 1 : 0);
				}
			}
			return (int)num;
		}

		private static int GetClosestDecodedValue(int[] moduleBitCount)
		{
			int bitCountSum = Pdf417Common.GetBitCountSum(moduleBitCount);
			float[] array = new float[8];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = (float)moduleBitCount[i] / (float)bitCountSum;
			}
			float num = float.MaxValue;
			int result = -1;
			for (int j = 0; j < RATIOS_TABLE.Length; j++)
			{
				float num2 = 0f;
				for (int k = 0; k < 8; k++)
				{
					float num3 = RATIOS_TABLE[j][k] - array[k];
					num2 += num3 * num3;
				}
				if (num2 < num)
				{
					num = num2;
					result = Pdf417Common.SYMBOL_TABLE[j];
				}
			}
			return result;
		}
	}
