			if (rightRowIndicatorColumn == null || rightRowIndicatorColumn.BarcodeMetadata == null)
			{
				return leftRowIndicatorColumn?.BarcodeMetadata;
			}
			BarcodeMetadata barcodeMetadata = leftRowIndicatorColumn.BarcodeMetadata;
			BarcodeMetadata barcodeMetadata2 = rightRowIndicatorColumn.BarcodeMetadata;
			if (barcodeMetadata.ColumnCount != barcodeMetadata2.ColumnCount && barcodeMetadata.ErrorCorrectionLevel != barcodeMetadata2.ErrorCorrectionLevel && barcodeMetadata.RowCount != barcodeMetadata2.RowCount)
			{
