			int[] array2 = new int[detectionResult.BarcodeRowCount * detectionResult.BarcodeColumnCount];
			IList<int[]> list2 = new List<int[]>();
			IList<int?> list3 = new List<int?>();
			for (int i = 0; i < detectionResult.BarcodeRowCount; i++)
			{
				for (int j = 0; j < detectionResult.BarcodeColumnCount; j++)
				{
					int[] value = array[i][j + 1].GetValue();
					int num = i * detectionResult.BarcodeColumnCount + j;
					if (value.Length == 0)
					{
						list.Add(num);
						continue;
					}
					if (value.Length == 1)
					{
						array2[num] = value[0];
						continue;
					}
					list3.Add(num);
					list2.Add(value);
				}
			}
			int[][] array3 = new int[list2.Count][];
			for (int k = 0; k < array3.Length; k++)
