				AlphaTo[i] = num;
				if (num < GPRIME && i != GPRIME - 1)
				{
					IndexOf[num] = i;
				}
				num = num * 3 % GPRIME;
			}
			IndexOf[0] = GPRIME - 1;
			AlphaTo[GPRIME - 1] = 1;
			IndexOf[GPRIME] = A0;
		}

		private int Modbase(int x)
		{
