	public sealed class Pdf417Symbol
	{
		public int K;

		public int codeword;

		public Pdf417Symbol()
		{
			K = -1;
			codeword = -1;
		}

		public Pdf417Symbol(int k, int cw)
		{
			K = k;
			codeword = cw;
		}

		public static bool GetPatternEdges(int[] pattern, int[] edges)
		{
			int num = 0;
			for (int i = 0; i < 8; i++)
			{
				num += pattern[i];
			}
			int num2 = Convert.ToInt32(Math.Round((float)(pattern[0] + pattern[1]) * (17f / (float)num)));
			int num3 = Convert.ToInt32(Math.Round((float)(pattern[1] + pattern[2]) * (17f / (float)num)));
			int num4 = Convert.ToInt32(Math.Round((float)(pattern[2] + pattern[3]) * (17f / (float)num)));
			int num5 = Convert.ToInt32(Math.Round((float)(pattern[3] + pattern[4]) * (17f / (float)num)));
			int num6 = Convert.ToInt32(Math.Round((float)(pattern[4] + pattern[5]) * (17f / (float)num)));
			int num7 = Convert.ToInt32(Math.Round((float)(pattern[5] + pattern[6]) * (17f / (float)num)));
			if (num2 < 2 || num2 > 9 || num3 < 2 || num3 > 9 || num4 < 2 || num4 > 9 || num5 < 2 || num5 > 9 || num6 < 2 || num6 > 9 || num7 < 2 || num7 > 9)
			{
				return false;
			}
			edges[0] = num2;
			edges[1] = num3;
			edges[2] = num4;
			edges[3] = num5;
			edges[4] = num6;
			edges[5] = num7;
			return true;
		}

		public static bool CheckPatternIsStartLocator(int[] pattern)
		{
			int[] array = new int[6];
			if (GetPatternEdges(pattern, array))
			{
				if (array[0] == 9 && array[1] == 2 && array[2] == 2 && array[3] == 2 && array[4] == 2)
				{
					return array[5] == 2;
				}
				return false;
			}
			return false;
		}

		public static bool CheckPatternIsEndLocator(int[] pattern)
		{
			int[] array = new int[6];
			if (GetPatternEdges(pattern, array))
			{
				if (array[0] == 8 && array[1] == 2 && array[2] == 4 && array[3] == 4 && array[4] == 2)
				{
					return array[5] == 2;
				}
				return false;
			}
			return false;
		}

		public static int GetPatternSizeInPixels(int[] pattern)
		{
			int num = 0;
			for (int i = 0; i < 8; i++)
			{
				num += pattern[i];
			}
			return num;
		}

		public static bool CheckPatternBlockLengths(int[] pattern)
		{
			for (int i = 0; i < 8; i++)
			{
				if (pattern[i] <= 0)
				{
					return false;
				}
			}
			return true;
		}

		public static int GetCluster(int[] edges)
		{
			int num = (edges[0] - edges[1] + edges[4] - edges[5] + 9) % 9;
			if (num != 3 && num != 0 && num != 6)
			{
				num = -1;
			}
			return num;
		}
	}
