namespace MessagingToolkit.Barcode.OneD
{
	public sealed class MsiDecoder : OneDDecoder
	{
		internal static string AlphabetString = "0123456789";

		private static readonly char[] Alphabet = AlphabetString.ToCharArray();

		internal static int[] CharacterEncodings = new int[10] { 2340, 2342, 2356, 2358, 2468, 2470, 2484, 2486, 3364, 3366 };

		private const int StartEncoding = 6;

		private const int EndEncoding = 9;

		private readonly bool usingCheckDigit;

		private readonly StringBuilder decodeRowResult;

		private readonly int[] counters;

		private int averageCounterWidth;

		private static readonly int[] DoubleAndCrossSum = new int[10] { 0, 2, 4, 6, 8, 1, 3, 5, 7, 9 };

		public MsiDecoder()
			: this(usingCheckDigit: false)
		{
		}

		public MsiDecoder(bool usingCheckDigit)
		{
			this.usingCheckDigit = usingCheckDigit;
			decodeRowResult = new StringBuilder(20);
			counters = new int[8];
		}

		public override Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, Dictionary<DecodeOptions, object> decodingOptions)
		{
			for (int i = 0; i < counters.Length; i++)
			{
				counters[i] = 0;
			}
			decodeRowResult.Length = 0;
			int[] array = FindStartPattern(row, counters);
			if (array == null)
			{
				throw NotFoundException.Instance;
			}
			int num = row.GetNextSet(array[1]);
			int num2 = num;
			char c;
			do
			{
				try
				{
					OneDDecoder.RecordPattern(row, num, counters);
				}
				catch
				{
					int[] array2 = FindEndPattern(row, num, counters);
					if (array2 == null)
					{
						throw NotFoundException.Instance;
					}
					num2 = num;
					num = array2[1];
					break;
				}
				if (!PatternToChar(ToPattern(counters, 8), out c))
				{
					int[] array3 = FindEndPattern(row, num, counters);
					if (array3 == null)
					{
						throw NotFoundException.Instance;
					}
					num2 = num;
					num = array3[1];
					break;
				}
				decodeRowResult.Append(c);
				num2 = num;
				int[] array4 = counters;
				foreach (int num3 in array4)
				{
					num += num3;
				}
				num = row.GetNextSet(num);
			}
			while (c != '*');
			if (decodeRowResult.Length < 3)
			{
				throw NotFoundException.Instance;
			}
			byte[] bytes = Encoding.UTF8.GetBytes(decodeRowResult.ToString());
			string text = decodeRowResult.ToString();
			if (usingCheckDigit)
			{
				string text2 = text.Substring(0, text.Length - 1);
				if ((ushort)(CalculateChecksumLuhn(text2) + 48) != text[text2.Length])
				{
					throw ChecksumException.Instance;
				}
			}
			float x = (float)(array[1] + array[0]) / 2f;
			float x2 = (float)(num + num2) / 2f;
			ResultPointCallback resultPointCallback = ((decodingOptions == null || !decodingOptions.ContainsKey(DecodeOptions.NeedResultPointCallback)) ? null : ((ResultPointCallback)decodingOptions[DecodeOptions.NeedResultPointCallback]));
			if (resultPointCallback != null)
			{
				resultPointCallback.FoundPossibleResultPoint(new ResultPoint(x, rowNumber));
				resultPointCallback.FoundPossibleResultPoint(new ResultPoint(x2, rowNumber));
			}
			return new Result(text, bytes, new ResultPoint[2]
			{
				new ResultPoint(x, rowNumber),
				new ResultPoint(x2, rowNumber)
			}, BarcodeFormat.MSIMod10);
		}

		private int[] FindStartPattern(MessagingToolkit.Barcode.Common.BitArray row, int[] counters)
		{
			int size = row.Size;
			int nextSet = row.GetNextSet(0);
			int num = 0;
			int num2 = nextSet;
			bool flag = false;
			counters[0] = 0;
			counters[1] = 0;
			for (int i = nextSet; i < size; i++)
			{
				if (row.Get(i) ^ flag)
				{
					counters[num]++;
					continue;
				}
				if (num == 1)
				{
					float num3 = (float)counters[0] / (float)counters[1];
					if ((double)num3 >= 1.5 && num3 <= 5f)
					{
						CalculateAverageCounterWidth(counters, 2);
						if (ToPattern(counters, 2) == 6 && row.IsRange(Math.Max(0, num2 - (i - num2 >> 1)), num2, val: false))
						{
							return new int[2] { num2, i };
						}
					}
					num2 += counters[0] + counters[1];
					Array.Copy(counters, 2, counters, 0, 0);
					counters[0] = 0;
					counters[1] = 0;
					num--;
				}
				else
				{
					num++;
				}
				counters[num] = 1;
				flag = !flag;
			}
			return null;
		}

		private int[] FindEndPattern(MessagingToolkit.Barcode.Common.BitArray row, int rowOffset, int[] counters)
		{
			int size = row.Size;
			int num = 0;
			bool flag = false;
			counters[0] = 0;
			counters[1] = 0;
			counters[2] = 0;
			for (int i = rowOffset; i < size; i++)
			{
				if (row.Get(i) ^ flag)
				{
					counters[num]++;
					continue;
				}
				if (num == 2)
				{
					float num2 = (float)counters[1] / (float)counters[0];
					if ((double)num2 >= 1.5 && num2 <= 5f && ToPattern(counters, 3) == 9)
					{
						int end = Math.Min(row.Size - 1, i + (i - rowOffset >> 1));
						if (row.IsRange(i, end, val: false))
						{
							return new int[2] { rowOffset, i };
						}
					}
					return null;
				}
				num++;
				counters[num] = 1;
				flag = !flag;
			}
			return null;
		}

		private void CalculateAverageCounterWidth(int[] counters, int patternLength)
		{
			int num = int.MaxValue;
			int num2 = 0;
			for (int i = 0; i < patternLength; i++)
			{
				int num3 = counters[i];
				if (num3 < num)
				{
					num = num3;
				}
				if (num3 > num2)
				{
					num2 = num3;
				}
			}
			averageCounterWidth = ((num2 << 8) + (num << 8)) / 2;
		}

		private int ToPattern(int[] counters, int patternLength)
		{
			int num = 0;
			int num2 = 1;
			int num3 = 3;
			for (int i = 0; i < patternLength; i++)
			{
				num = ((counters[i] << 8 >= averageCounterWidth) ? ((num << 2) | num3) : ((num << 1) | num2));
				num2 ^= 1;
				num3 ^= 3;
			}
			return num;
		}

		private static bool PatternToChar(int pattern, out char c)
		{
			for (int i = 0; i < CharacterEncodings.Length; i++)
			{
				if (CharacterEncodings[i] == pattern)
				{
					c = Alphabet[i];
					return true;
				}
			}
			c = '*';
			return false;
		}

		private static int CalculateChecksumLuhn(string number)
		{
			int num = 0;
			for (int num2 = number.Length - 2; num2 >= 0; num2 -= 2)
			{
				int num3 = number[num2] - 48;
				num += num3;
			}
			for (int num4 = number.Length - 1; num4 >= 0; num4 -= 2)
			{
				int num5 = DoubleAndCrossSum[number[num4] - 48];
				num += num5;
			}
			return (10 - num % 10) % 10;
		}
