				{
					int num6 = (num5 & 1) + (num4 & 1) * 2;
					array[num6] += counters[num2 + num5];
					array2[num6]++;
					num4 >>= 1;
				}
				if (num3 >= num)
				{
					break;
				}
				num2 += 8;
				num3++;
			}
			int[] array3 = new int[4];
			int[] array4 = new int[4];
			for (int i = 0; i < 2; i++)
			{
				array4[i] = 0;
				array4[i + 2] = (array[i] << 8) / array2[i] + (array[i + 2] << 8) / array2[i + 2] >> 1;
				array3[i] = array4[i + 2];
				array3[i + 2] = (array[i + 2] * 512 + 384) / array2[i + 2];
			}
			num2 = start;
			int num7 = 0;
			while (true)
			{
