					if (array[i] == key)
					{
						return true;
					}
				}
			}
			return false;
		}

		private int ToNarrowWidePattern(int position)
		{
			int num = position + 7;
			if (num >= counterLength)
			{
				return -1;
			}
			int[] array = counters;
			int num2 = 0;
			int num3 = int.MaxValue;
			for (int i = position; i < num; i += 2)
			{
				int num4 = array[i];
				if (num4 < num3)
				{
					num3 = num4;
				}
				if (num4 > num2)
				{
					num2 = num4;
				}
			}
			int num5 = (num3 + num2) / 2;
			int num6 = 0;
			int num7 = int.MaxValue;
			for (int j = position + 1; j < num; j += 2)
			{
				int num8 = array[j];
				if (num8 < num7)
				{
					num7 = num8;
				}
				if (num8 > num6)
				{
					num6 = num8;
				}
			}
			int num9 = (num7 + num6) / 2;
			int num10 = 128;
			int num11 = 0;
			for (int k = 0; k < 7; k++)
			{
				int num12 = (((k & 1) == 0) ? num5 : num9);
				num10 >>= 1;
				if (array[position + k] > num12)
				{
					num11 |= num10;
				}
			}
			for (int l = 0; l < CHARACTER_ENCODINGS.Length; l++)
			{
				if (CHARACTER_ENCODINGS[l] == num11)
				{
					return l;
				}
			}
			return -1;
		}
	}
	public sealed class CodaBarEncoder : OneDEncoder
	{
		private static readonly char[] START_END_CHARS = new char[4] { 'A', 'B', 'C', 'D' };

