		public override bool[] Encode(string contents)
		{
			if (contents.Length < 2)
			{
				throw new ArgumentException("Codabar should start/end with start/stop symbols");
			}
			char key = char.ToUpper(contents[0]);
			char key2 = char.ToUpper(contents[contents.Length - 1]);
			bool num = CodaBarDecoder.ArrayContains(START_END_CHARS, key) && CodaBarDecoder.ArrayContains(START_END_CHARS, key2);
			bool flag = CodaBarDecoder.ArrayContains(ALT_START_END_CHARS, key) && CodaBarDecoder.ArrayContains(ALT_START_END_CHARS, key2);
			if (!(num || flag))
			{
				throw new ArgumentException("Codabar should start/end with " + BarcodeHelper.Join(", ", START_END_CHARS) + ", or start/end with " + BarcodeHelper.Join(", ", ALT_START_END_CHARS));
			}
			int num2 = 20;
			char[] array = new char[4] { '/', ':', '+', '.' };
			for (int i = 1; i < contents.Length - 1; i++)
			{
				if (char.IsDigit(contents[i]) || contents[i] == '-' || contents[i] == '$')
				{
					num2 += 9;
					continue;
				}
				if (CodaBarDecoder.ArrayContains(array, contents[i]))
				{
					num2 += 10;
					continue;
				}
				throw new ArgumentException("Cannot Encode : '" + contents[i] + "'");
			}
			num2 += contents.Length - 1;
			bool[] array2 = new bool[num2];
			int num3 = 0;
			for (int j = 0; j < contents.Length; j++)
			{
				char c = char.ToUpper(contents[j]);
				if (j == contents.Length - 1)
				{
					switch (c)
					{
					case 'T':
						c = 'A';
						break;
					case 'N':
						c = 'B';
						break;
					case '*':
						c = 'C';
						break;
					case 'E':
						c = 'D';
						break;
					}
				}
				int num4 = 0;
				for (int k = 0; k < CodaBarDecoder.ALPHABET.Length; k++)
				{
					if (c == CodaBarDecoder.ALPHABET[k])
					{
						num4 = CodaBarDecoder.CHARACTER_ENCODINGS[k];
						break;
					}
				}
				bool flag2 = true;
				int num5 = 0;
				int num6 = 0;
				while (num6 < 7)
				{
					array2[num3] = flag2;
					num3++;
					if (((num4 >> 6 - num6) & 1) == 0 || num5 == 1)
					{
						flag2 = !flag2;
						num6++;
						num5 = 0;
					}
					else
					{
						num5++;
					}
				}
				if (j < contents.Length - 1)
				{
					array2[num3] = false;
					num3++;
				}
			}
			return array2;
		}
	}
