						{
						case 'ñ':
							num7 = 102;
							num5++;
							break;
						case 'ò':
							num7 = 97;
							num5++;
							break;
						case 'ó':
							num7 = 96;
							num5++;
							break;
						case 'ô':
							num7 = 100;
							num5++;
							break;
						default:
							num7 = int.Parse(contents.Substring(num5, num5 + 2 - num5));
							num5 += 2;
							break;
						}
					}
				}
				else
				{
					num7 = ((num4 != 0) ? num6 : ((num6 != 100) ? 105 : 104));
					num4 = num6;
				}
				collection.Add(Code128Decoder.CODE_PATTERNS[num7]);
				num2 += num7 * num3;
				if (num5 != 0)
				{
					num3++;
				}
			}
			num2 %= 103;
			collection.Add(Code128Decoder.CODE_PATTERNS[num2]);
			collection.Add(Code128Decoder.CODE_PATTERNS[106]);
			int num8 = 0;
			foreach (int[] item in collection)
			{
				foreach (int num9 in item)
				{
					num8 += num9;
