			}
			bool[] array = new bool[num8];
			int num10 = 0;
			foreach (int[] item2 in collection)
			{
				num10 += OneDEncoder.AppendPattern(array, num10, item2, startColor: true);
			}
			return array;
		}

		private static bool IsDigits(string val, int start, int length)
		{
			int num = start + length;
			int length2 = val.Length;
			for (int i = start; i < num && i < length2; i++)
			{
				char c = val[i];
				if (c < '0' || c > '9')
				{
					if (c != 'ñ')
					{
						return false;
					}
					num++;
				}
			}
			return num <= length2;
		}
