		private static int[] FindAsteriskPattern(MessagingToolkit.Barcode.Common.BitArray row, int[] counters)
		{
			int size = row.GetSize();
			int nextSet = row.GetNextSet(0);
			int num = 0;
			int num2 = nextSet;
			bool flag = false;
			int num3 = counters.Length;
			for (int i = nextSet; i < size; i++)
			{
				if (row.Get(i) ^ flag)
				{
					counters[num]++;
					continue;
				}
				if (num == num3 - 1)
				{
					if (ToNarrowWidePattern(counters) == AsteriskEncoding && row.IsRange(Math.Max(0, num2 - (i - num2 >> 1)), num2, val: false))
					{
						return new int[2] { num2, i };
					}
					num2 += counters[0] + counters[1];
					Array.Copy(counters, 2, counters, 0, num3 - 2);
					counters[num3 - 2] = 0;
					counters[num3 - 1] = 0;
					num--;
				}
				else
				{
					num++;
				}
				counters[num] = 1;
				flag = !flag;
			}
			throw NotFoundException.Instance;
		}

		private static int ToNarrowWidePattern(int[] counters)
		{
			int num = counters.Length;
			int num2 = 0;
			int num5;
			do
			{
				int num3 = int.MaxValue;
				foreach (int num4 in counters)
				{
					if (num4 < num3 && num4 > num2)
					{
						num3 = num4;
					}
				}
				num2 = num3;
				num5 = 0;
				int num6 = 0;
				int num7 = 0;
				for (int j = 0; j < num; j++)
				{
					int num8 = counters[j];
					if (num8 > num2)
					{
						num7 |= 1 << num - 1 - j;
						num5++;
						num6 += num8;
					}
				}
				if (num5 != 3)
				{
					continue;
				}
				for (int k = 0; k < num; k++)
				{
					if (num5 <= 0)
					{
						break;
					}
					int num9 = counters[k];
					if (num9 > num2)
					{
						num5--;
						if (num9 << 1 >= num6)
						{
							return -1;
						}
					}
				}
				return num7;
			}
			while (num5 > 3);
			return -1;
		}

		private static char PatternToChar(int pattern)
		{
			for (int i = 0; i < CharacterEncodings.Length; i++)
			{
				if (CharacterEncodings[i] == pattern)
				{
					return Alphabet[i];
				}
			}
			throw NotFoundException.Instance;
		}

		private static string DecodeExtended(StringBuilder encoded)
		{
			int length = encoded.Length;
			StringBuilder stringBuilder = new StringBuilder(length);
			for (int i = 0; i < length; i++)
			{
				char c = encoded[i];
				if (c == '+' || c == '$' || c == '%' || c == '/')
				{
					char c2 = encoded[i + 1];
					char value = '\0';
					switch (c)
					{
					case '+':
						if (c2 >= 'A' && c2 <= 'Z')
						{
							value = (char)(c2 + 32);
							break;
						}
						throw FormatException.Instance;
					case '$':
						if (c2 >= 'A' && c2 <= 'Z')
						{
							value = (char)(c2 - 64);
							break;
						}
						throw FormatException.Instance;
					case '%':
						if (c2 >= 'A' && c2 <= 'E')
						{
							value = (char)(c2 - 38);
							break;
						}
						if (c2 >= 'F' && c2 <= 'W')
						{
							value = (char)(c2 - 11);
							break;
						}
						throw FormatException.Instance;
					case '/':
						if (c2 >= 'A' && c2 <= 'O')
						{
							value = (char)(c2 - 32);
							break;
						}
						if (c2 == 'Z')
						{
							value = ':';
							break;
						}
						throw FormatException.Instance;
					}
					stringBuilder.Append(value);
					i++;
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}
	}
	public sealed class Code39Encoder : OneDEncoder
	{
		public override BitMatrix Encode(string contents, BarcodeFormat format, int width, int height, Dictionary<EncodeOptions, object> encodingOptions)
		{
			if (format != BarcodeFormat.Code39)
			{
				throw new ArgumentException("Can only encode CODE_39, but got " + format);
			}
			return base.Encode(contents, format, width, height, encodingOptions);
		}

		public override bool[] Encode(string contents)
		{
			int length = contents.Length;
			if (length > 80)
			{
				throw new ArgumentException("Requested contents should be less than 80 digits long, but got " + length);
			}
			int[] array = new int[9];
			int num = 25 + length;
			for (int i = 0; i < length; i++)
			{
				int num2 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. *$/+%".IndexOf(contents[i]);
				if (num2 < 0)
				{
					throw new ArgumentException("Bad contents: " + contents);
				}
				ToIntArray(Code39Decoder.CharacterEncodings[num2], array);
				int[] array2 = array;
				foreach (int num3 in array2)
				{
					num += num3;
				}
			}
			bool[] array3 = new bool[num];
			ToIntArray(Code39Decoder.CharacterEncodings[39], array);
			int num4 = OneDEncoder.AppendPattern(array3, 0, array, startColor: true);
			int[] pattern = new int[1] { 1 };
			num4 += OneDEncoder.AppendPattern(array3, num4, pattern, startColor: false);
			for (int num5 = length - 1; num5 >= 0; num5--)
			{
				int num6 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. *$/+%".IndexOf(contents[num5]);
				ToIntArray(Code39Decoder.CharacterEncodings[num6], array);
				num4 += OneDEncoder.AppendPattern(array3, num4, array, startColor: true);
				num4 += OneDEncoder.AppendPattern(array3, num4, pattern, startColor: false);
			}
			ToIntArray(Code39Decoder.CharacterEncodings[39], array);
			num4 += OneDEncoder.AppendPattern(array3, num4, array, startColor: true);
			return array3;
		}

		private static void ToIntArray(int a, int[] toReturn)
		{
			for (int i = 0; i < 9; i++)
			{
				int num = a & (1 << i);
				toReturn[i] = ((num == 0) ? 1 : 2);
			}
		}
	}
	public sealed class Code93Decoder : OneDDecoder
	{
		private const string AlphabetString = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%abcd*";

		private static readonly char[] Alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%abcd*".ToCharArray();

		private static readonly int[] CharacterEncodings = new int[48]
		{
			276, 328, 324, 322, 296, 292, 290, 336, 274, 266,
			424, 420, 418, 404, 402, 394, 360, 356, 354, 308,
			282, 344, 332, 326, 300, 278, 436, 434, 428, 422,
			406, 410, 364, 358, 310, 314, 302, 468, 466, 458,
			366, 374, 430, 294, 474, 470, 306, 350
		};

		private static readonly int AsteriskEncoding = CharacterEncodings[47];

		private readonly StringBuilder decodeRowResult;

		private readonly int[] counters;

		public Code93Decoder()
		{
			decodeRowResult = new StringBuilder(20);
			counters = new int[6];
		}

		public override Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, Dictionary<DecodeOptions, object> decodingOptions)
		{
			int[] array = FindAsteriskPattern(row);
			int num = row.GetNextSet(array[1]);
			int size = row.GetSize();
			int[] array2 = counters;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i] = 0;
			}
			StringBuilder stringBuilder = decodeRowResult;
			stringBuilder.Length = 0;
			char c;
			int num3;
			do
			{
				OneDDecoder.RecordPattern(row, num, array2);
				int num2 = ToPattern(array2);
				if (num2 < 0)
				{
					throw NotFoundException.Instance;
				}
				c = PatternToChar(num2);
				stringBuilder.Append(c);
				num3 = num;
				int[] array3 = array2;
				foreach (int num4 in array3)
				{
					num += num4;
				}
				num = row.GetNextSet(num);
			}
			while (c != '*');
			stringBuilder.Remove(stringBuilder.Length - 1, 1);
			if (num == size || !row.Get(num))
			{
				throw NotFoundException.Instance;
			}
			if (stringBuilder.Length < 2)
			{
				throw NotFoundException.Instance;
			}
			CheckChecksums(stringBuilder);
			stringBuilder.Length -= 2;
			string text = DecodeExtended(stringBuilder);
			float x = (float)(array[1] + array[0]) / 2f;
			float x2 = (float)(num + num3) / 2f;
			ResultPointCallback resultPointCallback = ((decodingOptions == null || !decodingOptions.ContainsKey(DecodeOptions.NeedResultPointCallback)) ? null : ((ResultPointCallback)decodingOptions[DecodeOptions.NeedResultPointCallback]));
			if (resultPointCallback != null)
			{
				resultPointCallback.FoundPossibleResultPoint(new ResultPoint(x, rowNumber));
				resultPointCallback.FoundPossibleResultPoint(new ResultPoint(x2, rowNumber));
			}
			return new Result(text, null, new ResultPoint[2]
			{
				new ResultPoint(x, rowNumber),
				new ResultPoint(x2, rowNumber)
			}, BarcodeFormat.Code93);
		}

		private int[] FindAsteriskPattern(MessagingToolkit.Barcode.Common.BitArray row)
		{
			int size = row.GetSize();
			int nextSet = row.GetNextSet(0);
			for (int i = 0; i < counters.Length; i++)
			{
				counters[i] = 0;
			}
			int[] array = counters;
			int num = nextSet;
			bool flag = false;
			int num2 = array.Length;
			int num3 = 0;
			for (int j = nextSet; j < size; j++)
			{
				if (row.Get(j) ^ flag)
				{
					array[num3]++;
					continue;
				}
				if (num3 == num2 - 1)
				{
					if (ToPattern(array) == AsteriskEncoding)
					{
						return new int[2] { num, j };
					}
					num += array[0] + array[1];
					Array.Copy(array, 2, array, 0, num2 - 2);
					array[num2 - 2] = 0;
					array[num2 - 1] = 0;
					num3--;
				}
				else
				{
					num3++;
				}
				array[num3] = 1;
				flag = !flag;
			}
			throw NotFoundException.Instance;
		}

		private static int ToPattern(int[] counters)
		{
			int num = counters.Length;
			int num2 = 0;
			foreach (int num3 in counters)
			{
				num2 += num3;
			}
			int num4 = 0;
			for (int j = 0; j < num; j++)
			{
				int num5 = (counters[j] << 8) * 9 / num2;
				int num6 = num5 >> 8;
				if ((num5 & 0xFF) > 127)
				{
					num6++;
				}
				if (num6 < 1 || num6 > 4)
				{
					return -1;
				}
				if ((j & 1) == 0)
				{
					for (int k = 0; k < num6; k++)
					{
						num4 = (num4 << 1) | 1;
					}
				}
				else
				{
					num4 <<= num6;
				}
			}
			return num4;
		}

		private static char PatternToChar(int pattern)
		{
			for (int i = 0; i < CharacterEncodings.Length; i++)
			{
				if (CharacterEncodings[i] == pattern)
				{
					return Alphabet[i];
				}
			}
			throw NotFoundException.Instance;
		}

		private static string DecodeExtended(StringBuilder encoded)
		{
			int length = encoded.Length;
			StringBuilder stringBuilder = new StringBuilder(length);
			for (int i = 0; i < length; i++)
			{
				char c = encoded[i];
				if (c >= 'a' && c <= 'd')
				{
					if (i >= length - 1)
					{
						throw FormatException.Instance;
					}
					char c2 = encoded[i + 1];
					char value = '\0';
					switch (c)
					{
					case 'd':
						if (c2 >= 'A' && c2 <= 'Z')
						{
							value = (char)(c2 + 32);
							break;
						}
						throw FormatException.Instance;
					case 'a':
						if (c2 >= 'A' && c2 <= 'Z')
						{
							value = (char)(c2 - 64);
							break;
						}
						throw FormatException.Instance;
					case 'b':
						if (c2 >= 'A' && c2 <= 'E')
						{
							value = (char)(c2 - 38);
							break;
						}
						if (c2 >= 'F' && c2 <= 'W')
						{
							value = (char)(c2 - 11);
							break;
						}
						throw FormatException.Instance;
					case 'c':
						if (c2 >= 'A' && c2 <= 'O')
						{
							value = (char)(c2 - 32);
							break;
						}
						if (c2 == 'Z')
						{
							value = ':';
							break;
						}
						throw FormatException.Instance;
					}
					stringBuilder.Append(value);
					i++;
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}

		private static void CheckChecksums(StringBuilder result)
		{
			int length = result.Length;
			CheckOneChecksum(result, length - 2, 20);
			CheckOneChecksum(result, length - 1, 15);
		}

		private static void CheckOneChecksum(StringBuilder result, int checkPosition, int weightMax)
		{
			int num = 1;
			int num2 = 0;
			for (int num3 = checkPosition - 1; num3 >= 0; num3--)
			{
				num2 += num * "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%abcd*".IndexOf(result[num3]);
				if (++num > weightMax)
				{
					num = 1;
				}
			}
			if (result[checkPosition] != Alphabet[num2 % 47])
			{
				throw ChecksumException.Instance;
			}
		}
	}
	public sealed class EAN13Decoder : UPCEANDecoder
	{
		internal static readonly int[] FirstDigitEncodings = new int[10] { 0, 11, 13, 14, 19, 25, 28, 21, 22, 26 };

		private readonly int[] decodeMiddleCounters;

		internal override BarcodeFormat BarcodeFormat => BarcodeFormat.EAN13;

		public EAN13Decoder()
		{
			decodeMiddleCounters = new int[4];
		}

		protected internal override int DecodeMiddle(MessagingToolkit.Barcode.Common.BitArray row, int[] startRange, StringBuilder resultString)
		{
			int[] array = decodeMiddleCounters;
			array[0] = 0;
			array[1] = 0;
			array[2] = 0;
			array[3] = 0;
			int size = row.GetSize();
			int num = startRange[1];
			int num2 = 0;
			for (int i = 0; i < 6; i++)
			{
				if (num >= size)
				{
					break;
				}
				int num3 = UPCEANDecoder.DecodeDigit(row, array, num, UPCEANDecoder.LAndGPatterns);
				resultString.Append((char)(48 + num3 % 10));
				int[] array2 = array;
				foreach (int num4 in array2)
				{
					num += num4;
				}
				if (num3 >= 10)
				{
					num2 |= 1 << 5 - i;
				}
			}
			DetermineFirstDigit(resultString, num2);
			num = UPCEANDecoder.FindGuardPattern(row, num, whiteFirst: true, UPCEANDecoder.MiddlePattern)[1];
			for (int k = 0; k < 6; k++)
			{
				if (num >= size)
				{
					break;
				}
				int num5 = UPCEANDecoder.DecodeDigit(row, array, num, UPCEANDecoder.LPatterns);
				resultString.Append((char)(48 + num5));
				int[] array2 = array;
				foreach (int num6 in array2)
				{
					num += num6;
				}
			}
			return num;
		}

		private static void DetermineFirstDigit(StringBuilder resultString, int lgPatternFound)
		{
			for (int i = 0; i < 10; i++)
			{
				if (lgPatternFound == FirstDigitEncodings[i])
				{
					resultString.Insert(0, (char)(48 + i));
					return;
				}
			}
			throw NotFoundException.Instance;
		}
	}
