			{
				throw new ArgumentException("Requested contents should be 13 digits long, but got " + contents.Length);
			}
			try
			{
				if (!UPCEANDecoder.CheckStandardUPCEANChecksum(contents))
				{
					throw new ArgumentException("Contents do not pass checksum");
				}
			}
			catch (FormatException)
			{
				throw new ArgumentException("Illegal contents");
			}
			int num = int.Parse(contents.Substring(0, 1));
			int num2 = EAN13Decoder.FirstDigitEncodings[num];
			bool[] array = new bool[95];
			int num3 = 0;
			num3 += OneDEncoder.AppendPattern(array, num3, UPCEANDecoder.StartEndPattern, startColor: true);
			for (int i = 1; i <= 6; i++)
			{
				int num4 = int.Parse(contents.Substring(i, i + 1 - i));
