				{
					num4 += 10;
				}
				num3 += OneDEncoder.AppendPattern(array, num3, UPCEANDecoder.LAndGPatterns[num4], startColor: false);
			}
			num3 += OneDEncoder.AppendPattern(array, num3, UPCEANDecoder.MiddlePattern, startColor: false);
			for (int j = 7; j <= 12; j++)
			{
				int num5 = int.Parse(contents.Substring(j, j + 1 - j));
				num3 += OneDEncoder.AppendPattern(array, num3, UPCEANDecoder.LPatterns[num5], startColor: true);
			}
			num3 += OneDEncoder.AppendPattern(array, num3, UPCEANDecoder.StartEndPattern, startColor: true);
			return array;
		}
