					num2++;
				}
				array[num2] = 1;
				flag = !flag;
			}
			throw NotFoundException.Instance;
		}

		private static int DecodeDigit(int[] counters)
		{
			int num = 107;
			int num2 = -1;
			int num3 = PATTERNS.Length;
			for (int i = 0; i < num3; i++)
			{
				int[] pattern = PATTERNS[i];
				int num4 = OneDDecoder.PatternMatchVariance(counters, pattern, 199);
				if (num4 < num)
				{
					num = num4;
					num2 = i;
				}
			}
			if (num2 >= 0)
			{
				return num2;
			}
			throw NotFoundException.Instance;
		}
