	public sealed class BarcodeOneDDecoder : OneDDecoder
	{
		private readonly List<OneDDecoder> decoders;

		public BarcodeOneDDecoder(Dictionary<DecodeOptions, object> decodingOptions)
		{
			List<BarcodeFormat> list = ((decodingOptions == null) ? null : ((List<BarcodeFormat>)BarcodeHelper.GetDecodeOptionType(decodingOptions, DecodeOptions.PossibleFormats)));
			bool usingCheckDigit = false;
			object decodeOptionType = BarcodeHelper.GetDecodeOptionType(decodingOptions, DecodeOptions.AssumeCode39CheckDigit);
			if (decodeOptionType != null)
			{
				usingCheckDigit = (bool)decodeOptionType;
			}
			bool usingCheckDigit2 = true;
			decodeOptionType = BarcodeHelper.GetDecodeOptionType(decodingOptions, DecodeOptions.AssumeMsiCheckDigit);
			if (decodeOptionType != null)
			{
				usingCheckDigit2 = (bool)decodeOptionType;
			}
			decoders = new List<OneDDecoder>();
			if (list != null)
			{
				if (list.Contains(BarcodeFormat.EAN13) || list.Contains(BarcodeFormat.UPCA) || list.Contains(BarcodeFormat.EAN8) || list.Contains(BarcodeFormat.UPCE))
				{
					decoders.Add(new BarcodeUPCEANDecoder(decodingOptions));
				}
				if (list.Contains(BarcodeFormat.MSIMod10))
				{
					decoders.Add(new MsiDecoder(usingCheckDigit2));
				}
				if (list.Contains(BarcodeFormat.Code39))
				{
					decoders.Add(new Code39Decoder(usingCheckDigit));
				}
				if (list.Contains(BarcodeFormat.Code93))
				{
					decoders.Add(new Code93Decoder());
				}
				if (list.Contains(BarcodeFormat.Code128))
				{
					decoders.Add(new Code128Decoder());
				}
				if (list.Contains(BarcodeFormat.ITF14))
				{
					decoders.Add(new ITFDecoder());
				}
				if (list.Contains(BarcodeFormat.Codabar))
				{
					decoders.Add(new CodaBarDecoder());
				}
				if (list.Contains(BarcodeFormat.RSS14))
				{
					decoders.Add(new Rss14Decoder());
				}
				if (list.Contains(BarcodeFormat.RSSExpanded))
				{
					decoders.Add(new RssExpandedDecoder());
				}
			}
			if (decoders.Count == 0)
			{
				decoders.Add(new BarcodeUPCEANDecoder(decodingOptions));
				decoders.Add(new Code39Decoder(usingCheckDigit));
				decoders.Add(new MsiDecoder(usingCheckDigit2));
				decoders.Add(new CodaBarDecoder());
				decoders.Add(new Code93Decoder());
				decoders.Add(new Code128Decoder());
				decoders.Add(new ITFDecoder());
				decoders.Add(new Rss14Decoder());
				decoders.Add(new RssExpandedDecoder());
			}
		}

		public override Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, Dictionary<DecodeOptions, object> decodingOptions)
		{
			foreach (OneDDecoder decoder in decoders)
			{
				try
				{
					return decoder.DecodeRow(rowNumber, row, decodingOptions);
				}
				catch (BarcodeDecoderException)
				{
				}
			}
			throw NotFoundException.Instance;
		}

		public override void Reset()
		{
			foreach (OneDDecoder decoder in decoders)
			{
				((IDecoder)decoder).Reset();
			}
		}
	}
	public sealed class BarcodeUPCEANDecoder : OneDDecoder
	{
		private readonly UPCEANDecoder[] decoders;

		public BarcodeUPCEANDecoder(Dictionary<DecodeOptions, object> decodingOptions)
		{
			List<BarcodeFormat> list = ((decodingOptions == null) ? null : ((List<BarcodeFormat>)BarcodeHelper.GetDecodeOptionType(decodingOptions, DecodeOptions.PossibleFormats)));
			List<UPCEANDecoder> list2 = new List<UPCEANDecoder>();
			if (list != null)
			{
				if (list.Contains(BarcodeFormat.EAN13))
				{
					list2.Add(new EAN13Decoder());
				}
				else if (list.Contains(BarcodeFormat.UPCA))
				{
					list2.Add(new UPCADecoder());
				}
				if (list.Contains(BarcodeFormat.EAN8))
				{
					list2.Add(new EAN8Decoder());
				}
				if (list.Contains(BarcodeFormat.UPCE))
				{
					list2.Add(new UPCEDecoder());
				}
			}
			if (list2.Count == 0)
			{
				list2.Add(new EAN13Decoder());
				list2.Add(new EAN8Decoder());
				list2.Add(new UPCEDecoder());
			}
			decoders = list2.ToArray();
		}

		public override Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, Dictionary<DecodeOptions, object> decodingOptions)
		{
			int[] startGuardRange = UPCEANDecoder.FindStartGuardPattern(row);
			UPCEANDecoder[] array = decoders;
			foreach (UPCEANDecoder uPCEANDecoder in array)
			{
				Result result;
				try
				{
					result = uPCEANDecoder.DecodeRow(rowNumber, row, startGuardRange, decodingOptions);
				}
				catch (BarcodeDecoderException)
				{
					continue;
				}
				bool num = result.BarcodeFormat == BarcodeFormat.EAN13 && result.Text[0] == '0';
				bool flag = ((decodingOptions == null) ? null : ((List<BarcodeFormat>)BarcodeHelper.GetDecodeOptionType(decodingOptions, DecodeOptions.PossibleFormats)))?.Contains(BarcodeFormat.UPCA) ?? true;
				if (num && flag)
				{
					Result result2 = new Result(result.Text.Substring(1), result.RawBytes, result.ResultPoints, BarcodeFormat.UPCA);
					result2.PutAllMetadata(result.ResultMetadata);
					return result2;
				}
				return result;
			}
			throw NotFoundException.Instance;
		}

		public override void Reset()
		{
			UPCEANDecoder[] array = decoders;
			for (int i = 0; i < array.Length; i++)
			{
				((IDecoder)array[i]).Reset();
			}
		}
	}
	public sealed class ITFEncoder : OneDEncoder
	{
		private static readonly int[] START_PATTERN = new int[4] { 1, 1, 1, 1 };

		private static readonly int[] END_PATTERN = new int[3] { 3, 1, 1 };

		public override BitMatrix Encode(string contents, BarcodeFormat format, int width, int height, Dictionary<EncodeOptions, object> encodingOptions)
		{
			if (format != BarcodeFormat.ITF14)
			{
				throw new ArgumentException("Can only encode ITF, but got " + format);
			}
			return base.Encode(contents, format, width, height, encodingOptions);
		}

		public override bool[] Encode(string contents)
		{
			int length = contents.Length;
			if (length % 2 != 0)
			{
				throw new ArgumentException("The length of the input should be even");
			}
			if (length > 80)
			{
				throw new ArgumentException("Requested contents should be less than 80 digits long, but got " + length);
			}
			bool[] array = new bool[9 + 9 * length];
			int num = OneDEncoder.AppendPattern(array, 0, START_PATTERN, startColor: true);
			for (int i = 0; i < length; i += 2)
			{
				int num2 = Convert.ToInt32(Convert.ToString(contents[i]), 10);
				int num3 = Convert.ToInt32(Convert.ToString(contents[i + 1]), 10);
				int[] array2 = new int[18];
				for (int j = 0; j < 5; j++)
				{
					array2[j << 1] = ITFDecoder.PATTERNS[num2][j];
					array2[(j << 1) + 1] = ITFDecoder.PATTERNS[num3][j];
				}
				num += OneDEncoder.AppendPattern(array, num, array2, startColor: true);
			}
			OneDEncoder.AppendPattern(array, num, END_PATTERN, startColor: true);
			return array;
		}
	}
	public abstract class OneDDecoder : IDecoder
	{
		protected internal const int IntegerMathShift = 8;

		protected internal const int PatternMatchResultScaleFactor = 256;

		public virtual Result Decode(BinaryBitmap image)
		{
			return Decode(image, null);
		}

		public virtual Result Decode(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions)
		{
			try
			{
				return DoDecode(image, decodingOptions);
			}
			catch (NotFoundException ex)
			{
				if (decodingOptions != null && decodingOptions.ContainsKey(DecodeOptions.TryHarder) && image.RotateSupported)
				{
					BinaryBitmap binaryBitmap = image.RotateCounterClockwise();
					Result result = DoDecode(binaryBitmap, decodingOptions);
					Dictionary<ResultMetadataType, object> resultMetadata = result.ResultMetadata;
					int num = 270;
					if (resultMetadata != null && resultMetadata.ContainsKey(ResultMetadataType.Orientation))
					{
						num = (num + (int)resultMetadata[ResultMetadataType.Orientation]) % 360;
					}
					result.PutMetadata(ResultMetadataType.Orientation, num);
					ResultPoint[] resultPoints = result.ResultPoints;
					int height = binaryBitmap.Height;
					for (int i = 0; i < resultPoints.Length; i++)
					{
						resultPoints[i] = new ResultPoint((float)height - resultPoints[i].Y - 1f, resultPoints[i].X);
					}
					return result;
				}
				throw ex;
			}
		}

		public virtual void Reset()
		{
		}

		private Result DoDecode(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions)
		{
			int width = image.Width;
			int height = image.Height;
			MessagingToolkit.Barcode.Common.BitArray bitArray = new MessagingToolkit.Barcode.Common.BitArray(width);
			int num = height >> 1;
			bool flag = decodingOptions?.ContainsKey(DecodeOptions.TryHarder) ?? false;
			int num2 = Math.Max(1, height >> (flag ? 8 : 5));
			int num3 = ((!flag) ? 15 : height);
			for (int i = 0; i < num3; i++)
			{
				int num4 = i + 1 >> 1;
				bool flag2 = (i & 1) == 0;
				int num5 = num + num2 * (flag2 ? num4 : (-num4));
				if (num5 < 0 || num5 >= height)
				{
					break;
				}
				try
				{
					bitArray = image.GetBlackRow(num5, bitArray);
				}
				catch (NotFoundException)
				{
					continue;
				}
				for (int j = 0; j < 2; j++)
				{
					if (j == 1)
					{
						bitArray.Reverse();
						if (decodingOptions != null && decodingOptions.ContainsKey(DecodeOptions.NeedResultPointCallback))
						{
							Dictionary<DecodeOptions, object> dictionary = new Dictionary<DecodeOptions, object>();
							IEnumerator<DecodeOptions> enumerator = decodingOptions.Keys.GetEnumerator();
							while (enumerator.MoveNext())
							{
								DecodeOptions current = enumerator.Current;
								if (current != DecodeOptions.NeedResultPointCallback)
								{
									dictionary.Add(current, decodingOptions[current]);
								}
							}
							decodingOptions = dictionary;
						}
					}
					try
					{
						Result result = DecodeRow(num5, bitArray, decodingOptions);
						if (j == 1)
						{
							result.PutMetadata(ResultMetadataType.Orientation, 180);
							ResultPoint[] resultPoints = result.ResultPoints;
							resultPoints[0] = new ResultPoint((float)width - resultPoints[0].X - 1f, resultPoints[0].Y);
							resultPoints[1] = new ResultPoint((float)width - resultPoints[1].X - 1f, resultPoints[1].Y);
						}
						return result;
					}
					catch (BarcodeDecoderException)
					{
					}
				}
			}
			throw NotFoundException.Instance;
		}

		protected internal static void RecordPattern(MessagingToolkit.Barcode.Common.BitArray row, int start, int[] counters)
		{
			int num = counters.Length;
			for (int i = 0; i < num; i++)
			{
				counters[i] = 0;
			}
			int size = row.GetSize();
			if (start >= size)
			{
				throw NotFoundException.Instance;
			}
			bool flag = !row.Get(start);
			int num2 = 0;
			int j;
			for (j = start; j < size; j++)
			{
				if (row.Get(j) ^ flag)
				{
					counters[num2]++;
					continue;
				}
				num2++;
				if (num2 == num)
				{
					break;
				}
				counters[num2] = 1;
				flag = !flag;
			}
			if (num2 != num && (num2 != num - 1 || j != size))
			{
				throw NotFoundException.Instance;
			}
		}

		protected internal static void RecordPatternInReverse(MessagingToolkit.Barcode.Common.BitArray row, int start, int[] counters)
		{
			int num = counters.Length;
			bool flag = row.Get(start);
			while (start > 0 && num >= 0)
			{
				if (row.Get(--start) != flag)
				{
					num--;
					flag = !flag;
				}
			}
			if (num >= 0)
			{
				throw NotFoundException.Instance;
			}
			RecordPattern(row, start + 1, counters);
		}

		protected internal static int PatternMatchVariance(int[] counters, int[] pattern, int maxIndividualVariance)
		{
			int num = counters.Length;
			int num2 = 0;
			int num3 = 0;
			for (int i = 0; i < num; i++)
			{
				num2 += counters[i];
				num3 += pattern[i];
			}
			if (num2 < num3)
			{
				return int.MaxValue;
			}
			int num4 = (num2 << 8) / num3;
			maxIndividualVariance = maxIndividualVariance * num4 >> 8;
			int num5 = 0;
			for (int j = 0; j < num; j++)
			{
				int num6 = counters[j] << 8;
				int num7 = pattern[j] * num4;
				int num8 = ((num6 > num7) ? (num6 - num7) : (num7 - num6));
				if (num8 > maxIndividualVariance)
				{
					return int.MaxValue;
				}
				num5 += num8;
			}
			return num5 / num2;
		}

		public abstract Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, Dictionary<DecodeOptions, object> decodingOptions);
	}
	public abstract class OneDEncoder : IEncoder
	{
		public virtual int DefaultMargin => 10;

		public BitMatrix Encode(string contents, BarcodeFormat format, int width, int height)
		{
			return Encode(contents, format, width, height, null);
		}

		public virtual BitMatrix Encode(string contents, BarcodeFormat format, int width, int height, Dictionary<EncodeOptions, object> encodingOptions)
		{
			if (string.IsNullOrEmpty(contents))
			{
				throw new ArgumentException("Found empty contents");
			}
			if (width < 0 || height < 0)
			{
				throw new ArgumentException("Negative size is not allowed. Input: " + width + "x" + height);
			}
			int sidesMargin = DefaultMargin;
			if (encodingOptions != null)
			{
				object encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.Margin);
				if (encodeOptionType != null)
				{
					sidesMargin = Convert.ToInt32(encodeOptionType);
				}
			}
			return RenderResult(Encode(contents), width, height, sidesMargin);
		}

		private static BitMatrix RenderResult(bool[] code, int width, int height, int sidesMargin)
		{
			int num = code.Length;
			int num2 = num + (UPCEANDecoder.StartEndPattern.Length << 1);
			int num3 = Math.Max(width, num2);
			int num4 = Math.Max(1, height);
			int num5 = num3 / num2;
			int num6 = (num3 - num * num5) / 2;
			BitMatrix bitMatrix = new BitMatrix(num3, num4);
			int num7 = 0;
			int num8 = num6;
			while (num7 < num)
			{
				if (code[num7])
				{
					bitMatrix.SetRegion(num8, 0, num5, num4);
				}
				num7++;
				num8 += num5;
			}
			return bitMatrix;
		}

		internal static int AppendPattern(bool[] target, int pos, int[] pattern, bool startColor)
		{
			bool flag = startColor;
			int num = 0;
			foreach (int num2 in pattern)
			{
				for (int j = 0; j < num2; j++)
				{
					target[pos++] = flag;
				}
				num += num2;
				flag = !flag;
			}
			return num;
		}

		public abstract bool[] Encode(string contents);
	}
