	public class UPCAEncoder : IEncoder
	{
		private readonly EAN13Encoder subEncoder;

		public UPCAEncoder()
		{
			subEncoder = new EAN13Encoder();
		}

		public virtual BitMatrix Encode(string contents, BarcodeFormat format, int width, int height)
		{
			return Encode(contents, format, width, height, null);
		}

		public virtual BitMatrix Encode(string contents, BarcodeFormat format, int width, int height, Dictionary<EncodeOptions, object> encodingOptions)
		{
			if (format != BarcodeFormat.UPCA)
			{
				throw new ArgumentException("Can only encode UPC-A, but got " + format);
			}
			return subEncoder.Encode(Preencode(contents), BarcodeFormat.EAN13, width, height, encodingOptions);
		}

		private static string Preencode(string contents)
		{
			switch (contents.Length)
			{
			case 11:
			{
				int num = 0;
				for (int i = 0; i < 11; i++)
				{
					num += (contents[i] - 48) * ((i % 2 != 0) ? 1 : 3);
				}
				contents += (1000 - num) % 10;
				break;
			}
			default:
				throw new ArgumentException("Requested contents should be 11 or 12 digits long, but got " + contents.Length);
			case 12:
				break;
			}
			return "0" + contents;
		}
	}
	public abstract class UPCEANDecoder : OneDDecoder
	{
		private const int MaxAvgVariance = 122;

		private const int MaxIndividualVariance = 179;

		internal static readonly int[] StartEndPattern;

		internal static readonly int[] MiddlePattern;

		internal static readonly int[][] LPatterns;

		internal static readonly int[][] LAndGPatterns;

		private readonly StringBuilder decodeRowStringBuffer;

		private readonly UPCEANExtensionSupport extensionReader;

		private readonly EANManufacturerOrgSupport eanManSupport;

		internal abstract BarcodeFormat BarcodeFormat { get; }

		protected internal UPCEANDecoder()
		{
			decodeRowStringBuffer = new StringBuilder(20);
			extensionReader = new UPCEANExtensionSupport();
			eanManSupport = new EANManufacturerOrgSupport();
		}

		internal static int[] FindStartGuardPattern(MessagingToolkit.Barcode.Common.BitArray row)
		{
			bool flag = false;
			int[] array = null;
			int num = 0;
			int[] array2 = new int[StartEndPattern.Length];
			while (!flag)
			{
				for (int i = 0; i < StartEndPattern.Length; i++)
				{
					array2[i] = 0;
				}
				array = FindGuardPattern(row, num, whiteFirst: false, StartEndPattern, array2);
				int num2 = array[0];
				num = array[1];
				int num3 = num2 - (num - num2);
				if (num3 >= 0)
				{
					flag = row.IsRange(num3, num2, val: false);
				}
			}
			return array;
		}

		public override Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, Dictionary<DecodeOptions, object> decodingOptions)
		{
			return DecodeRow(rowNumber, row, FindStartGuardPattern(row), decodingOptions);
		}

		public virtual Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, int[] startGuardRange, Dictionary<DecodeOptions, object> decodingOptions)
		{
			ResultPointCallback resultPointCallback = ((decodingOptions == null) ? null : ((ResultPointCallback)BarcodeHelper.GetDecodeOptionType(decodingOptions, DecodeOptions.NeedResultPointCallback)));
			resultPointCallback?.FoundPossibleResultPoint(new ResultPoint((float)(startGuardRange[0] + startGuardRange[1]) / 2f, rowNumber));
			StringBuilder stringBuilder = decodeRowStringBuffer;
			stringBuilder.Length = 0;
			int num = DecodeMiddle(row, startGuardRange, stringBuilder);
			resultPointCallback?.FoundPossibleResultPoint(new ResultPoint(num, rowNumber));
			int[] array = DecodeEnd(row, num);
			resultPointCallback?.FoundPossibleResultPoint(new ResultPoint((float)(array[0] + array[1]) / 2f, rowNumber));
			int num2 = array[1];
			int num3 = num2 + (num2 - array[0]);
			if (num3 >= row.GetSize() || !row.IsRange(num2, num3, val: false))
			{
				throw NotFoundException.Instance;
			}
			string text = stringBuilder.ToString();
			if (!CheckChecksum(text))
			{
				throw ChecksumException.Instance;
			}
			float x = (float)(startGuardRange[1] + startGuardRange[0]) / 2f;
			float x2 = (float)(array[1] + array[0]) / 2f;
			BarcodeFormat barcodeFormat = BarcodeFormat;
			Result result = new Result(text, null, new ResultPoint[2]
			{
				new ResultPoint(x, rowNumber),
				new ResultPoint(x2, rowNumber)
			}, barcodeFormat);
			try
			{
				Result result2 = extensionReader.DecodeRow(rowNumber, row, array[1]);
				result.PutMetadata(ResultMetadataType.UPCEANExtension, result2.Text);
				result.PutAllMetadata(result2.ResultMetadata);
				result.AddResultPoints(result2.ResultPoints);
			}
			catch (BarcodeDecoderException)
			{
			}
			if (barcodeFormat == BarcodeFormat.EAN13 || barcodeFormat == BarcodeFormat.UPCA)
			{
				string text2 = eanManSupport.LookupCountryIdentifier(text);
				if (text2 != null)
				{
					result.PutMetadata(ResultMetadataType.PossibleCountry, text2);
				}
			}
			return result;
		}

		internal virtual bool CheckChecksum(string s)
		{
			return CheckStandardUPCEANChecksum(s);
		}

		internal static bool CheckStandardUPCEANChecksum(string s)
		{
			int length = s.Length;
			if (length == 0)
			{
				return false;
			}
			int num = 0;
			for (int num2 = length - 2; num2 >= 0; num2 -= 2)
			{
				int num3 = s[num2] - 48;
				if (num3 < 0 || num3 > 9)
				{
					throw FormatException.Instance;
				}
				num += num3;
			}
			num *= 3;
			for (int num4 = length - 1; num4 >= 0; num4 -= 2)
			{
				int num5 = s[num4] - 48;
				if (num5 < 0 || num5 > 9)
				{
					throw FormatException.Instance;
				}
				num += num5;
			}
			return num % 10 == 0;
		}

		internal virtual int[] DecodeEnd(MessagingToolkit.Barcode.Common.BitArray row, int endStart)
		{
			return FindGuardPattern(row, endStart, whiteFirst: false, StartEndPattern);
		}

		internal static int[] FindGuardPattern(MessagingToolkit.Barcode.Common.BitArray row, int rowOffset, bool whiteFirst, int[] pattern)
		{
			return FindGuardPattern(row, rowOffset, whiteFirst, pattern, new int[pattern.Length]);
		}

		private static int[] FindGuardPattern(MessagingToolkit.Barcode.Common.BitArray row, int rowOffset, bool whiteFirst, int[] pattern, int[] counters)
		{
			int num = pattern.Length;
			int size = row.GetSize();
			bool flag = whiteFirst;
			rowOffset = (whiteFirst ? row.GetNextUnset(rowOffset) : row.GetNextSet(rowOffset));
			int num2 = 0;
			int num3 = rowOffset;
			for (int i = rowOffset; i < size; i++)
			{
				if (row.Get(i) ^ flag)
				{
					counters[num2]++;
					continue;
				}
				if (num2 == num - 1)
				{
					if (OneDDecoder.PatternMatchVariance(counters, pattern, 179) < 122)
					{
						return new int[2] { num3, i };
					}
					num3 += counters[0] + counters[1];
					Array.Copy(counters, 2, counters, 0, num - 2);
					counters[num - 2] = 0;
					counters[num - 1] = 0;
					num2--;
				}
				else
				{
					num2++;
				}
				counters[num2] = 1;
				flag = !flag;
			}
			throw NotFoundException.Instance;
		}

		internal static int DecodeDigit(MessagingToolkit.Barcode.Common.BitArray row, int[] counters, int rowOffset, int[][] patterns)
		{
			OneDDecoder.RecordPattern(row, rowOffset, counters);
			int num = 122;
			int num2 = -1;
			int num3 = patterns.Length;
			for (int i = 0; i < num3; i++)
			{
				int[] pattern = patterns[i];
				int num4 = OneDDecoder.PatternMatchVariance(counters, pattern, 179);
				if (num4 < num)
				{
					num = num4;
					num2 = i;
				}
			}
			if (num2 >= 0)
			{
				return num2;
			}
			throw NotFoundException.Instance;
		}

		protected internal abstract int DecodeMiddle(MessagingToolkit.Barcode.Common.BitArray row, int[] startRange, StringBuilder resultString);

		static UPCEANDecoder()
		{
			StartEndPattern = new int[3] { 1, 1, 1 };
			MiddlePattern = new int[5] { 1, 1, 1, 1, 1 };
			LPatterns = new int[10][]
			{
				new int[4] { 3, 2, 1, 1 },
				new int[4] { 2, 2, 2, 1 },
				new int[4] { 2, 1, 2, 2 },
				new int[4] { 1, 4, 1, 1 },
				new int[4] { 1, 1, 3, 2 },
				new int[4] { 1, 2, 3, 1 },
				new int[4] { 1, 1, 1, 4 },
				new int[4] { 1, 3, 1, 2 },
				new int[4] { 1, 2, 1, 3 },
				new int[4] { 3, 1, 1, 2 }
			};
			LAndGPatterns = new int[20][];
			Array.Copy(LPatterns, 0, LAndGPatterns, 0, 10);
			for (int i = 10; i < 20; i++)
			{
				int[] array = LPatterns[i - 10];
				int[] array2 = new int[array.Length];
				for (int j = 0; j < array.Length; j++)
				{
					array2[j] = array[array.Length - j - 1];
				}
				LAndGPatterns[i] = array2;
			}
		}
	}
	public abstract class UPCEANEncoder : OneDEncoder
	{
		public override int DefaultMargin => UPCEANDecoder.StartEndPattern.Length;
	}
	internal sealed class UPCEANExtension2Support
	{
		private readonly int[] decodeMiddleCounters;

		private readonly StringBuilder decodeRowStringBuffer;

		public UPCEANExtension2Support()
		{
			decodeMiddleCounters = new int[4];
			decodeRowStringBuffer = new StringBuilder();
		}

		internal Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, int[] extensionStartRange)
		{
			StringBuilder stringBuilder = decodeRowStringBuffer;
			stringBuilder.Length = 0;
			int num = DecodeMiddle(row, extensionStartRange, stringBuilder);
			string text = stringBuilder.ToString();
			Dictionary<ResultMetadataType, object> dictionary = ParseExtensionString(text);
			Result result = new Result(text, null, new ResultPoint[2]
			{
				new ResultPoint((float)(extensionStartRange[0] + extensionStartRange[1]) / 2f, rowNumber),
				new ResultPoint(num, rowNumber)
			}, BarcodeFormat.UPCEANExtension);
			if (dictionary != null)
			{
				result.PutAllMetadata(dictionary);
			}
			return result;
		}

		internal int DecodeMiddle(MessagingToolkit.Barcode.Common.BitArray row, int[] startRange, StringBuilder resultString)
		{
			int[] array = decodeMiddleCounters;
			array[0] = 0;
			array[1] = 0;
			array[2] = 0;
			array[3] = 0;
			int size = row.GetSize();
			int num = startRange[1];
			int num2 = 0;
			for (int i = 0; i < 2; i++)
			{
				if (num >= size)
				{
					break;
				}
				int num3 = UPCEANDecoder.DecodeDigit(row, array, num, UPCEANDecoder.LAndGPatterns);
				resultString.Append((char)(48 + num3 % 10));
				int[] array2 = array;
				foreach (int num4 in array2)
				{
					num += num4;
				}
				if (num3 >= 10)
				{
					num2 |= 1 << 1 - i;
				}
				if (i != 1)
				{
					num = row.GetNextSet(num);
					num = row.GetNextUnset(num);
				}
			}
			if (resultString.Length != 2)
			{
				throw NotFoundException.Instance;
			}
			if (int.Parse(resultString.ToString()) % 4 != num2)
			{
				throw NotFoundException.Instance;
			}
			return num;
		}

		private static Dictionary<ResultMetadataType, object> ParseExtensionString(string raw)
		{
			if (raw.Length != 2)
			{
				return null;
			}
			return new Dictionary<ResultMetadataType, object> { 
			{
				ResultMetadataType.IssueNumber,
				int.Parse(raw)
			} };
		}
	}
	internal sealed class UPCEANExtension5Support
	{
		private static readonly int[] CHECK_DIGIT_ENCODINGS = new int[10] { 24, 20, 18, 17, 12, 6, 3, 10, 9, 5 };

		private readonly int[] decodeMiddleCounters;

		private readonly StringBuilder decodeRowStringBuffer;

		public UPCEANExtension5Support()
		{
			decodeMiddleCounters = new int[4];
			decodeRowStringBuffer = new StringBuilder();
		}

		internal Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, int[] extensionStartRange)
		{
			StringBuilder stringBuilder = decodeRowStringBuffer;
			stringBuilder.Length = 0;
			int num = DecodeMiddle(row, extensionStartRange, stringBuilder);
			string text = stringBuilder.ToString();
			Dictionary<ResultMetadataType, object> dictionary = ParseExtensionString(text);
			Result result = new Result(text, null, new ResultPoint[2]
			{
				new ResultPoint((float)(extensionStartRange[0] + extensionStartRange[1]) / 2f, rowNumber),
				new ResultPoint(num, rowNumber)
			}, BarcodeFormat.UPCEANExtension);
			if (dictionary != null)
			{
				result.PutAllMetadata(dictionary);
			}
			return result;
		}

		internal int DecodeMiddle(MessagingToolkit.Barcode.Common.BitArray row, int[] startRange, StringBuilder resultString)
		{
			int[] array = decodeMiddleCounters;
			array[0] = 0;
			array[1] = 0;
			array[2] = 0;
			array[3] = 0;
			int size = row.GetSize();
			int num = startRange[1];
			int num2 = 0;
			for (int i = 0; i < 5; i++)
			{
				if (num >= size)
				{
					break;
				}
				int num3 = UPCEANDecoder.DecodeDigit(row, array, num, UPCEANDecoder.LAndGPatterns);
				resultString.Append((char)(48 + num3 % 10));
				int[] array2 = array;
				foreach (int num4 in array2)
				{
					num += num4;
				}
				if (num3 >= 10)
				{
					num2 |= 1 << 4 - i;
				}
				if (i != 4)
				{
					num = row.GetNextSet(num);
					num = row.GetNextUnset(num);
				}
			}
			if (resultString.Length != 5)
			{
				throw NotFoundException.Instance;
			}
			int num5 = DetermineCheckDigit(num2);
			if (ExtensionChecksum(resultString.ToString()) != num5)
			{
				throw NotFoundException.Instance;
			}
			return num;
		}

		private static int ExtensionChecksum(string s)
		{
			int length = s.Length;
			int num = 0;
			for (int num2 = length - 2; num2 >= 0; num2 -= 2)
			{
				num += s[num2] - 48;
			}
			num *= 3;
			for (int num3 = length - 1; num3 >= 0; num3 -= 2)
			{
				num += s[num3] - 48;
			}
			num *= 3;
			return num % 10;
		}

		private static int DetermineCheckDigit(int lgPatternFound)
		{
			for (int i = 0; i < 10; i++)
			{
				if (lgPatternFound == CHECK_DIGIT_ENCODINGS[i])
				{
					return i;
				}
			}
			throw NotFoundException.Instance;
		}

		private static Dictionary<ResultMetadataType, object> ParseExtensionString(string raw)
		{
			if (raw.Length != 5)
			{
				return null;
			}
			object obj = ParseExtension5String(raw);
			if (obj == null)
			{
				return null;
			}
			return new Dictionary<ResultMetadataType, object> { 
			{
				ResultMetadataType.SuggestedPrice,
				obj
			} };
		}

		private static string ParseExtension5String(string raw)
		{
			string text;
			switch (raw[0])
			{
			case '0':
				text = "£";
				break;
			case '5':
				text = "$";
				break;
			case '9':
				if ("90000".Equals(raw))
				{
					return null;
				}
				if ("99991".Equals(raw))
				{
					return "0.00";
				}
				if ("99990".Equals(raw))
				{
					return "Used";
				}
				text = "";
				break;
			default:
				text = "";
				break;
			}
			int num = int.Parse(raw.Substring(1));
			string text2 = (num / 100).ToString();
			int num2 = num % 100;
			string text3 = ((num2 < 10) ? ("0" + num2) : num2.ToString());
			return text + text2 + "." + text3;
		}
	}
	internal sealed class UPCEANExtensionSupport
	{
		private static readonly int[] EXTENSION_START_PATTERN = new int[3] { 1, 1, 2 };

		private readonly UPCEANExtension2Support twoSupport;

		private readonly UPCEANExtension5Support fiveSupport;

		public UPCEANExtensionSupport()
		{
			twoSupport = new UPCEANExtension2Support();
			fiveSupport = new UPCEANExtension5Support();
		}

		internal Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, int rowOffset)
		{
			int[] extensionStartRange = UPCEANDecoder.FindGuardPattern(row, rowOffset, whiteFirst: false, EXTENSION_START_PATTERN);
			try
			{
				return fiveSupport.DecodeRow(rowNumber, row, extensionStartRange);
			}
			catch (BarcodeDecoderException)
			{
				return twoSupport.DecodeRow(rowNumber, row, extensionStartRange);
			}
		}
	}
	public sealed class UPCEDecoder : UPCEANDecoder
	{
		private static readonly int[] MiddleEndPattern = new int[6] { 1, 1, 1, 1, 1, 1 };

		private static readonly int[][] NumSysAndCheckDigitPatterns = new int[2][]
		{
			new int[10] { 56, 52, 50, 49, 44, 38, 35, 42, 41, 37 },
			new int[10] { 7, 11, 13, 14, 19, 25, 28, 21, 22, 26 }
		};

		private readonly int[] decodeMiddleCounters;

		internal override BarcodeFormat BarcodeFormat => BarcodeFormat.UPCE;

		public UPCEDecoder()
		{
			decodeMiddleCounters = new int[4];
		}

		protected internal override int DecodeMiddle(MessagingToolkit.Barcode.Common.BitArray row, int[] startRange, StringBuilder result)
		{
			int[] array = decodeMiddleCounters;
			array[0] = 0;
			array[1] = 0;
			array[2] = 0;
			array[3] = 0;
			int size = row.GetSize();
			int num = startRange[1];
			int num2 = 0;
			for (int i = 0; i < 6; i++)
			{
				if (num >= size)
				{
					break;
				}
				int num3 = UPCEANDecoder.DecodeDigit(row, array, num, UPCEANDecoder.LAndGPatterns);
				result.Append((char)(48 + num3 % 10));
				for (int j = 0; j < array.Length; j++)
				{
					num += array[j];
				}
				if (num3 >= 10)
				{
					num2 |= 1 << 5 - i;
				}
			}
			DetermineNumSysAndCheckDigit(result, num2);
			return num;
		}

		internal override int[] DecodeEnd(MessagingToolkit.Barcode.Common.BitArray row, int endStart)
		{
			return UPCEANDecoder.FindGuardPattern(row, endStart, whiteFirst: true, MiddleEndPattern);
		}

		internal override bool CheckChecksum(string s)
		{
			return base.CheckChecksum(ConvertUPCEtoUPCA(s));
		}

		private static void DetermineNumSysAndCheckDigit(StringBuilder resultString, int lgPatternFound)
		{
			for (int i = 0; i <= 1; i++)
			{
				for (int j = 0; j < 10; j++)
				{
					if (lgPatternFound == NumSysAndCheckDigitPatterns[i][j])
					{
						resultString.Insert(0, (char)(48 + i));
						resultString.Append((char)(48 + j));
						return;
					}
				}
			}
			throw NotFoundException.Instance;
		}

		public static string ConvertUPCEtoUPCA(string upce)
		{
			char[] array = new char[6];
			upce.CopyTo(1, array, 0, 6);
			StringBuilder stringBuilder = new StringBuilder(12);
			stringBuilder.Append(upce[0]);
			char c = array[5];
			switch (c)
			{
			case '0':
			case '1':
			case '2':
				stringBuilder.Append(array, 0, 2);
				stringBuilder.Append(c);
				stringBuilder.Append("0000");
				stringBuilder.Append(array, 2, 3);
				break;
			case '3':
				stringBuilder.Append(array, 0, 3);
				stringBuilder.Append("00000");
				stringBuilder.Append(array, 3, 2);
				break;
			case '4':
				stringBuilder.Append(array, 0, 4);
				stringBuilder.Append("00000");
				stringBuilder.Append(array[4]);
				break;
			default:
				stringBuilder.Append(array, 0, 5);
				stringBuilder.Append("0000");
				stringBuilder.Append(c);
				break;
			}
			stringBuilder.Append(upce[7]);
			return stringBuilder.ToString();
		}
	}
