	internal class Codabar : BarcodeCommon, IBarcode
	{
		private Dictionary<char, string> CodabarCode = new Dictionary<char, string>();

		public string EncodedValue => EncodeCodabar();

		public Codabar(string input)
		{
			rawData = input;
		}

		private string EncodeCodabar()
		{
			if (rawData.Length < 2)
			{
				Error("Data Format invalid. (Invalid length)");
			}
			switch (rawData[0].ToString().ToUpper().Trim())
			{
			default:
				Error("Data Format invalid. (Invalid Start character)");
				break;
			case "A":
			case "B":
			case "C":
			case "D":
				break;
			}
			switch (rawData[rawData.Trim().Length - 1].ToString().ToUpper().Trim())
			{
			default:
				Error("Data Format invalid. (Invalid STOP character)");
				break;
			case "A":
			case "B":
			case "C":
			case "D":
				break;
			}
			string input = rawData.Trim().Substring(1, base.RawData.Trim().Length - 2);
			if (!IsNumeric(input))
			{
				Error("Data contains non-numeric characters.");
			}
			string text = "";
			init_Codabar();
			string text2 = rawData;
			foreach (char key in text2)
			{
				text += CodabarCode[key].ToString();
				text += "0";
			}
			text = text.Remove(text.Length - 1);
			CodabarCode.Clear();
			rawData = rawData.Trim().Substring(1, base.RawData.Trim().Length - 2);
			return text;
		}

		private void init_Codabar()
		{
			CodabarCode.Clear();
			CodabarCode.Add('0', "101010011");
