	internal class Code11 : BarcodeCommon, IBarcode
	{
		private string[] C11_Code = new string[12]
		{
			"101011", "1101011", "1001011", "1100101", "1011011", "1101101", "1001101", "1010011", "1101001", "110101",
			"101101", "1011001"
		};

		public string EncodedValue => Encode_Code11();

		public Code11(string input)
		{
			rawData = input;
		}

		private string Encode_Code11()
		{
			if (!BarcodeEncoder.CheckNumericOnly(rawData.Replace("-", "")))
			{
				Error("Numeric data and '-' Only");
			}
			int num = 1;
			int num2 = 0;
			string text = rawData;
			for (int num3 = rawData.Length - 1; num3 >= 0; num3--)
			{
				if (num == 10)
				{
					num = 1;
				}
				num2 = ((rawData[num3] == '-') ? (num2 + 10 * num++) : (num2 + int.Parse(rawData[num3].ToString()) * num++));
			}
			text += num2 % 11;
			if (rawData.Length >= 1)
			{
				num = 1;
				int num4 = 0;
				for (int num5 = text.Length - 1; num5 >= 0; num5--)
				{
					if (num == 9)
					{
						num = 1;
					}
					num4 = ((text[num5] == '-') ? (num4 + 10 * num++) : (num4 + int.Parse(text[num5].ToString()) * num++));
				}
				text += num4 % 11;
			}
			string text2 = "0";
			string text3 = C11_Code[11] + text2;
			string text4 = text;
			for (int i = 0; i < text4.Length; i++)
			{
				char c = text4[i];
				int num6 = ((c == '-') ? 10 : int.Parse(c.ToString()));
				text3 += C11_Code[num6];
				text3 += text2;
			}
			return text3 + C11_Code[11];
		}
	}
