		private List<DataRow> FindStartorCodeCharacter(string s, ref int col)
		{
			List<DataRow> list = new List<DataRow>();
			if (s.Length > 1 && char.IsNumber(s[0]) && char.IsNumber(s[1]))
			{
				if (StartCharacter == null)
				{
					StartCharacter = C128_Code.Select("A = 'START_C'")[0];
					list.Add(StartCharacter);
				}
				else
				{
					list.Add(C128_Code.Select("A = 'CODE_C'")[0]);
				}
				col = 1;
			}
			else
			{
				bool flag = false;
				bool flag2 = false;
				foreach (DataRow row in C128_Code.Rows)
				{
					try
					{
						if (!flag && s == row["A"].ToString())
						{
							flag = true;
							col = 2;
							if (StartCharacter == null)
							{
								StartCharacter = C128_Code.Select("A = 'START_A'")[0];
								list.Add(StartCharacter);
							}
							else
							{
								list.Add(C128_Code.Select("B = 'CODE_A'")[0]);
							}
						}
						else if (!flag2 && s == row["B"].ToString())
						{
							flag2 = true;
							col = 1;
							if (StartCharacter == null)
							{
								StartCharacter = C128_Code.Select("A = 'START_B'")[0];
								list.Add(StartCharacter);
							}
							else
							{
								list.Add(C128_Code.Select("A = 'CODE_B'")[0]);
							}
						}
						else if (flag && flag2)
						{
							break;
						}
					}
					catch (Exception ex)
					{
						Error("EC128-1: " + ex.Message);
					}
				}
				if (list.Count <= 0)
				{
					Error("EC128-2: Could not determine start character.");
				}
			}
			return list;
		}

		private string CalculateCheckDigit()
		{
			_ = _FormattedData[0];
			uint num = 0u;
			for (uint num2 = 0u; num2 < _FormattedData.Count; num2++)
			{
				string text = _FormattedData[(int)num2].Replace("'", "''");
				DataRow[] array = C128_Code.Select("A = '" + text + "'");
				if (array.Length == 0)
				{
					array = C128_Code.Select("B = '" + text + "'");
				}
				if (array.Length == 0)
				{
					array = C128_Code.Select("C = '" + text + "'");
				}
				uint num3 = uint.Parse(array[0]["Value"].ToString()) * ((num2 == 0) ? 1 : num2);
				num += num3;
			}
			uint num4 = num % 103;
			return C128_Code.Select("Value = '" + num4 + "'")[0]["Encoding"].ToString();
		}

		private void BreakUpDataForEncoding()
		{
			string text = "";
			string text2 = rawData;
			string text3;
			if (type == Types.A || type == Types.B)
			{
				text3 = rawData;
				foreach (char c in text3)
				{
					_FormattedData.Add(c.ToString());
				}
				return;
			}
			if (type == Types.C)
			{
				if (!IsNumeric(rawData))
				{
					Error("EC128-6: Only numeric values can be encoded with C128-C.");
				}
				if (rawData.Length % 2 > 0)
				{
					text2 = "0" + rawData;
				}
			}
			text3 = text2;
			for (int i = 0; i < text3.Length; i++)
			{
				char c2 = text3[i];
				if (char.IsNumber(c2))
				{
					if (text == "")
					{
						text += c2;
						continue;
					}
					text += c2;
					_FormattedData.Add(text);
					text = "";
				}
				else
				{
					if (text != "")
					{
						_FormattedData.Add(text);
						text = "";
					}
					_FormattedData.Add(c2.ToString());
				}
			}
			if (text != "")
			{
				_FormattedData.Add(text);
				text = "";
			}
		}

		private void InsertStartandCodeCharacters()
		{
			DataRow dataRow = null;
			string text = "";
			if (type != 0)
			{
				switch (type)
				{
				case Types.A:
					_FormattedData.Insert(0, "START_A");
					break;
				case Types.B:
					_FormattedData.Insert(0, "START_B");
					break;
				case Types.C:
					_FormattedData.Insert(0, "START_C");
					break;
				default:
					Error("EC128-4: Unknown start type in fixed type encoding.");
					break;
				}
				return;
			}
			try
			{
				for (int i = 0; i < _FormattedData.Count; i++)
				{
					int col = 0;
					List<DataRow> list = FindStartorCodeCharacter(_FormattedData[i], ref col);
					bool flag = false;
					foreach (DataRow item in list)
					{
						if (item["A"].ToString().EndsWith(text) || item["B"].ToString().EndsWith(text) || item["C"].ToString().EndsWith(text))
						{
							flag = true;
							break;
						}
					}
					if (!(text == "") && flag)
					{
						continue;
					}
					dataRow = list[0];
					bool flag2 = true;
					while (flag2)
					{
						try
						{
							text = dataRow[col].ToString().Split(new char[1] { '_' })[1];
							flag2 = false;
						}
						catch
						{
							flag2 = true;
							if (col++ > dataRow.ItemArray.Length)
							{
								Error("No start character found in CurrentCodeSet.");
							}
						}
					}
					_FormattedData.Insert(i++, dataRow[col].ToString());
				}
			}
			catch (Exception ex)
			{
				Error("EC128-3: Could not insert start and code characters.\n Message: " + ex.Message);
			}
		}

		private string GetEncoding()
		{
			BreakUpDataForEncoding();
			InsertStartandCodeCharacters();
			CalculateCheckDigit();
			string text = "";
			foreach (string formattedDatum in _FormattedData)
			{
				string text2 = formattedDatum.Replace("'", "''");
				DataRow[] array;
				switch (type)
				{
				case Types.A:
					array = C128_Code.Select("A = '" + text2 + "'");
					break;
				case Types.B:
					array = C128_Code.Select("B = '" + text2 + "'");
					break;
				case Types.C:
					array = C128_Code.Select("C = '" + text2 + "'");
					break;
				case Types.Dynamic:
					array = C128_Code.Select("A = '" + text2 + "'");
					if (array.Length == 0)
					{
						array = C128_Code.Select("B = '" + text2 + "'");
						if (array.Length == 0)
						{
							array = C128_Code.Select("C = '" + text2 + "'");
						}
					}
					break;
				default:
					array = null;
					break;
				}
				if (array == null || array.Length == 0)
				{
					Error("EC128-5: Could not find encoding of a value( " + text2 + " ) in C128 type " + type);
				}
				text += array[0]["Encoding"].ToString();
				_EncodedData.Add(array[0]["Encoding"].ToString());
			}
			text += CalculateCheckDigit();
			_EncodedData.Add(CalculateCheckDigit());
			text += C128_Code.Select("A = 'STOP'")[0]["Encoding"].ToString();
			_EncodedData.Add(C128_Code.Select("A = 'STOP'")[0]["Encoding"].ToString());
			text += "11";
			_EncodedData.Add("11");
			return text;
		}
	}
