		private string Add_CheckDigits(string input)
		{
			int[] array = new int[input.Length];
			int num = 1;
			for (int num2 = input.Length - 1; num2 >= 0; num2--)
			{
				if (num > 20)
				{
					num = 1;
				}
				array[num2] = num;
				num++;
			}
			int[] array2 = new int[input.Length + 1];
			num = 1;
			for (int num3 = input.Length; num3 >= 0; num3--)
			{
				if (num > 15)
				{
					num = 1;
				}
				array2[num3] = num;
				num++;
			}
			int num4 = 0;
			for (int i = 0; i < input.Length; i++)
			{
				num4 += array[i] * int.Parse(C93_Code.Select("Character = '" + input[i] + "'")[0]["Value"].ToString());
			}
			int num5 = num4 % 47;
			input += C93_Code.Select("Value = '" + num5 + "'")[0]["Character"].ToString();
			num4 = 0;
			for (int j = 0; j < input.Length; j++)
			{
				num4 += array2[j] * int.Parse(C93_Code.Select("Character = '" + input[j] + "'")[0]["Value"].ToString());
			}
			num5 = num4 % 47;
			input += C93_Code.Select("Value = '" + num5 + "'")[0]["Character"].ToString();
			return input;
		}
	}
	internal class EAN13 : BarcodeCommon, IBarcode
	{
		private string[] EAN_CodeA = new string[10] { "0001101", "0011001", "0010011", "0111101", "0100011", "0110001", "0101111", "0111011", "0110111", "0001011" };

		private string[] EAN_CodeB = new string[10] { "0100111", "0110011", "0011011", "0100001", "0011101", "0111001", "0000101", "0010001", "0001001", "0010111" };

		private string[] EAN_CodeC = new string[10] { "1110010", "1100110", "1101100", "1000010", "1011100", "1001110", "1010000", "1000100", "1001000", "1110100" };

		private string[] EAN_Pattern = new string[10] { "aaaaaa", "aababb", "aabbab", "aabbba", "abaabb", "abbaab", "abbbaa", "ababab", "ababba", "abbaba" };

		private Dictionary<string, string> CountryCodes = new Dictionary<string, string>();

		private string _Country_Assigning_Manufacturer_Code = "N/A";

		public string EncodedValue => Encode_EAN13();

		public EAN13(string input)
		{
			rawData = input;
			CheckDigit();
		}

		private string Encode_EAN13()
		{
			if (rawData.Length < 12 || rawData.Length > 13)
			{
				Error("Data length invalid. (Length must be 12 or 13)");
			}
			if (!BarcodeEncoder.CheckNumericOnly(rawData))
			{
				Error("Numeric data Only");
			}
			string text = EAN_Pattern[int.Parse(rawData[0].ToString())];
			string text2 = "101";
			int i;
			for (i = 0; i < 6; i++)
			{
				if (text[i] == 'a')
				{
					text2 += EAN_CodeA[int.Parse(rawData[i + 1].ToString())];
				}
				if (text[i] == 'b')
				{
					text2 += EAN_CodeB[int.Parse(rawData[i + 1].ToString())];
				}
			}
			text2 += "01010";
			i = 1;
			while (i <= 5)
			{
				text2 += EAN_CodeC[int.Parse(rawData[i++ + 6].ToString())];
			}
			int num = int.Parse(rawData[rawData.Length - 1].ToString());
			text2 += EAN_CodeC[num];
			text2 += "101";
			init_CountryCodes();
			_Country_Assigning_Manufacturer_Code = "N/A";
			string key = rawData.Substring(0, 2);
			string key2 = rawData.Substring(0, 3);
			try
			{
				_Country_Assigning_Manufacturer_Code = CountryCodes[key2].ToString();
			}
			catch
			{
				try
				{
					_Country_Assigning_Manufacturer_Code = CountryCodes[key].ToString();
				}
				catch
				{
					Error("Country assigning manufacturer code not found.");
				}
			}
			finally
			{
				CountryCodes.Clear();
			}
			return text2;
		}

