		private void CheckDigit()
		{
			try
			{
				string text = rawData.Substring(0, 12);
				int num = 0;
				int num2 = 0;
				for (int i = 0; i < text.Length; i++)
				{
					if (i % 2 == 0)
					{
						num2 += int.Parse(text.Substring(i, 1));
					}
					else
					{
						num += int.Parse(text.Substring(i, 1)) * 3;
					}
				}
				int num3 = (num + num2) % 10;
				num3 = 10 - num3;
				if (num3 == 10)
				{
					num3 = 0;
				}
				rawData = text + num3.ToString()[0];
			}
			catch
			{
				Error("Error calculating check digit.");
			}
		}
	}
	internal class EAN8 : BarcodeCommon, IBarcode
	{
		private string[] EAN_CodeA = new string[10] { "0001101", "0011001", "0010011", "0111101", "0100011", "0110001", "0101111", "0111011", "0110111", "0001011" };

		private string[] EAN_CodeC = new string[10] { "1110010", "1100110", "1101100", "1000010", "1011100", "1001110", "1010000", "1000100", "1001000", "1110100" };

		public string EncodedValue => Encode_EAN8();

		public EAN8(string input)
		{
			rawData = input;
			CheckDigit();
		}

		private string Encode_EAN8()
		{
			if (rawData.Length != 8 && rawData.Length != 7)
			{
				Error("Invalid data length. (7 or 8 numbers only)");
			}
			if (!BarcodeEncoder.CheckNumericOnly(rawData))
			{
				Error("Numeric only.");
			}
			string text = "101";
			for (int i = 0; i < rawData.Length / 2; i++)
			{
				text += EAN_CodeA[int.Parse(rawData[i].ToString())];
			}
			text += "01010";
			for (int j = rawData.Length / 2; j < rawData.Length; j++)
			{
				text += EAN_CodeC[int.Parse(rawData[j].ToString())];
			}
			return text + "101";
		}

		private void CheckDigit()
		{
			if (rawData.Length == 7)
			{
				int num = 0;
				int num2 = 0;
				for (int i = 0; i <= 6; i += 2)
				{
					num2 += int.Parse(rawData.Substring(i, 1)) * 3;
				}
				for (int j = 1; j <= 5; j += 2)
				{
					num += int.Parse(rawData.Substring(j, 1));
				}
				int num3 = (num + num2) % 10;
				num3 = 10 - num3;
				if (num3 == 10)
				{
					num3 = 0;
				}
				rawData += num3;
			}
		}
	}
	internal class FIM : BarcodeCommon, IBarcode
	{
		public enum FIMTypes
		{
			FIM_A,
			FIM_B,
			FIM_C,
			FIM_D
		}

		private string[] FIM_Codes = new string[4] { "110010011", "101101101", "110101011", "111010111" };

		public string EncodedValue => Encode_FIM();

		public FIM(string input)
		{
			input = input.Trim();
			switch (input)
			{
			case "A":
			case "a":
				rawData = FIM_Codes[0];
				break;
			case "B":
			case "b":
				rawData = FIM_Codes[1];
				break;
			case "C":
			case "c":
				rawData = FIM_Codes[2];
				break;
			case "D":
			case "d":
				rawData = FIM_Codes[3];
				break;
			default:
				Error("Could not determine encoding type. (Only pass in A, B, C, or D)");
				break;
			}
		}

		public string Encode_FIM()
		{
			string text = "";
			string text2 = base.RawData;
			for (int i = 0; i < text2.Length; i++)
			{
				text = text + text2[i] + "0";
			}
			return text.Substring(0, text.Length - 1);
		}
	}
	internal class Interleaved2of5 : BarcodeCommon, IBarcode
	{
		private string[] I25_Code = new string[10] { "NNWWN", "WNNNW", "NWNNW", "WWNNN", "NNWNW", "WNWNN", "NWWNN", "NNNWW", "WNNWN", "NWNWN" };

		public string EncodedValue => Encode_Interleaved2of5();

		public Interleaved2of5(string input)
		{
			rawData = input;
		}

		private string Encode_Interleaved2of5()
		{
			if (rawData.Length % 2 != 0)
			{
				Error("Data length invalid.");
			}
			if (!BarcodeEncoder.CheckNumericOnly(rawData))
			{
				Error("Numeric data Only");
			}
			string text = "1010";
			for (int i = 0; i < rawData.Length; i += 2)
			{
				bool flag = true;
				string text2 = I25_Code[int.Parse(rawData[i].ToString())];
				string text3 = I25_Code[int.Parse(rawData[i + 1].ToString())];
				string text4 = "";
				while (text2.Length > 0)
				{
					text4 = text4 + text2[0] + text3[0];
					text2 = text2.Substring(1);
					text3 = text3.Substring(1);
				}
				string text5 = text4;
				foreach (char c in text5)
				{
					text = ((!flag) ? ((c != 'N') ? (text + "00") : (text + "0")) : ((c != 'N') ? (text + "11") : (text + "1")));
					flag = !flag;
				}
			}
			return text + "1101";
		}
	}
	internal class ISBN : BarcodeCommon, IBarcode
	{
		public string EncodedValue => Encode_ISBN_Bookland();

		public ISBN(string input)
		{
			rawData = input;
		}

		private string Encode_ISBN_Bookland()
		{
			if (!BarcodeEncoder.CheckNumericOnly(rawData))
			{
				Error("Numeric data Only");
			}
			string text = "UNKNOWN";
			if (rawData.Length == 10 || rawData.Length == 9)
			{
				if (rawData.Length == 10)
				{
					rawData = rawData.Remove(9, 1);
				}
				rawData = "978" + rawData;
				text = "ISBN";
			}
			else if (rawData.Length == 12 && rawData.StartsWith("978"))
			{
				text = "Bookland-NOCHECKDIGIT";
			}
			else if (rawData.Length == 13 && rawData.StartsWith("978"))
			{
				text = "Bookland-CHECKDIGIT";
				rawData = rawData.Remove(12, 1);
			}
			if (text == "UNKNOWN")
			{
				Error("Invalid input.  Must start with 978 and the length must be 9, 10, 12, 13 characters.");
			}
			return new EAN13(rawData).EncodedValue;
		}
	}
