	internal class MSI : BarcodeCommon, IBarcode
	{
		private string[] MSI_Code = new string[10] { "100100100100", "100100100110", "100100110100", "100100110110", "100110100100", "100110100110", "100110110100", "100110110110", "110100100100", "110100100110" };

		private BarcodeFormat Encoded_Type;

		public string EncodedValue => Encode_MSI();

		public MSI(string input, BarcodeFormat EncodedType)
		{
			Encoded_Type = EncodedType;
			rawData = input;
		}

		private string Encode_MSI()
		{
			if (!BarcodeEncoder.CheckNumericOnly(rawData))
			{
				Error("Numeric data Only");
			}
			string text = rawData;
			string text4;
			if (Encoded_Type == BarcodeFormat.MSIMod10 || Encoded_Type == BarcodeFormat.MSI2Mod10)
			{
				string text2 = "";
				string text3 = "";
				for (int num = text.Length - 1; num >= 0; num -= 2)
				{
					text2 = text[num] + text2;
					if (num - 1 >= 0)
					{
						text3 = text[num - 1] + text3;
					}
				}
				text2 = Convert.ToString(int.Parse(text2) * 2);
				int num2 = 0;
				int num3 = 0;
				text4 = text3;
				for (int i = 0; i < text4.Length; i++)
				{
					num2 += int.Parse(text4[i].ToString());
				}
				text4 = text2;
				for (int i = 0; i < text4.Length; i++)
				{
					num3 += int.Parse(text4[i].ToString());
				}
				text += 10 - (num3 + num2) % 10;
			}
			if (Encoded_Type == BarcodeFormat.MSIMod11 || Encoded_Type == BarcodeFormat.MSIMod11Mod10)
			{
				int num4 = 0;
				int num5 = 2;
				for (int num6 = text.Length - 1; num6 >= 0; num6--)
				{
					if (num5 > 7)
					{
						num5 = 2;
					}
					num4 += int.Parse(text[num6].ToString()) * num5++;
				}
				text += 11 - num4 % 11;
			}
			if (Encoded_Type == BarcodeFormat.MSI2Mod10 || Encoded_Type == BarcodeFormat.MSIMod11Mod10)
			{
				string text5 = "";
				string text6 = "";
				for (int num7 = text.Length - 1; num7 >= 0; num7 -= 2)
				{
					text5 = text[num7] + text5;
					if (num7 - 1 >= 0)
					{
						text6 = text[num7 - 1] + text6;
					}
				}
				text5 = Convert.ToString(int.Parse(text5) * 2);
				int num8 = 0;
				int num9 = 0;
				text4 = text6;
				for (int i = 0; i < text4.Length; i++)
				{
					num8 += int.Parse(text4[i].ToString());
				}
				text4 = text5;
				for (int i = 0; i < text4.Length; i++)
				{
					num9 += int.Parse(text4[i].ToString());
				}
				text += 10 - (num9 + num8) % 10;
			}
			string text7 = "110";
			text4 = text;
			foreach (char c in text4)
			{
				text7 += MSI_Code[int.Parse(c.ToString())];
			}
			return text7 + "1001";
		}
	}
	internal class Postnet : BarcodeCommon, IBarcode
	{
		private string[] POSTNET_Code = new string[10] { "11000", "00011", "00101", "00110", "01001", "01010", "01100", "10001", "10010", "10100" };

		public string EncodedValue => Encode_Postnet();

		public Postnet(string input)
		{
			rawData = input;
		}

		private string Encode_Postnet()
		{
			rawData = rawData.Replace("-", "");
			switch (rawData.Length)
			{
			default:
				Error("Invalid data length. (5, 6, 9, or 11 digits only)");
				break;
			case 5:
			case 6:
			case 9:
			case 11:
				break;
			}
			string text = "1";
			int num = 0;
			string text2 = rawData;
			for (int i = 0; i < text2.Length; i++)
			{
				char c = text2[i];
				try
				{
					int num2 = Convert.ToInt32(c.ToString());
					text += POSTNET_Code[num2];
					num += num2;
				}
				catch (Exception ex)
				{
					Error("Invalid data. (Numeric only) --> " + ex.Message);
				}
			}
			int num3 = num % 10;
			int num4 = 10 - ((num3 == 0) ? 10 : num3);
			text += POSTNET_Code[num4];
			return text + "1";
		}
	}
