	internal class Telepen : BarcodeCommon, IBarcode
	{
		private enum StartStopCode
		{
			START1,
			STOP1,
			START2,
			STOP2,
			START3,
			STOP3
		}

		private static Dictionary<object, string> Telepen_Code = new Dictionary<object, string>();

		private StartStopCode StartCode;

		private StartStopCode StopCode = StartStopCode.STOP1;

		private int SwitchModeIndex;

		private int iCheckSum;

		public string EncodedValue => Encode_Telepen();

		public Telepen(string input)
		{
			rawData = input;
		}

		private string Encode_Telepen()
		{
			if (Telepen_Code.Count == 0)
			{
				Init_Telepen();
			}
			iCheckSum = 0;
			string text = "";
			SetEncodingSequence();
			text = Telepen_Code[StartCode].ToString();
			switch (StartCode)
			{
			case StartStopCode.START2:
				EncodeNumeric(base.RawData.Substring(0, SwitchModeIndex), ref text);
				if (SwitchModeIndex < base.RawData.Length)
				{
					EncodeSwitchMode(ref text);
					EncodeASCII(base.RawData.Substring(SwitchModeIndex), ref text);
				}
				break;
			case StartStopCode.START3:
				EncodeASCII(base.RawData.Substring(0, SwitchModeIndex), ref text);
				EncodeSwitchMode(ref text);
				EncodeNumeric(base.RawData.Substring(SwitchModeIndex), ref text);
				break;
			default:
				EncodeASCII(base.RawData, ref text);
				break;
			}
			text += Telepen_Code[Calculate_Checksum(iCheckSum)];
			return text + Telepen_Code[StopCode];
		}

		private void EncodeASCII(string input, ref string output)
		{
			try
			{
				foreach (char c in input)
				{
					output += Telepen_Code[c];
					iCheckSum += Convert.ToInt32(c);
				}
			}
			catch
			{
				Error("Invalid data when encoding ASCII");
			}
		}

		private void EncodeNumeric(string input, ref string output)
		{
			try
			{
				if (input.Length % 2 > 0)
				{
					Error("Numeric encoding attempted on odd number of characters");
				}
				for (int i = 0; i < input.Length; i += 2)
				{
					output += Telepen_Code[Convert.ToChar(int.Parse(input.Substring(i, 2)) + 27)];
					iCheckSum += int.Parse(input.Substring(i, 2)) + 27;
				}
			}
			catch
			{
				Error("Numeric encoding failed");
			}
		}

		private void EncodeSwitchMode(ref string output)
		{
			iCheckSum += 16;
			output += Telepen_Code[Convert.ToChar(16)];
		}

		private char Calculate_Checksum(int iCheckSum)
		{
			return Convert.ToChar(127 - iCheckSum % 127);
		}

		private void SetEncodingSequence()
		{
			StartCode = StartStopCode.START1;
			StopCode = StartStopCode.STOP1;
			SwitchModeIndex = rawData.Length;
			int num = 0;
			string text = rawData;
			for (int i = 0; i < text.Length && char.IsNumber(text[i]); i++)
			{
				num++;
			}
			if (num == rawData.Length)
			{
				StartCode = StartStopCode.START2;
				StopCode = StartStopCode.STOP2;
				if (rawData.Length % 2 > 0)
				{
					SwitchModeIndex = base.RawData.Length - 1;
				}
				return;
			}
			int num2 = 0;
			int num3 = rawData.Length - 1;
			while (num3 >= 0 && char.IsNumber(rawData[num3]))
			{
				num2++;
				num3--;
			}
			if (num >= 4 || num2 >= 4)
			{
				if (num > num2)
				{
					StartCode = StartStopCode.START2;
					StopCode = StartStopCode.STOP2;
					SwitchModeIndex = ((num % 2 == 1) ? (num - 1) : num);
				}
				else
				{
					StartCode = StartStopCode.START3;
					StopCode = StartStopCode.STOP3;
					SwitchModeIndex = ((num2 % 2 == 1) ? (rawData.Length - num2 + 1) : (rawData.Length - num2));
				}
			}
		}

