		{
			if (rawData.Length != 11 && rawData.Length != 12)
			{
				Error("Data length invalid. (Length must be 11 or 12)");
			}
			if (!BarcodeEncoder.CheckNumericOnly(rawData))
			{
				Error("Numeric data Only");
			}
			CheckDigit();
			string text = "101";
			text += UPC_CodeA[int.Parse(rawData[0].ToString())];
			int i;
			for (i = 0; i < 5; i++)
			{
				text += UPC_CodeA[int.Parse(rawData[i + 1].ToString())];
			}
			text += "01010";
			i = 0;
			while (i < 5)
			{
				text += UPC_CodeB[int.Parse(rawData[i++ + 6].ToString())];
			}
			text += UPC_CodeB[int.Parse(rawData[rawData.Length - 1].ToString())];
			text += "101";
			init_CountryCodes();
			string key = "0" + rawData.Substring(0, 1);
			try
			{
				_Country_Assigning_Manufacturer_Code = CountryCodes[key].ToString();
			}
			catch
			{
				Error("Country assigning manufacturer code not found.");
