		private void CheckDigit()
		{
			try
			{
				string text = rawData.Substring(0, 11);
				int num = 0;
				int num2 = 0;
				for (int i = 0; i < text.Length; i++)
				{
					if (i % 2 == 0)
					{
						num2 += int.Parse(text.Substring(i, 1)) * 3;
					}
					else
					{
						num += int.Parse(text.Substring(i, 1));
					}
				}
				int num3 = (num + num2) % 10;
				num3 = 10 - num3;
				if (num3 == 10)
				{
					num3 = 0;
				}
				rawData = text + num3.ToString()[0];
			}
			catch
			{
				Error("Error calculating check digit.");
			}
		}
	}
	internal class UPCE : BarcodeCommon, IBarcode
	{
		private string[] EAN_CodeA = new string[10] { "0001101", "0011001", "0010011", "0111101", "0100011", "0110001", "0101111", "0111011", "0110111", "0001011" };

		private string[] EAN_CodeB = new string[10] { "0100111", "0110011", "0011011", "0100001", "0011101", "0111001", "0000101", "0010001", "0001001", "0010111" };

		private string[] EAN_CodeC = new string[10] { "1110010", "1100110", "1101100", "1000010", "1011100", "1001110", "1010000", "1000100", "1001000", "1110100" };

		private string[] EAN_Pattern = new string[10] { "aaaaaa", "aababb", "aabbab", "aabbba", "abaabb", "abbaab", "abbbaa", "ababab", "ababba", "abbaba" };

		private string[] UPCE_Code_0 = new string[10] { "bbbaaa", "bbabaa", "bbaaba", "bbaaab", "babbaa", "baabba", "baaabb", "bababa", "babaab", "baabab" };

		private string[] UPCE_Code_1 = new string[10] { "aaabbb", "aababb", "aabbab", "aabbba", "abaabb", "abbaab", "abbbaa", "ababab", "ababba", "abbaba" };

		public string EncodedValue => Encode_UPCE();

		public UPCE(string input)
		{
			rawData = input;
		}

		private string Encode_UPCE()
		{
			if (rawData.Length != 6 && rawData.Length != 8 && rawData.Length != 12)
			{
				Error("Invalid data length. (8 or 12 numbers only)");
			}
			if (!BarcodeEncoder.CheckNumericOnly(rawData))
			{
				Error("Numeric only.");
			}
			int num = int.Parse(rawData[rawData.Length - 1].ToString());
			int num2 = int.Parse(rawData[0].ToString());
			if (rawData.Length == 12)
			{
				string text = "";
				string text2 = rawData.Substring(1, 5);
				string text3 = rawData.Substring(6, 5);
				if (num2 != 0 && num2 != 1)
				{
					Error("Invalid Number System (only 0 & 1 are valid)");
				}
				if (text2.EndsWith("000") || text2.EndsWith("100") || (text2.EndsWith("200") && int.Parse(text3) <= 999))
				{
					text += text2.Substring(0, 2);
					text += text3.Substring(2, 3);
					text += text2[2];
				}
				else if (text2.EndsWith("00") && int.Parse(text3) <= 99)
				{
					text += text2.Substring(0, 3);
					text += text3.Substring(3, 2);
					text += "3";
				}
				else if (text2.EndsWith("0") && int.Parse(text3) <= 9)
				{
					text += text2.Substring(0, 4);
					text += text3[4];
					text += "4";
				}
				else if (!text2.EndsWith("0") && int.Parse(text3) <= 9 && int.Parse(text3) >= 5)
				{
					text += text2;
					text += text3[4];
				}
				else
				{
					Error("Illegal UPC-A entered for conversion.  Unable to convert.");
				}
				rawData = text;
			}
			string text4 = "";
			text4 = ((num2 != 0) ? UPCE_Code_1[num] : UPCE_Code_0[num]);
			string text5 = "101";
			int num3 = 0;
			string text6 = text4;
			foreach (char c in text6)
			{
				int num4 = int.Parse(rawData[num3++].ToString());
				switch (c)
				{
				case 'a':
					text5 += EAN_CodeA[num4];
					break;
				case 'b':
					text5 += EAN_CodeB[num4];
					break;
				}
			}
			text5 += "01010";
			return text5 + "1";
		}
	}
