	public abstract class AbstractRssDecoder : OneDDecoder
	{
		private static int MaxAvgVariance = 51;

		private static int MaxIndividualVariance = 115;

		private const float MinFinderPatternRatio = 19f / 24f;

		private const float MaxFinderPatternRatio = 25f / 28f;

		protected internal readonly int[] decodeFinderCounters;

		protected internal readonly int[] dataCharacterCounters;

		protected internal readonly float[] oddRoundingErrors;

		protected internal readonly float[] evenRoundingErrors;

		protected internal readonly int[] oddCounts;

		protected internal readonly int[] evenCounts;

		protected int[] DecodeFinderCounters => decodeFinderCounters;

		protected int[] DataCharacterCounters => dataCharacterCounters;

		protected float[] OddRoundingErrors => oddRoundingErrors;

		protected float[] EvenRoundingErrors => evenRoundingErrors;

		protected int[] OddCounts => oddCounts;

		protected int[] EvenCounts => evenCounts;

		protected internal AbstractRssDecoder()
		{
			decodeFinderCounters = new int[4];
			dataCharacterCounters = new int[8];
			oddRoundingErrors = new float[4];
			evenRoundingErrors = new float[4];
			oddCounts = new int[dataCharacterCounters.Length / 2];
			evenCounts = new int[dataCharacterCounters.Length / 2];
		}

		protected internal static int ParseFinderValue(int[] counters, int[][] finderPatterns)
		{
			for (int i = 0; i < finderPatterns.Length; i++)
			{
				if (OneDDecoder.PatternMatchVariance(counters, finderPatterns[i], MaxIndividualVariance) < MaxAvgVariance)
				{
					return i;
				}
			}
			throw NotFoundException.Instance;
		}

		protected internal static int Count(int[] array)
		{
			int num = 0;
			for (int i = 0; i < array.Length; i++)
			{
				num += array[i];
			}
			return num;
		}

		protected internal static void Increment(int[] array, float[] errors)
		{
			int num = 0;
			float num2 = errors[0];
			for (int i = 1; i < array.Length; i++)
			{
				if (errors[i] > num2)
				{
					num2 = errors[i];
					num = i;
				}
			}
			array[num]++;
		}

		protected internal static void Decrement(int[] array, float[] errors)
		{
			int num = 0;
			float num2 = errors[0];
			for (int i = 1; i < array.Length; i++)
			{
				if (errors[i] < num2)
				{
					num2 = errors[i];
					num = i;
				}
			}
			array[num]--;
		}

		protected internal static bool IsFinderPattern(int[] counters)
		{
			int num = counters[0] + counters[1];
			int num2 = num + counters[2] + counters[3];
			float num3 = (float)num / (float)num2;
			if (num3 >= 19f / 24f && num3 <= 25f / 28f)
			{
				int num4 = int.MaxValue;
				int num5 = int.MinValue;
				foreach (int num6 in counters)
				{
					if (num6 > num5)
					{
						num5 = num6;
					}
					if (num6 < num4)
					{
						num4 = num6;
					}
				}
				return num5 < 10 * num4;
			}
			return false;
		}
	}
	public class DataCharacter
	{
		private readonly int val;

		private readonly int checksumPortion;

		public int Value => val;

		public int ChecksumPortion => checksumPortion;

		public DataCharacter(int value, int checksumPortion)
		{
			val = value;
			this.checksumPortion = checksumPortion;
		}

		public override string ToString()
		{
			return Value + "(" + ChecksumPortion + ")";
		}

		public override bool Equals(object o)
		{
			if (!(o is DataCharacter))
			{
				return false;
			}
			DataCharacter dataCharacter = (DataCharacter)o;
			if (Value == dataCharacter.Value)
			{
				return ChecksumPortion == dataCharacter.ChecksumPortion;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return Value ^ ChecksumPortion;
		}
	}
