		private static readonly int[] InsideOddTotalSubset = new int[4] { 4, 20, 48, 81 };

		private static readonly int[] OutsideGSum = new int[5] { 0, 161, 961, 2015, 2715 };

		private static readonly int[] InsideGSum = new int[4] { 0, 336, 1036, 1516 };

		private static readonly int[] OutsideOddWidest = new int[5] { 8, 6, 4, 3, 1 };

		private static readonly int[] InsideOddWidest = new int[4] { 2, 4, 6, 8 };

		private static readonly int[][] FinderPatterns = new int[9][]
		{
			new int[4] { 3, 8, 2, 1 },
			new int[4] { 3, 5, 5, 1 },
			new int[4] { 3, 3, 7, 1 },
			new int[4] { 3, 1, 9, 1 },
			new int[4] { 2, 7, 4, 1 },
			new int[4] { 2, 5, 6, 1 },
			new int[4] { 2, 3, 8, 1 },
			new int[4] { 1, 5, 7, 1 },
			new int[4] { 1, 3, 9, 1 }
		};

		private readonly List<Pair> possibleLeftPairs;

		private readonly List<Pair> possibleRightPairs;

		public Rss14Decoder()
		{
			possibleLeftPairs = new List<Pair>();
			possibleRightPairs = new List<Pair>();
		}

		public override Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, Dictionary<DecodeOptions, object> decodingOptions)
		{
			Pair pair = DecodePair(row, right: false, rowNumber, decodingOptions);
			AddOrTally(possibleLeftPairs, pair);
			row.Reverse();
			Pair pair2 = DecodePair(row, right: true, rowNumber, decodingOptions);
			AddOrTally(possibleRightPairs, pair2);
			row.Reverse();
			int count = possibleLeftPairs.Count;
			for (int i = 0; i < count; i++)
			{
				Pair pair3 = possibleLeftPairs[i];
				if (pair3.Count <= 1)
				{
					continue;
				}
				int count2 = possibleRightPairs.Count;
				for (int j = 0; j < count2; j++)
				{
					Pair pair4 = possibleRightPairs[j];
					if (pair4.Count > 1 && CheckChecksum(pair3, pair4))
					{
						return ConstructResult(pair3, pair4);
					}
				}
			}
			throw NotFoundException.Instance;
		}

		private static void AddOrTally(List<Pair> possiblePairs, Pair pair)
		{
			if (pair == null)
			{
				return;
			}
			IEnumerator enumerator = possiblePairs.GetEnumerator();
			bool flag = false;
			while (enumerator.MoveNext())
			{
				Pair pair2 = (Pair)enumerator.Current;
				if (pair2.Value == pair.Value)
				{
					pair2.IncrementCount();
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				possiblePairs.Add(pair);
			}
		}

		public override void Reset()
		{
			possibleLeftPairs.RemoveRange(0, possibleLeftPairs.Count);
			possibleRightPairs.RemoveRange(0, possibleRightPairs.Count);
		}

		private static Result ConstructResult(Pair leftPair, Pair rightPair)
		{
			string text = (4537077L * (long)leftPair.Value + rightPair.Value).ToString();
			StringBuilder stringBuilder = new StringBuilder(14);
			for (int num = 13 - text.Length; num > 0; num--)
			{
				stringBuilder.Append('0');
			}
			stringBuilder.Append(text);
			int num2 = 0;
			for (int i = 0; i < 13; i++)
			{
				int num3 = stringBuilder[i] - 48;
				num2 += (((i & 1) == 0) ? (3 * num3) : num3);
			}
			num2 = 10 - num2 % 10;
			if (num2 == 10)
			{
				num2 = 0;
			}
			stringBuilder.Append(num2);
			ResultPoint[] resultPoints = leftPair.FinderPattern.ResultPoints;
			ResultPoint[] resultPoints2 = rightPair.FinderPattern.ResultPoints;
			return new Result(stringBuilder.ToString().ToString(), null, new ResultPoint[4]
			{
				resultPoints[0],
				resultPoints[1],
				resultPoints2[0],
				resultPoints2[1]
