			if (num2 > 72)
			{
				num2--;
			}
			if (num2 > 8)
			{
				num2--;
			}
			return num == num2;
		}

		private Pair DecodePair(MessagingToolkit.Barcode.Common.BitArray row, bool right, int rowNumber, Dictionary<DecodeOptions, object> decodingOptions)
