		private int[] FindFinderPattern(MessagingToolkit.Barcode.Common.BitArray row, int rowOffset, bool rightFinderPattern)
		{
			int[] array = decodeFinderCounters;
			array[0] = 0;
			array[1] = 0;
			array[2] = 0;
			array[3] = 0;
			int size = row.GetSize();
			bool flag = false;
			while (rowOffset < size)
			{
				flag = !row.Get(rowOffset);
				if (rightFinderPattern == flag)
				{
					break;
				}
				rowOffset++;
			}
			int num = 0;
			int num2 = rowOffset;
			for (int i = rowOffset; i < size; i++)
			{
				if (row.Get(i) ^ flag)
				{
					array[num]++;
					continue;
				}
				if (num == 3)
				{
					if (AbstractRssDecoder.IsFinderPattern(array))
					{
						return new int[2] { num2, i };
					}
					num2 += array[0] + array[1];
					array[0] = array[2];
					array[1] = array[3];
					array[2] = 0;
					array[3] = 0;
					num--;
				}
				else
				{
					num++;
				}
				array[num] = 1;
				flag = !flag;
			}
			throw NotFoundException.Instance;
		}

		private FinderPattern ParseFoundFinderPattern(MessagingToolkit.Barcode.Common.BitArray row, int rowNumber, bool right, int[] startEnd)
		{
			bool flag = row.Get(startEnd[0]);
			int num = startEnd[0] - 1;
			while (num >= 0 && (flag ^ row.Get(num)))
			{
				num--;
			}
			num++;
			int num2 = startEnd[0] - num;
			int[] array = decodeFinderCounters;
			for (int num3 = array.Length - 1; num3 > 0; num3--)
			{
				array[num3] = array[num3 - 1];
			}
			array[0] = num2;
			int value = AbstractRssDecoder.ParseFinderValue(array, FinderPatterns);
			int num4 = num;
			int num5 = startEnd[1];
			if (right)
			{
				num4 = row.GetSize() - 1 - num4;
				num5 = row.GetSize() - 1 - num5;
			}
			return new FinderPattern(value, new int[2]
			{
				num,
				startEnd[1]
			}, num4, num5, rowNumber);
		}

