			if (flag4)
			{
				AbstractRssDecoder.Decrement(oddCounts, oddRoundingErrors);
			}
			if (flag5)
			{
				if (flag6)
				{
					throw NotFoundException.Instance;
				}
				AbstractRssDecoder.Increment(evenCounts, oddRoundingErrors);
			}
			if (flag6)
			{
				AbstractRssDecoder.Decrement(evenCounts, evenRoundingErrors);
			}
		}
	}
	public sealed class RssUtils
	{
		private RssUtils()
		{
		}

		internal static int[] GetRssWidths(int val, int n, int elements, int maxWidth, bool noNarrow)
		{
			int[] array = new int[elements];
			int num = 0;
			int i;
			for (i = 0; i < elements - 1; i++)
			{
				num |= 1 << i;
				int num2 = 1;
				int num3;
				while (true)
				{
					num3 = Combins(n - num2 - 1, elements - i - 2);
					if (noNarrow && num == 0 && n - num2 - (elements - i - 1) >= elements - i - 1)
					{
						num3 -= Combins(n - num2 - (elements - i), elements - i - 2);
					}
					if (elements - i - 1 > 1)
					{
						int num4 = 0;
						for (int num5 = n - num2 - (elements - i - 2); num5 > maxWidth; num5--)
						{
							num4 += Combins(n - num2 - num5 - 1, elements - i - 3);
						}
						num3 -= num4 * (elements - 1 - i);
					}
					else if (n - num2 > maxWidth)
					{
						num3--;
					}
					val -= num3;
					if (val < 0)
					{
						break;
					}
					num2++;
					num &= ~(1 << i);
				}
				val += num3;
				n -= num2;
				array[i] = num2;
			}
			array[i] = n;
			return array;
		}

		public static int GetRssValue(int[] widths, int maxWidth, bool noNarrow)
		{
			int num = widths.Length;
			int num2 = 0;
			for (int i = 0; i < num; i++)
			{
				num2 += widths[i];
			}
			int num3 = 0;
			int num4 = 0;
			for (int j = 0; j < num - 1; j++)
			{
				int num5 = 1;
				num4 |= 1 << j;
				while (num5 < widths[j])
				{
					int num6 = Combins(num2 - num5 - 1, num - j - 2);
					if (noNarrow && num4 == 0 && num2 - num5 - (num - j - 1) >= num - j - 1)
					{
						num6 -= Combins(num2 - num5 - (num - j), num - j - 2);
					}
					if (num - j - 1 > 1)
					{
						int num7 = 0;
						for (int num8 = num2 - num5 - (num - j - 2); num8 > maxWidth; num8--)
						{
							num7 += Combins(num2 - num5 - num8 - 1, num - j - 3);
						}
						num6 -= num7 * (num - 1 - j);
					}
					else if (num2 - num5 > maxWidth)
					{
						num6--;
					}
					num3 += num6;
					num5++;
					num4 &= ~(1 << j);
				}
				num2 -= num5;
			}
			return num3;
		}

		internal static int Combins(int n, int r)
		{
			int num;
			int num2;
			if (n - r > r)
			{
				num = r;
				num2 = n - r;
			}
			else
			{
				num = n - r;
				num2 = r;
			}
			int num3 = 1;
			int i = 1;
			for (int num4 = n; num4 > num2; num4--)
			{
				num3 *= num4;
				if (i <= num)
				{
					num3 /= i;
					i++;
				}
			}
			for (; i <= num; i++)
			{
				num3 /= i;
			}
			return num3;
		}

		internal static int[] Elements(int[] eDist, int N, int K)
		{
			int[] array = new int[eDist.Length + 2];
			int num = K << 1;
			array[0] = 1;
			int num2 = 10;
			int num3 = 1;
			for (int i = 1; i < num - 2; i += 2)
			{
				array[i] = eDist[i - 1] - array[i - 1];
				array[i + 1] = eDist[i] - array[i];
				num3 += array[i] + array[i + 1];
				if (array[i] < num2)
				{
					num2 = array[i];
				}
			}
			array[num - 1] = N - num3;
			if (array[num - 1] < num2)
			{
				num2 = array[num - 1];
			}
			if (num2 > 1)
			{
				for (int i = 0; i < num; i += 2)
				{
					array[i] += num2 - 1;
					array[i + 1] -= num2 - 1;
				}
			}
			return array;
		}
	}
