	public sealed class BinaryUtil
	{
		private BinaryUtil()
		{
		}

		public static MessagingToolkit.Barcode.Common.BitArray BuildBitArrayFromString(string data)
		{
			string text = data.Replace("1", "X").Replace("0", ".");
			MessagingToolkit.Barcode.Common.BitArray bitArray = new MessagingToolkit.Barcode.Common.BitArray(text.Replace(" ", "").Length);
			int num = 0;
			for (int i = 0; i < text.Length; i++)
			{
				if (i % 9 == 0)
				{
					if (text[i] != ' ')
					{
						throw new InvalidOperationException("space expected");
					}
					continue;
				}
				char c = text[i];
				if (c == 'X' || c == 'x')
				{
					bitArray.Set(num);
				}
				num++;
			}
			return bitArray;
		}

		public static MessagingToolkit.Barcode.Common.BitArray BuildBitArrayFromStringWithoutSpaces(string data)
		{
			StringBuilder stringBuilder = new StringBuilder();
			string text = data.Replace("1", "X").Replace("0", ".");
			int num = 0;
			while (num < text.Length)
			{
				stringBuilder.Append(' ');
				for (int i = 0; i < 8; i++)
				{
					if (num >= text.Length)
					{
						break;
					}
					stringBuilder.Append(text[num]);
					num++;
				}
			}
			return BuildBitArrayFromString(stringBuilder.ToString());
		}
	}
	internal sealed class BitArrayBuilder
	{
		private BitArrayBuilder()
		{
		}

		internal static MessagingToolkit.Barcode.Common.BitArray BuildBitArray(List<ExpandedPair> pairs)
		{
			int num = (pairs.Count << 1) - 1;
			if (pairs[pairs.Count - 1].RightChar == null)
			{
				num--;
			}
			MessagingToolkit.Barcode.Common.BitArray bitArray = new MessagingToolkit.Barcode.Common.BitArray(12 * num);
			int num2 = 0;
			int value = pairs[0].RightChar.Value;
			for (int num3 = 11; num3 >= 0; num3--)
			{
				if ((value & (1 << num3)) != 0)
				{
					bitArray.Set(num2);
				}
				num2++;
			}
			for (int i = 1; i < pairs.Count; i++)
			{
				ExpandedPair expandedPair = pairs[i];
				int value2 = expandedPair.LeftChar.Value;
				for (int num4 = 11; num4 >= 0; num4--)
				{
					if ((value2 & (1 << num4)) != 0)
					{
						bitArray.Set(num2);
					}
					num2++;
				}
				if (expandedPair.RightChar == null)
				{
					continue;
				}
				int value3 = expandedPair.RightChar.Value;
				for (int num5 = 11; num5 >= 0; num5--)
				{
					if ((value3 & (1 << num5)) != 0)
					{
						bitArray.Set(num2);
					}
					num2++;
				}
			}
			return bitArray;
		}
	}
	internal sealed class ExpandedPair
	{
		private readonly bool mayBeLast;

		private readonly DataCharacter leftChar;

		private readonly DataCharacter rightChar;

		private readonly FinderPattern finderPattern;

		internal bool MayBeLast => mayBeLast;

		internal DataCharacter LeftChar => leftChar;

		internal DataCharacter RightChar => rightChar;

		internal FinderPattern FinderPattern => finderPattern;

		public bool MustBeLast => rightChar == null;

		internal ExpandedPair(DataCharacter leftChar, DataCharacter rightChar, FinderPattern finderPattern, bool mayBeLast)
		{
			this.leftChar = leftChar;
			this.rightChar = rightChar;
			this.finderPattern = finderPattern;
			this.mayBeLast = mayBeLast;
		}

		public override string ToString()
		{
			return string.Concat("[ ", LeftChar, " , ", RightChar, " : ", (FinderPattern == null) ? "null" : FinderPattern.Value.ToString(), " ]");
		}

		public override bool Equals(object o)
		{
			if (!(o is ExpandedPair))
			{
				return false;
			}
			ExpandedPair expandedPair = (ExpandedPair)o;
			if (EqualsOrNull(LeftChar, expandedPair.LeftChar) && EqualsOrNull(RightChar, expandedPair.RightChar))
			{
				return EqualsOrNull(FinderPattern, expandedPair.FinderPattern);
			}
			return false;
		}

		private static bool EqualsOrNull(object o1, object o2)
		{
			return o1?.Equals(o2) ?? (o2 == null);
		}

		public override int GetHashCode()
		{
			return hashNotNull(LeftChar) ^ hashNotNull(RightChar) ^ hashNotNull(FinderPattern);
		}

		private static int hashNotNull(object o)
		{
			return o?.GetHashCode() ?? 0;
		}
	}
	internal sealed class ExpandedRow
	{
		internal List<ExpandedPair> Pairs { get; private set; }

		internal int RowNumber { get; private set; }

		internal bool IsReversed { get; private set; }

		internal ExpandedRow(List<ExpandedPair> pairs, int rowNumber, bool wasReversed)
		{
