		public RssExpandedDecoder()
		{
			pairs = new List<ExpandedPair>(11);
			rows = new List<ExpandedRow>();
			startEnd = new int[2];
		}

		public override Result DecodeRow(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row, Dictionary<DecodeOptions, object> decodingOptions)
		{
			pairs.Clear();
			startFromEven = false;
			try
			{
				DecodeRow2pairs(rowNumber, row);
				return ConstructResult(pairs);
			}
			catch (NotFoundException)
			{
			}
			pairs.Clear();
			startFromEven = true;
			DecodeRow2pairs(rowNumber, row);
			return ConstructResult(pairs);
		}

		public override void Reset()
		{
			pairs.Clear();
			rows.Clear();
		}

		private List<ExpandedPair> DecodeRow2pairs(int rowNumber, MessagingToolkit.Barcode.Common.BitArray row)
		{
			try
			{
				while (true)
				{
					ExpandedPair item = RetrieveNextPair(row, pairs, rowNumber);
					pairs.Add(item);
				}
			}
			catch (NotFoundException ex)
			{
				if (pairs.Count == 0)
				{
					throw ex;
				}
			}
			if (CheckChecksum())
			{
				return pairs;
			}
			bool num = rows.Count != 0;
			bool wasReversed = false;
			StoreRow(rowNumber, wasReversed);
			if (num)
			{
				List<ExpandedPair> list = CheckRows(reverse: false);
				if (list != null)
				{
					return list;
				}
				list = CheckRows(reverse: true);
				if (list != null)
				{
					return list;
				}
			}
			throw NotFoundException.Instance;
		}

		private List<ExpandedPair> CheckRows(bool reverse)
		{
			if (rows.Count > 25)
			{
				rows.Clear();
				return null;
			}
			pairs.Clear();
			if (reverse)
			{
				rows.Reverse();
			}
			List<ExpandedPair> result = null;
			try
			{
				result = CheckRows(new List<ExpandedRow>(), 0);
			}
			catch (NotFoundException)
			{
			}
			if (reverse)
			{
				rows.Reverse();
			}
			return result;
		}

		private List<ExpandedPair> CheckRows(List<ExpandedRow> collectedRows, int currentRow)
		{
			for (int i = currentRow; i < rows.Count; i++)
			{
				ExpandedRow expandedRow = rows[i];
				pairs.Clear();
				int count = collectedRows.Count;
				for (int j = 0; j < count; j++)
				{
					pairs.AddRange(collectedRows[j].Pairs);
				}
				pairs.AddRange(expandedRow.Pairs);
				if (IsValidSequence(pairs))
				{
					if (CheckChecksum())
					{
						return pairs;
					}
					List<ExpandedRow> list = new List<ExpandedRow>();
					list.AddRange(collectedRows);
					list.Add(expandedRow);
					try
					{
						return CheckRows(list, i + 1);
					}
					catch (NotFoundException)
					{
					}
				}
			}
			throw NotFoundException.Instance;
		}

		private static bool IsValidSequence(List<ExpandedPair> pairs)
		{
			int[][] finderPatternSequences = FinderPatternSequences;
			foreach (int[] array in finderPatternSequences)
			{
				if (pairs.Count > array.Length)
				{
					continue;
				}
				bool flag = true;
				for (int j = 0; j < pairs.Count; j++)
				{
					if (pairs[j].FinderPattern.Value != array[j])
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					return true;
				}
			}
			return false;
		}

		private void StoreRow(int rowNumber, bool wasReversed)
		{
			int i = 0;
			bool flag = false;
			bool flag2 = false;
			for (; i < rows.Count; i++)
			{
				ExpandedRow expandedRow = rows[i];
				if (expandedRow.RowNumber > rowNumber)
				{
					flag2 = expandedRow.IsEquivalent(pairs);
					break;
				}
				flag = expandedRow.IsEquivalent(pairs);
			}
			if (!(flag2 || flag) && !IsPartialRow(pairs, rows))
			{
				rows.Insert(i, new ExpandedRow(pairs, rowNumber, wasReversed));
				RemovePartialRows(pairs, rows);
			}
		}

		private static void RemovePartialRows(List<ExpandedPair> pairs, List<ExpandedRow> rows)
		{
			for (int i = 0; i < rows.Count; i++)
			{
				ExpandedRow expandedRow = rows[i];
				if (expandedRow.Pairs.Count == pairs.Count)
				{
					continue;
				}
				bool flag = true;
				foreach (ExpandedPair pair in expandedRow.Pairs)
				{
					bool flag2 = false;
					foreach (ExpandedPair pair2 in pairs)
					{
						if (pair.Equals(pair2))
						{
							flag2 = true;
							break;
						}
					}
					if (!flag2)
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					rows.RemoveAt(i);
				}
			}
		}

		private static bool IsPartialRow(IEnumerable<ExpandedPair> pairs, IEnumerable<ExpandedRow> rows)
		{
			foreach (ExpandedRow row in rows)
			{
				bool flag = true;
				foreach (ExpandedPair pair in pairs)
				{
					bool flag2 = false;
					foreach (ExpandedPair pair2 in row.Pairs)
					{
						if (pair.Equals(pair2))
						{
							flag2 = true;
							break;
						}
					}
					if (!flag2)
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					return true;
				}
			}
			return false;
		}

		private static Result ConstructResult(List<ExpandedPair> pairs)
		{
			string text = AbstractExpandedDecoder.CreateDecoder(BitArrayBuilder.BuildBitArray(pairs)).ParseInformation();
			ResultPoint[] resultPoints = pairs[0].FinderPattern.ResultPoints;
			ResultPoint[] resultPoints2 = pairs[pairs.Count - 1].FinderPattern.ResultPoints;
			return new Result(text, null, new ResultPoint[4]
			{
				resultPoints[0],
				resultPoints[1],
				resultPoints2[0],
				resultPoints2[1]
			}, BarcodeFormat.RSSExpanded);
		}

		private bool CheckChecksum()
		{
			ExpandedPair expandedPair = pairs[0];
			DataCharacter leftChar = expandedPair.LeftChar;
			DataCharacter rightChar = expandedPair.RightChar;
			if (rightChar == null)
			{
				return false;
			}
			int num = rightChar.ChecksumPortion;
			int num2 = 2;
			for (int i = 1; i < pairs.Count; i++)
			{
				ExpandedPair expandedPair2 = pairs[i];
				num += expandedPair2.LeftChar.ChecksumPortion;
				num2++;
				if (expandedPair2.RightChar != null)
				{
					num += expandedPair2.RightChar.ChecksumPortion;
					num2++;
				}
			}
			num %= 211;
			return 211 * (num2 - 4) + num == leftChar.Value;
		}

		private static int GetNextSecondBar(MessagingToolkit.Barcode.Common.BitArray row, int initialPos)
		{
			int nextUnset;
			if (row.Get(initialPos))
			{
				nextUnset = row.GetNextUnset(initialPos);
				return row.GetNextSet(nextUnset);
			}
			nextUnset = row.GetNextSet(initialPos);
			return row.GetNextUnset(nextUnset);
		}

		internal ExpandedPair RetrieveNextPair(MessagingToolkit.Barcode.Common.BitArray row, List<ExpandedPair> previousPairs, int rowNumber)
		{
			bool flag = previousPairs.Count % 2 == 0;
			if (startFromEven)
			{
				flag = !flag;
			}
			bool flag2 = true;
			int forcedOffset = -1;
			FinderPattern finderPattern;
			do
			{
				FindNextPair(row, previousPairs, forcedOffset);
				finderPattern = ParseFoundFinderPattern(row, rowNumber, flag);
				if (finderPattern == null)
				{
					forcedOffset = GetNextSecondBar(row, startEnd[0]);
				}
				else
				{
					flag2 = false;
				}
			}
			while (flag2);
			DataCharacter leftChar = DecodeDataCharacter(row, finderPattern, flag, leftChar: true);
			if (previousPairs.Count != 0 && previousPairs[previousPairs.Count - 1].MustBeLast)
			{
				throw NotFoundException.Instance;
			}
			DataCharacter rightChar;
			try
			{
				rightChar = DecodeDataCharacter(row, finderPattern, flag, leftChar: false);
