			}
			float num4 = (float)AbstractRssDecoder.Count(array) / 17f;
			float num5 = (float)(pattern.StartEnd[1] - pattern.StartEnd[0]) / 15f;
			if (Math.Abs(num4 - num5) / num5 > 0.3f)
			{
