			int rssValue2 = RssUtils.GetRssValue(array3, maxWidth, noNarrow: false);
			int num19 = EventTotalSubset[num17];
			int num20 = GSum[num17];
			return new DataCharacter(rssValue * num19 + rssValue2 + num20, checksumPortion);
