		private static bool IsNotA1left(FinderPattern pattern, bool isOddPattern, bool leftChar)
		{
			return !(pattern.Value == 0 && isOddPattern && leftChar);
		}

		private void AdjustOddEvenCounts(int numModules)
		{
			int num = AbstractRssDecoder.Count(oddCounts);
			int num2 = AbstractRssDecoder.Count(evenCounts);
			int num3 = num + num2 - numModules;
			bool flag = (num & 1) == 1;
			bool flag2 = (num2 & 1) == 0;
			bool flag3 = false;
			bool flag4 = false;
			if (num > 13)
			{
				flag4 = true;
			}
			else if (num < 4)
			{
				flag3 = true;
			}
			bool flag5 = false;
			bool flag6 = false;
			if (num2 > 13)
			{
				flag6 = true;
			}
			else if (num2 < 4)
			{
				flag5 = true;
			}
			switch (num3)
			{
			case 1:
				if (flag)
				{
					if (flag2)
					{
						throw NotFoundException.Instance;
					}
					flag4 = true;
				}
				else
				{
					if (!flag2)
					{
						throw NotFoundException.Instance;
					}
					flag6 = true;
				}
				break;
			case -1:
				if (flag)
