					{
						throw NotFoundException.Instance;
					}
					flag3 = true;
				}
				else
				{
					if (!flag2)
					{
						throw NotFoundException.Instance;
					}
					flag5 = true;
				}
				break;
			case 0:
				if (flag)
				{
					if (!flag2)
					{
						throw NotFoundException.Instance;
					}
					if (num < num2)
					{
						flag3 = true;
						flag6 = true;
					}
					else
					{
						flag4 = true;
						flag5 = true;
					}
				}
				else if (flag2)
				{
					throw NotFoundException.Instance;
				}
				break;
			default:
				throw NotFoundException.Instance;
			}
			if (flag3)
			{
				if (flag4)
				{
					throw NotFoundException.Instance;
				}
				AbstractRssDecoder.Increment(oddCounts, oddRoundingErrors);
			}
			if (flag4)
			{
				AbstractRssDecoder.Decrement(oddCounts, oddRoundingErrors);
			}
			if (flag5)
			{
				if (flag6)
				{
					throw NotFoundException.Instance;
				}
				AbstractRssDecoder.Increment(evenCounts, oddRoundingErrors);
			}
			if (flag6)
			{
				AbstractRssDecoder.Decrement(evenCounts, evenRoundingErrors);
			}
		}
	}
