	internal sealed class AI01392xDecoder : AI01decoder
	{
		private const int headerSize = 8;

		private const int lastDigitSize = 2;

		internal AI01392xDecoder(MessagingToolkit.Barcode.Common.BitArray information)
			: base(information)
		{
		}

		public override string ParseInformation()
		{
			if (information.Size < 48)
			{
				throw NotFoundException.Instance;
			}
			StringBuilder stringBuilder = new StringBuilder();
			EncodeCompressedGtin(stringBuilder, 8);
			int value = generalDecoder.ExtractNumericValueFromBitArray(48, 2);
			stringBuilder.Append("(392");
			stringBuilder.Append(value);
			stringBuilder.Append(')');
			DecodedInformation decodedInformation = generalDecoder.DecodeGeneralPurposeField(50, null);
			stringBuilder.Append(decodedInformation.NewString);
			return stringBuilder.ToString();
		}
