	internal sealed class AI013x0x1xDecoder : AI01weightDecoder
	{
		private const int headerSize = 8;

		private const int weightSize = 20;

		private const int dateSize = 16;

		private readonly string dateCode;

		private readonly string firstAIdigits;

		internal AI013x0x1xDecoder(MessagingToolkit.Barcode.Common.BitArray information, string firstAIdigits, string dateCode)
			: base(information)
		{
			this.dateCode = dateCode;
			this.firstAIdigits = firstAIdigits;
		}

		public override string ParseInformation()
		{
			if (information.Size != 84)
			{
				throw NotFoundException.Instance;
			}
			StringBuilder stringBuilder = new StringBuilder();
			EncodeCompressedGtin(stringBuilder, 8);
			EncodeCompressedWeight(stringBuilder, 48, 20);
			EncodeCompressedDate(stringBuilder, 68);
			return stringBuilder.ToString();
		}

		private void EncodeCompressedDate(StringBuilder buf, int currentPos)
		{
			int num = generalDecoder.ExtractNumericValueFromBitArray(currentPos, 16);
			if (num != 38400)
			{
				buf.Append('(');
				buf.Append(dateCode);
				buf.Append(')');
				int num2 = num % 32;
				num /= 32;
				int num3 = num % 12 + 1;
				num /= 12;
				int num4 = num;
				if (num4 / 10 == 0)
				{
					buf.Append('0');
				}
				buf.Append(num4);
				if (num3 / 10 == 0)
				{
					buf.Append('0');
				}
				buf.Append(num3);
				if (num2 / 10 == 0)
				{
					buf.Append('0');
				}
				buf.Append(num2);
			}
		}

		protected internal override void AddWeightCode(StringBuilder buf, int weight)
		{
			int value = weight / 100000;
			buf.Append('(');
			buf.Append(firstAIdigits);
			buf.Append(value);
			buf.Append(')');
		}

		protected internal override int CheckWeight(int weight)
		{
			return weight % 100000;
		}
	}
