	internal sealed class AI01AndOtherAIs : AI01decoder
	{
		private const int HEADER_SIZE = 4;

		internal AI01AndOtherAIs(MessagingToolkit.Barcode.Common.BitArray information)
			: base(information)
		{
		}

		public override string ParseInformation()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("(01)");
			int length = stringBuilder.Length;
			int value = generalDecoder.ExtractNumericValueFromBitArray(4, 4);
			stringBuilder.Append(value);
