	internal abstract class AI01decoder : AbstractExpandedDecoder
	{
		protected internal const int gtinSize = 40;

		internal AI01decoder(MessagingToolkit.Barcode.Common.BitArray information)
			: base(information)
		{
		}

		protected internal void EncodeCompressedGtin(StringBuilder buf, int currentPos)
		{
			buf.Append("(01)");
			int length = buf.Length;
			buf.Append('9');
			EncodeCompressedGtinWithoutAI(buf, currentPos, length);
		}

		protected internal void EncodeCompressedGtinWithoutAI(StringBuilder buf, int currentPos, int initialBufferPosition)
		{
			for (int i = 0; i < 4; i++)
			{
				int num = generalDecoder.ExtractNumericValueFromBitArray(currentPos + 10 * i, 10);
				if (num / 100 == 0)
				{
					buf.Append('0');
				}
				if (num / 10 == 0)
				{
					buf.Append('0');
				}
				buf.Append(num);
			}
			AppendCheckDigit(buf, initialBufferPosition);
		}

		private static void AppendCheckDigit(StringBuilder buf, int currentPos)
		{
			int num = 0;
			for (int i = 0; i < 13; i++)
			{
				int num2 = buf[i + currentPos] - 48;
				num += (((i & 1) == 0) ? (3 * num2) : num2);
			}
			num = 10 - num % 10;
			if (num == 10)
			{
				num = 0;
			}
			buf.Append(num);
		}
	}
	internal abstract class AI01weightDecoder : AI01decoder
	{
		internal AI01weightDecoder(MessagingToolkit.Barcode.Common.BitArray information)
			: base(information)
		{
		}

		protected internal void EncodeCompressedWeight(StringBuilder buf, int currentPos, int weightSize)
		{
			int weight = generalDecoder.ExtractNumericValueFromBitArray(currentPos, weightSize);
			AddWeightCode(buf, weight);
			int num = CheckWeight(weight);
			int num2 = 100000;
			for (int i = 0; i < 5; i++)
			{
				if (num / num2 == 0)
				{
					buf.Append('0');
				}
				num2 /= 10;
			}
			buf.Append(num);
		}

		protected internal abstract void AddWeightCode(StringBuilder buf, int weight);

		protected internal abstract int CheckWeight(int weight);
	}
