		internal static string ParseFieldsInGeneralPurpose(string rawInformation)
		{
			if (string.IsNullOrEmpty(rawInformation))
			{
				return null;
			}
			if (rawInformation.Length < 2)
			{
				throw NotFoundException.Instance;
			}
			string obj = rawInformation.Substring(0, 2);
			for (int i = 0; i < TwoDigitDataLength.Length; i++)
			{
				if (TwoDigitDataLength[i][0].Equals(obj))
				{
					if (TwoDigitDataLength[i][1] == VariableLength)
					{
						return ProcessVariableAI(2, (int)TwoDigitDataLength[i][2], rawInformation);
					}
					return ProcessFixedAI(2, (int)TwoDigitDataLength[i][1], rawInformation);
				}
			}
			if (rawInformation.Length < 3)
			{
				throw NotFoundException.Instance;
			}
			string obj2 = rawInformation.Substring(0, 3);
			for (int j = 0; j < ThreeDigitDataLength.Length; j++)
			{
				if (ThreeDigitDataLength[j][0].Equals(obj2))
				{
					if (ThreeDigitDataLength[j][1] == VariableLength)
					{
						return ProcessVariableAI(3, (int)ThreeDigitDataLength[j][2], rawInformation);
					}
					return ProcessFixedAI(3, (int)ThreeDigitDataLength[j][1], rawInformation);
				}
			}
			for (int k = 0; k < ThreeDigitPlusDigitDataLength.Length; k++)
			{
				if (ThreeDigitPlusDigitDataLength[k][0].Equals(obj2))
				{
					if (ThreeDigitPlusDigitDataLength[k][1] == VariableLength)
					{
						return ProcessVariableAI(4, (int)ThreeDigitPlusDigitDataLength[k][2], rawInformation);
					}
					return ProcessFixedAI(4, (int)ThreeDigitPlusDigitDataLength[k][1], rawInformation);
				}
			}
			if (rawInformation.Length < 4)
			{
				throw NotFoundException.Instance;
			}
			string obj3 = rawInformation.Substring(0, 4);
			for (int l = 0; l < FourDigitDataLength.Length; l++)
			{
				if (FourDigitDataLength[l][0].Equals(obj3))
				{
					if (FourDigitDataLength[l][1] == VariableLength)
					{
						return ProcessVariableAI(4, (int)FourDigitDataLength[l][2], rawInformation);
					}
					return ProcessFixedAI(4, (int)FourDigitDataLength[l][1], rawInformation);
				}
			}
			throw NotFoundException.Instance;
		}

		private static string ProcessFixedAI(int aiSize, int fieldSize, string rawInformation)
		{
			if (rawInformation.Length < aiSize)
			{
				throw NotFoundException.Instance;
			}
			string text = rawInformation.Substring(0, aiSize);
			if (rawInformation.Length < aiSize + fieldSize)
			{
				throw NotFoundException.Instance;
			}
			string text2 = rawInformation.Substring(aiSize, aiSize + fieldSize - aiSize);
			string rawInformation2 = rawInformation.Substring(aiSize + fieldSize);
			return "(" + text + ")" + text2 + ParseFieldsInGeneralPurpose(rawInformation2);
		}

		private static string ProcessVariableAI(int aiSize, int variableFieldSize, string rawInformation)
		{
			string text = rawInformation.Substring(0, aiSize);
			int num = ((rawInformation.Length >= aiSize + variableFieldSize) ? (aiSize + variableFieldSize) : rawInformation.Length);
			string text2 = rawInformation.Substring(aiSize, num - aiSize);
			string rawInformation2 = rawInformation.Substring(num);
			return "(" + text + ")" + text2 + ParseFieldsInGeneralPurpose(rawInformation2);
		}
	}
	public sealed class GeneralAppIdDecoder
	{
		private readonly MessagingToolkit.Barcode.Common.BitArray information;

		private readonly CurrentParsingState current;

		private readonly StringBuilder buffer;

		public GeneralAppIdDecoder(MessagingToolkit.Barcode.Common.BitArray information)
		{
			current = new CurrentParsingState();
			buffer = new StringBuilder();
			this.information = information;
		}

		internal string DecodeAllCodes(StringBuilder buff, int initialPosition)
		{
			int num = initialPosition;
			string remaining = null;
			while (true)
			{
				DecodedInformation decodedInformation = DecodeGeneralPurposeField(num, remaining);
				string value = FieldParser.ParseFieldsInGeneralPurpose(decodedInformation.NewString);
				buff.Append(value);
				remaining = ((!decodedInformation.IsRemaining) ? null : decodedInformation.RemainingValue.ToString());
				if (num == decodedInformation.NewPosition)
				{
					break;
				}
				num = decodedInformation.NewPosition;
			}
			return buff.ToString();
		}

		private bool IsStillNumeric(int pos)
		{
			if (pos + 7 > information.Size)
			{
				return pos + 4 <= information.Size;
			}
			for (int i = pos; i < pos + 3; i++)
			{
				if (information.Get(i))
				{
					return true;
				}
			}
			return information.Get(pos + 3);
		}

		private DecodedNumeric DecodeNumeric(int pos)
		{
			if (pos + 7 > information.Size)
			{
				int num = ExtractNumericValueFromBitArray(pos, 4);
				if (num == 0)
				{
					return new DecodedNumeric(information.Size, 10, 10);
				}
				return new DecodedNumeric(information.Size, num - 1, 10);
			}
			int num2 = ExtractNumericValueFromBitArray(pos, 7);
			int firstDigit = (num2 - 8) / 11;
			int secondDigit = (num2 - 8) % 11;
			return new DecodedNumeric(pos + 7, firstDigit, secondDigit);
		}

		internal int ExtractNumericValueFromBitArray(int pos, int bits)
		{
			return ExtractNumericValueFromBitArray(information, pos, bits);
		}

		internal static int ExtractNumericValueFromBitArray(MessagingToolkit.Barcode.Common.BitArray information_0, int pos, int bits)
		{
			if (bits > 32)
			{
				throw new ArgumentException("extractNumberValueFromBitArray can't handle more than 32 bits");
			}
			int num = 0;
			for (int i = 0; i < bits; i++)
			{
				if (information_0.Get(pos + i))
				{
					num |= 1 << bits - i - 1;
				}
			}
			return num;
		}

		internal DecodedInformation DecodeGeneralPurposeField(int pos, string remaining)
		{
			buffer.Length = 0;
			if (remaining != null)
			{
				buffer.Append(remaining);
			}
			current.position = pos;
			DecodedInformation decodedInformation = ParseBlocks();
			if (decodedInformation != null && decodedInformation.IsRemaining)
			{
				return new DecodedInformation(current.position, buffer.ToString(), decodedInformation.RemainingValue);
			}
			return new DecodedInformation(current.position, buffer.ToString());
		}

		private DecodedInformation ParseBlocks()
		{
			int position;
			BlockParsedResult blockParsedResult;
			bool isFinished;
			do
			{
				position = current.position;
				if (current.IsAlpha)
				{
					blockParsedResult = ParseAlphaBlock();
					isFinished = blockParsedResult.IsFinished;
				}
				else if (current.IsIsoIec646)
				{
					blockParsedResult = ParseIsoIec646Block();
					isFinished = blockParsedResult.IsFinished;
				}
				else
				{
					blockParsedResult = ParseNumericBlock();
					isFinished = blockParsedResult.IsFinished;
				}
			}
			while ((position != current.position || isFinished) && !isFinished);
			return blockParsedResult.DecodedInformation;
		}

		private BlockParsedResult ParseNumericBlock()
		{
			while (IsStillNumeric(current.position))
			{
				DecodedNumeric decodedNumeric = DecodeNumeric(current.position);
				current.position = decodedNumeric.NewPosition;
				if (decodedNumeric.IsFirstDigitFnc1())
				{
					DecodedInformation decodedInformation = ((!decodedNumeric.IsSecondDigitFnc1()) ? new DecodedInformation(current.position, buffer.ToString(), decodedNumeric.SecondDigit) : new DecodedInformation(current.position, buffer.ToString()));
					return new BlockParsedResult(decodedInformation, finished: true);
				}
				buffer.Append(decodedNumeric.FirstDigit);
				if (decodedNumeric.IsSecondDigitFnc1())
				{
					return new BlockParsedResult(new DecodedInformation(current.position, buffer.ToString()), finished: true);
				}
				buffer.Append(decodedNumeric.SecondDigit);
			}
			if (IsNumericToAlphaNumericLatch(current.position))
			{
				current.SetAlpha();
				current.position += 4;
			}
			return new BlockParsedResult(finished: false);
		}

		private BlockParsedResult ParseIsoIec646Block()
		{
			while (IsStillIsoIec646(current.position))
			{
				DecodedChar decodedChar = DecodeIsoIec646(current.position);
				current.position = decodedChar.NewPosition;
				if (decodedChar.IsFnc1)
				{
					return new BlockParsedResult(new DecodedInformation(current.position, buffer.ToString()), finished: true);
				}
				buffer.Append(decodedChar.Value);
			}
			if (IsAlphaOr646ToNumericLatch(current.position))
			{
				current.position += 3;
				current.SetNumeric();
			}
			else if (IsAlphaTo646ToAlphaLatch(current.position))
			{
				if (current.position + 5 < information.Size)
				{
					current.position += 5;
				}
				else
				{
					current.position = information.Size;
				}
				current.SetAlpha();
			}
			return new BlockParsedResult(finished: false);
		}

		private BlockParsedResult ParseAlphaBlock()
		{
			while (IsStillAlpha(current.position))
			{
				DecodedChar decodedChar = DecodeAlphanumeric(current.position);
				current.position = decodedChar.NewPosition;
				if (decodedChar.IsFnc1)
				{
					return new BlockParsedResult(new DecodedInformation(current.position, buffer.ToString()), finished: true);
				}
				buffer.Append(decodedChar.Value);
			}
			if (IsAlphaOr646ToNumericLatch(current.position))
			{
				current.position += 3;
				current.SetNumeric();
			}
			else if (IsAlphaTo646ToAlphaLatch(current.position))
			{
				if (current.position + 5 < information.Size)
				{
					current.position += 5;
				}
				else
				{
					current.position = information.Size;
				}
				current.SetIsoIec646();
			}
			return new BlockParsedResult(finished: false);
		}

		private bool IsStillIsoIec646(int pos)
		{
			if (pos + 5 > information.Size)
			{
				return false;
			}
			int num = ExtractNumericValueFromBitArray(pos, 5);
			if (num >= 5 && num < 16)
			{
				return true;
			}
			if (pos + 7 > information.Size)
			{
				return false;
			}
			int num2 = ExtractNumericValueFromBitArray(pos, 7);
			if (num2 >= 64 && num2 < 116)
			{
				return true;
			}
			if (pos + 8 > information.Size)
			{
				return false;
			}
			int num3 = ExtractNumericValueFromBitArray(pos, 8);
			if (num3 >= 232)
			{
				return num3 < 253;
			}
			return false;
		}

		private DecodedChar DecodeIsoIec646(int pos)
		{
			int num = ExtractNumericValueFromBitArray(pos, 5);
			switch (num)
			{
			case 15:
				return new DecodedChar(pos + 5, '$');
			case 5:
			case 6:
			case 7:
			case 8:
			case 9:
			case 10:
			case 11:
			case 12:
			case 13:
			case 14:
				return new DecodedChar(pos + 5, (char)(48 + num - 5));
			default:
			{
				int num2 = ExtractNumericValueFromBitArray(pos, 7);
				if (num2 >= 64 && num2 < 90)
				{
					return new DecodedChar(pos + 7, (char)(num2 + 1));
				}
				if (num2 >= 90 && num2 < 116)
				{
					return new DecodedChar(pos + 7, (char)(num2 + 7));
				}
				int num3 = ExtractNumericValueFromBitArray(pos, 8);
				return num3 switch
				{
					232 => new DecodedChar(pos + 8, '!'), 
					233 => new DecodedChar(pos + 8, '"'), 
					234 => new DecodedChar(pos + 8, '%'), 
					235 => new DecodedChar(pos + 8, '&'), 
					236 => new DecodedChar(pos + 8, '\''), 
					237 => new DecodedChar(pos + 8, '('), 
					238 => new DecodedChar(pos + 8, ')'), 
					239 => new DecodedChar(pos + 8, '*'), 
					240 => new DecodedChar(pos + 8, '+'), 
					241 => new DecodedChar(pos + 8, ','), 
					242 => new DecodedChar(pos + 8, '-'), 
					243 => new DecodedChar(pos + 8, '.'), 
					244 => new DecodedChar(pos + 8, '/'), 
					245 => new DecodedChar(pos + 8, ':'), 
					246 => new DecodedChar(pos + 8, ';'), 
					247 => new DecodedChar(pos + 8, '<'), 
					248 => new DecodedChar(pos + 8, '='), 
					249 => new DecodedChar(pos + 8, '>'), 
					250 => new DecodedChar(pos + 8, '?'), 
					251 => new DecodedChar(pos + 8, '_'), 
					252 => new DecodedChar(pos + 8, ' '), 
					_ => throw new Exception("Decoding invalid ISO/IEC 646 value: " + num3), 
				};
			}
			}
		}

		private bool IsStillAlpha(int pos)
		{
			if (pos + 5 > information.Size)
			{
				return false;
			}
			int num = ExtractNumericValueFromBitArray(pos, 5);
			if (num >= 5 && num < 16)
			{
				return true;
			}
			if (pos + 6 > information.Size)
			{
				return false;
			}
			int num2 = ExtractNumericValueFromBitArray(pos, 6);
			if (num2 >= 16)
			{
				return num2 < 63;
			}
			return false;
		}

		private DecodedChar DecodeAlphanumeric(int pos)
		{
			int num = ExtractNumericValueFromBitArray(pos, 5);
			switch (num)
			{
			case 15:
				return new DecodedChar(pos + 5, '$');
			case 5:
			case 6:
			case 7:
			case 8:
			case 9:
			case 10:
			case 11:
			case 12:
			case 13:
			case 14:
				return new DecodedChar(pos + 5, (char)(48 + num - 5));
			default:
			{
				int num2 = ExtractNumericValueFromBitArray(pos, 6);
				if (num2 >= 32 && num2 < 58)
				{
					return new DecodedChar(pos + 6, (char)(num2 + 33));
				}
				return num2 switch
				{
					58 => new DecodedChar(pos + 6, '*'), 
					59 => new DecodedChar(pos + 6, ','), 
					60 => new DecodedChar(pos + 6, '-'), 
					61 => new DecodedChar(pos + 6, '.'), 
					62 => new DecodedChar(pos + 6, '/'), 
					_ => throw new Exception("Decoding invalid alphanumeric value: " + num2), 
				};
			}
			}
		}

		private bool IsAlphaTo646ToAlphaLatch(int pos)
		{
			if (pos + 1 > information.Size)
			{
				return false;
			}
			for (int i = 0; i < 5 && i + pos < information.Size; i++)
			{
				if (i == 2)
				{
					if (!information.Get(pos + 2))
					{
						return false;
					}
				}
				else if (information.Get(pos + i))
				{
					return false;
				}
			}
			return true;
		}

		private bool IsAlphaOr646ToNumericLatch(int pos)
		{
			if (pos + 3 > information.Size)
			{
				return false;
			}
			for (int i = pos; i < pos + 3; i++)
			{
				if (information.Get(i))
				{
					return false;
				}
			}
			return true;
		}

		private bool IsNumericToAlphaNumericLatch(int pos)
		{
			if (pos + 1 > information.Size)
			{
				return false;
			}
			for (int i = 0; i < 4 && i + pos < information.Size; i++)
			{
				if (information.Get(pos + i))
				{
					return false;
				}
			}
			return true;
		}
	}
