	public sealed class DataMatrixDecoder : IDecoder
	{
		private static readonly ResultPoint[] NO_POINTS = new ResultPoint[0];

		private readonly MessagingToolkit.Barcode.DataMatrix.Decoders.Decoder decoder;

		public DataMatrixDecoder()
		{
			decoder = new MessagingToolkit.Barcode.DataMatrix.Decoders.Decoder();
		}

		public Result Decode(BinaryBitmap image)
		{
			return Decode(image, null);
		}

		public Result Decode(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions)
		{
			DecoderResult decoderResult;
			ResultPoint[] resultPoints;
			if (decodingOptions != null && decodingOptions.ContainsKey(DecodeOptions.PureBarcode))
			{
				BitMatrix bits = ExtractPureBits(image.BlackMatrix);
				decoderResult = decoder.Decode(bits);
				resultPoints = NO_POINTS;
			}
			else
			{
				DetectorResult detectorResult = new MessagingToolkit.Barcode.DataMatrix.detector.Detector(image.BlackMatrix).Detect();
				decoderResult = decoder.Decode(detectorResult.Bits);
				resultPoints = detectorResult.Points;
			}
			Result result = new Result(decoderResult.Text, decoderResult.RawBytes, resultPoints, BarcodeFormat.DataMatrix);
			List<byte[]> byteSegments = decoderResult.ByteSegments;
			if (byteSegments != null)
			{
				result.PutMetadata(ResultMetadataType.ByteSegments, byteSegments);
			}
			string eCLevel = decoderResult.ECLevel;
			if (eCLevel != null)
			{
				result.PutMetadata(ResultMetadataType.ErrorCorrectionLevel, eCLevel);
			}
			return result;
		}

		public void Reset()
		{
		}

		private static BitMatrix ExtractPureBits(BitMatrix image)
		{
			int[] topLeftOnBit = image.GetTopLeftOnBit();
			int[] bottomRightOnBit = image.GetBottomRightOnBit();
			if (topLeftOnBit == null || bottomRightOnBit == null)
			{
				throw NotFoundException.Instance;
			}
			int num = ModuleSize(topLeftOnBit, image);
			int num2 = topLeftOnBit[1];
			int num3 = bottomRightOnBit[1];
			int num4 = topLeftOnBit[0];
			int num5 = (bottomRightOnBit[0] - num4 + 1) / num;
			int num6 = (num3 - num2 + 1) / num;
			if (num5 <= 0 || num6 <= 0)
			{
				throw NotFoundException.Instance;
			}
			int num7 = num >> 1;
			num2 += num7;
			num4 += num7;
			BitMatrix bitMatrix = new BitMatrix(num5, num6);
			for (int i = 0; i < num6; i++)
			{
				int y = num2 + i * num;
				for (int j = 0; j < num5; j++)
				{
					if (image.Get(num4 + j * num, y))
					{
						bitMatrix.Set(j, i);
					}
				}
			}
			return bitMatrix;
		}

		private static int ModuleSize(int[] leftTopBlack, BitMatrix image)
		{
			int width = image.Width;
			int i = leftTopBlack[0];
			for (int y = leftTopBlack[1]; i < width && image.Get(i, y); i++)
			{
			}
			if (i == width)
			{
				throw NotFoundException.Instance;
			}
			int num = i - leftTopBlack[0];
			if (num == 0)
			{
				throw NotFoundException.Instance;
			}
			return num;
		}
	}
	public sealed class DataMatrixWriter : IEncoder
	{
		public BitMatrix Encode(string contents, BarcodeFormat format, int width, int height)
		{
			return Encode(contents, format, width, height, null);
		}

		public BitMatrix Encode(string contents, BarcodeFormat format, int width, int height, Dictionary<EncodeOptions, object> encodingOptions)
		{
			if (string.IsNullOrEmpty(contents))
			{
				throw new ArgumentException("Found empty contents");
			}
			if (format != BarcodeFormat.DataMatrix)
			{
				throw new ArgumentException("Can only encode DATA_MATRIX, but got " + format);
			}
			if (width < 0 || height < 0)
			{
				throw new ArgumentException("Requested dimensions are too small: " + width + "x" + height);
			}
			SymbolShapeHint shape = SymbolShapeHint.ForceNone;
			Dimension minSize = null;
			Dimension maxSize = null;
			if (encodingOptions != null)
			{
				object encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.DataMatrixShape);
				if (encodeOptionType != null)
				{
					shape = (SymbolShapeHint)encodeOptionType;
				}
				encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.MinimumSize);
				if (encodeOptionType != null)
				{
					minSize = (Dimension)encodeOptionType;
				}
				encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.MaximumSize);
				if (encodeOptionType != null)
				{
					maxSize = (Dimension)encodeOptionType;
				}
			}
			string text = MessagingToolkit.Barcode.DataMatrix.Encoder.HighLevelEncoder.EncodeHighLevel(contents, shape, minSize, maxSize, encodingOptions);
			SymbolInfo symbolInfo = SymbolInfo.Lookup(text.Length, shape, minSize, maxSize, fail: true);
			DefaultPlacement defaultPlacement = new DefaultPlacement(MessagingToolkit.Barcode.DataMatrix.Encoder.ErrorCorrection.EncodeECC200(text, symbolInfo), symbolInfo.SymbolDataWidth, symbolInfo.SymbolDataHeight);
			defaultPlacement.Place();
			return EncodeLowLevel(defaultPlacement, symbolInfo);
		}

		private static BitMatrix EncodeLowLevel(DefaultPlacement placement, SymbolInfo symbolInfo)
		{
			int symbolDataWidth = symbolInfo.SymbolDataWidth;
			int symbolDataHeight = symbolInfo.SymbolDataHeight;
			ByteMatrix byteMatrix = new ByteMatrix(symbolInfo.SymbolWidth, symbolInfo.SymbolHeight);
			int num = 0;
			for (int i = 0; i < symbolDataHeight; i++)
			{
				int num2;
				if (i % symbolInfo.matrixHeight == 0)
				{
					num2 = 0;
					for (int j = 0; j < symbolInfo.SymbolWidth; j++)
					{
						byteMatrix.Set(num2, num, j % 2 == 0);
						num2++;
					}
					num++;
				}
				num2 = 0;
				for (int k = 0; k < symbolDataWidth; k++)
				{
					if (k % symbolInfo.matrixWidth == 0)
					{
						byteMatrix.Set(num2, num, val: true);
						num2++;
					}
					byteMatrix.Set(num2, num, placement.GetBit(k, i));
					num2++;
					if (k % symbolInfo.matrixWidth == symbolInfo.matrixWidth - 1)
					{
						byteMatrix.Set(num2, num, i % 2 == 0);
						num2++;
					}
				}
				num++;
				if (i % symbolInfo.matrixHeight == symbolInfo.matrixHeight - 1)
				{
					num2 = 0;
					for (int l = 0; l < symbolInfo.SymbolWidth; l++)
					{
						byteMatrix.Set(num2, num, val: true);
						num2++;
					}
					num++;
				}
			}
			return ConvertByteMatrixToBitMatrix(byteMatrix);
		}

		private static BitMatrix ConvertByteMatrixToBitMatrix(ByteMatrix matrix)
		{
			int width = matrix.Width;
			int height = matrix.Height;
			BitMatrix bitMatrix = new BitMatrix(width, height);
			bitMatrix.Clear();
			for (int i = 0; i < width; i++)
			{
				for (int j = 0; j < height; j++)
				{
					if (matrix.Get(i, j) == 1)
					{
						bitMatrix.Set(i, j);
					}
				}
			}
			return bitMatrix;
		}
	}
	public sealed class DataMatrixNewEncoder : IEncoder
	{
		private const int QUIET_ZONE_SIZE = 4;

		public BitMatrix Encode(string contents, BarcodeFormat format, int width, int height)
		{
			return Encode(contents, format, width, height, null);
		}

		public BitMatrix Encode(string contents, BarcodeFormat format, int width, int height, Dictionary<EncodeOptions, object> encodingOptions)
		{
			if (string.IsNullOrEmpty(contents))
			{
				throw new ArgumentException("Found empty contents");
			}
			if (format != BarcodeFormat.DataMatrix)
			{
				throw new ArgumentException("Can only encode Data Matrix, but got " + format);
			}
			if (width < 0 || height < 0)
			{
				throw new ArgumentException("Requested dimensions are too small: " + width + "x" + height);
			}
			SymbolShapeHint shape = SymbolShapeHint.ForceNone;
			Dimension minSize = null;
			Dimension maxSize = null;
			int quietZone = 4;
			if (encodingOptions != null)
			{
				object encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.DataMatrixShape);
				if (encodeOptionType != null)
				{
					shape = (SymbolShapeHint)encodeOptionType;
				}
				encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.MinimumSize);
				if (encodeOptionType != null)
				{
					minSize = (Dimension)encodeOptionType;
				}
				encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.MaximumSize);
				if (encodeOptionType != null)
				{
					maxSize = (Dimension)encodeOptionType;
				}
				encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.Margin);
				if (encodeOptionType != null)
				{
					quietZone = Convert.ToInt32(encodeOptionType);
				}
			}
			string text;
			try
			{
				text = MessagingToolkit.Barcode.DataMatrix.Encoder.HighLevelEncoder.EncodeHighLevel(contents, shape, minSize, maxSize, encodingOptions);
			}
			catch (Exception ex)
			{
				throw new ArgumentException("Cannot fetch data: " + ex.Message);
			}
			SymbolInfo symbolInfo = SymbolInfo.Lookup(text.Length, shape, minSize, maxSize, fail: true);
			DefaultPlacement defaultPlacement = new DefaultPlacement(MessagingToolkit.Barcode.DataMatrix.Encoder.ErrorCorrection.EncodeECC200(text, symbolInfo), symbolInfo.SymbolDataWidth, symbolInfo.SymbolDataHeight);
			defaultPlacement.Place();
			return RenderResult(EncodeLowLevel(defaultPlacement, symbolInfo), width, height, quietZone);
		}

		private ByteMatrix EncodeLowLevel(DefaultPlacement placement, SymbolInfo symbolInfo)
		{
			int symbolDataWidth = symbolInfo.SymbolDataWidth;
			int symbolDataHeight = symbolInfo.SymbolDataHeight;
			ByteMatrix byteMatrix = new ByteMatrix(symbolInfo.SymbolWidth, symbolInfo.SymbolHeight);
			int num = 0;
			int num2 = 0;
			for (int i = 0; i < symbolDataHeight; i++)
			{
				if (i % symbolInfo.matrixHeight == 0)
				{
					num = 0;
					for (int j = 0; j < symbolInfo.SymbolWidth; j++)
					{
						byteMatrix.Set(num, num2, j % 2 == 0);
						num++;
					}
					num2++;
				}
				num = 0;
				for (int k = 0; k < symbolDataWidth; k++)
				{
					if (k % symbolInfo.matrixWidth == 0)
					{
						byteMatrix.Set(num, num2, val: true);
						num++;
					}
					byteMatrix.Set(num, num2, placement.GetBit(k, i));
					num++;
					if (k % symbolInfo.matrixWidth == symbolInfo.matrixWidth - 1)
					{
						byteMatrix.Set(num, num2, i % 2 == 0);
						num++;
					}
				}
				num2++;
				if (i % symbolInfo.matrixHeight == symbolInfo.matrixHeight - 1)
				{
					num = 0;
					for (int l = 0; l < symbolInfo.SymbolWidth; l++)
					{
						byteMatrix.Set(num, num2, val: true);
						num++;
					}
					num2++;
				}
			}
			return byteMatrix;
		}

		private BitMatrix ConvertByteMatrixToBitMatrix(ByteMatrix matrix)
		{
			int width = matrix.Width;
			int height = matrix.Height;
			BitMatrix bitMatrix = new BitMatrix(width, height);
			bitMatrix.Clear();
			for (int i = 0; i < width; i++)
			{
				for (int j = 0; j < height; j++)
				{
					if (matrix.Get(i, j) == 1)
					{
						bitMatrix.Set(i, j);
					}
				}
			}
			return bitMatrix;
		}

		private static BitMatrix RenderResult(ByteMatrix input, int width, int height, int quietZone)
		{
			if (input == null)
			{
				throw new InvalidOperationException();
			}
			int width2 = input.Width;
			int height2 = input.Height;
			int num = width2 + (quietZone << 1);
			int num2 = height2 + (quietZone << 1);
			int num3 = Math.Max(width, num);
			int num4 = Math.Max(height, num2);
			int num5 = Math.Min(num3 / num, num4 / num2);
			int num6 = (num3 - width2 * num5) / 2;
			int num7 = (num4 - height2 * num5) / 2;
			BitMatrix bitMatrix = new BitMatrix(num3, num4);
			bitMatrix.LeftPadding = num6;
			bitMatrix.TopPadding = num7;
			bitMatrix.ActualHeight = num5 * height2;
			bitMatrix.ActualWidth = num5 * width2;
			int num8 = 0;
			int num9 = num7;
			while (num8 < height2)
			{
				int num10 = 0;
				int num11 = num6;
				while (num10 < width2)
				{
					if (input.Get(num10, num8) == 1)
					{
						bitMatrix.SetRegion(num11, num9, num5, num5);
					}
					num10++;
					num11 += num5;
				}
				num8++;
				num9 += num5;
			}
			return bitMatrix;
		}
	}
