			};
			_loc1 = new DataMatrixPixelLoc
			{
				X = orig._loc1.X,
				Y = orig._loc1.Y
			};
			_outward = orig._outward;
			_steep = orig._steep;
			_travel = orig._travel;
			_xDelta = orig._xDelta;
			_xOut = orig._xOut;
			_xStep = orig._xStep;
			_yDelta = orig._yDelta;
			_yOut = orig._yOut;
			_yStep = orig._yStep;
		}

		internal DataMatrixBresLine(DataMatrixPixelLoc loc0, DataMatrixPixelLoc loc1, DataMatrixPixelLoc locInside)
		{
			_loc0 = loc0;
			_loc1 = loc1;
			_xStep = ((loc0.X < loc1.X) ? 1 : (-1));
			_yStep = ((loc0.Y < loc1.Y) ? 1 : (-1));
			_xDelta = Math.Abs(loc1.X - loc0.X);
			_yDelta = Math.Abs(loc1.Y - loc0.Y);
			_steep = _yDelta > _xDelta;
			if (_steep)
			{
				DataMatrixPixelLoc dataMatrixPixelLoc;
				DataMatrixPixelLoc dataMatrixPixelLoc2;
				if (loc0.Y < loc1.Y)
				{
					dataMatrixPixelLoc = loc0;
					dataMatrixPixelLoc2 = loc1;
				}
				else
				{
					dataMatrixPixelLoc = loc1;
					dataMatrixPixelLoc2 = loc0;
				}
				int num = (dataMatrixPixelLoc2.X - dataMatrixPixelLoc.X) * (locInside.Y - dataMatrixPixelLoc2.Y) - (dataMatrixPixelLoc2.Y - dataMatrixPixelLoc.Y) * (locInside.X - dataMatrixPixelLoc2.X);
				_xOut = ((num > 0) ? 1 : (-1));
				_yOut = 0;
			}
			else
			{
				DataMatrixPixelLoc dataMatrixPixelLoc;
				DataMatrixPixelLoc dataMatrixPixelLoc2;
				if (loc0.X > loc1.X)
				{
					dataMatrixPixelLoc = loc0;
					dataMatrixPixelLoc2 = loc1;
				}
				else
				{
					dataMatrixPixelLoc = loc1;
					dataMatrixPixelLoc2 = loc0;
				}
				int num = (dataMatrixPixelLoc2.X - dataMatrixPixelLoc.X) * (locInside.Y - dataMatrixPixelLoc2.Y) - (dataMatrixPixelLoc2.Y - dataMatrixPixelLoc.Y) * (locInside.X - dataMatrixPixelLoc2.X);
				_xOut = 0;
				_yOut = ((num > 0) ? 1 : (-1));
			}
			_loc = loc0;
			_travel = 0;
			_outward = 0;
			_error = (_steep ? (_yDelta / 2) : (_xDelta / 2));
		}

		internal bool GetStep(DataMatrixPixelLoc target, ref int travel, ref int outward)
		{
			if (_steep)
			{
				travel = ((_yStep > 0) ? (target.Y - _loc.Y) : (_loc.Y - target.Y));
				Step(travel, 0);
				outward = ((_xOut > 0) ? (target.X - _loc.X) : (_loc.X - target.X));
				if (_yOut != 0)
				{
					throw new Exception("Invald yOut value for bresline step!");
				}
			}
			else
			{
				travel = ((_xStep > 0) ? (target.X - _loc.X) : (_loc.X - target.X));
				Step(travel, 0);
				outward = ((_yOut > 0) ? (target.Y - _loc.Y) : (_loc.Y - target.Y));
				if (_xOut != 0)
				{
					throw new Exception("Invald xOut value for bresline step!");
				}
			}
			return true;
		}

		internal bool Step(int travel, int outward)
		{
			if (Math.Abs(travel) >= 2)
			{
				throw new ArgumentException("Invalid value for 'travel' in BaseLineStep!");
			}
			if (travel > 0)
			{
				_travel++;
				if (_steep)
				{
					_loc = new DataMatrixPixelLoc
					{
						X = _loc.X,
						Y = _loc.Y + _yStep
					};
					_error -= _xDelta;
					if (_error < 0)
					{
						_loc = new DataMatrixPixelLoc
						{
							X = _loc.X + _xStep,
							Y = _loc.Y
						};
						_error += _yDelta;
					}
				}
				else
				{
					_loc = new DataMatrixPixelLoc
					{
						X = _loc.X + _xStep,
						Y = _loc.Y
					};
					_error -= _yDelta;
					if (_error < 0)
					{
						_loc = new DataMatrixPixelLoc
						{
							X = _loc.X,
							Y = _loc.Y + _yStep
						};
						_error += _xDelta;
					}
				}
			}
			else if (travel < 0)
			{
				_travel--;
				if (_steep)
				{
					_loc = new DataMatrixPixelLoc
					{
						X = _loc.X,
						Y = _loc.Y - _yStep
					};
					_error += _xDelta;
					if (Error >= YDelta)
					{
						_loc = new DataMatrixPixelLoc
						{
							X = _loc.X - _xStep,
							Y = _loc.Y
						};
						_error -= _yDelta;
					}
				}
				else
				{
					_loc = new DataMatrixPixelLoc
					{
						X = _loc.X - _xStep,
						Y = _loc.Y
					};
					_error += _yDelta;
					if (_error >= _xDelta)
					{
						_loc = new DataMatrixPixelLoc
						{
							X = _loc.X,
							Y = _loc.Y - _yStep
						};
						_error -= _xDelta;
					}
				}
			}
			for (int i = 0; i < outward; i++)
			{
				_outward++;
				_loc = new DataMatrixPixelLoc
				{
					X = _loc.X + _xOut,
					Y = _loc.Y + _yOut
				};
			}
			return true;
		}
