				ValidateSettingsAndInitScanGrid();
			}
		}

		internal int SquareDevn
		{
			get
			{
				return (int)(Math.Acos(_squareDevn) * 180.0 / Math.PI);
			}
			set
			{
				_squareDevn = Math.Cos((double)value * (Math.PI / 180.0));
				ValidateSettingsAndInitScanGrid();
			}
		}

		internal DataMatrixSymbolSize SizeIdxExpected
