		internal int Height => _image.Height / _scale;

		internal int Width => _image.Width / _scale;

		internal DataMatrixDecode(DataMatrixImage img, int scale)
		{
			int num = img.Width / scale;
			int num2 = img.Height / scale;
			_edgeMin = DataMatrixConstants.DataMatrixUndefined;
			_edgeMax = DataMatrixConstants.DataMatrixUndefined;
			_scanGap = 1;
			_squareDevn = Math.Cos(Math.PI * 5.0 / 18.0);
			_sizeIdxExpected = DataMatrixSymbolSize.SymbolShapeAuto;
			_edgeThresh = 10;
			_xMin = 0;
			_xMax = num - 1;
			_yMin = 0;
			_yMax = num2 - 1;
			_scale = scale;
			_cache = new byte[num * num2];
			_image = img;
			ValidateSettingsAndInitScanGrid();
		}

		private void ValidateSettingsAndInitScanGrid()
		{
			if (_squareDevn <= 0.0 || _squareDevn >= 1.0)
			{
				throw new ArgumentException("Invalid Decode settings!");
			}
			if (_scanGap < 1)
			{
				throw new ArgumentException("Invalid Decode settings!");
			}
			if (_edgeThresh < 1 || _edgeThresh > 100)
			{
				throw new ArgumentException("Invalid Decode settings!");
			}
			_grid = new DataMatrixScanGrid(this);
		}

		internal int GetCacheIndex(int x, int y)
		{
			if (x < 0 || x >= Width || y < 0 || y >= Height)
			{
				throw new ArgumentException("Error: x and/or y outside cache size");
			}
			return y * Width + x;
		}

		private bool GetPixelValue(int x, int y, int channel, ref int value)
		{
			int x2 = x * _scale;
			int y2 = y * _scale;
			return _image.GetPixelValue(x2, y2, channel, ref value);
		}

		internal void CacheFillQuad(DataMatrixPixelLoc p0, DataMatrixPixelLoc p1, DataMatrixPixelLoc p2, DataMatrixPixelLoc p3)
		{
			DataMatrixBresLine[] array = new DataMatrixBresLine[4];
			DataMatrixPixelLoc dataMatrixPixelLoc = default(DataMatrixPixelLoc);
			dataMatrixPixelLoc.X = 0;
			dataMatrixPixelLoc.Y = 0;
			DataMatrixPixelLoc locInside = dataMatrixPixelLoc;
			array[0] = new DataMatrixBresLine(p0, p1, locInside);
			array[1] = new DataMatrixBresLine(p1, p2, locInside);
			array[2] = new DataMatrixBresLine(p2, p3, locInside);
			array[3] = new DataMatrixBresLine(p3, p0, locInside);
			int yMax = _yMax;
			int x = 0;
			yMax = DataMatrixCommon.Min(yMax, p0.Y);
			x = DataMatrixCommon.Max(x, p0.Y);
			yMax = DataMatrixCommon.Min(yMax, p1.Y);
			x = DataMatrixCommon.Max(x, p1.Y);
			yMax = DataMatrixCommon.Min(yMax, p2.Y);
			x = DataMatrixCommon.Max(x, p2.Y);
			yMax = DataMatrixCommon.Min(yMax, p3.Y);
			x = DataMatrixCommon.Max(x, p3.Y);
			int num = x - yMax + 1;
			int[] array2 = new int[num];
			int[] array3 = new int[num];
			for (int i = 0; i < num; i++)
			{
				array2[i] = _xMax;
			}
			for (int i = 0; i < 4; i++)
			{
				while (array[i].Loc.X != array[i].Loc1.X || array[i].Loc.Y != array[i].Loc1.Y)
				{
					int num2 = array[i].Loc.Y - yMax;
					array2[num2] = DataMatrixCommon.Min(array2[num2], array[i].Loc.X);
					array3[num2] = DataMatrixCommon.Max(array3[num2], array[i].Loc.X);
					array[i].Step(1, 0);
				}
			}
			for (int j = yMax; j < x && j < _yMax; j++)
			{
				int num2 = j - yMax;
				for (int k = array2[num2]; k < array3[num2] && k < _xMax; k++)
				{
					if (k >= 0 && j >= 0)
					{
						try
						{
							int cacheIndex = GetCacheIndex(k, j);
							_cache[cacheIndex] |= 128;
						}
						catch
						{
						}
					}
				}
			}
		}

		internal DataMatrixMessage MosaicRegion(DataMatrixRegion reg, int fix)
		{
			int plane = reg.FlowBegin.Plane;
			reg.FlowBegin.Plane = 0;
			DataMatrixMessage dataMatrixMessage = MatrixRegion(reg, fix);
			reg.FlowBegin.Plane = 1;
			DataMatrixMessage dataMatrixMessage2 = MatrixRegion(reg, fix);
			reg.FlowBegin.Plane = 2;
			DataMatrixMessage dataMatrixMessage3 = MatrixRegion(reg, fix);
			reg.FlowBegin.Plane = plane;
			DataMatrixMessage dataMatrixMessage4 = new DataMatrixMessage(reg.SizeIdx, DataMatrixFormat.Mosaic);
			List<byte> list = new List<byte>();
			for (int i = 0; i < dataMatrixMessage3.OutputSize && dataMatrixMessage3.Output[i] != 0; i++)
			{
				list.Add(dataMatrixMessage3.Output[i]);
			}
			for (int j = 0; j < dataMatrixMessage2.OutputSize && dataMatrixMessage2.Output[j] != 0; j++)
			{
				list.Add(dataMatrixMessage2.Output[j]);
			}
			for (int k = 0; k < dataMatrixMessage.OutputSize && dataMatrixMessage.Output[k] != 0; k++)
			{
				list.Add(dataMatrixMessage.Output[k]);
			}
			list.Add(0);
			dataMatrixMessage4.Output = list.ToArray();
			return dataMatrixMessage4;
		}

		internal DataMatrixMessage MatrixRegion(DataMatrixRegion reg, int fix)
		{
			DataMatrixMessage dataMatrixMessage = new DataMatrixMessage(reg.SizeIdx, DataMatrixFormat.Matrix);
			DataMatrixVector2 dataMatrixVector = new DataMatrixVector2();
			DataMatrixVector2 dataMatrixVector2 = new DataMatrixVector2();
			DataMatrixVector2 dataMatrixVector3 = new DataMatrixVector2();
			DataMatrixVector2 dataMatrixVector4 = new DataMatrixVector2();
			DataMatrixPixelLoc p = default(DataMatrixPixelLoc);
			DataMatrixPixelLoc p2 = default(DataMatrixPixelLoc);
			DataMatrixPixelLoc p3 = default(DataMatrixPixelLoc);
			DataMatrixPixelLoc p4 = default(DataMatrixPixelLoc);
			if (!PopulateArrayFromMatrix(reg, dataMatrixMessage))
			{
				throw new Exception("Populating Array from matrix failed!");
			}
			ModulePlacementEcc200(dataMatrixMessage.Array, dataMatrixMessage.Code, reg.SizeIdx, DataMatrixConstants.DataMatrixModuleOnRed | DataMatrixConstants.DataMatrixModuleOnGreen | DataMatrixConstants.DataMatrixModuleOnBlue);
			if (!DataMatrixCommon.DecodeCheckErrors(dataMatrixMessage.Code, 0, reg.SizeIdx, fix))
			{
				return null;
			}
			DataMatrixVector2 dataMatrixVector5 = dataMatrixVector;
			DataMatrixVector2 dataMatrixVector6 = dataMatrixVector3;
			DataMatrixVector2 dataMatrixVector7 = dataMatrixVector;
			double num2 = (dataMatrixVector2.Y = -0.1);
			double num4 = (dataMatrixVector7.Y = num2);
			double x = (dataMatrixVector6.X = num4);
			dataMatrixVector5.X = x;
			DataMatrixVector2 dataMatrixVector8 = dataMatrixVector2;
			DataMatrixVector2 dataMatrixVector9 = dataMatrixVector3;
			num2 = (dataMatrixVector4.Y = 1.1);
			num4 = (dataMatrixVector9.Y = num2);
			x = (dataMatrixVector4.X = num4);
			dataMatrixVector8.X = x;
			dataMatrixVector *= reg.Fit2Raw;
			dataMatrixVector2 *= reg.Fit2Raw;
			dataMatrixVector3 *= reg.Fit2Raw;
			dataMatrixVector3 *= reg.Fit2Raw;
			p.X = (int)(0.5 + dataMatrixVector.X);
			p.Y = (int)(0.5 + dataMatrixVector.Y);
			p3.X = (int)(0.5 + dataMatrixVector3.X);
			p3.Y = (int)(0.5 + dataMatrixVector3.Y);
			p2.X = (int)(0.5 + dataMatrixVector2.X);
			p2.Y = (int)(0.5 + dataMatrixVector2.Y);
			p4.X = (int)(0.5 + dataMatrixVector4.X);
			p4.Y = (int)(0.5 + dataMatrixVector4.Y);
			CacheFillQuad(p, p2, p4, p3);
			dataMatrixMessage.DecodeDataStream(reg.SizeIdx, null);
			return dataMatrixMessage;
		}

		private bool PopulateArrayFromMatrix(DataMatrixRegion reg, DataMatrixMessage msg)
		{
			int symbolAttribute = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribHorizDataRegions, reg.SizeIdx);
			int symbolAttribute2 = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribVertDataRegions, reg.SizeIdx);
			int symbolAttribute3 = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribDataRegionCols, reg.SizeIdx);
			int symbolAttribute4 = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribDataRegionRows, reg.SizeIdx);
			int num = 2 * (symbolAttribute4 + symbolAttribute3 + 2);
			if (num <= 0)
			{
				throw new ArgumentException("PopulateArrayFromMatrix error: Weight Factor must be greater 0");
			}
			for (int i = 0; i < symbolAttribute2; i++)
			{
				int yOrigin = i * (symbolAttribute4 + 2) + 1;
				for (int j = 0; j < symbolAttribute; j++)
				{
					int[,] array = new int[24, 24];
					int xOrigin = j * (symbolAttribute3 + 2) + 1;
					for (int k = 0; k < 24; k++)
					{
						for (int l = 0; l < 24; l++)
						{
							array[k, l] = 0;
						}
					}
					TallyModuleJumps(reg, array, xOrigin, yOrigin, symbolAttribute3, symbolAttribute4, DataMatrixDirection.DirUp);
					TallyModuleJumps(reg, array, xOrigin, yOrigin, symbolAttribute3, symbolAttribute4, DataMatrixDirection.DirLeft);
					TallyModuleJumps(reg, array, xOrigin, yOrigin, symbolAttribute3, symbolAttribute4, DataMatrixDirection.DirDown);
					TallyModuleJumps(reg, array, xOrigin, yOrigin, symbolAttribute3, symbolAttribute4, DataMatrixDirection.DirRight);
					for (int m = 0; m < symbolAttribute4; m++)
					{
						for (int n = 0; n < symbolAttribute3; n++)
						{
							int num2 = i * symbolAttribute4 + m;
							num2 = symbolAttribute2 * symbolAttribute4 - num2 - 1;
							int num3 = j * symbolAttribute3 + n;
							int num4 = num2 * symbolAttribute * symbolAttribute3 + num3;
							if ((double)array[m, n] / (double)num >= 0.5)
							{
								msg.Array[num4] = (byte)DataMatrixConstants.DataMatrixModuleOnRGB;
							}
							else
							{
								msg.Array[num4] = (byte)DataMatrixConstants.DataMatrixModuleOff;
							}
							msg.Array[num4] |= (byte)DataMatrixConstants.DataMatrixModuleAssigned;
						}
					}
				}
			}
			return true;
		}

		private void TallyModuleJumps(DataMatrixRegion reg, int[,] tally, int xOrigin, int yOrigin, int mapWidth, int mapHeight, DataMatrixDirection dir)
		{
			if (dir != DataMatrixDirection.DirUp && dir != DataMatrixDirection.DirLeft && dir != DataMatrixDirection.DirDown && dir != DataMatrixDirection.DirRight)
			{
				throw new ArgumentException("Only orthogonal directions are allowed in tally module jumps!");
			}
			int num = ((dir == DataMatrixDirection.DirUp || dir == DataMatrixDirection.DirRight) ? 1 : (-1));
			bool flag = false;
			int num2;
			int num3;
			int num4;
			int num5;
			int num6;
			if ((dir & DataMatrixDirection.DirHorizontal) != 0)
			{
				flag = true;
				num2 = mapWidth;
				num3 = yOrigin;
				num4 = yOrigin + mapHeight;
				num5 = ((num == 1) ? (xOrigin - 1) : (xOrigin + mapWidth));
				num6 = ((num == 1) ? (xOrigin + mapWidth) : (xOrigin - 1));
			}
			else
			{
				num2 = mapHeight;
				num3 = xOrigin;
				num4 = xOrigin + mapWidth;
				num5 = ((num == 1) ? (yOrigin - 1) : (yOrigin + mapHeight));
				num6 = ((num == 1) ? (yOrigin + mapHeight) : (yOrigin - 1));
			}
			bool flag2 = reg.OffColor > reg.OnColor;
			int num7 = Math.Abs((int)(0.4 * (double)(reg.OffColor - reg.OnColor) + 0.5));
			if (num7 < 0)
			{
				throw new Exception("Negative jump threshold is not allowed in tally module jumps");
			}
			for (int i = num3; i < num4; i++)
			{
				int num8 = num5;
				int num9 = (flag ? ReadModuleColor(reg, i, num8, reg.SizeIdx, reg.FlowBegin.Plane) : ReadModuleColor(reg, num8, i, reg.SizeIdx, reg.FlowBegin.Plane));
				int num10 = (flag2 ? (reg.OffColor - num9) : (num9 - reg.OffColor));
				int num11 = ((num == 1 || (i & 1) == 0) ? DataMatrixConstants.DataMatrixModuleOnRGB : DataMatrixConstants.DataMatrixModuleOff);
				int num12 = num2;
				while ((num8 += num) != num6)
				{
					int num13 = num10;
					int num14 = num11;
					num9 = (flag ? ReadModuleColor(reg, i, num8, reg.SizeIdx, reg.FlowBegin.Plane) : ReadModuleColor(reg, num8, i, reg.SizeIdx, reg.FlowBegin.Plane));
					num10 = (flag2 ? (reg.OffColor - num9) : (num9 - reg.OffColor));
					if (num14 == DataMatrixConstants.DataMatrixModuleOnRGB)
					{
						num11 = ((num10 < num13 - num7) ? DataMatrixConstants.DataMatrixModuleOff : DataMatrixConstants.DataMatrixModuleOnRGB);
					}
					else if (num14 == DataMatrixConstants.DataMatrixModuleOff)
					{
						num11 = ((num10 > num13 + num7) ? DataMatrixConstants.DataMatrixModuleOnRGB : DataMatrixConstants.DataMatrixModuleOff);
					}
					int num15;
					int num16;
					if (flag)
					{
						num15 = i - yOrigin;
						num16 = num8 - xOrigin;
					}
					else
					{
						num15 = num8 - yOrigin;
						num16 = i - xOrigin;
					}
					if (num15 >= 24 || num16 >= 24)
					{
						throw new Exception("Tally module mump failed, index out of range!");
					}
					if (num11 == DataMatrixConstants.DataMatrixModuleOnRGB)
					{
						tally[num15, num16] += 2 * num12;
					}
					num12--;
				}
				if (num12 != 0)
				{
					throw new Exception("Tally module jump failed, weight <> 0!");
				}
			}
		}

		private int ReadModuleColor(DataMatrixRegion reg, int symbolRow, int symbolCol, DataMatrixSymbolSize sizeIdx, int colorPlane)
		{
			double[] array = new double[5] { 0.5, 0.4, 0.5, 0.6, 0.5 };
			double[] array2 = new double[5] { 0.5, 0.5, 0.4, 0.5, 0.6 };
			DataMatrixVector2 dataMatrixVector = new DataMatrixVector2();
			int symbolAttribute = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolRows, sizeIdx);
			int symbolAttribute2 = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolCols, sizeIdx);
			int num;
			int value = (num = 0);
			for (int i = 0; i < 5; i++)
			{
				dataMatrixVector.X = 1.0 / (double)symbolAttribute2 * ((double)symbolCol + array[i]);
				dataMatrixVector.Y = 1.0 / (double)symbolAttribute * ((double)symbolRow + array2[i]);
				dataMatrixVector *= reg.Fit2Raw;
				GetPixelValue((int)(dataMatrixVector.X + 0.5), (int)(dataMatrixVector.Y + 0.5), colorPlane, ref value);
				num += value;
			}
			return num / 5;
		}

		internal static int ModulePlacementEcc200(byte[] modules, byte[] codewords, DataMatrixSymbolSize sizeIdx, int moduleOnColor)
		{
			if ((moduleOnColor & (DataMatrixConstants.DataMatrixModuleOnRed | DataMatrixConstants.DataMatrixModuleOnGreen | DataMatrixConstants.DataMatrixModuleOnBlue)) == 0)
			{
				throw new Exception("Error with module placement ECC 200");
			}
			int symbolAttribute = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribMappingMatrixRows, sizeIdx);
			int symbolAttribute2 = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribMappingMatrixCols, sizeIdx);
			int result = 0;
			int num = 4;
			int num2 = 0;
			do
			{
				if (num == symbolAttribute && num2 == 0)
				{
					PatternShapeSpecial1(modules, symbolAttribute, symbolAttribute2, codewords, result++, moduleOnColor);
				}
				else if (num == symbolAttribute - 2 && num2 == 0 && symbolAttribute2 % 4 != 0)
				{
					PatternShapeSpecial2(modules, symbolAttribute, symbolAttribute2, codewords, result++, moduleOnColor);
				}
				else if (num == symbolAttribute - 2 && num2 == 0 && symbolAttribute2 % 8 == 4)
				{
					PatternShapeSpecial3(modules, symbolAttribute, symbolAttribute2, codewords, result++, moduleOnColor);
				}
				else if (num == symbolAttribute + 4 && num2 == 2 && symbolAttribute2 % 8 == 0)
				{
					PatternShapeSpecial4(modules, symbolAttribute, symbolAttribute2, codewords, result++, moduleOnColor);
				}
				do
				{
					if (num < symbolAttribute && num2 >= 0 && (modules[num * symbolAttribute2 + num2] & DataMatrixConstants.DataMatrixModuleVisited) == 0)
					{
						PatternShapeStandard(modules, symbolAttribute, symbolAttribute2, num, num2, codewords, result++, moduleOnColor);
					}
					num -= 2;
					num2 += 2;
				}
				while (num >= 0 && num2 < symbolAttribute2);
				num++;
				num2 += 3;
				do
				{
					if (num >= 0 && num2 < symbolAttribute2 && (modules[num * symbolAttribute2 + num2] & DataMatrixConstants.DataMatrixModuleVisited) == 0)
					{
						PatternShapeStandard(modules, symbolAttribute, symbolAttribute2, num, num2, codewords, result++, moduleOnColor);
					}
					num += 2;
					num2 -= 2;
				}
				while (num < symbolAttribute && num2 >= 0);
				num += 3;
				num2++;
			}
			while (num < symbolAttribute || num2 < symbolAttribute2);
			if ((modules[symbolAttribute * symbolAttribute2 - 1] & DataMatrixConstants.DataMatrixModuleVisited) == 0)
			{
				modules[symbolAttribute * symbolAttribute2 - 1] |= (byte)moduleOnColor;
				modules[symbolAttribute * symbolAttribute2 - symbolAttribute2 - 2] |= (byte)moduleOnColor;
			}
			return result;
		}

		internal static void PatternShapeStandard(byte[] modules, int mappingRows, int mappingCols, int row, int col, byte[] codeword, int codeWordIndex, int moduleOnColor)
		{
			PlaceModule(modules, mappingRows, mappingCols, row - 2, col - 2, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit1, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, row - 2, col - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit2, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, row - 1, col - 2, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit3, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, row - 1, col - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit4, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, row - 1, col, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit5, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, row, col - 2, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit6, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, row, col - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit7, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, row, col, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit8, moduleOnColor);
		}

		internal static void PatternShapeSpecial1(byte[] modules, int mappingRows, int mappingCols, byte[] codeword, int codeWordIndex, int moduleOnColor)
		{
			PlaceModule(modules, mappingRows, mappingCols, mappingRows - 1, 0, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit1, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, mappingRows - 1, 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit2, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, mappingRows - 1, 2, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit3, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 0, mappingCols - 2, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit4, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 0, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit5, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 1, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit6, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 2, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit7, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 3, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit8, moduleOnColor);
		}

		internal static void PatternShapeSpecial2(byte[] modules, int mappingRows, int mappingCols, byte[] codeword, int codeWordIndex, int moduleOnColor)
		{
			PlaceModule(modules, mappingRows, mappingCols, mappingRows - 3, 0, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit1, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, mappingRows - 2, 0, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit2, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, mappingRows - 1, 0, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit3, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 0, mappingCols - 4, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit4, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 0, mappingCols - 3, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit5, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 0, mappingCols - 2, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit6, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 0, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit7, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 1, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit8, moduleOnColor);
		}

		internal static void PatternShapeSpecial3(byte[] modules, int mappingRows, int mappingCols, byte[] codeword, int codeWordIndex, int moduleOnColor)
		{
			PlaceModule(modules, mappingRows, mappingCols, mappingRows - 3, 0, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit1, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, mappingRows - 2, 0, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit2, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, mappingRows - 1, 0, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit3, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 0, mappingCols - 2, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit4, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 0, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit5, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 1, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit6, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 2, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit7, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 3, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit8, moduleOnColor);
		}

		internal static void PatternShapeSpecial4(byte[] modules, int mappingRows, int mappingCols, byte[] codeword, int codeWordIndex, int moduleOnColor)
		{
			PlaceModule(modules, mappingRows, mappingCols, mappingRows - 1, 0, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit1, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, mappingRows - 1, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit2, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 0, mappingCols - 3, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit3, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 0, mappingCols - 2, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit4, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 0, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit5, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 1, mappingCols - 3, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit6, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 1, mappingCols - 2, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit7, moduleOnColor);
			PlaceModule(modules, mappingRows, mappingCols, 1, mappingCols - 1, codeword, codeWordIndex, DataMatrixMaskBit.MaskBit8, moduleOnColor);
		}

		internal static void PlaceModule(byte[] modules, int mappingRows, int mappingCols, int row, int col, byte[] codeword, int codeWordIndex, DataMatrixMaskBit mask, int moduleOnColor)
		{
			if (row < 0)
			{
				row += mappingRows;
				col += 4 - (mappingRows + 4) % 8;
			}
			if (col < 0)
			{
				col += mappingCols;
				row += 4 - (mappingCols + 4) % 8;
			}
			if ((modules[row * mappingCols + col] & DataMatrixConstants.DataMatrixModuleAssigned) != 0)
			{
				if ((modules[row * mappingCols + col] & moduleOnColor) != 0)
				{
					codeword[codeWordIndex] |= (byte)mask;
				}
				else
				{
					codeword[codeWordIndex] &= (byte)((DataMatrixMaskBit)255 ^ mask);
				}
			}
			else
			{
				if ((codeword[codeWordIndex] & (byte)mask) != 0)
				{
					modules[row * mappingCols + col] |= (byte)moduleOnColor;
				}
				modules[row * mappingCols + col] |= (byte)DataMatrixConstants.DataMatrixModuleAssigned;
			}
			modules[row * mappingCols + col] |= (byte)DataMatrixConstants.DataMatrixModuleVisited;
		}

		internal DataMatrixRegion RegionFindNext(TimeSpan timeout)
		{
			DataMatrixPixelLoc loc = default(DataMatrixPixelLoc);
			DateTime now = DateTime.Now;
			while (_grid.PopGridLocation(ref loc) != DataMatrixRange.RangeEnd)
			{
				DataMatrixRegion dataMatrixRegion = RegionScanPixel(loc.X, loc.Y);
				if (dataMatrixRegion != null)
				{
					return dataMatrixRegion;
				}
				if (DateTime.Now - now > timeout)
				{
					break;
				}
			}
			return null;
		}

		private DataMatrixRegion RegionScanPixel(int x, int y)
		{
			DataMatrixRegion dataMatrixRegion = new DataMatrixRegion();
			DataMatrixPixelLoc dataMatrixPixelLoc = default(DataMatrixPixelLoc);
			dataMatrixPixelLoc.X = x;
			dataMatrixPixelLoc.Y = y;
			DataMatrixPixelLoc loc = dataMatrixPixelLoc;
			int num = DecodeGetCache(loc.X, loc.Y);
			if (num == -1)
			{
				return null;
			}
			if (_cache[num] != 0)
			{
				return null;
			}
			DataMatrixPointFlow dataMatrixPointFlow = MatrixRegionSeekEdge(loc);
			if (dataMatrixPointFlow.Mag < (int)((double)_edgeThresh * 7.65 + 0.5))
			{
				return null;
			}
			if (!MatrixRegionOrientation(dataMatrixRegion, dataMatrixPointFlow))
			{
				return null;
			}
			if (!RegionUpdateXfrms(dataMatrixRegion))
			{
				return null;
			}
			if (!MatrixRegionAlignCalibEdge(dataMatrixRegion, DataMatrixEdge.EdgeTop))
			{
				return null;
			}
			if (!RegionUpdateXfrms(dataMatrixRegion))
			{
				return null;
			}
			if (!MatrixRegionAlignCalibEdge(dataMatrixRegion, DataMatrixEdge.EdgeRight))
			{
				return null;
			}
			if (!RegionUpdateXfrms(dataMatrixRegion))
			{
				return null;
			}
			if (!MatrixRegionFindSize(dataMatrixRegion))
			{
				return null;
			}
			return new DataMatrixRegion(dataMatrixRegion);
		}

		private int DecodeGetCache(int x, int y)
		{
			int width = Width;
			int height = Height;
			if (x < 0 || x >= width || y < 0 || y >= height)
			{
				return DataMatrixConstants.DataMatrixUndefined;
			}
			return y * width + x;
		}

		private DataMatrixPointFlow MatrixRegionSeekEdge(DataMatrixPixelLoc loc)
		{
			DataMatrixPointFlow[] array = new DataMatrixPointFlow[3];
			int channelCount = _image.ChannelCount;
			int num = 0;
			for (int i = 0; i < channelCount; i++)
			{
				array[i] = GetPointFlow(i, loc, DataMatrixConstants.DataMatrixNeighborNone);
				if (i > 0 && array[i].Mag > array[num].Mag)
				{
					num = i;
				}
			}
			if (array[num].Mag < 10)
			{
				return DataMatrixConstants.DataMatrixBlankEdge;
			}
			DataMatrixPointFlow dataMatrixPointFlow = array[num];
			DataMatrixPointFlow dataMatrixPointFlow2 = FindStrongestNeighbor(dataMatrixPointFlow, 1);
			DataMatrixPointFlow dataMatrixPointFlow3 = FindStrongestNeighbor(dataMatrixPointFlow, -1);
			if (dataMatrixPointFlow2.Mag != 0 && dataMatrixPointFlow3.Mag != 0)
			{
				DataMatrixPointFlow dataMatrixPointFlow4 = FindStrongestNeighbor(dataMatrixPointFlow2, -1);
				DataMatrixPointFlow dataMatrixPointFlow5 = FindStrongestNeighbor(dataMatrixPointFlow3, 1);
				if (dataMatrixPointFlow2.Arrive == (dataMatrixPointFlow4.Arrive + 4) % 8 && dataMatrixPointFlow3.Arrive == (dataMatrixPointFlow5.Arrive + 4) % 8)
				{
					dataMatrixPointFlow.Arrive = DataMatrixConstants.DataMatrixNeighborNone;
					return dataMatrixPointFlow;
				}
			}
			return DataMatrixConstants.DataMatrixBlankEdge;
		}

		private DataMatrixPointFlow FindStrongestNeighbor(DataMatrixPointFlow center, int sign)
		{
			DataMatrixPixelLoc loc = default(DataMatrixPixelLoc);
			DataMatrixPointFlow[] array = new DataMatrixPointFlow[8];
			int num = ((sign < 0) ? center.Depart : ((center.Depart + 4) % 8));
			int num2 = 0;
			int num3 = DataMatrixConstants.DataMatrixUndefined;
			for (int i = 0; i < 8; i++)
			{
				loc.X = center.Loc.X + DataMatrixConstants.DataMatrixPatternX[i];
				loc.Y = center.Loc.Y + DataMatrixConstants.DataMatrixPatternY[i];
				int num4 = DecodeGetCache(loc.X, loc.Y);
				if (num4 == DataMatrixConstants.DataMatrixUndefined)
				{
					continue;
				}
				if ((_cache[num4] & 0x80u) != 0)
				{
					if (++num2 > 2)
					{
						return DataMatrixConstants.DataMatrixBlankEdge;
					}
					continue;
				}
				int num5 = Math.Abs(num - i);
				if (num5 > 4)
				{
					num5 = 8 - num5;
				}
				if (num5 <= 1)
				{
					array[i] = GetPointFlow(center.Plane, loc, i);
					if (num3 == DataMatrixConstants.DataMatrixUndefined || array[i].Mag > array[num3].Mag || (array[i].Mag == array[num3].Mag && ((uint)i & (true ? 1u : 0u)) != 0))
					{
						num3 = i;
					}
				}
			}
			if (num3 != DataMatrixConstants.DataMatrixUndefined)
			{
				return array[num3];
			}
			return DataMatrixConstants.DataMatrixBlankEdge;
		}

		private DataMatrixPointFlow GetPointFlow(int colorPlane, DataMatrixPixelLoc loc, int arrive)
		{
			int[] array = new int[8] { 0, 1, 2, 1, 0, -1, -2, -1 };
			int[] array2 = new int[4];
			int[] array3 = new int[8];
			DataMatrixPointFlow dataMatrixPointFlow = new DataMatrixPointFlow();
			for (int i = 0; i < 8; i++)
			{
				int x = loc.X + DataMatrixConstants.DataMatrixPatternX[i];
				int y = loc.Y + DataMatrixConstants.DataMatrixPatternY[i];
				if (!GetPixelValue(x, y, colorPlane, ref array3[i]))
				{
					return DataMatrixConstants.DataMatrixBlankEdge;
				}
			}
			int num = 0;
			for (int j = 0; j < 4; j++)
			{
				for (int i = 0; i < 8; i++)
				{
					int num2 = (i - j + 8) % 8;
					if (array[num2] != 0)
					{
						int num3 = array3[i];
						switch (array[num2])
						{
						case 2:
							array2[j] += 2 * num3;
							break;
						case 1:
							array2[j] += num3;
							break;
						case -2:
							array2[j] -= 2 * num3;
							break;
						case -1:
							array2[j] -= num3;
							break;
						}
					}
				}
				if (j != 0 && Math.Abs(array2[j]) > Math.Abs(array2[num]))
				{
					num = j;
				}
			}
			dataMatrixPointFlow.Plane = colorPlane;
			dataMatrixPointFlow.Arrive = arrive;
			dataMatrixPointFlow.Depart = ((array2[num] > 0) ? (num + 4) : num);
			dataMatrixPointFlow.Mag = Math.Abs(array2[num]);
			dataMatrixPointFlow.Loc = loc;
			return dataMatrixPointFlow;
		}

		private bool MatrixRegionFindSize(DataMatrixRegion reg)
		{
