		private int TrailClear(DataMatrixRegion reg, int clearMask)
		{
			if ((clearMask | 0xFF) != 255)
			{
				throw new Exception("TrailClear mask is invalid!");
			}
			int num = 0;
			DataMatrixFollow followBeg = FollowSeek(reg, 0);
			while (Math.Abs(followBeg.Step) <= reg.StepsTotal)
			{
				if ((followBeg.CurrentPtr & clearMask) == 0)
				{
					throw new Exception("Error performing TrailClear");
				}
				followBeg.CurrentPtr &= (byte)(clearMask ^ 0xFF);
				followBeg = FollowStep(reg, followBeg, 1);
				num++;
			}
			return num;
		}

		private DataMatrixFollow FollowStep(DataMatrixRegion reg, DataMatrixFollow followBeg, int sign)
		{
