					Y = followBeg.Loc.Y + DataMatrixConstants.DataMatrixPatternY[num3]
				};
			}
			result.Step = followBeg.Step + sign;
			result.Ptr = _cache;
			result.PtrIndex = DecodeGetCache(result.Loc.X, result.Loc.Y);
			return result;
		}

