				{
					int num15 = followBeg.Loc.X - loc.X;
					int num16 = followBeg.Loc.Y - loc.Y;
					value = num * num15 + num2 * num16;
					num13 = num * num16 - num2 * num15;
					if (num13 >= -768 && num13 < 768)
					{
						int num17 = DistanceSquared(followBeg.Loc, b);
						if (num17 > num3)
						{
							loc2 = followBeg.Loc;
							num3 = num17;
							line.StepNeg = followBeg.Step;
							line.LocNeg = followBeg.Loc;
							num10 = num12;
							num9 = num11;
						}
					}
					else
					{
						num12 = DataMatrixCommon.Min(num12, num13);
						num11 = DataMatrixCommon.Max(num11, num13);
					}
				}
				followBeg2 = FollowStep(reg, followBeg2, 1);
				followBeg = FollowStep(reg, followBeg, -1);
			}
			line.Devn = DataMatrixCommon.Max(num4 - num5, num9 - num10) / 256;
			line.DistSq = num3;
		}

		private int DistanceSquared(DataMatrixPixelLoc a, DataMatrixPixelLoc b)
		{
			int num = a.X - b.X;
			int num2 = a.Y - b.Y;
			return num * num + num2 * num2;
		}

		private bool RegionUpdateXfrms(DataMatrixRegion reg)
		{
			DataMatrixRay2 dataMatrixRay = new DataMatrixRay2();
			DataMatrixRay2 dataMatrixRay2 = new DataMatrixRay2();
			DataMatrixRay2 dataMatrixRay3 = new DataMatrixRay2();
			DataMatrixRay2 dataMatrixRay4 = new DataMatrixRay2();
			DataMatrixVector2 dataMatrixVector = new DataMatrixVector2();
			DataMatrixVector2 dataMatrixVector2 = new DataMatrixVector2();
			DataMatrixVector2 dataMatrixVector3 = new DataMatrixVector2();
			DataMatrixVector2 dataMatrixVector4 = new DataMatrixVector2();
			if (reg.LeftKnown == 0 || reg.BottomKnown == 0)
			{
				throw new ArgumentException("Error updating Xfrms!");
			}
			dataMatrixRay.P.X = reg.LeftLoc.X;
			dataMatrixRay.P.Y = reg.LeftLoc.Y;
			double num = (double)reg.LeftAngle * (Math.PI / (double)DataMatrixConstants.DataMatrixHoughRes);
			dataMatrixRay.V.X = Math.Cos(num);
			dataMatrixRay.V.Y = Math.Sin(num);
			dataMatrixRay.TMin = 0.0;
			dataMatrixRay.TMax = dataMatrixRay.V.Norm();
			dataMatrixRay2.P.X = reg.BottomLoc.X;
			dataMatrixRay2.P.Y = reg.BottomLoc.Y;
			num = (double)reg.BottomAngle * (Math.PI / (double)DataMatrixConstants.DataMatrixHoughRes);
			dataMatrixRay2.V.X = Math.Cos(num);
			dataMatrixRay2.V.Y = Math.Sin(num);
			dataMatrixRay2.TMin = 0.0;
			dataMatrixRay2.TMax = dataMatrixRay2.V.Norm();
			if (reg.TopKnown != 0)
			{
				dataMatrixRay3.P.X = reg.TopLoc.X;
				dataMatrixRay3.P.Y = reg.TopLoc.Y;
				num = (double)reg.TopAngle * (Math.PI / (double)DataMatrixConstants.DataMatrixHoughRes);
				dataMatrixRay3.V.X = Math.Cos(num);
				dataMatrixRay3.V.Y = Math.Sin(num);
				dataMatrixRay3.TMin = 0.0;
				dataMatrixRay3.TMax = dataMatrixRay3.V.Norm();
			}
			else
			{
				dataMatrixRay3.P.X = reg.LocT.X;
				dataMatrixRay3.P.Y = reg.LocT.Y;
				num = (double)reg.BottomAngle * (Math.PI / (double)DataMatrixConstants.DataMatrixHoughRes);
				dataMatrixRay3.V.X = Math.Cos(num);
				dataMatrixRay3.V.Y = Math.Sin(num);
				dataMatrixRay3.TMin = 0.0;
				dataMatrixRay3.TMax = dataMatrixRay2.TMax;
			}
			if (reg.RightKnown != 0)
			{
				dataMatrixRay4.P.X = reg.RightLoc.X;
				dataMatrixRay4.P.Y = reg.RightLoc.Y;
				num = (double)reg.RightAngle * (Math.PI / (double)DataMatrixConstants.DataMatrixHoughRes);
				dataMatrixRay4.V.X = Math.Cos(num);
				dataMatrixRay4.V.Y = Math.Sin(num);
				dataMatrixRay4.TMin = 0.0;
				dataMatrixRay4.TMax = dataMatrixRay4.V.Norm();
			}
			else
			{
				dataMatrixRay4.P.X = reg.LocR.X;
				dataMatrixRay4.P.Y = reg.LocR.Y;
				num = (double)reg.LeftAngle * (Math.PI / (double)DataMatrixConstants.DataMatrixHoughRes);
				dataMatrixRay4.V.X = Math.Cos(num);
				dataMatrixRay4.V.Y = Math.Sin(num);
				dataMatrixRay4.TMin = 0.0;
				dataMatrixRay4.TMax = dataMatrixRay.TMax;
			}
			if (!dataMatrixVector.Intersect(dataMatrixRay, dataMatrixRay2))
			{
				return false;
			}
			if (!dataMatrixVector2.Intersect(dataMatrixRay2, dataMatrixRay4))
			{
				return false;
			}
			if (!dataMatrixVector3.Intersect(dataMatrixRay4, dataMatrixRay3))
			{
				return false;
			}
			if (!dataMatrixVector4.Intersect(dataMatrixRay3, dataMatrixRay))
			{
				return false;
			}
			if (!RegionUpdateCorners(reg, dataMatrixVector, dataMatrixVector2, dataMatrixVector3, dataMatrixVector4))
			{
				return false;
			}
			return true;
		}

		private bool RegionUpdateCorners(DataMatrixRegion reg, DataMatrixVector2 p00, DataMatrixVector2 p10, DataMatrixVector2 p11, DataMatrixVector2 p01)
		{
			double num = Width - 1;
			double num2 = Height - 1;
			if (p00.X < 0.0 || p00.Y < 0.0 || p00.X > num || p00.Y > num2 || p01.X < 0.0 || p01.Y < 0.0 || p01.X > num || p01.Y > num2 || p10.X < 0.0 || p10.Y < 0.0 || p10.X > num || p10.Y > num2)
			{
				return false;
			}
			DataMatrixVector2 dataMatrixVector = p01 - p00;
			DataMatrixVector2 dataMatrixVector2 = p10 - p00;
			DataMatrixVector2 dataMatrixVector3 = p11 - p01;
			DataMatrixVector2 dataMatrixVector4 = p11 - p10;
			double num3 = dataMatrixVector.Mag();
			double num4 = dataMatrixVector2.Mag();
			double num5 = dataMatrixVector3.Mag();
			double num6 = dataMatrixVector4.Mag();
			if (num3 <= 8.0 || num4 <= 8.0 || num5 <= 8.0 || num6 <= 8.0)
			{
				return false;
			}
			double num7 = num3 / num6;
			if (num7 <= 0.5 || num7 >= 2.0)
			{
				return false;
			}
			num7 = num4 / num5;
			if (num7 <= 0.5 || num7 >= 2.0)
			{
				return false;
			}
			if (dataMatrixVector2.Cross(dataMatrixVector4) <= 0.0 || dataMatrixVector.Cross(dataMatrixVector3) >= 0.0)
			{
				return false;
			}
			if (DataMatrixCommon.RightAngleTrueness(p00, p10, p11, Math.PI / 2.0) <= _squareDevn)
			{
				return false;
			}
			if (DataMatrixCommon.RightAngleTrueness(p10, p11, p01, Math.PI / 2.0) <= _squareDevn)
			{
				return false;
			}
			double num8 = -1.0 * p00.X;
			double num9 = -1.0 * p00.Y;
			DataMatrixMatrix3 dataMatrixMatrix = DataMatrixMatrix3.Translate(num8, num9);
			double num10 = Math.Atan2(dataMatrixVector.X, dataMatrixVector.Y);
			DataMatrixMatrix3 dataMatrixMatrix2 = DataMatrixMatrix3.Rotate(num10);
			DataMatrixMatrix3 dataMatrixMatrix3 = dataMatrixMatrix * dataMatrixMatrix2;
			DataMatrixVector2 dataMatrixVector5 = p10 * dataMatrixMatrix3;
			double num11 = (0.0 - dataMatrixVector5.Y) / dataMatrixVector5.X;
			DataMatrixMatrix3 dataMatrixMatrix4 = DataMatrixMatrix3.Shear(0.0, num11);
			dataMatrixMatrix3 *= dataMatrixMatrix4;
			double num12 = 1.0 / dataMatrixVector5.X;
			DataMatrixMatrix3 dataMatrixMatrix5 = DataMatrixMatrix3.Scale(num12, 1.0);
			dataMatrixMatrix3 *= dataMatrixMatrix5;
			dataMatrixVector5 = p11 * dataMatrixMatrix3;
			double num13 = 1.0 / dataMatrixVector5.Y;
			DataMatrixMatrix3 dataMatrixMatrix6 = DataMatrixMatrix3.Scale(1.0, num13);
			dataMatrixMatrix3 *= dataMatrixMatrix6;
			dataMatrixVector5 = p11 * dataMatrixMatrix3;
			double x = dataMatrixVector5.X;
			DataMatrixMatrix3 dataMatrixMatrix7 = DataMatrixMatrix3.LineSkewSide(1.0, x, 1.0);
			dataMatrixMatrix3 *= dataMatrixMatrix7;
			dataMatrixVector5 = p01 * dataMatrixMatrix3;
			double y = dataMatrixVector5.Y;
			DataMatrixMatrix3 dataMatrixMatrix8 = DataMatrixMatrix3.LineSkewTop(y, 1.0, 1.0);
			reg.Raw2Fit = dataMatrixMatrix3 * dataMatrixMatrix8;
			dataMatrixMatrix8 = DataMatrixMatrix3.LineSkewTopInv(y, 1.0, 1.0);
			dataMatrixMatrix7 = DataMatrixMatrix3.LineSkewSideInv(1.0, x, 1.0);
			dataMatrixMatrix3 = dataMatrixMatrix8 * dataMatrixMatrix7;
			DataMatrixMatrix3 dataMatrixMatrix9 = DataMatrixMatrix3.Scale(1.0 / num12, 1.0 / num13);
			dataMatrixMatrix3 *= dataMatrixMatrix9;
			dataMatrixMatrix4 = DataMatrixMatrix3.Shear(0.0, 0.0 - num11);
			dataMatrixMatrix3 *= dataMatrixMatrix4;
			dataMatrixMatrix2 = DataMatrixMatrix3.Rotate(0.0 - num10);
			dataMatrixMatrix3 *= dataMatrixMatrix2;
			dataMatrixMatrix = DataMatrixMatrix3.Translate(0.0 - num8, 0.0 - num9);
			reg.Fit2Raw = dataMatrixMatrix3 * dataMatrixMatrix;
			return true;
		}

		private bool MatrixRegionAlignCalibEdge(DataMatrixRegion reg, DataMatrixEdge edgeLoc)
		{
			DataMatrixVector2 dataMatrixVector = new DataMatrixVector2();
			DataMatrixPixelLoc loc = default(DataMatrixPixelLoc);
			DataMatrixPixelLoc locInside = default(DataMatrixPixelLoc);
			dataMatrixVector.X = 0.0;
			dataMatrixVector.Y = 0.0;
			dataMatrixVector *= reg.Fit2Raw;
			locInside.X = (int)(dataMatrixVector.X + 0.5);
			locInside.Y = (int)(dataMatrixVector.Y + 0.5);
			DataMatrixSymbolSize dataMatrixSymbolSize = ((_sizeIdxExpected != DataMatrixSymbolSize.SymbolSquareAuto && (_sizeIdxExpected < DataMatrixSymbolSize.Symbol10x10 || _sizeIdxExpected > DataMatrixSymbolSize.Symbol144x144)) ? ((_sizeIdxExpected != DataMatrixSymbolSize.SymbolRectAuto && (_sizeIdxExpected < DataMatrixSymbolSize.Symbol8x18 || _sizeIdxExpected > DataMatrixSymbolSize.Symbol16x48)) ? DataMatrixSymbolSize.SymbolShapeAuto : DataMatrixSymbolSize.SymbolRectAuto) : DataMatrixSymbolSize.SymbolSquareAuto);
			int num;
			int angle;
			DataMatrixFollow dataMatrixFollow;
			if (edgeLoc == DataMatrixEdge.EdgeTop)
			{
				num = reg.Polarity * -1;
				angle = reg.LeftLine.Angle;
				dataMatrixFollow = FollowSeekLoc(reg.LocT);
				dataMatrixVector.X = 0.8;
				dataMatrixVector.Y = ((dataMatrixSymbolSize == DataMatrixSymbolSize.SymbolRectAuto) ? 0.2 : 0.6);
			}
			else
			{
				num = reg.Polarity;
				angle = reg.BottomLine.Angle;
				dataMatrixFollow = FollowSeekLoc(reg.LocR);
				dataMatrixVector.X = ((dataMatrixSymbolSize == DataMatrixSymbolSize.SymbolSquareAuto) ? 0.7 : 0.9);
				dataMatrixVector.Y = 0.8;
			}
			dataMatrixVector *= reg.Fit2Raw;
			loc.X = (int)(dataMatrixVector.X + 0.5);
			loc.Y = (int)(dataMatrixVector.Y + 0.5);
			DataMatrixPixelLoc loc2 = dataMatrixFollow.Loc;
			DataMatrixBresLine line = new DataMatrixBresLine(loc2, loc, locInside);
			int tripSteps = TrailBlazeGapped(reg, line, num);
			DataMatrixBestLine dataMatrixBestLine = FindBestSolidLine2(loc2, tripSteps, num, angle);
			if (edgeLoc == DataMatrixEdge.EdgeTop)
			{
				reg.TopKnown = 1;
				reg.TopAngle = dataMatrixBestLine.Angle;
				reg.TopLoc = dataMatrixBestLine.LocBeg;
			}
			else
			{
				reg.RightKnown = 1;
				reg.RightAngle = dataMatrixBestLine.Angle;
				reg.RightLoc = dataMatrixBestLine.LocBeg;
			}
			return true;
		}

		private int TrailBlazeGapped(DataMatrixRegion reg, DataMatrixBresLine line, int streamDir)
		{
			int travel = 0;
			int outward = 0;
			int[] array = new int[9] { 0, 1, 2, 7, 8, 3, 6, 5, 4 };
			DataMatrixPixelLoc loc = line.Loc;
			DataMatrixPointFlow dataMatrixPointFlow = GetPointFlow(reg.FlowBegin.Plane, loc, DataMatrixConstants.DataMatrixNeighborNone);
			int num = line.XDelta * line.XDelta + line.YDelta * line.YDelta;
			int num2 = 0;
			bool flag = true;
			DataMatrixPixelLoc dataMatrixPixelLoc = loc;
			int num3 = DecodeGetCache(loc.X, loc.Y);
			if (num3 == -1)
			{
				return 0;
			}
			_cache[num3] = 0;
			int num10;
			do
			{
				if (flag)
				{
					DataMatrixPointFlow dataMatrixPointFlow2 = FindStrongestNeighbor(dataMatrixPointFlow, streamDir);
					if (dataMatrixPointFlow2.Mag == DataMatrixConstants.DataMatrixUndefined)
					{
						break;
					}
					new DataMatrixBresLine(line).GetStep(dataMatrixPointFlow2.Loc, ref travel, ref outward);
					if (dataMatrixPointFlow2.Mag < 50 || outward < 0 || (outward == 0 && travel < 0))
					{
						flag = false;
					}
					else
					{
						line.Step(travel, outward);
						dataMatrixPointFlow = dataMatrixPointFlow2;
					}
				}
				if (!flag)
				{
					line.Step(1, 0);
					dataMatrixPointFlow = GetPointFlow(reg.FlowBegin.Plane, line.Loc, DataMatrixConstants.DataMatrixNeighborNone);
					if (dataMatrixPointFlow.Mag > 50)
					{
						flag = true;
					}
				}
				DataMatrixPixelLoc loc2 = line.Loc;
				int num4 = DecodeGetCache(loc2.X, loc2.Y);
				if (num4 == -1)
				{
					break;
				}
				int num5 = loc2.X - dataMatrixPixelLoc.X;
				int num6 = loc2.Y - dataMatrixPixelLoc.Y;
				if (Math.Abs(num5) > 1 || Math.Abs(num6) > 1)
				{
					throw new Exception("Invalid step directions!");
				}
				int num7 = array[3 * num6 + num5 + 4];
				if (num7 == 8)
				{
					throw new Exception("Invalid step direction!");
				}
				if (streamDir < 0)
				{
					_cache[num3] |= (byte)(0x40 | num7);
					_cache[num4] = (byte)((num7 + 4) % 8 << 3);
				}
				else
				{
					_cache[num3] |= (byte)(0x40 | (num7 << 3));
					_cache[num4] = (byte)((num7 + 4) % 8);
				}
				int num8 = line.Loc.X - loc.X;
				int num9 = line.Loc.Y - loc.Y;
				num10 = num8 * num8 + num9 * num9;
				dataMatrixPixelLoc = line.Loc;
				num3 = num4;
				num2++;
			}
			while (num10 < num);
			return num2;
		}

		private DataMatrixBestLine FindBestSolidLine2(DataMatrixPixelLoc loc0, int tripSteps, int sign, int houghAvoid)
		{
			int[,] array = new int[3, DataMatrixConstants.DataMatrixHoughRes];
			char[] array2 = new char[DataMatrixConstants.DataMatrixHoughRes];
			DataMatrixBestLine result = default(DataMatrixBestLine);
			int num = 0;
			int num2 = 0;
			DataMatrixFollow followBeg = FollowSeekLoc(loc0);
			DataMatrixPixelLoc dataMatrixPixelLoc = (result.LocNeg = followBeg.Loc);
			DataMatrixPixelLoc dataMatrixPixelLoc3 = (result.LocPos = dataMatrixPixelLoc);
			DataMatrixPixelLoc dataMatrixPixelLoc5 = (result.LocBeg = dataMatrixPixelLoc3);
			DataMatrixPixelLoc dataMatrixPixelLoc6 = dataMatrixPixelLoc5;
			int num4 = (result.StepNeg = 0);
			int stepBeg = (result.StepPos = num4);
			result.StepBeg = stepBeg;
			for (int i = 0; i < DataMatrixConstants.DataMatrixHoughRes; i++)
			{
				if (houghAvoid == DataMatrixConstants.DataMatrixUndefined)
				{
					array2[i] = '\u0001';
					continue;
				}
				int num6 = (houghAvoid + DataMatrixConstants.DataMatrixHoughRes / 6) % DataMatrixConstants.DataMatrixHoughRes;
				int num7 = (houghAvoid - DataMatrixConstants.DataMatrixHoughRes / 6 + DataMatrixConstants.DataMatrixHoughRes) % DataMatrixConstants.DataMatrixHoughRes;
				if (num6 > num7)
				{
					array2[i] = ((i > num6 || i < num7) ? '\u0001' : '\0');
				}
				else
				{
					array2[i] = ((i > num6 && i < num7) ? '\u0001' : '\0');
				}
			}
			for (int j = 0; j < tripSteps; j++)
			{
				int num8 = followBeg.Loc.X - dataMatrixPixelLoc6.X;
				int num9 = followBeg.Loc.Y - dataMatrixPixelLoc6.Y;
				for (int i = 0; i < DataMatrixConstants.DataMatrixHoughRes; i++)
				{
					if (array2[i] == '\0')
					{
						continue;
					}
					int num10 = DataMatrixConstants.rHvX[i] * num9 - DataMatrixConstants.rHvY[i] * num8;
					if (num10 >= -384 && num10 <= 384)
					{
						int num11 = ((num10 > 128) ? 2 : ((num10 >= -128) ? 1 : 0));
						array[num11, i]++;
						if (array[num11, i] > array[num2, num])
						{
							num = i;
							num2 = num11;
						}
					}
				}
				followBeg = FollowStep2(followBeg, sign);
			}
			result.Angle = num;
			result.HOffset = num2;
			result.Mag = array[num2, num];
			return result;
		}

		private DataMatrixFollow FollowStep2(DataMatrixFollow followBeg, int sign)
		{
			DataMatrixFollow result = default(DataMatrixFollow);
			if (Math.Abs(sign) != 1)
			{
				throw new Exception("Invalid parameter 'sign', can only be -1 or +1");
			}
			if ((followBeg.Neighbor & 0x40) == 0)
			{
				throw new Exception("Invalid value for neighbor!");
			}
			int num = ((sign < 0) ? (followBeg.Neighbor & 7) : ((followBeg.Neighbor & 0x38) >> 3));
			result.Loc = new DataMatrixPixelLoc
			{
				X = followBeg.Loc.X + DataMatrixConstants.DataMatrixPatternX[num],
				Y = followBeg.Loc.Y + DataMatrixConstants.DataMatrixPatternY[num]
			};
			result.Step = followBeg.Step + sign;
			result.Ptr = _cache;
			result.PtrIndex = DecodeGetCache(result.Loc.X, result.Loc.Y);
			return result;
		}

		private DataMatrixFollow FollowSeekLoc(DataMatrixPixelLoc loc)
		{
			DataMatrixFollow dataMatrixFollow = default(DataMatrixFollow);
			dataMatrixFollow.Loc = loc;
			dataMatrixFollow.Step = 0;
			dataMatrixFollow.Ptr = _cache;
			DataMatrixFollow result = dataMatrixFollow;
			result.PtrIndex = DecodeGetCache(result.Loc.X, result.Loc.Y);
			return result;
		}
	}
	public class DataMatrixDimension
	{
		private double width;

		private double height;

		private double widthPlusQuiet;

		private double heightPlusQuiet;

		private double xOffset;

		private double yOffset;

		public virtual double Height => height;

		public virtual double HeightPlusQuiet => heightPlusQuiet;

		public virtual double Width => width;

		public virtual double WidthPlusQuiet => widthPlusQuiet;

		public virtual double XOffset => xOffset;

		public virtual double YOffset => yOffset;

		public DataMatrixDimension(double w, double h)
		{
			width = w;
			height = h;
			widthPlusQuiet = width;
			heightPlusQuiet = height;
			xOffset = 0.0;
			yOffset = 0.0;
		}

		public DataMatrixDimension(double w, double h, double wpq, double hpq, double xoffset, double yoffset)
		{
			width = w;
			height = h;
			widthPlusQuiet = wpq;
			heightPlusQuiet = hpq;
			xOffset = xoffset;
			yOffset = yoffset;
		}

		public virtual double GetHeight(int orientation)
		{
			orientation = NormalizeOrientation(orientation);
			if (orientation % 180 != 0)
			{
				return Width;
			}
			return Height;
		}

		public virtual double GetHeightPlusQuiet(int orientation)
		{
			orientation = NormalizeOrientation(orientation);
			if (orientation % 180 != 0)
			{
				return WidthPlusQuiet;
			}
			return HeightPlusQuiet;
		}

		public static int NormalizeOrientation(int orientation)
		{
			switch (orientation)
			{
			case 0:
				return 0;
			case -270:
			case 90:
				return 90;
			case -180:
			case 180:
				return 180;
			case -90:
			case 270:
				return 270;
			default:
				throw new ArgumentException("Orientation must be 0, 90, 180, 270, -90, -180 or -270");
			}
		}

		public virtual double GetWidth(int orientation)
		{
			orientation = NormalizeOrientation(orientation);
			if (orientation % 180 != 0)
			{
				return Height;
			}
			return Width;
		}

		public virtual double GetWidthPlusQuiet(int orientation)
		{
			orientation = NormalizeOrientation(orientation);
			if (orientation % 180 != 0)
			{
				return HeightPlusQuiet;
			}
			return WidthPlusQuiet;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(base.ToString());
			stringBuilder.Append("[width=");
			stringBuilder.Append(Width);
			stringBuilder.Append("(");
			stringBuilder.Append(WidthPlusQuiet);
			stringBuilder.Append("),height=");
			stringBuilder.Append(Height);
			stringBuilder.Append("(");
			stringBuilder.Append(HeightPlusQuiet);
			stringBuilder.Append(")]");
			return stringBuilder.ToString();
		}
	}
