		internal DataMatrixEncode()
		{
			_scheme = DataMatrixScheme.SchemeAscii;
			_sizeIdxRequest = DataMatrixSymbolSize.SymbolSquareAuto;
			_marginSize = 10;
			_moduleSize = 5;
			_width = 250;
			_height = 250;
			_quietZone = 1;
			_pixelPacking = DataMatrixPackOrder.Pack24bppRGB;
			_imageFlip = DataMatrixFlip.FlipNone;
			_rowPadBytes = 0;
		}

		private DataMatrixEncode(DataMatrixEncode src)
		{
			_scheme = src._scheme;
			_sizeIdxRequest = src._sizeIdxRequest;
			_marginSize = src._marginSize;
			_moduleSize = src._moduleSize;
			_pixelPacking = src._pixelPacking;
			_imageFlip = src._imageFlip;
			_rowPadBytes = src._rowPadBytes;
			_image = src._image;
			_message = src._message;
			_method = src._method;
			_region = src._region;
		}

		internal bool EncodeDataMatrixRaw(byte[] inputString)
		{
			return EncodeDataMatrix(null, null, inputString, encodeRaw: true);
		}

		internal bool EncodeDataMatrix(Color? foreColor, Color? backColor, byte[] inputString)
		{
			return EncodeDataMatrix(foreColor, backColor, inputString, encodeRaw: false);
		}

		internal bool EncodeDataMatrix(Color? foreColor, Color? backColor, byte[] inputString, bool encodeRaw)
		{
			byte[] array = new byte[4096];
			DataMatrixSymbolSize sizeIdx = _sizeIdxRequest;
			int dataWordCount = EncodeDataCodewords(array, inputString, ref sizeIdx);
			if (dataWordCount <= 0)
			{
				return false;
			}
			if (sizeIdx == DataMatrixSymbolSize.SymbolSquareAuto || sizeIdx == DataMatrixSymbolSize.SymbolRectAuto)
			{
				throw new Exception("Invalid symbol size for encoding!");
			}
			int padCount = AddPadChars(array, ref dataWordCount, DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolDataWords, sizeIdx));
			_region = new DataMatrixRegion();
			_region.SizeIdx = sizeIdx;
			_region.SymbolRows = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolRows, sizeIdx);
			_region.SymbolCols = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolCols, sizeIdx);
			_region.MappingRows = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribMappingMatrixRows, sizeIdx);
			_region.MappingCols = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribMappingMatrixCols, sizeIdx);
			_message = new DataMatrixMessage(sizeIdx, DataMatrixFormat.Matrix)
			{
				PadCount = padCount
			};
			for (int i = 0; i < dataWordCount; i++)
			{
				_message.Code[i] = array[i];
			}
			DataMatrixCommon.GenReedSolEcc(_message, _region.SizeIdx);
			DataMatrixDecode.ModulePlacementEcc200(_message.Array, _message.Code, _region.SizeIdx, DataMatrixConstants.DataMatrixModuleOnRGB);
			int num = 2 * _marginSize + _region.SymbolCols * _moduleSize;
			int num2 = 2 * _marginSize + _region.SymbolRows * _moduleSize;
			int bitsPerPixel = DataMatrixCommon.GetBitsPerPixel(_pixelPacking);
			if (bitsPerPixel == DataMatrixConstants.DataMatrixUndefined)
			{
				return false;
			}
			if (bitsPerPixel % 8 != 0)
			{
				throw new Exception("Invalid color depth for encoding!");
			}
			byte[] pxl = new byte[num * num2 * (bitsPerPixel / 8) + _rowPadBytes];
			_image = new DataMatrixImage(pxl, num, num2, _pixelPacking)
			{
				ImageFlip = _imageFlip,
				RowPadBytes = _rowPadBytes
			};
			if (encodeRaw)
			{
				PrintPatternRaw();
			}
			else
			{
				PrintPattern(foreColor, backColor);
			}
			return true;
		}

		internal bool EncodeDataMosaic(byte[] inputString)
		{
			int[] array = new int[3];
			List<byte[]> list = new List<byte[]>(3);
			for (int i = 0; i < 3; i++)
			{
				list.Add(new byte[4096]);
			}
			DataMatrixSymbolSize sizeIdxRequest;
			DataMatrixSymbolSize sizeIdx = (sizeIdxRequest = _sizeIdxRequest);
			if (EncodeDataCodewords(list[0], inputString, ref sizeIdx) <= 0)
			{
				return false;
			}
			int dataWords = (array[1] = (array[0] = (inputString.Length + 2) / 3));
			array[2] = inputString.Length - (array[0] + array[1]);
			DataMatrixSymbolSize dataMatrixSymbolSize = FindCorrectSymbolSize(dataWords, sizeIdxRequest);
			if (dataMatrixSymbolSize == DataMatrixSymbolSize.SymbolShapeAuto)
			{
				return false;
			}
			DataMatrixSymbolSize dataMatrixSymbolSize2 = sizeIdxRequest switch
			{
				DataMatrixSymbolSize.SymbolSquareAuto => DataMatrixSymbolSize.Symbol144x144, 
				DataMatrixSymbolSize.SymbolRectAuto => DataMatrixSymbolSize.Symbol16x48, 
				_ => dataMatrixSymbolSize, 
			};
			byte[] array2 = new byte[array[0]];
			for (int j = 0; j < array[0]; j++)
			{
				array2[j] = inputString[j];
			}
			byte[] array3 = new byte[array[1]];
			for (int k = array[0]; k < array[0] + array[1]; k++)
			{
				array3[k - array[0]] = inputString[k];
			}
			byte[] array4 = new byte[array[2]];
			for (int l = array[0] + array[1]; l < inputString.Length; l++)
			{
				array4[l - array[0] - array[1]] = inputString[l];
			}
			DataMatrixSymbolSize dataMatrixSymbolSize3;
			for (dataMatrixSymbolSize3 = dataMatrixSymbolSize; dataMatrixSymbolSize3 <= dataMatrixSymbolSize2; dataMatrixSymbolSize3++)
			{
				sizeIdx = dataMatrixSymbolSize3;
				EncodeDataCodewords(list[0], array2, ref sizeIdx);
				if (sizeIdx != dataMatrixSymbolSize3)
				{
					continue;
				}
				sizeIdx = dataMatrixSymbolSize3;
				EncodeDataCodewords(list[1], array3, ref sizeIdx);
				if (sizeIdx == dataMatrixSymbolSize3)
				{
					sizeIdx = dataMatrixSymbolSize3;
					EncodeDataCodewords(list[2], array4, ref sizeIdx);
					if (sizeIdx == dataMatrixSymbolSize3)
					{
						break;
					}
				}
			}
			_sizeIdxRequest = dataMatrixSymbolSize3;
			DataMatrixEncode dataMatrixEncode = new DataMatrixEncode(this);
			DataMatrixEncode dataMatrixEncode2 = new DataMatrixEncode(this);
			EncodeDataMatrix(null, null, array2);
			dataMatrixEncode.EncodeDataMatrix(null, null, array3);
			dataMatrixEncode2.EncodeDataMatrix(null, null, array4);
			int symbolAttribute = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribMappingMatrixRows, dataMatrixSymbolSize3);
			int symbolAttribute2 = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribMappingMatrixCols, dataMatrixSymbolSize3);
			for (int m = 0; m < _region.MappingCols * _region.MappingRows; m++)
			{
				_message.Array[m] = 0;
			}
			DataMatrixDecode.ModulePlacementEcc200(_message.Array, _message.Code, _region.SizeIdx, DataMatrixConstants.DataMatrixModuleOnRed);
			for (int n = 0; n < symbolAttribute; n++)
			{
				for (int num = 0; num < symbolAttribute2; num++)
				{
					_message.Array[n * symbolAttribute2 + num] &= (byte)(0xFF ^ (DataMatrixConstants.DataMatrixModuleAssigned | DataMatrixConstants.DataMatrixModuleVisited));
				}
			}
			DataMatrixDecode.ModulePlacementEcc200(_message.Array, dataMatrixEncode.Message.Code, _region.SizeIdx, DataMatrixConstants.DataMatrixModuleOnGreen);
			for (int n = 0; n < symbolAttribute; n++)
			{
				for (int num = 0; num < symbolAttribute2; num++)
				{
					_message.Array[n * symbolAttribute2 + num] &= (byte)(0xFF ^ (DataMatrixConstants.DataMatrixModuleAssigned | DataMatrixConstants.DataMatrixModuleVisited));
				}
			}
			DataMatrixDecode.ModulePlacementEcc200(_message.Array, dataMatrixEncode2.Message.Code, _region.SizeIdx, DataMatrixConstants.DataMatrixModuleOnBlue);
			PrintPattern(null, null);
			return true;
		}

		private void PrintPatternRaw()
		{
			_rawData = new bool[_region.SymbolCols, _region.SymbolRows];
			for (int i = 0; i < _region.SymbolRows; i++)
			{
				for (int j = 0; j < _region.SymbolCols; j++)
				{
					int num = _message.SymbolModuleStatus(_region.SizeIdx, i, j);
					_rawData[j, _region.SymbolRows - i - 1] = (num & DataMatrixConstants.DataMatrixModuleOnBlue) != 0;
				}
			}
		}

		private void PrintPattern(Color? foreColor, Color? backColor)
		{
			int[] array = new int[3];
			double num = _marginSize;
			DataMatrixMatrix3 dataMatrixMatrix = DataMatrixMatrix3.Translate(num, num);
			DataMatrixMatrix3 dataMatrixMatrix2 = DataMatrixMatrix3.Scale(_moduleSize, _moduleSize) * dataMatrixMatrix;
			int rowSizeBytes = _image.RowSizeBytes;
			int height = _image.Height;
			for (int i = 0; i < rowSizeBytes * height; i++)
			{
				_image.Pxl[i] = byte.MaxValue;
			}
			for (int j = 0; j < _region.SymbolRows; j++)
			{
				for (int k = 0; k < _region.SymbolCols; k++)
				{
					DataMatrixVector2 dataMatrixVector = new DataMatrixVector2(k, j) * dataMatrixMatrix2;
					int num2 = (int)dataMatrixVector.X;
					int num3 = (int)dataMatrixVector.Y;
					int num4 = _message.SymbolModuleStatus(_region.SizeIdx, j, k);
					for (int l = num3; l < num3 + _moduleSize; l++)
					{
						for (int m = num2; m < num2 + _moduleSize; m++)
						{
							if (foreColor.HasValue && backColor.HasValue)
							{
								array[0] = (((num4 & DataMatrixConstants.DataMatrixModuleOnRed) != 0) ? foreColor.Value.B : backColor.Value.B);
								array[1] = (((num4 & DataMatrixConstants.DataMatrixModuleOnGreen) != 0) ? foreColor.Value.G : backColor.Value.G);
								array[2] = (((num4 & DataMatrixConstants.DataMatrixModuleOnBlue) != 0) ? foreColor.Value.R : backColor.Value.R);
							}
							else
							{
								array[0] = (((num4 & DataMatrixConstants.DataMatrixModuleOnBlue) == 0) ? 255 : 0);
								array[1] = (((num4 & DataMatrixConstants.DataMatrixModuleOnGreen) == 0) ? 255 : 0);
								array[2] = (((num4 & DataMatrixConstants.DataMatrixModuleOnRed) == 0) ? 255 : 0);
							}
							_image.SetPixelValue(m, l, 0, (byte)array[0]);
							_image.SetPixelValue(m, l, 1, (byte)array[1]);
							_image.SetPixelValue(m, l, 2, (byte)array[2]);
						}
					}
				}
			}
		}

		private int AddPadChars(byte[] buf, ref int dataWordCount, int paddedSize)
		{
			int num = 0;
			if (dataWordCount < paddedSize)
			{
				num++;
				buf[dataWordCount++] = DataMatrixConstants.DataMatrixCharAsciiPad;
			}
			while (dataWordCount < paddedSize)
			{
				num++;
				buf[dataWordCount] = Randomize253State(DataMatrixConstants.DataMatrixCharAsciiPad, dataWordCount + 1);
				dataWordCount++;
			}
			return num;
		}

		private byte Randomize253State(byte codewordValue, int codewordPosition)
		{
			int num = 149 * codewordPosition % 253 + 1;
			int num2 = codewordValue + num;
			if (num2 > 254)
			{
				num2 -= 254;
			}
			if (num2 < 0 || num2 > 255)
			{
				throw new Exception("Error randomizing 253 state!");
			}
			return (byte)num2;
		}

		private int EncodeDataCodewords(byte[] buf, byte[] inputString, ref DataMatrixSymbolSize sizeIdx)
		{
			int num = _scheme switch
			{
				DataMatrixScheme.SchemeAutoBest => EncodeAutoBest(buf, inputString), 
				DataMatrixScheme.SchemeAutoFast => 0, 
				_ => EncodeSingleScheme(buf, inputString, _scheme), 
			};
			sizeIdx = FindCorrectSymbolSize(num, sizeIdx);
			if (sizeIdx == DataMatrixSymbolSize.SymbolShapeAuto)
			{
				return 0;
			}
			return num;
		}

		private DataMatrixSymbolSize FindCorrectSymbolSize(int dataWords, DataMatrixSymbolSize sizeIdxRequest)
		{
			if (dataWords <= 0)
			{
				return DataMatrixSymbolSize.SymbolShapeAuto;
			}
			DataMatrixSymbolSize dataMatrixSymbolSize;
			if (sizeIdxRequest == DataMatrixSymbolSize.SymbolSquareAuto || sizeIdxRequest == DataMatrixSymbolSize.SymbolRectAuto)
			{
				int num;
				int num2;
				if (sizeIdxRequest == DataMatrixSymbolSize.SymbolSquareAuto)
				{
					num = 0;
					num2 = DataMatrixConstants.DataMatrixSymbolSquareCount;
				}
				else
				{
					num = DataMatrixConstants.DataMatrixSymbolSquareCount;
					num2 = DataMatrixConstants.DataMatrixSymbolSquareCount + DataMatrixConstants.DataMatrixSymbolRectCount;
				}
				for (dataMatrixSymbolSize = (DataMatrixSymbolSize)num; (int)dataMatrixSymbolSize < num2 && DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolDataWords, dataMatrixSymbolSize) < dataWords; dataMatrixSymbolSize++)
				{
				}
				if (dataMatrixSymbolSize == (DataMatrixSymbolSize)num2)
				{
					return DataMatrixSymbolSize.SymbolShapeAuto;
				}
			}
			else
			{
				dataMatrixSymbolSize = sizeIdxRequest;
			}
			if (dataWords > DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolDataWords, dataMatrixSymbolSize))
			{
				return DataMatrixSymbolSize.SymbolShapeAuto;
			}
			return dataMatrixSymbolSize;
		}

		private int EncodeSingleScheme(byte[] buf, byte[] codewords, DataMatrixScheme scheme)
		{
			DataMatrixChannel dataMatrixChannel = new DataMatrixChannel();
			InitChannel(dataMatrixChannel, codewords);
			while (dataMatrixChannel.InputIndex < dataMatrixChannel.Input.Length)
			{
				if (!EncodeNextWord(dataMatrixChannel, scheme))
				{
					return 0;
				}
				if (dataMatrixChannel.Invalid != 0)
				{
					return 0;
				}
			}
			int num = dataMatrixChannel.EncodedLength / 12;
			for (int i = 0; i < num; i++)
			{
				buf[i] = dataMatrixChannel.EncodedWords[i];
			}
			return num;
		}

		private int EncodeAutoBest(byte[] buf, byte[] codewords)
		{
			DmtxChannelGroup dmtxChannelGroup = new DmtxChannelGroup();
			DmtxChannelGroup dmtxChannelGroup2 = new DmtxChannelGroup();
			for (DataMatrixScheme dataMatrixScheme = DataMatrixScheme.SchemeAscii; dataMatrixScheme <= DataMatrixScheme.SchemeBase256; dataMatrixScheme++)
			{
				DataMatrixChannel channel = dmtxChannelGroup.Channels[(int)dataMatrixScheme];
				InitChannel(channel, codewords);
				if (EncodeNextWord(channel, dataMatrixScheme))
				{
					return 0;
				}
			}
			while (dmtxChannelGroup.Channels[0].InputIndex < dmtxChannelGroup.Channels[0].Input.Length)
			{
				for (DataMatrixScheme dataMatrixScheme = DataMatrixScheme.SchemeAscii; dataMatrixScheme <= DataMatrixScheme.SchemeBase256; dataMatrixScheme++)
				{
					dmtxChannelGroup2.Channels[(int)dataMatrixScheme] = FindBestChannel(dmtxChannelGroup, dataMatrixScheme);
				}
				dmtxChannelGroup = dmtxChannelGroup2;
			}
			DataMatrixChannel dataMatrixChannel = dmtxChannelGroup.Channels[0];
			for (DataMatrixScheme dataMatrixScheme = DataMatrixScheme.SchemeC40; dataMatrixScheme <= DataMatrixScheme.SchemeBase256; dataMatrixScheme++)
			{
				if (dmtxChannelGroup.Channels[(int)dataMatrixScheme].Invalid == DataMatrixChannelStatus.ChannelValid && dmtxChannelGroup.Channels[(int)dataMatrixScheme].EncodedLength < dataMatrixChannel.EncodedLength)
				{
					dataMatrixChannel = dmtxChannelGroup.Channels[(int)dataMatrixScheme];
				}
			}
			int num = dataMatrixChannel.EncodedLength / 12;
			for (int i = 0; i < num; i++)
			{
				buf[i] = dataMatrixChannel.EncodedWords[i];
			}
			return num;
		}

		private DataMatrixChannel FindBestChannel(DmtxChannelGroup group, DataMatrixScheme targetScheme)
		{
			DataMatrixChannel dataMatrixChannel = null;
			for (DataMatrixScheme dataMatrixScheme = DataMatrixScheme.SchemeAscii; dataMatrixScheme <= DataMatrixScheme.SchemeBase256; dataMatrixScheme++)
			{
				DataMatrixChannel dataMatrixChannel2 = group.Channels[(int)dataMatrixScheme];
				if (dataMatrixChannel2.Invalid == DataMatrixChannelStatus.ChannelValid && dataMatrixChannel2.InputIndex != dataMatrixChannel2.Input.Length)
				{
					EncodeNextWord(dataMatrixChannel2, targetScheme);
					if ((dataMatrixChannel2.Invalid & DataMatrixChannelStatus.ChannelUnsupportedChar) != 0)
					{
						dataMatrixChannel = dataMatrixChannel2;
						break;
					}
					if ((dataMatrixChannel2.Invalid & DataMatrixChannelStatus.ChannelCannotUnlatch) == 0 && (dataMatrixChannel == null || dataMatrixChannel2.CurrentLength < dataMatrixChannel.CurrentLength))
					{
						dataMatrixChannel = dataMatrixChannel2;
					}
				}
			}
			return dataMatrixChannel;
		}

		private bool EncodeNextWord(DataMatrixChannel channel, DataMatrixScheme targetScheme)
		{
			if (channel.EncScheme != targetScheme)
			{
				ChangeEncScheme(channel, targetScheme, DmtxUnlatch.Explicit);
				if (channel.Invalid != 0)
				{
					return false;
				}
			}
			if (channel.EncScheme != targetScheme)
			{
				throw new Exception("For encoding, channel scheme must equal target scheme!");
			}
			return channel.EncScheme switch
			{
				DataMatrixScheme.SchemeAscii => EncodeAsciiCodeword(channel), 
				DataMatrixScheme.SchemeC40 => EncodeTripletCodeword(channel), 
				DataMatrixScheme.SchemeText => EncodeTripletCodeword(channel), 
				DataMatrixScheme.SchemeX12 => EncodeTripletCodeword(channel), 
				DataMatrixScheme.SchemeEdifact => EncodeEdifactCodeword(channel), 
				DataMatrixScheme.SchemeBase256 => EncodeBase256Codeword(channel), 
				_ => false, 
			};
		}

		private bool EncodeBase256Codeword(DataMatrixChannel channel)
		{
			byte[] array = new byte[2];
			if (channel.EncScheme != DataMatrixScheme.SchemeBase256)
			{
				throw new Exception("Invalid encoding scheme selected!");
			}
			int num = channel.FirstCodeWord / 12;
			array[0] = DataMatrixMessage.UnRandomize255State(channel.EncodedWords[num], channel.FirstCodeWord / 12 + 1);
			int num2;
			if (array[0] <= 249)
			{
				num2 = array[0];
			}
			else
			{
				num2 = 250 * (array[0] - 249);
				num2 += DataMatrixMessage.UnRandomize255State(channel.EncodedWords[num + 1], channel.FirstCodeWord / 12 + 2);
			}
			num2++;
			int num3;
			if (num2 <= 249)
			{
				num3 = 1;
				array[0] = (byte)num2;
				array[1] = 0;
			}
			else
			{
				num3 = 2;
				array[0] = (byte)(num2 / 250 + 249);
				array[1] = (byte)(num2 % 250);
			}
			if (num2 <= 0 || num2 > 1555)
			{
				throw new Exception("Encoding failed, data length out of range!");
			}
			if (num2 == 250)
			{
				for (int num4 = channel.CurrentLength / 12 - 1; num4 > channel.FirstCodeWord / 12; num4--)
				{
					byte codewordValue = DataMatrixMessage.UnRandomize255State(channel.EncodedWords[num4], num4 + 1);
					channel.EncodedWords[num4 + 1] = Randomize255State(codewordValue, num4 + 2);
				}
				IncrementProgress(channel, 12);
				channel.EncodedLength += 12;
			}
			for (int num4 = 0; num4 < num3; num4++)
			{
				channel.EncodedWords[num + num4] = Randomize255State(array[num4], channel.FirstCodeWord / 12 + num4 + 1);
			}
			PushInputWord(channel, Randomize255State(channel.Input[channel.InputIndex], channel.CurrentLength / 12 + 1));
			IncrementProgress(channel, 12);
			channel.InputIndex++;
			return true;
		}

		private bool EncodeEdifactCodeword(DataMatrixChannel channel)
		{
			if (channel.EncScheme != DataMatrixScheme.SchemeEdifact)
			{
				throw new Exception("Invalid encoding scheme selected!");
			}
			byte b = channel.Input[channel.InputIndex];
			if (b < 32 || b > 94)
			{
				channel.Invalid = DataMatrixChannelStatus.ChannelUnsupportedChar;
				return false;
			}
			PushInputWord(channel, (byte)(b & 0x3Fu));
			IncrementProgress(channel, 9);
			channel.InputIndex++;
			CheckForEndOfSymbolEdifact(channel);
			return true;
		}

		private void CheckForEndOfSymbolEdifact(DataMatrixChannel channel)
		{
			if (channel.InputIndex > channel.Input.Length)
			{
				throw new Exception("Input index out of range while encoding!");
			}
			int num = channel.Input.Length - channel.InputIndex;
			if (num > 4)
			{
				return;
			}
			int num2 = channel.CurrentLength / 12;
			DataMatrixSymbolSize sizeIdx = FindCorrectSymbolSize(num2, DataMatrixSymbolSize.SymbolSquareAuto);
			int num3 = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolDataWords, sizeIdx) - num2;
			if (channel.CurrentLength % 12 == 0 && (num3 == 1 || num3 == 2))
			{
				if (num > num3)
				{
					return;
				}
				ChangeEncScheme(channel, DataMatrixScheme.SchemeAscii, DmtxUnlatch.Implicit);
				for (int i = 0; i < num; i++)
				{
					if (!EncodeNextWord(channel, DataMatrixScheme.SchemeAscii))
					{
						break;
					}
					if (channel.Invalid != 0)
					{
						throw new Exception("Error checking for end of symbol edifact");
					}
				}
			}
			else if (num == 0)
			{
				ChangeEncScheme(channel, DataMatrixScheme.SchemeAscii, DmtxUnlatch.Explicit);
			}
		}

		private void PushInputWord(DataMatrixChannel channel, byte codeword)
		{
			if (channel.EncodedLength / 12 > 4674)
			{
				throw new Exception("Can't push input word, encoded length exceeds limits!");
			}
			switch (channel.EncScheme)
			{
			case DataMatrixScheme.SchemeAscii:
				channel.EncodedWords[channel.CurrentLength / 12] = codeword;
				channel.EncodedLength += 12;
				break;
			case DataMatrixScheme.SchemeC40:
				channel.EncodedWords[channel.EncodedLength / 12] = codeword;
				channel.EncodedLength += 12;
				break;
			case DataMatrixScheme.SchemeText:
				channel.EncodedWords[channel.EncodedLength / 12] = codeword;
				channel.EncodedLength += 12;
				break;
			case DataMatrixScheme.SchemeX12:
				channel.EncodedWords[channel.EncodedLength / 12] = codeword;
				channel.EncodedLength += 12;
				break;
			case DataMatrixScheme.SchemeEdifact:
			{
				int num = channel.CurrentLength % 4;
				int num2 = (channel.CurrentLength + 9) / 12 - num;
				DataMatrixQuadruplet quadrupletValues = GetQuadrupletValues(channel.EncodedWords[num2], channel.EncodedWords[num2 + 1], channel.EncodedWords[num2 + 2]);
				quadrupletValues.Value[num] = codeword;
				for (int i = num + 1; i < 4; i++)
				{
					quadrupletValues.Value[i] = 0;
				}
				switch (num)
				{
				case 3:
					channel.EncodedWords[num2 + 2] = (byte)(((quadrupletValues.Value[2] & 3) << 6) | quadrupletValues.Value[3]);
					break;
				case 2:
					channel.EncodedWords[num2 + 2] = (byte)(((quadrupletValues.Value[2] & 3) << 6) | quadrupletValues.Value[3]);
					break;
				case 1:
					channel.EncodedWords[num2 + 1] = (byte)(((quadrupletValues.Value[1] & 0xF) << 4) | (quadrupletValues.Value[2] >> 2));
					break;
				case 0:
					channel.EncodedWords[num2] = (byte)((quadrupletValues.Value[0] << 2) | (quadrupletValues.Value[1] >> 4));
					break;
				}
				channel.EncodedLength += 9;
				break;
			}
			case DataMatrixScheme.SchemeBase256:
				channel.EncodedWords[channel.CurrentLength / 12] = codeword;
				channel.EncodedLength += 12;
				break;
			}
		}

		private bool EncodeTripletCodeword(DataMatrixChannel channel)
		{
			int[] array = new int[4];
			byte[] array2 = new byte[6];
			DataMatrixTriplet triplet = default(DataMatrixTriplet);
			if (channel.EncScheme != DataMatrixScheme.SchemeX12 && channel.EncScheme != DataMatrixScheme.SchemeText && channel.EncScheme != DataMatrixScheme.SchemeC40)
			{
				throw new Exception("Invalid encoding scheme selected!");
			}
			if (channel.CurrentLength > channel.EncodedLength)
			{
				throw new Exception("Encoding length out of range!");
			}
			if (channel.CurrentLength == channel.EncodedLength)
			{
				if (channel.CurrentLength % 12 != 0)
				{
					throw new Exception("Invalid encoding length!");
				}
				int inputIndex = channel.InputIndex;
				int num = 0;
				while (true)
				{
					if (num < 3 && inputIndex < channel.Input.Length)
					{
						byte inputWord = channel.Input[inputIndex++];
						int c40TextX12Words = GetC40TextX12Words(array, inputWord, channel.EncScheme);
						if (c40TextX12Words == 0)
						{
							channel.Invalid = DataMatrixChannelStatus.ChannelUnsupportedChar;
							return false;
						}
						for (int i = 0; i < c40TextX12Words; i++)
						{
							array2[num++] = (byte)array[i];
						}
						continue;
					}
					triplet.Value[0] = array2[0];
					triplet.Value[1] = array2[1];
					triplet.Value[2] = array2[2];
					if (num >= 3)
					{
						PushTriplet(channel, triplet);
						array2[0] = array2[3];
						array2[1] = array2[4];
						array2[2] = array2[5];
						num -= 3;
					}
					if (inputIndex == channel.Input.Length)
					{
						while (channel.CurrentLength < channel.EncodedLength)
						{
							IncrementProgress(channel, 8);
							channel.InputIndex++;
						}
						if (channel.CurrentLength == channel.EncodedLength + 8)
						{
							channel.CurrentLength = channel.EncodedLength;
							channel.InputIndex--;
						}
						if (channel.Input.Length < channel.InputIndex)
						{
							throw new Exception("Channel input index exceeds range!");
						}
						int inputCount = channel.Input.Length - channel.InputIndex;
						if (ProcessEndOfSymbolTriplet(channel, triplet, num, inputCount))
						{
							break;
						}
						return false;
					}
					if (num == 0)
					{
						break;
					}
				}
			}
			if (channel.CurrentLength < channel.EncodedLength)
			{
				IncrementProgress(channel, 8);
				channel.InputIndex++;
			}
			return true;
		}

		private int GetC40TextX12Words(int[] outputWords, byte inputWord, DataMatrixScheme encScheme)
		{
			if (encScheme != DataMatrixScheme.SchemeX12 && encScheme != DataMatrixScheme.SchemeText && encScheme != DataMatrixScheme.SchemeC40)
			{
				throw new Exception("Invalid encoding scheme selected!");
			}
			int result = 0;
			if (inputWord > 127)
			{
				if (encScheme == DataMatrixScheme.SchemeX12)
				{
					return 0;
				}
				outputWords[result++] = DataMatrixConstants.DataMatrixCharTripletShift2;
				outputWords[result++] = 30;
				inputWord -= 128;
			}
			if (encScheme == DataMatrixScheme.SchemeX12)
			{
				switch (inputWord)
				{
				case 13:
					outputWords[result++] = 0;
					break;
				case 42:
					outputWords[result++] = 1;
					break;
				case 62:
					outputWords[result++] = 2;
					break;
				case 32:
					outputWords[result++] = 3;
					break;
				case 48:
				case 49:
				case 50:
				case 51:
				case 52:
				case 53:
				case 54:
				case 55:
				case 56:
				case 57:
					outputWords[result++] = inputWord - 44;
					break;
				default:
					if (inputWord >= 65 && inputWord <= 90)
					{
						outputWords[result++] = inputWord - 51;
					}
					break;
				}
			}
			else if (inputWord <= 31)
			{
				outputWords[result++] = DataMatrixConstants.DataMatrixCharTripletShift1;
				outputWords[result++] = inputWord;
			}
			else if (inputWord == 32)
			{
				outputWords[result++] = 3;
			}
			else if (inputWord <= 47)
			{
				outputWords[result++] = DataMatrixConstants.DataMatrixCharTripletShift2;
				outputWords[result++] = inputWord - 33;
			}
			else if (inputWord <= 57)
			{
				outputWords[result++] = inputWord - 44;
			}
			else if (inputWord <= 64)
			{
				outputWords[result++] = DataMatrixConstants.DataMatrixCharTripletShift2;
				outputWords[result++] = inputWord - 43;
			}
			else if (inputWord <= 90 && encScheme == DataMatrixScheme.SchemeC40)
			{
				outputWords[result++] = inputWord - 51;
			}
			else if (inputWord <= 90 && encScheme == DataMatrixScheme.SchemeText)
			{
				outputWords[result++] = DataMatrixConstants.DataMatrixCharTripletShift3;
				outputWords[result++] = inputWord - 64;
			}
			else if (inputWord <= 95)
			{
				outputWords[result++] = DataMatrixConstants.DataMatrixCharTripletShift2;
				outputWords[result++] = inputWord - 69;
			}
			else if (inputWord == 96 && encScheme == DataMatrixScheme.SchemeText)
			{
				outputWords[result++] = DataMatrixConstants.DataMatrixCharTripletShift3;
				outputWords[result++] = 0;
			}
			else if (inputWord <= 122 && encScheme == DataMatrixScheme.SchemeText)
			{
				outputWords[result++] = inputWord - 83;
			}
			else if (inputWord <= 127)
			{
				outputWords[result++] = DataMatrixConstants.DataMatrixCharTripletShift3;
				outputWords[result++] = inputWord - 96;
			}
			return result;
		}

		private bool ProcessEndOfSymbolTriplet(DataMatrixChannel channel, DataMatrixTriplet triplet, int tripletCount, int inputCount)
		{
			if (channel.CurrentLength % 12 != 0)
			{
				throw new Exception("Invalid current length for encoding!");
			}
			int num = tripletCount - inputCount;
			int num2 = channel.CurrentLength / 12;
			DataMatrixSymbolSize dataMatrixSymbolSize = FindCorrectSymbolSize(num2 + ((inputCount == 3) ? 2 : inputCount), _sizeIdxRequest);
			if (dataMatrixSymbolSize == DataMatrixSymbolSize.SymbolShapeAuto)
			{
				return false;
			}
			int num3 = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolDataWords, dataMatrixSymbolSize) - num2;
			if (inputCount == 1 && num3 == 1)
			{
				ChangeEncScheme(channel, DataMatrixScheme.SchemeAscii, DmtxUnlatch.Implicit);
				if (!EncodeNextWord(channel, DataMatrixScheme.SchemeAscii))
				{
					return false;
				}
				if (channel.Invalid != 0 || channel.InputIndex != channel.Input.Length)
				{
					throw new Exception("Error processing end of symbol triplet!");
				}
			}
			else if (num3 == 2)
			{
				switch (tripletCount)
				{
				case 3:
					PushTriplet(channel, triplet);
					IncrementProgress(channel, 24);
					channel.EncScheme = DataMatrixScheme.SchemeAscii;
					channel.InputIndex += 3;
					channel.InputIndex -= num;
					break;
				case 2:
					triplet.Value[2] = 0;
					PushTriplet(channel, triplet);
					IncrementProgress(channel, 24);
					channel.EncScheme = DataMatrixScheme.SchemeAscii;
					channel.InputIndex += 2;
					channel.InputIndex -= num;
					break;
				case 1:
					ChangeEncScheme(channel, DataMatrixScheme.SchemeAscii, DmtxUnlatch.Explicit);
					if (!EncodeNextWord(channel, DataMatrixScheme.SchemeAscii))
					{
						return false;
					}
					if (channel.Invalid != 0)
					{
						throw new Exception("Error processing end of symbol triplet!");
					}
					break;
				}
			}
			else
			{
				num2 = channel.CurrentLength / 12;
				num3 = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolDataWords, dataMatrixSymbolSize) - num2;
				if (num3 > 0)
				{
					ChangeEncScheme(channel, DataMatrixScheme.SchemeAscii, DmtxUnlatch.Explicit);
					while (channel.InputIndex < channel.Input.Length)
					{
						if (!EncodeNextWord(channel, DataMatrixScheme.SchemeAscii))
						{
							return false;
						}
						if (channel.Invalid != 0)
						{
							throw new Exception("Error processing end of symbol triplet!");
						}
					}
				}
			}
			if (channel.InputIndex != channel.Input.Length)
			{
				throw new Exception("Could not fully process end of symbol triplet!");
			}
			return true;
		}

		private void PushTriplet(DataMatrixChannel channel, DataMatrixTriplet triplet)
		{
			int num = 1600 * triplet.Value[0] + 40 * triplet.Value[1] + triplet.Value[2] + 1;
			PushInputWord(channel, (byte)(num / 256));
			PushInputWord(channel, (byte)(num % 256));
		}

		private bool EncodeAsciiCodeword(DataMatrixChannel channel)
		{
			if (channel.EncScheme != 0)
			{
				throw new Exception("Invalid encoding scheme selected!");
			}
			byte b = channel.Input[channel.InputIndex];
			if (IsDigit(b) && channel.CurrentLength >= channel.FirstCodeWord + 12)
			{
				int num = (channel.CurrentLength - 12) / 12;
				byte b2 = (byte)(channel.EncodedWords[num] - 1);
				if (((num > channel.FirstCodeWord / 12) ? channel.EncodedWords[num - 1] : 0) != 235 && IsDigit(b2))
				{
					channel.EncodedWords[num] = (byte)(10 * (b2 - 48) + (b - 48) + 130);
					channel.InputIndex++;
					return true;
				}
			}
			if (b == DataMatrixConstants.DataMatrixCharFNC1)
			{
				PushInputWord(channel, DataMatrixConstants.DataMatrixCharFNC1);
				IncrementProgress(channel, 12);
				channel.InputIndex++;
				return true;
			}
			if (b >= 128)
			{
				PushInputWord(channel, DataMatrixConstants.DataMatrixCharAsciiUpperShift);
				IncrementProgress(channel, 12);
				b -= 128;
			}
			PushInputWord(channel, (byte)(b + 1));
			IncrementProgress(channel, 12);
			channel.InputIndex++;
			return true;
		}

		private bool IsDigit(byte inputValue)
		{
			if (inputValue >= 48)
			{
				return inputValue <= 57;
			}
			return false;
		}

		private void ChangeEncScheme(DataMatrixChannel channel, DataMatrixScheme targetScheme, DmtxUnlatch unlatchType)
		{
			if (channel.EncScheme == targetScheme)
			{
				throw new Exception("Target scheme already equals channel scheme, cannot be changed!");
			}
			switch (channel.EncScheme)
			{
			case DataMatrixScheme.SchemeAscii:
				if (channel.CurrentLength % 12 != 0)
				{
					throw new Exception("Invalid current length detected encoding ascii code");
				}
				break;
			case DataMatrixScheme.SchemeC40:
			case DataMatrixScheme.SchemeText:
			case DataMatrixScheme.SchemeX12:
				if (channel.CurrentLength % 12 != 0)
				{
					channel.Invalid = DataMatrixChannelStatus.ChannelCannotUnlatch;
					return;
				}
				if (channel.CurrentLength != channel.EncodedLength)
				{
					channel.Invalid = DataMatrixChannelStatus.ChannelCannotUnlatch;
					return;
				}
				if (unlatchType == DmtxUnlatch.Explicit)
				{
					PushInputWord(channel, (byte)DataMatrixConstants.DataMatrixCharTripletUnlatch);
					IncrementProgress(channel, 12);
				}
				break;
			case DataMatrixScheme.SchemeEdifact:
			{
				if (channel.CurrentLength % 3 != 0)
				{
					throw new Exception("Error changing encryption scheme, current length is invalid!");
				}
				if (unlatchType == DmtxUnlatch.Explicit)
				{
					PushInputWord(channel, (byte)DataMatrixConstants.DataMatrixCharEdifactUnlatch);
					IncrementProgress(channel, 9);
				}
				int num = channel.CurrentLength % 4 * 3;
				channel.CurrentLength += num;
				channel.EncodedLength += num;
				break;
			}
			}
			channel.EncScheme = DataMatrixScheme.SchemeAscii;
			switch (targetScheme)
			{
			case DataMatrixScheme.SchemeC40:
				PushInputWord(channel, DataMatrixConstants.DataMatrixCharC40Latch);
				IncrementProgress(channel, 12);
				break;
			case DataMatrixScheme.SchemeText:
				PushInputWord(channel, DataMatrixConstants.DataMatrixCharTextLatch);
				IncrementProgress(channel, 12);
				break;
			case DataMatrixScheme.SchemeX12:
				PushInputWord(channel, DataMatrixConstants.DataMatrixCharX12Latch);
				IncrementProgress(channel, 12);
				break;
			case DataMatrixScheme.SchemeEdifact:
				PushInputWord(channel, DataMatrixConstants.DataMatrixCharEdifactLatch);
				IncrementProgress(channel, 12);
				break;
			case DataMatrixScheme.SchemeBase256:
				PushInputWord(channel, DataMatrixConstants.DataMatrixCharBase256Latch);
				IncrementProgress(channel, 12);
				PushInputWord(channel, Randomize255State(0, 2));
				IncrementProgress(channel, 12);
				break;
			}
			channel.EncScheme = targetScheme;
			channel.FirstCodeWord = channel.CurrentLength - 12;
			if (channel.FirstCodeWord % 12 != 0)
			{
				throw new Exception("Error while changin encoding scheme, invalid first code word!");
			}
		}

		private byte Randomize255State(byte codewordValue, int codewordPosition)
		{
			int num = 149 * codewordPosition % 255 + 1;
			int num2 = codewordValue + num;
			return (byte)((num2 <= 255) ? num2 : (num2 - 256));
		}

		private void IncrementProgress(DataMatrixChannel channel, int encodedUnits)
		{
			if (channel.EncScheme == DataMatrixScheme.SchemeC40 || channel.EncScheme == DataMatrixScheme.SchemeText)
			{
				int num = channel.CurrentLength % 6 / 2;
				int num2 = channel.CurrentLength / 12 - (num >> 1);
				if (GetTripletValues(channel.EncodedWords[num2], channel.EncodedWords[num2 + 1]).Value[num] <= 2)
				{
					channel.CurrentLength += 8;
				}
			}
			channel.CurrentLength += encodedUnits;
		}

		private static DataMatrixTriplet GetTripletValues(byte cw1, byte cw2)
		{
			DataMatrixTriplet result = default(DataMatrixTriplet);
			int num = (cw1 << 8) | cw2;
			result.Value[0] = (byte)((num - 1) / 1600);
			result.Value[1] = (byte)((num - 1) / 40 % 40);
			result.Value[2] = (byte)((num - 1) % 40);
			return result;
		}

		private DataMatrixQuadruplet GetQuadrupletValues(byte cw1, byte cw2, byte cw3)
		{
			DataMatrixQuadruplet result = default(DataMatrixQuadruplet);
			result.Value[0] = (byte)(cw1 >> 2);
			result.Value[1] = (byte)(((cw1 & 3) << 4) | ((cw2 & 0xF0) >> 4));
			result.Value[2] = (byte)(((cw2 & 0xF) << 2) | ((cw3 & 0xC0) >> 6));
			result.Value[3] = (byte)(cw3 & 0x3Fu);
			return result;
		}

		private static void InitChannel(DataMatrixChannel channel, byte[] codewords)
		{
			channel.EncScheme = DataMatrixScheme.SchemeAscii;
			channel.Invalid = DataMatrixChannelStatus.ChannelValid;
			channel.InputIndex = 0;
			channel.Input = codewords;
		}
	}
	internal struct DataMatrixFollow
	{
		private int _ptrIndex;

		internal int PtrIndex
		{
			set
			{
				_ptrIndex = value;
			}
		}

		internal byte CurrentPtr
		{
			get
			{
				return Ptr[_ptrIndex];
			}
			set
			{
				Ptr[_ptrIndex] = value;
			}
		}

		internal byte[] Ptr { get; set; }

		internal byte Neighbor
		{
			get
			{
				return Ptr[_ptrIndex];
			}
