			}
		}

		internal int Step { get; set; }

		internal DataMatrixPixelLoc Loc { get; set; }
	}
	internal class DataMatrixImage
	{
		private int _rowPadBytes;

		internal int Width { get; set; }

		internal int Height { get; set; }

		internal DataMatrixPackOrder PixelPacking { get; set; }

		internal int BitsPerPixel { get; set; }

		internal int BytesPerPixel { get; set; }

		internal int RowPadBytes
		{
			get
			{
				return _rowPadBytes;
			}
			set
			{
				_rowPadBytes = value;
				RowSizeBytes = Width * (BitsPerPixel / 8) + _rowPadBytes;
			}
		}

		internal int RowSizeBytes { get; set; }

		internal DataMatrixFlip ImageFlip { get; set; }

		internal int ChannelCount { get; set; }

		internal int[] ChannelStart { get; set; }

		internal int[] BitsPerChannel { get; set; }

		internal byte[] Pxl { get; set; }

		internal DataMatrixImage(byte[] pxl, int width, int height, DataMatrixPackOrder pack)
		{
			BitsPerChannel = new int[4];
			ChannelStart = new int[4];
			if (pxl == null || width < 1 || height < 1)
			{
				throw new ArgumentException("Cannot create image of size null");
			}
			Pxl = pxl;
			Width = width;
			Height = height;
			PixelPacking = pack;
			BitsPerPixel = DataMatrixCommon.GetBitsPerPixel(pack);
			BytesPerPixel = BitsPerPixel / 8;
			_rowPadBytes = 0;
			RowSizeBytes = Width * BytesPerPixel + _rowPadBytes;
			ImageFlip = DataMatrixFlip.FlipNone;
			ChannelCount = 0;
			switch (pack)
			{
			case DataMatrixPackOrder.Pack1bppK:
				throw new ArgumentException("Cannot create image: not supported pack order!");
			case DataMatrixPackOrder.Pack8bppK:
				SetChannel(0, 8);
				break;
			case DataMatrixPackOrder.Pack16bppRGB:
			case DataMatrixPackOrder.Pack16bppBGR:
			case DataMatrixPackOrder.Pack16bppYCbCr:
				SetChannel(0, 5);
				SetChannel(5, 5);
				SetChannel(10, 5);
				break;
			case DataMatrixPackOrder.Pack24bppRGB:
			case DataMatrixPackOrder.Pack24bppBGR:
			case DataMatrixPackOrder.Pack24bppYCbCr:
			case DataMatrixPackOrder.Pack32bppRGBX:
			case DataMatrixPackOrder.Pack32bppBGRX:
				SetChannel(0, 8);
				SetChannel(8, 8);
				SetChannel(16, 8);
				break;
			case DataMatrixPackOrder.Pack16bppRGBX:
			case DataMatrixPackOrder.Pack16bppBGRX:
				SetChannel(0, 5);
				SetChannel(5, 5);
				SetChannel(10, 5);
				break;
			case DataMatrixPackOrder.Pack16bppXRGB:
			case DataMatrixPackOrder.Pack16bppXBGR:
				SetChannel(1, 5);
				SetChannel(6, 5);
				SetChannel(11, 5);
				break;
			case DataMatrixPackOrder.Pack32bppXRGB:
			case DataMatrixPackOrder.Pack32bppXBGR:
				SetChannel(8, 8);
				SetChannel(16, 8);
				SetChannel(24, 8);
				break;
			case DataMatrixPackOrder.Pack32bppCMYK:
				SetChannel(0, 8);
				SetChannel(8, 8);
				SetChannel(16, 8);
				SetChannel(24, 8);
				break;
			default:
				throw new ArgumentException("Cannot create image: Invalid Pack Order");
			case DataMatrixPackOrder.PackCustom:
				break;
			}
		}

		internal bool SetChannel(int channelStart, int bitsPerChannel)
		{
			if (ChannelCount >= 4)
			{
				return false;
			}
			BitsPerChannel[ChannelCount] = bitsPerChannel;
			ChannelStart[ChannelCount] = channelStart;
			ChannelCount++;
			return true;
		}

		internal int GetByteOffset(int x, int y)
		{
			if (ImageFlip == DataMatrixFlip.FlipX)
			{
				throw new ArgumentException("FlipX is not an option!");
			}
			if (!ContainsInt(0, x, y))
			{
				return DataMatrixConstants.DataMatrixUndefined;
			}
			if (ImageFlip == DataMatrixFlip.FlipY)
			{
				return y * RowSizeBytes + x * BytesPerPixel;
			}
			return (Height - y - 1) * RowSizeBytes + x * BytesPerPixel;
		}

		internal bool GetPixelValue(int x, int y, int channel, ref int value)
		{
			if (channel >= ChannelCount)
			{
				throw new ArgumentException("Channel greater than channel count!");
			}
			int byteOffset = GetByteOffset(x, y);
			if (byteOffset == DataMatrixConstants.DataMatrixUndefined)
			{
				return false;
			}
			int num = BitsPerChannel[channel];
			if (num != 1 && num != 5 && num == 8)
			{
				if (ChannelStart[channel] % 8 != 0 || BitsPerPixel % 8 != 0)
				{
					throw new Exception("Error getting pixel value");
				}
				value = Pxl[byteOffset + channel];
			}
			return true;
		}

		internal bool SetPixelValue(int x, int y, int channel, byte value)
		{
			if (channel >= ChannelCount)
			{
				throw new ArgumentException("Channel greater than channel count!");
			}
			int byteOffset = GetByteOffset(x, y);
			if (byteOffset == DataMatrixConstants.DataMatrixUndefined)
			{
				return false;
			}
			int num = BitsPerChannel[channel];
			if (num != 1 && num != 5 && num == 8)
			{
				if (ChannelStart[channel] % 8 != 0 || BitsPerPixel % 8 != 0)
				{
					throw new Exception("Error getting pixel value");
				}
				Pxl[byteOffset + channel] = value;
			}
			return true;
		}

		internal bool ContainsInt(int margin, int x, int y)
		{
			if (x - margin >= 0 && x + margin < Width && y - margin >= 0 && y + margin < Height)
			{
				return true;
			}
			return false;
		}

		internal bool ContainsFloat(double x, double y)
		{
			if (x >= 0.0 && x < (double)Width && y >= 0.0 && y < (double)Height)
			{
				return true;
			}
			return false;
		}
	}
	internal class DataMatrixImageDecoder
	{
		public List<string> DecodeImage(Bitmap image)
		{
			return DecodeImage(image, int.MaxValue, TimeSpan.MaxValue);
		}

		public List<string> DecodeImage(Bitmap image, TimeSpan timeSpan)
		{
			return DecodeImage(image, int.MaxValue, timeSpan);
		}

		public List<string> DecodeImageMosaic(Bitmap image)
		{
			return DecodeImageMosaic(image, int.MaxValue, TimeSpan.MaxValue);
		}

		public List<string> DecodeImageMosaic(Bitmap image, int maxResultCount, TimeSpan timeOut)
		{
			return DecodeImage(image, maxResultCount, timeOut, isMosaic: true);
		}

		public List<string> DecodeImageMosaic(Bitmap image, TimeSpan timeSpan)
		{
			return DecodeImage(image, int.MaxValue, timeSpan);
		}

		public List<string> DecodeImage(Bitmap image, int maxResultCount, TimeSpan timeOut)
		{
			return DecodeImage(image, maxResultCount, timeOut, isMosaic: false);
		}

		private List<string> DecodeImage(Bitmap image, int maxResultCount, TimeSpan timeOut, bool isMosaic)
		{
			List<string> list = new List<string>();
			int stride;
			DataMatrixDecode dataMatrixDecode = new DataMatrixDecode(new DataMatrixImage(ImageToByteArray(image, out stride), ((Image)image).Width, ((Image)image).Height, DataMatrixPackOrder.Pack24bppRGB)
			{
				RowPadBytes = stride % 3
			}, 1);
			Stopwatch stopwatch = new Stopwatch();
			stopwatch.Start();
			while (!(stopwatch.Elapsed > timeOut))
			{
				DataMatrixRegion dataMatrixRegion = dataMatrixDecode.RegionFindNext(timeOut);
				if (dataMatrixRegion == null)
				{
					break;
				}
				DataMatrixMessage dataMatrixMessage = (isMosaic ? dataMatrixDecode.MosaicRegion(dataMatrixRegion, -1) : dataMatrixDecode.MatrixRegion(dataMatrixRegion, -1));
				string @string = Encoding.ASCII.GetString(dataMatrixMessage.Output, 0, dataMatrixMessage.Output.Length);
				@string = @string.Substring(0, @string.IndexOf('\0'));
				if (!list.Contains(@string))
				{
					list.Add(@string);
					if (list.Count >= maxResultCount)
					{
						break;
					}
				}
			}
			return list;
		}

		private byte[] ImageToByteArray(Bitmap b, out int stride)
		{
			Rectangle rectangle = new Rectangle(0, 0, ((Image)b).Width, ((Image)b).Height);
			BitmapData val = b.LockBits(rectangle, (ImageLockMode)1, (PixelFormat)137224);
			try
			{
				byte[] array = new byte[val.Stride * ((Image)b).Height];
				Marshal.Copy(val.Scan0, array, 0, val.Stride * ((Image)b).Height);
				stride = val.Stride;
				return array;
			}
			finally
			{
				b.UnlockBits(val);
			}
		}
	}
	internal class DataMatrixImageEncoder
	{
		public static readonly int DefaultDotSize = 5;

		public static readonly int DefaultMargin = 10;

		public static readonly Color DefaultBackColor = Color.White;

		public static readonly Color DefaultForeColor = Color.Black;

		private static NumberFormatInfo _dotFormatProvider;

		public Bitmap EncodeImageMosaic(string val)
		{
			return EncodeImageMosaic(val, DefaultDotSize);
		}

		public Bitmap EncodeImageMosaic(string val, int dotSize)
		{
			return EncodeImageMosaic(val, dotSize, DefaultMargin);
		}

		public Bitmap EncodeImageMosaic(string val, int dotSize, int margin)
		{
			DataMatrixImageEncoderOptions options = new DataMatrixImageEncoderOptions
			{
				MarginSize = margin,
				ModuleSize = dotSize
			};
			return EncodeImageMosaic(val, options);
		}

		public Bitmap EncodeImageMosaic(string val, DataMatrixImageEncoderOptions options)
		{
			return EncodeImage(val, options, isMosaic: true);
		}

		private Bitmap EncodeImage(string val, DataMatrixImageEncoderOptions options, bool isMosaic)
		{
			DataMatrixEncode dataMatrixEncode = new DataMatrixEncode
			{
				ModuleSize = options.ModuleSize,
				MarginSize = options.MarginSize,
				SizeIdxRequest = options.SizeIdx,
				Width = options.Width,
				Height = options.Height,
				QuietZone = options.QuietZone
			};
			byte[] rawDataAndSetEncoding = GetRawDataAndSetEncoding(val, options, dataMatrixEncode);
			if (isMosaic)
			{
				dataMatrixEncode.EncodeDataMosaic(rawDataAndSetEncoding);
			}
			else
			{
				dataMatrixEncode.EncodeDataMatrix(options.ForeColor, options.BackColor, rawDataAndSetEncoding);
			}
			return CopyDataToBitmap(dataMatrixEncode.Image.Pxl, dataMatrixEncode.Image.Width, dataMatrixEncode.Image.Height);
		}

		private static byte[] GetRawDataAndSetEncoding(string code, DataMatrixImageEncoderOptions options, DataMatrixEncode encode)
		{
			byte[] array = Encoding.GetEncoding(options.CharacterSet).GetBytes(code);
			encode.Scheme = options.Scheme;
			if (options.Scheme == DataMatrixScheme.SchemeAsciiGS1)
			{
				List<byte> list = new List<byte>(new byte[1] { 232 });
				list.AddRange(array);
				array = list.ToArray();
				encode.Scheme = DataMatrixScheme.SchemeAscii;
			}
			return array;
		}

		public Bitmap EncodeImage(string val)
		{
			return EncodeImage(val, DefaultDotSize, DefaultMargin);
		}

