				SizeIdxRequest = options.SizeIdx,
				Width = options.Width,
				Height = options.Height,
				QuietZone = options.QuietZone,
				Scheme = options.Scheme
			};
			byte[] rawDataAndSetEncoding = GetRawDataAndSetEncoding(val, options, dataMatrixEncode);
			dataMatrixEncode.EncodeDataMatrix(options.ForeColor, options.BackColor, rawDataAndSetEncoding);
			return EncodeSvgFile(dataMatrixEncode, "", options.ModuleSize, options.MarginSize, options.ForeColor, options.BackColor);
		}

		internal static Bitmap CopyDataToBitmap(byte[] data, int width, int height)
		{
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Expected O, but got Unknown
			data = InsertPaddingBytes(data, width, height, 24);
			Bitmap val = new Bitmap(width, height);
			BitmapData val2 = val.LockBits(new Rectangle(0, 0, width, height), (ImageLockMode)2, (PixelFormat)137224);
			Marshal.Copy(data, 0, val2.Scan0, data.Length);
			val.UnlockBits(val2);
			return val;
		}

		private static byte[] InsertPaddingBytes(byte[] data, int width, int height, int bitsPerPixel)
		{
			int num = 4 * ((width * bitsPerPixel + 31) / 32);
			int num2 = num - 3 * width;
			if (num2 == 0)
			{
				return data;
			}
			byte[] array = new byte[num * height];
			for (int i = 0; i < height; i++)
			{
				for (int j = 0; j < width; j++)
				{
					array[i * num + 3 * j] = data[3 * (i * width + j)];
					array[i * num + 3 * j + 1] = data[3 * (i * width + j) + 1];
					array[i * num + 3 * j + 2] = data[3 * (i * width + j) + 2];
				}
				for (int k = 0; k < num2; k++)
				{
					array[i * num + 3 * k] = byte.MaxValue;
					array[i * num + 3 * k + 1] = byte.MaxValue;
					array[i * num + 3 * k + 2] = byte.MaxValue;
				}
			}
			return array;
		}

		internal string EncodeSvgFile(DataMatrixEncode enc, string format, int moduleSize, int margin, Color foreColor, Color backColor)
		{
			bool flag = false;
			string text = null;
			string text2 = "";
			if (_dotFormatProvider == null)
			{
				_dotFormatProvider = new NumberFormatInfo
				{
					NumberDecimalSeparator = "."
				};
			}
			if (format == "svg:")
			{
				flag = true;
				text = format.Substring(4);
			}
			if (string.IsNullOrEmpty(text))
			{
				text = "dmtx_0001";
			}
			int num = 2 * enc.MarginSize + enc.Region.SymbolCols * enc.ModuleSize;
			int num2 = 2 * enc.MarginSize + enc.Region.SymbolRows * enc.ModuleSize;
			int symbolAttribute = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolCols, enc.Region.SizeIdx);
			int symbolAttribute2 = DataMatrixCommon.GetSymbolAttribute(DataMatrixSymAttribute.SymAttribSymbolRows, enc.Region.SizeIdx);
			if (!flag)
			{
				text2 += string.Format("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"no\"?>\n<!-- Created with MessagingToolkit.Barcode.DataMatrix.Pdf417Encoder (http://datamatrixnet.sourceforge.Pdf417Encoder/) -->\n<svg\nxmlns:svg=\"http://www.w3.org/2000/svg\"\nxmlns=\"http://www.w3.org/2000/svg\"\nxmlns:xlink=\"http://www.w3.org/1999/xlink\"\nversion=\"1.0\"\nwidth=\"{0}\"\nheight=\"{1}\"\nid=\"svg2\">\n<defs>\n<symbol id=\"{2}\">\n    <desc>Layout:{0}x%{1} Symbol:{3}x{4} data Matrix</desc>\n", num, num2, text, symbolAttribute, symbolAttribute2);
			}
			if (backColor != Color.White)
			{
				string arg = string.Format("style=\"fill:#{0}{1}{2};fill-opacity:{3};stroke:none\" ", backColor.R.ToString("X2"), backColor.G.ToString("X2"), backColor.B.ToString("X2"), ((double)(int)backColor.A / 255.0).ToString("0.##", _dotFormatProvider));
				text2 += $"    <rect width=\"{num}\" height=\"{num2}\" x=\"0\" y=\"0\" {arg}/>\n";
			}
			for (int i = 0; i < enc.Region.SymbolRows; i++)
			{
				int num3 = enc.Region.SymbolRows - i - 1;
				for (int j = 0; j < enc.Region.SymbolCols; j++)
				{
					int num4 = enc.Message.SymbolModuleStatus(enc.Region.SizeIdx, i, j);
					string arg = string.Format("style=\"fill:#{0}{1}{2};fill-opacity:{3};stroke:none\" ", foreColor.R.ToString("X2"), foreColor.G.ToString("X2"), foreColor.B.ToString("X2"), ((double)(int)foreColor.A / 255.0).ToString("0.##", _dotFormatProvider));
					if ((num4 & DataMatrixConstants.DataMatrixModuleOn) != 0)
					{
						text2 += $"    <rect width=\"{moduleSize}\" height=\"{moduleSize}\" x=\"{j * moduleSize + margin}\" y=\"{num3 * moduleSize + margin}\" {arg}/>\n";
					}
				}
			}
			text2 += "  </symbol>\n";
			if (!flag)
			{
				text2 += $"</defs>\n<use xlink:href=\"#{text}\" x='0' y='0' style=\"fill:#000000;fill-opacity:1;stroke:none\" />\n\n</svg>\n";
			}
			return text2;
		}
	}
