		internal DataMatrixScanGrid(DataMatrixDecode dec)
		{
			int scanGap = dec.ScanGap;
			_xMin = dec.XMin;
			_xMax = dec.XMax;
			_yMin = dec.YMin;
			_yMax = dec.YMax;
			int num = _xMax - _xMin;
			int num2 = _yMax - _yMin;
			int num3 = ((num > num2) ? num : num2);
			if (num3 < 1)
			{
				throw new ArgumentException("Invalid max extent for Scan Grid: Must be greater than 0");
			}
			int num4;
			for (num4 = (_minExtent = 1); num4 < num3; num4 = (num4 + 1) * 2 - 1)
			{
				if (num4 <= scanGap)
				{
					_minExtent = num4;
				}
			}
			_maxExtent = num4;
			_xOffset = (_xMin + _xMax - _maxExtent) / 2;
			_yOffset = (_yMin + _yMax - _maxExtent) / 2;
			_total = 1;
			_extent = _maxExtent;
			_jumpSize = _extent + 1;
			_pixelTotal = 2 * _extent - 1;
			_startPos = _extent / 2;
			_pixelCount = 0;
			_xCenter = (_yCenter = _startPos);
			SetDerivedFields();
		}

		internal DataMatrixRange PopGridLocation(ref DataMatrixPixelLoc loc)
		{
			DataMatrixRange gridCoordinates;
			do
			{
				gridCoordinates = GetGridCoordinates(ref loc);
				_pixelCount++;
			}
			while (gridCoordinates == DataMatrixRange.RangeBad);
			return gridCoordinates;
		}

		private DataMatrixRange GetGridCoordinates(ref DataMatrixPixelLoc locRef)
		{
			if (_pixelCount >= _pixelTotal)
			{
				_pixelCount = 0;
				_xCenter += _jumpSize;
			}
			if (_xCenter > _maxExtent)
			{
				_xCenter = _startPos;
				_yCenter += _jumpSize;
			}
			if (_yCenter > _maxExtent)
			{
				_total *= 4;
				_extent /= 2;
				SetDerivedFields();
			}
			if (_extent == 0 || _extent < _minExtent)
			{
				int x = (locRef.Y = -1);
				locRef.X = x;
				return DataMatrixRange.RangeEnd;
			}
			int pixelCount = _pixelCount;
			if (pixelCount >= _pixelTotal)
			{
				throw new Exception("Scangrid is beyong image limits!");
			}
			DataMatrixPixelLoc dataMatrixPixelLoc = default(DataMatrixPixelLoc);
			if (pixelCount == _pixelTotal - 1)
			{
				dataMatrixPixelLoc.X = _xCenter;
				dataMatrixPixelLoc.Y = _yCenter;
			}
			else
			{
				int num2 = _pixelTotal / 2;
				int num3 = num2 / 2;
				if (pixelCount < num2)
				{
					dataMatrixPixelLoc.X = _xCenter + ((pixelCount < num3) ? (pixelCount - num3) : (num2 - pixelCount));
					dataMatrixPixelLoc.Y = _yCenter;
				}
				else
				{
					pixelCount -= num2;
					dataMatrixPixelLoc.X = _xCenter;
					dataMatrixPixelLoc.Y = _yCenter + ((pixelCount < num3) ? (pixelCount - num3) : (num2 - pixelCount));
				}
			}
			dataMatrixPixelLoc.X += _xOffset;
			dataMatrixPixelLoc.Y += _yOffset;
			locRef.X = dataMatrixPixelLoc.X;
			locRef.Y = dataMatrixPixelLoc.Y;
			if (dataMatrixPixelLoc.X < _xMin || dataMatrixPixelLoc.X > _xMax || dataMatrixPixelLoc.Y < _yMin || dataMatrixPixelLoc.Y > _yMax)
			{
				return DataMatrixRange.RangeBad;
			}
			return DataMatrixRange.RangeGood;
		}

		private void SetDerivedFields()
		{
			_jumpSize = _extent + 1;
			_pixelTotal = 2 * _extent - 1;
			_startPos = _extent / 2;
			_pixelCount = 0;
			_xCenter = (_yCenter = _startPos);
		}
