	internal class DataMatrixVector2
	{
		internal double X { get; set; }

		internal double Y { get; set; }

		internal DataMatrixVector2()
		{
			X = 0.0;
			Y = 0.0;
		}

		internal DataMatrixVector2(double x, double y)
		{
			X = x;
			Y = y;
		}

		public static DataMatrixVector2 operator +(DataMatrixVector2 v1, DataMatrixVector2 v2)
		{
			DataMatrixVector2 dataMatrixVector = new DataMatrixVector2(v1.X, v1.Y);
			dataMatrixVector.X += v2.X;
			dataMatrixVector.Y += v2.Y;
			return dataMatrixVector;
		}

		public static DataMatrixVector2 operator -(DataMatrixVector2 v1, DataMatrixVector2 v2)
		{
			DataMatrixVector2 dataMatrixVector = new DataMatrixVector2(v1.X, v1.Y);
			dataMatrixVector.X -= v2.X;
			dataMatrixVector.Y -= v2.Y;
			return dataMatrixVector;
		}

		public static DataMatrixVector2 operator *(DataMatrixVector2 v1, double factor)
		{
			return new DataMatrixVector2(v1.X * factor, v1.Y * factor);
		}

		internal double Cross(DataMatrixVector2 v2)
		{
			return X * v2.Y - Y * v2.X;
		}

		internal double Norm()
		{
			double num = Mag();
			if (num <= DataMatrixConstants.DataMatrixAlmostZero)
			{
				return -1.0;
			}
			X /= num;
			Y /= num;
			return num;
		}

		internal double Dot(DataMatrixVector2 v2)
		{
			return Math.Sqrt(X * v2.X + Y * v2.Y);
		}

		internal double Mag()
		{
			return Math.Sqrt(X * X + Y * Y);
		}

		internal double DistanceFromRay2(DataMatrixRay2 ray)
		{
			if (Math.Abs(1.0 - ray.V.Mag()) > DataMatrixConstants.DataMatrixAlmostZero)
			{
				throw new ArgumentException("DistanceFromRay2: The ray's V vector must be a unit vector");
			}
			return ray.V.Cross(this - ray.P);
		}

		internal double DistanceAlongRay2(DataMatrixRay2 ray)
		{
			if (Math.Abs(1.0 - ray.V.Mag()) > DataMatrixConstants.DataMatrixAlmostZero)
			{
				throw new ArgumentException("DistanceAlongRay2: The ray's V vector must be a unit vector");
			}
			return (this - ray.P).Dot(ray.V);
		}

		internal bool Intersect(DataMatrixRay2 p0, DataMatrixRay2 p1)
		{
			double num = p1.V.Cross(p0.V);
			if (Math.Abs(num) < DataMatrixConstants.DataMatrixAlmostZero)
			{
				return false;
			}
			double num2 = p1.V.Cross(p1.P - p0.P);
			return PointAlongRay2(p0, num2 / num);
		}

		internal bool PointAlongRay2(DataMatrixRay2 ray, double t)
		{
			if (Math.Abs(1.0 - ray.V.Mag()) > DataMatrixConstants.DataMatrixAlmostZero)
			{
				throw new ArgumentException("PointAlongRay: The ray's V vector must be a unit vector");
			}
			DataMatrixVector2 dataMatrixVector = new DataMatrixVector2(ray.V.X * t, ray.V.Y * t);
			X = ray.P.X + dataMatrixVector.X;
			Y = ray.P.Y + dataMatrixVector.Y;
			return true;
		}
	}
	public class DefaultPlacement
	{
		private string codewords;

		protected internal int numrows;

		protected internal int numcols;

		protected internal sbyte[] bits;

		internal int Numrows => numrows;

		internal int Numcols => numcols;

		internal sbyte[] Bits => bits;

		public DefaultPlacement(string codewords, int numcols, int numrows)
		{
			this.codewords = codewords;
			this.numcols = numcols;
			this.numrows = numrows;
			bits = new sbyte[numcols * numrows];
			for (int i = 0; i < bits.Length; i++)
			{
				bits[i] = -1;
			}
		}

		public virtual bool GetBit(int col, int row)
		{
			return bits[row * numcols + col] == 1;
		}

		public virtual void SetBit(int col, int row, bool bit)
		{
			bits[row * numcols + col] = (sbyte)(bit ? 1 : 0);
		}

		public virtual bool HasBit(int col, int row)
		{
			return bits[row * numcols + col] >= 0;
		}

		public virtual void Place()
		{
			int num = 0;
			int num2 = 4;
			int num3 = 0;
			do
			{
				if (num2 == numrows && num3 == 0)
				{
					Corner1(num++);
				}
				if (num2 == numrows - 2 && num3 == 0 && numcols % 4 != 0)
				{
					Corner2(num++);
				}
				if (num2 == numrows - 2 && num3 == 0 && numcols % 8 == 4)
				{
					Corner3(num++);
				}
				if (num2 == numrows + 4 && num3 == 2 && numcols % 8 == 0)
				{
					Corner4(num++);
				}
				do
				{
					if (num2 < numrows && num3 >= 0 && !HasBit(num3, num2))
					{
						Utah(num2, num3, num++);
					}
					num2 -= 2;
					num3 += 2;
				}
				while (num2 >= 0 && num3 < numcols);
				num2++;
				num3 += 3;
				do
				{
					if (num2 >= 0 && num3 < numcols && !HasBit(num3, num2))
					{
						Utah(num2, num3, num++);
					}
					num2 += 2;
					num3 -= 2;
				}
				while (num2 < numrows && num3 >= 0);
				num2 += 3;
				num3++;
			}
			while (num2 < numrows || num3 < numcols);
			if (!HasBit(numcols - 1, numrows - 1))
			{
				SetBit(numcols - 1, numrows - 1, bit: true);
				SetBit(numcols - 2, numrows - 2, bit: true);
			}
		}

		private void Module(int row, int col, int pos, int bit)
		{
			if (row < 0)
			{
				row += numrows;
				col += 4 - (numrows + 4) % 8;
			}
			if (col < 0)
			{
				col += numcols;
				row += 4 - (numcols + 4) % 8;
			}
			int num = codewords[pos];
			num &= 1 << 8 - bit;
			SetBit(col, row, num != 0);
		}

		private void Utah(int row, int col, int pos)
		{
			Module(row - 2, col - 2, pos, 1);
			Module(row - 2, col - 1, pos, 2);
			Module(row - 1, col - 2, pos, 3);
			Module(row - 1, col - 1, pos, 4);
			Module(row - 1, col, pos, 5);
			Module(row, col - 2, pos, 6);
			Module(row, col - 1, pos, 7);
			Module(row, col, pos, 8);
		}

		private void Corner1(int pos)
		{
			Module(numrows - 1, 0, pos, 1);
			Module(numrows - 1, 1, pos, 2);
			Module(numrows - 1, 2, pos, 3);
			Module(0, numcols - 2, pos, 4);
			Module(0, numcols - 1, pos, 5);
			Module(1, numcols - 1, pos, 6);
			Module(2, numcols - 1, pos, 7);
			Module(3, numcols - 1, pos, 8);
		}

		private void Corner2(int pos)
		{
			Module(numrows - 3, 0, pos, 1);
			Module(numrows - 2, 0, pos, 2);
			Module(numrows - 1, 0, pos, 3);
			Module(0, numcols - 4, pos, 4);
			Module(0, numcols - 3, pos, 5);
			Module(0, numcols - 2, pos, 6);
			Module(0, numcols - 1, pos, 7);
			Module(1, numcols - 1, pos, 8);
		}

		private void Corner3(int pos)
		{
			Module(numrows - 3, 0, pos, 1);
			Module(numrows - 2, 0, pos, 2);
			Module(numrows - 1, 0, pos, 3);
			Module(0, numcols - 2, pos, 4);
			Module(0, numcols - 1, pos, 5);
			Module(1, numcols - 1, pos, 6);
			Module(2, numcols - 1, pos, 7);
			Module(3, numcols - 1, pos, 8);
		}

		private void Corner4(int pos)
		{
			Module(numrows - 1, 0, pos, 1);
			Module(numrows - 1, numcols - 1, pos, 2);
			Module(0, numcols - 3, pos, 3);
			Module(0, numcols - 2, pos, 4);
			Module(0, numcols - 1, pos, 5);
			Module(1, numcols - 3, pos, 6);
			Module(1, numcols - 2, pos, 7);
			Module(1, numcols - 1, pos, 8);
		}
	}
	internal class EdifactEncoder : Encoder
	{
		public virtual int EncodingMode => 4;

		public virtual void Encode(EncoderContext context)
		{
			StringBuilder stringBuilder = new StringBuilder();
			while (context.HasMoreCharacters())
			{
				encodeChar(context.CurrentChar, stringBuilder);
				context.pos++;
				if (stringBuilder.Length >= 4)
				{
					context.WriteCodewords(EncodeToCodewords(stringBuilder, 0));
					stringBuilder.Remove(0, 4);
					if (HighLevelEncoder.LookAheadTest(context.Message, context.pos, EncodingMode) != EncodingMode)
					{
						context.SignalEncoderChange(0);
						break;
					}
				}
			}
			stringBuilder.Append('\u001f');
			HandleEOD(context, stringBuilder);
		}

		private static void HandleEOD(EncoderContext context, StringBuilder buffer)
		{
			try
			{
				int length = buffer.Length;
				switch (length)
				{
				case 0:
					return;
				case 1:
				{
					context.UpdateSymbolInfo();
					int num = context.SymbolInfo.DataCapacity - context.CodewordCount;
					if (context.RemainingCharacters == 0 && num <= 2)
					{
						return;
					}
					break;
				}
				}
				if (length > 4)
				{
					throw new ArgumentException("Count must not exceed 4");
				}
				int num2 = length - 1;
				string text = EncodeToCodewords(buffer, 0);
				bool flag = !context.HasMoreCharacters() && num2 <= 2;
				if (num2 <= 2)
				{
					context.UpdateSymbolInfo(context.CodewordCount + num2);
					if (context.SymbolInfo.DataCapacity - context.CodewordCount >= 3)
					{
						flag = false;
						context.UpdateSymbolInfo(context.CodewordCount + text.Length);
					}
				}
				if (flag)
				{
					context.ResetSymbolInfo();
					context.pos -= num2;
				}
				else
				{
					context.WriteCodewords(text);
				}
			}
			finally
			{
				context.SignalEncoderChange(0);
			}
		}

		private static void encodeChar(char c, StringBuilder sb)
		{
			if (c >= ' ' && c <= '?')
			{
				sb.Append(c);
			}
			else if (c >= '@' && c <= '^')
			{
				sb.Append((char)(c - 64));
			}
			else
			{
				HighLevelEncoder.IllegalCharacter(c);
			}
		}

		private static string EncodeToCodewords(StringBuilder sb, int startPos)
		{
			int num = sb.Length - startPos;
			if (num == 0)
			{
				throw new ArgumentException("StringBuilder must not be empty");
			}
			char c = sb[startPos];
			char c2 = ((num >= 2) ? sb[startPos + 1] : '\0');
			char c3 = ((num >= 3) ? sb[startPos + 2] : '\0');
			char c4 = ((num >= 4) ? sb[startPos + 3] : '\0');
			uint num2 = ((uint)c << 18) + ((uint)c2 << 12) + ((uint)c3 << 6) + c4;
			char value = (char)((uint)((int)num2 >> 16) & 0xFFu);
			char value2 = (char)((uint)((int)num2 >> 8) & 0xFFu);
			char value3 = (char)(num2 & 0xFFu);
			StringBuilder stringBuilder = new StringBuilder(3);
			stringBuilder.Append(value);
			if (num >= 2)
			{
				stringBuilder.Append(value2);
			}
			if (num >= 3)
			{
				stringBuilder.Append(value3);
			}
			return stringBuilder.ToString();
		}
	}
	internal interface Encoder
	{
		int EncodingMode { get; }

		void Encode(EncoderContext context);
	}
	internal sealed class EncoderContext
	{
		public const string DefaultEncoding = "ISO-8859-1";

		private string msg;

		private SymbolShapeHint shape;

		private Dimension minSize;

		private Dimension maxSize;

		private StringBuilder codewords;

		internal int pos;

		private int newEncoding;

		private SymbolInfo symbolInfo;

		private int skipAtEnd;

		public SymbolShapeHint SymbolShape
		{
			set
			{
				shape = value;
			}
		}

		public string Message => msg;

		public int SkipAtEnd
		{
			set
			{
				skipAtEnd = value;
			}
		}

		public char CurrentChar => msg[pos];

		public char Current => msg[pos];

		public StringBuilder Codewords => codewords;

		public int CodewordCount => codewords.Length;

		public int NewEncoding => newEncoding;

		public int Position => pos;

		private int TotalMessageCharCount => msg.Length - skipAtEnd;

		public int RemainingCharacters => TotalMessageCharCount - pos;

		public SymbolInfo SymbolInfo => symbolInfo;

		internal EncoderContext(string msg)
		{
			byte[] bytes;
			try
			{
				bytes = Encoding.GetEncoding("ISO-8859-1").GetBytes(msg);
			}
			catch (Exception ex)
			{
				throw new NotSupportedException("Unsupported encoding: " + ex.Message);
			}
			StringBuilder stringBuilder = new StringBuilder(bytes.Length);
			int i = 0;
			for (int num = bytes.Length; i < num; i++)
			{
				char c = (char)(bytes[i] & 0xFFu);
				if (c == '?' && msg[i] != '?')
				{
					throw new ArgumentException("Message contains characters outside ISO-8859-1 encoding.");
				}
				stringBuilder.Append(c);
			}
			this.msg = stringBuilder.ToString();
			shape = SymbolShapeHint.ForceNone;
			codewords = new StringBuilder(msg.Length);
			newEncoding = -1;
		}

		public EncoderContext(byte[] data)
		{
			StringBuilder stringBuilder = new StringBuilder(data.Length);
			int i = 0;
			for (int num = data.Length; i < num; i++)
			{
				char value = (char)(data[i] & 0xFFu);
				stringBuilder.Append(value);
			}
			msg = stringBuilder.ToString();
			codewords = new StringBuilder(msg.Length);
		}

		public void SetSizeConstraints(Dimension minSize, Dimension maxSize)
		{
			this.minSize = minSize;
			this.maxSize = maxSize;
		}

		public void WriteCodewords(string codewords)
		{
			this.codewords.Append(codewords);
		}

		public void WriteCodeword(char codeword)
		{
			codewords.Append(codeword);
		}

		public void SignalEncoderChange(int encoding)
		{
			newEncoding = encoding;
		}

		public void ResetEncoderSignal()
		{
			newEncoding = -1;
		}

		public bool HasMoreCharacters()
		{
			return pos < TotalMessageCharCount;
		}

		public void UpdateSymbolInfo()
		{
			UpdateSymbolInfo(CodewordCount);
		}

		public void UpdateSymbolInfo(int len)
		{
			if (symbolInfo == null || len > symbolInfo.DataCapacity)
			{
				symbolInfo = SymbolInfo.Lookup(len, shape, minSize, maxSize, fail: true);
			}
		}

		public void ResetSymbolInfo()
		{
			symbolInfo = null;
		}
	}
