		public static string EncodeECC200(string codewords, SymbolInfo symbolInfo)
		{
			if (codewords.Length != symbolInfo.DataCapacity)
			{
				throw new ArgumentException("The number of codewords does not match the selected symbol");
			}
			StringBuilder stringBuilder = new StringBuilder(symbolInfo.DataCapacity + symbolInfo.ErrorCodewords);
			stringBuilder.Append(codewords);
			int interleavedBlockCount = symbolInfo.InterleavedBlockCount;
			if (interleavedBlockCount == 1)
			{
				string value = CreateECCBlock(codewords, symbolInfo.ErrorCodewords);
				stringBuilder.Append(value);
			}
			else
			{
				stringBuilder.Length = stringBuilder.Capacity;
				int[] array = new int[interleavedBlockCount];
				int[] array2 = new int[interleavedBlockCount];
				int[] array3 = new int[interleavedBlockCount];
				for (int i = 0; i < interleavedBlockCount; i++)
				{
					array[i] = symbolInfo.GetDataLengthForInterleavedBlock(i + 1);
					array2[i] = symbolInfo.GetErrorLengthForInterleavedBlock(i + 1);
					array3[i] = 0;
					if (i > 0)
					{
						array3[i] = array3[i - 1] + array[i];
					}
				}
				for (int j = 0; j < interleavedBlockCount; j++)
				{
					StringBuilder stringBuilder2 = new StringBuilder(array[j]);
					for (int k = j; k < symbolInfo.DataCapacity; k += interleavedBlockCount)
					{
						stringBuilder2.Append(codewords[k]);
					}
					string text = CreateECCBlock(stringBuilder2.ToString(), array2[j]);
					int num = 0;
					for (int l = j; l < array2[j] * interleavedBlockCount; l += interleavedBlockCount)
					{
						stringBuilder[symbolInfo.DataCapacity + l] = text[num++];
					}
				}
			}
			return stringBuilder.ToString();
		}

		private static string CreateECCBlock(string codewords, int numECWords)
		{
			return CreateECCBlock(codewords, 0, codewords.Length, numECWords);
		}

		private static string CreateECCBlock(string codewords, int start, int len, int numECWords)
		{
			int num = -1;
			for (int i = 0; i < FactorSets.Length; i++)
			{
				if (FactorSets[i] == numECWords)
				{
					num = i;
					break;
				}
			}
			if (num < 0)
			{
				throw new ArgumentException("Illegal number of error correction codewords specified: " + numECWords);
			}
			int[] array = Factors[num];
			char[] array2 = new char[numECWords];
			for (int j = 0; j < numECWords; j++)
			{
				array2[j] = '\0';
			}
			for (int k = start; k < start + len; k++)
			{
				int num2 = array2[numECWords - 1] ^ codewords[k];
				for (int num3 = numECWords - 1; num3 > 0; num3--)
				{
					if (num2 != 0 && array[num3] != 0)
					{
						array2[num3] = (char)(array2[num3 - 1] ^ ALOG[(LOG[num2] + LOG[array[num3]]) % 255]);
					}
					else
					{
						array2[num3] = array2[num3 - 1];
					}
				}
				if (num2 != 0 && array[0] != 0)
				{
					array2[0] = (char)ALOG[(LOG[num2] + LOG[array[0]]) % 255];
				}
				else
				{
					array2[0] = '\0';
				}
			}
			char[] array3 = new char[numECWords];
			for (int l = 0; l < numECWords; l++)
			{
				array3[l] = array2[numECWords - l - 1];
			}
			return new string(array3);
		}
	}
	public sealed class HighLevelEncoder
	{
		internal static char PAD = '\u0081';

		internal static char LATCH_TO_C40 = 'æ';

		internal static char LATCH_TO_BASE256 = 'ç';

		internal static char UPPER_SHIFT = 'ë';

		internal static char MACRO_05 = 'ì';

		internal static char MACRO_06 = 'í';

		internal static char LATCH_TO_ANSIX12 = 'î';

		internal static char LATCH_TO_TEXT = 'ï';

		internal static char LATCH_TO_EDIFACT = 'ð';

		internal static char ECI = 'ñ';

		internal static char C40_UNLATCH = 'þ';

		internal static char X12_UNLATCH = 'þ';

		internal static string MACRO_05_HEADER = "[)>\u001e05\u001d";

		internal static string MACRO_06_HEADER = "[)>\u001e06\u001d";

		internal static string MACRO_TRAILER = "\u001e\u0004";

		internal const int ASCII_ENCODATION = 0;

		internal const int C40_ENCODATION = 1;

		internal const int TEXT_ENCODATION = 2;

		internal const int X12_ENCODATION = 3;

		internal const int EDIFACT_ENCODATION = 4;

		internal const int BASE256_ENCODATION = 5;

		private HighLevelEncoder()
		{
		}

		public static byte[] GetBytesForMessage(string msg)
		{
			try
			{
				return Encoding.GetEncoding("CP437").GetBytes(msg);
			}
			catch (ArgumentException)
			{
				throw new NotSupportedException("Incompatible environment. The 'CP437' charset is not available!");
			}
		}

		private static char Randomize253State(char ch, int codewordPosition)
		{
			int num = 149 * codewordPosition % 253 + 1;
			int num2 = ch + num;
			if (num2 > 254)
			{
				return (char)(num2 - 254);
			}
			return (char)num2;
		}

		private static char Randomize255State(char ch, int codewordPosition)
		{
			int num = 149 * codewordPosition % 255 + 1;
			int num2 = ch + num;
			if (num2 <= 255)
			{
				return (char)num2;
			}
			return (char)(num2 - 256);
		}

		public static string EncodeHighLevel(string msg)
		{
			return EncodeHighLevel(msg, SymbolShapeHint.ForceNone, null, null, null);
		}

		public static string EncodeHighLevel(string msg, SymbolShapeHint shape, Dimension minSize, Dimension maxSize, Dictionary<EncodeOptions, object> encodingOptions)
		{
			Encoder[] array = new Encoder[6]
			{
				new ASCIIEncoder(),
				new C40Encoder(),
				new TextEncoder(),
				new X12Encoder(),
				new EdifactEncoder(),
				new Base256Encoder()
			};
			EncoderContext encoderContext = new EncoderContext(msg);
			encoderContext.SymbolShape = shape;
			encoderContext.SetSizeConstraints(minSize, maxSize);
			if (msg.StartsWith(MACRO_05_HEADER) && msg.EndsWith(MACRO_TRAILER))
			{
				encoderContext.WriteCodeword(MACRO_05);
				encoderContext.SkipAtEnd = 2;
				encoderContext.pos += MACRO_05_HEADER.Length;
			}
			else if (msg.StartsWith(MACRO_06_HEADER) && msg.EndsWith(MACRO_TRAILER))
			{
				encoderContext.WriteCodeword(MACRO_06);
				encoderContext.SkipAtEnd = 2;
				encoderContext.pos += MACRO_06_HEADER.Length;
			}
			int num = 0;
			while (encoderContext.HasMoreCharacters())
			{
				array[num].Encode(encoderContext);
				if (encoderContext.NewEncoding >= 0)
				{
					num = encoderContext.NewEncoding;
					encoderContext.ResetEncoderSignal();
				}
			}
			int length = encoderContext.Codewords.Length;
			encoderContext.UpdateSymbolInfo();
			int dataCapacity = encoderContext.SymbolInfo.DataCapacity;
			if (length < dataCapacity && num != 0 && num != 5)
			{
				encoderContext.WriteCodeword('þ');
			}
			StringBuilder codewords = encoderContext.Codewords;
			if (codewords.Length < dataCapacity)
			{
				codewords.Append(PAD);
			}
			while (codewords.Length < dataCapacity)
			{
				codewords.Append(Randomize253State(PAD, codewords.Length + 1));
			}
			return encoderContext.Codewords.ToString();
		}

		internal static int LookAheadTest(string msg, int startpos, int currentMode)
		{
			if (startpos >= msg.Length)
			{
				return currentMode;
			}
			float[] array;
			if (currentMode == 0)
			{
				array = new float[6] { 0f, 1f, 1f, 1f, 1f, 1.25f };
			}
			else
			{
				array = new float[6] { 1f, 2f, 2f, 2f, 2f, 2.25f };
				array[currentMode] = 0f;
			}
			int num = 0;
			while (true)
			{
				if (startpos + num == msg.Length)
				{
					int min = int.MaxValue;
					sbyte[] array2 = new sbyte[6];
					int[] array3 = new int[6];
					min = FindMinimums(array, array3, min, array2);
					int minimumCount = GetMinimumCount(array2);
					if (array3[0] == min)
					{
						return 0;
					}
					if (minimumCount == 1 && array2[5] > 0)
					{
						return 5;
					}
					if (minimumCount == 1 && array2[4] > 0)
					{
						return 4;
					}
					if (minimumCount == 1 && array2[2] > 0)
					{
						return 2;
					}
					if (minimumCount == 1 && array2[3] > 0)
					{
						return 3;
					}
					return 1;
				}
				char ch = msg[startpos + num];
				num++;
				if (IsDigit(ch))
				{
					array[0] += 0.5f;
				}
				else if (IsExtendedASCII(ch))
				{
					array[0] = (int)Math.Ceiling(array[0]);
					array[0] += 2f;
				}
				else
				{
					array[0] = (int)Math.Ceiling(array[0]);
					array[0] += 1f;
				}
				if (IsNativeC40(ch))
				{
					array[1] += 2f / 3f;
				}
				else if (IsExtendedASCII(ch))
				{
					array[1] += 2.6666667f;
				}
				else
				{
					array[1] += 1.3333334f;
				}
				if (IsNativeText(ch))
				{
					array[2] += 2f / 3f;
				}
				else if (IsExtendedASCII(ch))
				{
					array[2] += 2.6666667f;
				}
				else
				{
					array[2] += 1.3333334f;
				}
				if (IsNativeX12(ch))
				{
					array[3] += 2f / 3f;
				}
				else if (IsExtendedASCII(ch))
				{
					array[3] += 4.3333335f;
				}
				else
				{
					array[3] += 3.3333333f;
				}
				if (IsNativeEDIFACT(ch))
				{
					array[4] += 0.75f;
				}
				else if (IsExtendedASCII(ch))
				{
					array[4] += 4.25f;
				}
				else
				{
					array[4] += 3.25f;
				}
				if (IsSpecialB256(ch))
				{
					array[5] += 4f;
				}
				else
				{
					array[5] += 1f;
				}
				if (num < 4)
				{
					continue;
				}
				int[] array4 = new int[6];
				sbyte[] array5 = new sbyte[6];
				FindMinimums(array, array4, int.MaxValue, array5);
				int minimumCount2 = GetMinimumCount(array5);
				if (array4[0] < array4[5] && array4[0] < array4[1] && array4[0] < array4[2] && array4[0] < array4[3] && array4[0] < array4[4])
				{
					return 0;
				}
				if (array4[5] < array4[0] || array5[1] + array5[2] + array5[3] + array5[4] == 0)
				{
					return 5;
				}
				if (minimumCount2 == 1 && array5[4] > 0)
				{
					return 4;
				}
				if (minimumCount2 == 1 && array5[2] > 0)
				{
					return 2;
				}
				if (minimumCount2 == 1 && array5[3] > 0)
				{
					return 3;
				}
				if (array4[1] + 1 < array4[0] && array4[1] + 1 < array4[5] && array4[1] + 1 < array4[4] && array4[1] + 1 < array4[2])
				{
					if (array4[1] < array4[3])
					{
						return 1;
					}
					if (array4[1] == array4[3])
					{
						break;
					}
				}
			}
			for (int i = startpos + num + 1; i < msg.Length; i++)
			{
				char ch2 = msg[i];
				if (IsX12TermSep(ch2))
				{
					return 3;
				}
				if (!IsNativeX12(ch2))
				{
					break;
				}
			}
			return 1;
		}

		private static int FindMinimums(float[] charCounts, int[] intCharCounts, int min, sbyte[] mins)
		{
			for (int i = 0; i < mins.Length; i++)
			{
				mins[i] = 0;
			}
			for (int j = 0; j < 6; j++)
			{
				intCharCounts[j] = (int)Math.Ceiling(charCounts[j]);
				int num = intCharCounts[j];
				if (min > num)
				{
					min = num;
					for (int k = 0; k < mins.Length; k++)
					{
						mins[k] = 0;
					}
				}
				if (min == num)
				{
					mins[j]++;
				}
			}
			return min;
		}

		private static int GetMinimumCount(sbyte[] mins)
		{
			int num = 0;
			for (int i = 0; i < 6; i++)
			{
				num += mins[i];
			}
			return num;
		}

		internal static bool IsDigit(char ch)
		{
			if (ch >= '0')
			{
				return ch <= '9';
			}
			return false;
		}

		internal static bool IsExtendedASCII(char ch)
		{
			if (ch >= '\u0080')
			{
				return ch <= 'ÿ';
			}
			return false;
		}

		private static bool IsASCII7(char ch)
		{
			if (ch >= '\0')
			{
				return ch <= '\u007f';
			}
			return false;
		}

		private static bool IsNativeC40(char ch)
		{
			switch (ch)
			{
			default:
				if (ch >= 'A')
				{
					return ch <= 'Z';
				}
				return false;
			case ' ':
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
				return true;
			}
		}

		private static bool IsNativeText(char ch)
		{
			switch (ch)
			{
			default:
				if (ch >= 'a')
				{
					return ch <= 'z';
				}
				return false;
			case ' ':
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
				return true;
			}
		}

		private static bool IsNativeX12(char ch)
		{
			if (!IsX12TermSep(ch))
			{
				switch (ch)
				{
				default:
					if (ch >= 'A')
					{
						return ch <= 'Z';
					}
					return false;
				case ' ':
				case '0':
				case '1':
				case '2':
				case '3':
				case '4':
				case '5':
				case '6':
				case '7':
				case '8':
				case '9':
					break;
				}
			}
			return true;
		}

		private static bool IsX12TermSep(char ch)
		{
			if (ch != '\r' && ch != '*')
			{
				return ch == '>';
			}
			return true;
		}

		private static bool IsNativeEDIFACT(char ch)
		{
			if (ch >= ' ')
			{
				return ch <= '^';
			}
			return false;
		}

		private static bool IsSpecialB256(char ch)
		{
			return false;
		}

		public static int DetermineConsecutiveDigitCount(string msg, int startpos)
		{
			int num = 0;
			int length = msg.Length;
			int num2 = startpos;
			if (num2 < length)
			{
				char ch = msg[num2];
				while (IsDigit(ch) && num2 < length)
				{
					num++;
					num2++;
					if (num2 < length)
					{
						ch = msg[num2];
					}
				}
			}
			return num;
		}

		internal static void IllegalCharacter(char c)
		{
			string text = Convert.ToInt32(c).ToString("X");
			text = "0000".Substring(0, 4 - text.Length) + text;
			throw new ArgumentException("Illegal character: " + c + " (0x" + text + ")");
		}
	}
