			new SymbolInfo(rectangular: false, 696, 272, 22, 22, 16, 174, 68),
			new SymbolInfo(rectangular: false, 816, 336, 24, 24, 16, 136, 56),
			new SymbolInfo(rectangular: false, 1050, 408, 18, 18, 36, 175, 68),
			new SymbolInfo(rectangular: false, 1304, 496, 20, 20, 36, 163, 62),
			new DataMatrixSymbolInfo144()
		};

		private static SymbolInfo[] symbols = ProdSymbols;

		public int matrixWidth;

		public int matrixHeight;

		private int dataRegions;

		private int rsBlockData;

		private int rsBlockError;

		public bool Rectangular { get; set; }

		public int DataCapacity { get; set; }

		public int ErrorCodewords { get; set; }

		public virtual int HorzDataRegions => dataRegions switch
		{
			1 => 1, 
			2 => 2, 
			4 => 2, 
			16 => 4, 
			36 => 6, 
			_ => throw new ArgumentException("Cannot handle this number of data regions"), 
		};

		public virtual int VertDataRegions => dataRegions switch
		{
			1 => 1, 
			2 => 1, 
			4 => 2, 
			16 => 4, 
			36 => 6, 
			_ => throw new ArgumentException("Cannot handle this number of data regions"), 
		};

		public virtual int SymbolDataWidth => HorzDataRegions * matrixWidth;

		public virtual int SymbolDataHeight => VertDataRegions * matrixHeight;

		public virtual int SymbolWidth => SymbolDataWidth + HorzDataRegions * 2;

		public virtual int SymbolHeight => SymbolDataHeight + VertDataRegions * 2;

		public virtual int CodewordCount => DataCapacity + ErrorCodewords;

		public virtual int InterleavedBlockCount => DataCapacity / rsBlockData;

		public static void OverrideSymbolSet(SymbolInfo[] s)
		{
			symbols = s;
		}

		public SymbolInfo(bool rectangular, int dataCapacity, int errorCodewords, int matrixWidth, int matrixHeight, int dataRegions)
			: this(rectangular, dataCapacity, errorCodewords, matrixWidth, matrixHeight, dataRegions, dataCapacity, errorCodewords)
		{
		}

		public SymbolInfo(bool rectangular, int dataCapacity, int errorCodewords, int matrixWidth, int matrixHeight, int dataRegions, int rsBlockData, int rsBlockError)
		{
			Rectangular = rectangular;
			DataCapacity = dataCapacity;
			ErrorCodewords = errorCodewords;
			this.matrixWidth = matrixWidth;
			this.matrixHeight = matrixHeight;
			this.dataRegions = dataRegions;
			this.rsBlockData = rsBlockData;
			this.rsBlockError = rsBlockError;
		}

		public static SymbolInfo Lookup(int dataCodewords)
		{
			return Lookup(dataCodewords, SymbolShapeHint.ForceNone, fail: true);
		}

		public static SymbolInfo Lookup(int dataCodewords, SymbolShapeHint shape)
		{
			return Lookup(dataCodewords, shape, fail: true);
		}

		public static SymbolInfo Lookup(int dataCodewords, bool allowRectangular, bool fail)
		{
			SymbolShapeHint shape = ((!allowRectangular) ? SymbolShapeHint.ForceSquare : SymbolShapeHint.ForceNone);
			return Lookup(dataCodewords, shape, fail);
		}

		public static SymbolInfo Lookup(int dataCodewords, SymbolShapeHint shape, bool fail)
		{
			return Lookup(dataCodewords, shape, null, null, fail);
		}

		public static SymbolInfo Lookup(int dataCodewords, SymbolShapeHint shape, Dimension minSize, Dimension maxSize, bool fail)
		{
			int i = 0;
			for (int num = symbols.Length; i < num; i++)
			{
				SymbolInfo symbolInfo = symbols[i];
				if ((shape != SymbolShapeHint.ForceSquare || !symbolInfo.Rectangular) && (shape != SymbolShapeHint.ForceRectangle || symbolInfo.Rectangular) && (minSize == null || (symbolInfo.SymbolWidth >= minSize.Width && symbolInfo.SymbolHeight >= minSize.Height)) && (maxSize == null || (symbolInfo.SymbolWidth <= maxSize.Width && symbolInfo.SymbolHeight <= maxSize.Height)) && dataCodewords <= symbolInfo.DataCapacity)
				{
					return symbolInfo;
				}
			}
			if (fail)
			{
				throw new ArgumentException("Can't find a symbol arrangement that matches the message. Data codewords: " + dataCodewords);
			}
			return null;
		}

		public virtual int GetDataLengthForInterleavedBlock(int index)
		{
			return rsBlockData;
		}

		public virtual int GetErrorLengthForInterleavedBlock(int index)
		{
			return rsBlockError;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(Rectangular ? "Rectangular Symbol:" : "Square Symbol:");
			stringBuilder.Append(" data region ").Append(matrixWidth).Append("x")
				.Append(matrixHeight);
			stringBuilder.Append(", symbol size ").Append(SymbolWidth).Append("x")
				.Append(SymbolHeight);
			stringBuilder.Append(", symbol data size ").Append(SymbolDataWidth).Append("x")
				.Append(SymbolDataHeight);
			stringBuilder.Append(", codewords ").Append(DataCapacity).Append("+")
				.Append(ErrorCodewords);
			return stringBuilder.ToString();
		}
	}
	public enum SymbolShapeHint
	{
		ForceNone,
		ForceSquare,
		ForceRectangle
	}
	internal sealed class TextEncoder : C40Encoder
	{
		public override int EncodingMode => 2;

		internal override int EncodeChar(char c, StringBuilder sb)
		{
			switch (c)
			{
			case ' ':
				sb.Append('\u0003');
				return 1;
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
				sb.Append((char)(c - 48 + 4));
				return 1;
			default:
				if (c >= 'a' && c <= 'z')
				{
					sb.Append((char)(c - 97 + 14));
					return 1;
				}
				if (c >= '\0' && c <= '\u001f')
				{
					sb.Append('\0');
					sb.Append(c);
					return 2;
				}
				if (c >= '!' && c <= '/')
				{
					sb.Append('\u0001');
					sb.Append((char)(c - 33));
					return 2;
				}
				if (c >= ':' && c <= '@')
				{
					sb.Append('\u0001');
					sb.Append((char)(c - 58 + 15));
					return 2;
				}
				if (c >= '[' && c <= '_')
				{
					sb.Append('\u0001');
					sb.Append((char)(c - 91 + 22));
					return 2;
				}
				switch (c)
				{
				case '`':
					sb.Append('\u0002');
					sb.Append((char)(c - 96));
					return 2;
				case 'A':
				case 'B':
				case 'C':
				case 'D':
				case 'E':
				case 'F':
				case 'G':
				case 'H':
				case 'I':
				case 'J':
				case 'K':
				case 'L':
				case 'M':
				case 'N':
				case 'O':
				case 'P':
				case 'Q':
				case 'R':
				case 'S':
				case 'T':
				case 'U':
				case 'V':
				case 'W':
				case 'X':
				case 'Y':
				case 'Z':
					sb.Append('\u0002');
					sb.Append((char)(c - 65 + 1));
					return 2;
				default:
					if (c >= '{' && c <= '\u007f')
					{
						sb.Append('\u0002');
						sb.Append((char)(c - 123 + 27));
						return 2;
					}
					if (c >= '\u0080')
					{
						sb.Append('\u0001');
						sb.Append('\u001e');
						return 2 + EncodeChar((char)(c - 128), sb);
					}
					HighLevelEncoder.IllegalCharacter(c);
					return -1;
				}
			}
		}
	}
	internal sealed class X12Encoder : C40Encoder
	{
		public override int EncodingMode => 3;

		public override void Encode(EncoderContext context)
		{
			StringBuilder stringBuilder = new StringBuilder();
			while (context.HasMoreCharacters())
			{
				char currentChar = context.CurrentChar;
				context.pos++;
				EncodeChar(currentChar, stringBuilder);
				if (stringBuilder.Length % 3 == 0)
				{
					C40Encoder.WriteNextTriplet(context, stringBuilder);
					int num = HighLevelEncoder.LookAheadTest(context.Message, context.pos, EncodingMode);
					if (num != EncodingMode)
					{
						context.SignalEncoderChange(num);
						break;
					}
				}
			}
			HandleEOD(context, stringBuilder);
		}

		internal override int EncodeChar(char c, StringBuilder sb)
		{
			switch (c)
			{
			case '\r':
				sb.Append('\0');
				break;
			case '*':
				sb.Append('\u0001');
				break;
			case '>':
				sb.Append('\u0002');
				break;
			case ' ':
				sb.Append('\u0003');
				break;
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
				sb.Append((char)(c - 48 + 4));
				break;
			default:
				if (c >= 'A' && c <= 'Z')
				{
					sb.Append((char)(c - 65 + 14));
				}
				else
				{
					HighLevelEncoder.IllegalCharacter(c);
				}
				break;
			}
			return 1;
		}

		internal override void HandleEOD(EncoderContext context, StringBuilder buffer)
		{
			context.UpdateSymbolInfo();
			int num = context.SymbolInfo.DataCapacity - context.CodewordCount;
			switch (buffer.Length)
			{
			case 2:
				context.WriteCodeword(HighLevelEncoder.X12_UNLATCH);
				context.pos -= 2;
				context.SignalEncoderChange(0);
				break;
			case 1:
				context.pos--;
				if (num > 1)
				{
					context.WriteCodeword(HighLevelEncoder.X12_UNLATCH);
				}
				context.SignalEncoderChange(0);
				break;
			}
		}
	}
}
namespace MessagingToolkit.Barcode.DataMatrix.detector
{
	public sealed class Detector
	{
		private sealed class ResultPointsAndTransitions
		{
			private readonly ResultPoint from;

			private readonly ResultPoint to;

			private readonly int transitions;

			public ResultPointsAndTransitions(ResultPoint from, ResultPoint to, int transitions)
			{
				this.from = from;
				this.to = to;
				this.transitions = transitions;
			}

			internal ResultPoint GetFrom()
			{
				return from;
			}

			internal ResultPoint GetTo()
			{
				return to;
			}

			public int GetTransitions()
			{
				return transitions;
			}

			public override string ToString()
			{
				return string.Concat(from, "/", to, "/", transitions);
			}
		}

		[Serializable]
		private class ResultPointsAndTransitionsComparator : Comparator
		{
			public virtual int Compare(object o1, object o2)
			{
				return ((ResultPointsAndTransitions)o1).GetTransitions() - ((ResultPointsAndTransitions)o2).GetTransitions();
			}
		}

		private readonly BitMatrix image;

		private readonly WhiteRectangleDetector rectangleDetector;

		public Detector(BitMatrix image)
		{
			this.image = image;
			rectangleDetector = new WhiteRectangleDetector(image);
		}

		public DetectorResult Detect()
		{
			ResultPoint[] array = rectangleDetector.Detect();
			ResultPoint resultPoint = array[0];
			ResultPoint resultPoint2 = array[1];
			ResultPoint resultPoint3 = array[2];
			ResultPoint resultPoint4 = array[3];
			List<ResultPointsAndTransitions> obj = new List<ResultPointsAndTransitions>(4)
			{
				TransitionsBetween(resultPoint, resultPoint2),
				TransitionsBetween(resultPoint, resultPoint3),
				TransitionsBetween(resultPoint2, resultPoint4),
				TransitionsBetween(resultPoint3, resultPoint4)
			};
			Collections.InsertionSort(obj, new ResultPointsAndTransitionsComparator());
			ResultPointsAndTransitions resultPointsAndTransitions = obj[0];
			ResultPointsAndTransitions resultPointsAndTransitions2 = obj[1];
			Dictionary<ResultPoint, int> dictionary = new Dictionary<ResultPoint, int>();
			Increment(dictionary, resultPointsAndTransitions.GetFrom());
			Increment(dictionary, resultPointsAndTransitions.GetTo());
			Increment(dictionary, resultPointsAndTransitions2.GetFrom());
			Increment(dictionary, resultPointsAndTransitions2.GetTo());
			ResultPoint resultPoint5 = null;
			ResultPoint resultPoint6 = null;
			ResultPoint resultPoint7 = null;
			IEnumerator<ResultPoint> enumerator = dictionary.Keys.GetEnumerator();
			while (enumerator.MoveNext())
			{
				ResultPoint current = enumerator.Current;
				if (dictionary[current] == 2)
				{
					resultPoint6 = current;
				}
				else if (resultPoint5 == null)
				{
					resultPoint5 = current;
				}
				else
				{
					resultPoint7 = current;
				}
			}
			if (resultPoint5 == null || resultPoint6 == null || resultPoint7 == null)
			{
				throw NotFoundException.Instance;
			}
			ResultPoint[] obj2 = new ResultPoint[3] { resultPoint5, resultPoint6, resultPoint7 };
			ResultPoint.OrderBestPatterns(obj2);
			ResultPoint resultPoint8 = obj2[0];
			resultPoint6 = obj2[1];
			ResultPoint resultPoint9 = obj2[2];
			ResultPoint resultPoint10 = ((!dictionary.ContainsKey(resultPoint)) ? resultPoint : ((!dictionary.ContainsKey(resultPoint2)) ? resultPoint2 : (dictionary.ContainsKey(resultPoint3) ? resultPoint4 : resultPoint3)));
			int num = TransitionsBetween(resultPoint9, resultPoint10).GetTransitions();
			int num2 = TransitionsBetween(resultPoint8, resultPoint10).GetTransitions();
			if ((num & 1) == 1)
			{
				num++;
			}
			num += 2;
			if ((num2 & 1) == 1)
			{
				num2++;
			}
			num2 += 2;
			ResultPoint resultPoint11;
			BitMatrix bits;
			if (4 * num >= 7 * num2 || 4 * num2 >= 7 * num)
			{
				resultPoint11 = CorrectTopRightRectangular(resultPoint6, resultPoint8, resultPoint9, resultPoint10, num, num2);
				if (resultPoint11 == null)
				{
					resultPoint11 = resultPoint10;
				}
				num = TransitionsBetween(resultPoint9, resultPoint11).GetTransitions();
				num2 = TransitionsBetween(resultPoint8, resultPoint11).GetTransitions();
				if ((num & 1) == 1)
				{
					num++;
				}
				if ((num2 & 1) == 1)
				{
					num2++;
				}
				bits = SampleGrid(image, resultPoint9, resultPoint6, resultPoint8, resultPoint11, num, num2);
			}
			else
			{
				int dimension = Math.Min(num2, num);
				resultPoint11 = CorrectTopRight(resultPoint6, resultPoint8, resultPoint9, resultPoint10, dimension);
				if (resultPoint11 == null)
				{
					resultPoint11 = resultPoint10;
				}
				int num3 = Math.Max(TransitionsBetween(resultPoint9, resultPoint11).GetTransitions(), TransitionsBetween(resultPoint8, resultPoint11).GetTransitions());
				num3++;
				if ((num3 & 1) == 1)
				{
					num3++;
				}
				bits = SampleGrid(image, resultPoint9, resultPoint6, resultPoint8, resultPoint11, num3, num3);
			}
			return new DetectorResult(bits, new ResultPoint[4] { resultPoint9, resultPoint6, resultPoint8, resultPoint11 });
		}

		private ResultPoint CorrectTopRightRectangular(ResultPoint bottomLeft, ResultPoint bottomRight, ResultPoint topLeft, ResultPoint topRight, int dimensionTop, int dimensionRight)
		{
			float num = (float)Distance(bottomLeft, bottomRight) / (float)dimensionTop;
			int num2 = Distance(topLeft, topRight);
			if (num2 == 0)
			{
				return null;
			}
			float num3 = (topRight.X - topLeft.X) / (float)num2;
			float num4 = (topRight.Y - topLeft.Y) / (float)num2;
			ResultPoint resultPoint = new ResultPoint(topRight.X + num * num3, topRight.Y + num * num4);
			num = (float)Distance(bottomLeft, topLeft) / (float)dimensionRight;
			num2 = Distance(bottomRight, topRight);
			if (num2 == 0)
			{
				return null;
			}
			num3 = (topRight.X - bottomRight.X) / (float)num2;
			num4 = (topRight.Y - bottomRight.Y) / (float)num2;
			ResultPoint resultPoint2 = new ResultPoint(topRight.X + num * num3, topRight.Y + num * num4);
			if (!IsValid(resultPoint))
			{
				if (IsValid(resultPoint2))
				{
					return resultPoint2;
				}
				return null;
			}
			if (!IsValid(resultPoint2))
			{
				return resultPoint;
			}
			int num5 = Math.Abs(dimensionTop - TransitionsBetween(topLeft, resultPoint).GetTransitions()) + Math.Abs(dimensionRight - TransitionsBetween(bottomRight, resultPoint).GetTransitions());
			int num6 = Math.Abs(dimensionTop - TransitionsBetween(topLeft, resultPoint2).GetTransitions()) + Math.Abs(dimensionRight - TransitionsBetween(bottomRight, resultPoint2).GetTransitions());
			if (num5 <= num6)
			{
				return resultPoint;
			}
			return resultPoint2;
		}

		private ResultPoint CorrectTopRight(ResultPoint bottomLeft, ResultPoint bottomRight, ResultPoint topLeft, ResultPoint topRight, int dimension)
		{
			float num = (float)Distance(bottomLeft, bottomRight) / (float)dimension;
			int num2 = Distance(topLeft, topRight);
			if (num2 == 0)
			{
				return null;
			}
			float num3 = (topRight.X - topLeft.X) / (float)num2;
			float num4 = (topRight.Y - topLeft.Y) / (float)num2;
			ResultPoint resultPoint = new ResultPoint(topRight.X + num * num3, topRight.Y + num * num4);
			num = (float)Distance(bottomLeft, bottomRight) / (float)dimension;
			num2 = Distance(bottomRight, topRight);
			if (num2 == 0)
			{
				return null;
			}
			num3 = (topRight.X - bottomRight.X) / (float)num2;
			num4 = (topRight.Y - bottomRight.Y) / (float)num2;
			ResultPoint resultPoint2 = new ResultPoint(topRight.X + num * num3, topRight.Y + num * num4);
			if (!IsValid(resultPoint))
			{
				if (IsValid(resultPoint2))
				{
					return resultPoint2;
				}
				return null;
			}
			if (!IsValid(resultPoint2))
			{
				return resultPoint;
			}
			int num5 = Math.Abs(TransitionsBetween(topLeft, resultPoint).GetTransitions() - TransitionsBetween(bottomRight, resultPoint).GetTransitions());
			int num6 = Math.Abs(TransitionsBetween(topLeft, resultPoint2).GetTransitions() - TransitionsBetween(bottomRight, resultPoint2).GetTransitions());
			if (num5 > num6)
			{
				return resultPoint2;
			}
			return resultPoint;
		}

		private bool IsValid(ResultPoint p)
		{
			if (p.X >= 0f && p.X < (float)image.Width && p.Y > 0f)
			{
				return p.Y < (float)image.Height;
			}
			return false;
		}

		private static int Distance(ResultPoint a, ResultPoint b)
		{
			return MathUtils.Round(ResultPoint.Distance(a, b));
		}

		private static void Increment(Dictionary<ResultPoint, int> table, ResultPoint key)
		{
			if (table.ContainsKey(key))
			{
				table[key]++;
			}
			else
			{
				table[key] = 1;
			}
		}

		private static BitMatrix SampleGrid(BitMatrix image_0, ResultPoint topLeft, ResultPoint bottomLeft, ResultPoint bottomRight, ResultPoint topRight, int dimensionX, int dimensionY)
		{
			return GridSampler.GetInstance().SampleGrid(image_0, dimensionX, dimensionY, 0.5f, 0.5f, (float)dimensionX - 0.5f, 0.5f, (float)dimensionX - 0.5f, (float)dimensionY - 0.5f, 0.5f, (float)dimensionY - 0.5f, topLeft.X, topLeft.Y, topRight.X, topRight.Y, bottomRight.X, bottomRight.Y, bottomLeft.X, bottomLeft.Y);
		}

		private ResultPointsAndTransitions TransitionsBetween(ResultPoint from, ResultPoint to)
		{
			int num = (int)from.X;
			int num2 = (int)from.Y;
			int num3 = (int)to.X;
			int num4 = (int)to.Y;
			bool flag = Math.Abs(num4 - num2) > Math.Abs(num3 - num);
			if (flag)
			{
				int num5 = num;
				num = num2;
				num2 = num5;
				int num6 = num3;
				num3 = num4;
				num4 = num6;
			}
			int num7 = Math.Abs(num3 - num);
			int num8 = Math.Abs(num4 - num2);
			int num9 = -num7 >> 1;
			int num10 = ((num2 < num4) ? 1 : (-1));
			int num11 = ((num < num3) ? 1 : (-1));
			int num12 = 0;
			bool flag2 = image.Get(flag ? num2 : num, flag ? num : num2);
			int i = num;
			int num13 = num2;
			for (; i != num3; i += num11)
			{
				bool flag3 = image.Get(flag ? num13 : i, flag ? i : num13);
				if (flag3 != flag2)
				{
					num12++;
					flag2 = flag3;
				}
				num9 += num8;
				if (num9 > 0)
				{
					if (num13 == num4)
					{
						break;
					}
					num13 += num10;
					num9 -= num7;
				}
			}
			return new ResultPointsAndTransitions(from, to, num12);
		}
	}
