	public sealed class Decoder
	{
		private readonly ReedSolomonDecoder rsDecoder;

		public Decoder()
		{
			rsDecoder = new ReedSolomonDecoder(GenericGF.DataMatrixField256);
		}

		public DecoderResult Decode(bool[][] image)
		{
			int num = image.Length;
			BitMatrix bitMatrix = new BitMatrix(num);
			for (int i = 0; i < num; i++)
			{
				for (int j = 0; j < num; j++)
				{
					if (image[i][j])
					{
						bitMatrix.Set(j, i);
					}
				}
			}
			return Decode(bitMatrix);
		}

		public DecoderResult Decode(BitMatrix bits)
		{
			BitMatrixParser bitMatrixParser = new BitMatrixParser(bits);
			DataBlock[] array = DataBlock.GetDataBlocks(version: bitMatrixParser.GetVersion(), rawCodewords: bitMatrixParser.ReadCodewords());
			int num = array.Length;
			int num2 = 0;
			for (int i = 0; i < num; i++)
			{
				num2 += array[i].GetNumDataCodewords();
			}
			byte[] array2 = new byte[num2];
			for (int j = 0; j < num; j++)
			{
				DataBlock obj = array[j];
				byte[] codewords = obj.GetCodewords();
				int numDataCodewords = obj.GetNumDataCodewords();
				CorrectErrors(codewords, numDataCodewords);
				for (int k = 0; k < numDataCodewords; k++)
				{
					array2[k * num + j] = codewords[k];
				}
			}
			return DecodedBitStreamParser.Decode(array2);
		}

		private void CorrectErrors(byte[] codewordBytes, int numDataCodewords)
		{
			int num = codewordBytes.Length;
			int[] array = new int[num];
			for (int i = 0; i < num; i++)
			{
				array[i] = codewordBytes[i] & 0xFF;
			}
			int twoS = codewordBytes.Length - numDataCodewords;
			try
			{
				rsDecoder.Decode(array, twoS);
			}
			catch (ReedSolomonException)
			{
				throw ChecksumException.Instance;
			}
			for (int j = 0; j < numDataCodewords; j++)
			{
				codewordBytes[j] = (byte)array[j];
			}
		}
	}
