		public static readonly BaseColor GRAY = new BaseColor(128, 128, 128);

		public static readonly BaseColor DARK_GRAY = new BaseColor(64, 64, 64);

		public static readonly BaseColor BLACK = new BaseColor(0, 0, 0);

		public static readonly BaseColor RED = new BaseColor(255, 0, 0);

		public static readonly BaseColor PINK = new BaseColor(255, 175, 175);

		public static readonly BaseColor ORANGE = new BaseColor(255, 200, 0);

		public static readonly BaseColor YELLOW = new BaseColor(255, 255, 0);

		public static readonly BaseColor GREEN = new BaseColor(0, 255, 0);

		public static readonly BaseColor MAGENTA = new BaseColor(255, 0, 255);

		public static readonly BaseColor CYAN = new BaseColor(0, 255, 255);

		public static readonly BaseColor BLUE = new BaseColor(0, 0, 255);

		private const double FACTOR = 0.7;

		private Color color;

		public int R => color.R;

		public int G => color.G;

		public int B => color.B;

		public BaseColor(int red, int green, int blue)
		{
			color = Color.FromArgb(red, green, blue);
		}

		public BaseColor(int red, int green, int blue, int alpha)
		{
			color = Color.FromArgb(alpha, red, green, blue);
		}

		public BaseColor(float red, float green, float blue)
		{
			color = Color.FromArgb((int)((double)(red * 255f) + 0.5), (int)((double)(green * 255f) + 0.5), (int)((double)(blue * 255f) + 0.5));
		}

		public BaseColor(float red, float green, float blue, float alpha)
		{
			color = Color.FromArgb((int)((double)(alpha * 255f) + 0.5), (int)((double)(red * 255f) + 0.5), (int)((double)(green * 255f) + 0.5), (int)((double)(blue * 255f) + 0.5));
		}

		public BaseColor(int argb)
		{
			color = Color.FromArgb(argb);
		}

		public BaseColor(Color color)
		{
			this.color = color;
		}

		public BaseColor Brighter()
		{
			int num = color.R;
			int num2 = color.G;
			int num3 = color.B;
			int num4 = 3;
			if (num == 0 && num2 == 0 && num3 == 0)
			{
				return new BaseColor(num4, num4, num4);
			}
			if (num > 0 && num < num4)
			{
				num = num4;
			}
			if (num2 > 0 && num2 < num4)
			{
				num2 = num4;
			}
			if (num3 > 0 && num3 < num4)
			{
				num3 = num4;
			}
			return new BaseColor(Math.Min((int)((double)num / 0.7), 255), Math.Min((int)((double)num2 / 0.7), 255), Math.Min((int)((double)num3 / 0.7), 255));
		}

		public BaseColor Darker()
		{
			return new BaseColor(Math.Max((int)((double)(int)color.R * 0.7), 0), Math.Max((int)((double)(int)color.G * 0.7), 0), Math.Max((int)((double)(int)color.B * 0.7), 0));
		}

		public override bool Equals(object obj)
		{
			if (!(obj is BaseColor))
			{
				return false;
			}
			return color.Equals((object?)((BaseColor)obj).color);
		}

		public override int GetHashCode()
		{
			return color.GetHashCode();
		}

		public int ToArgb()
		{
			return color.ToArgb();
		}

		public override string ToString()
		{
			return color.ToString();
		}
	}
	public sealed class BitArray
	{
		private int[] bits;

		private int size;

		private static readonly int[] Lookup = new int[37]
		{
			32, 0, 1, 26, 2, 23, 27, 0, 3, 16,
			24, 30, 28, 11, 0, 13, 4, 7, 17, 0,
			25, 22, 31, 15, 29, 10, 12, 6, 0, 21,
			14, 9, 5, 20, 8, 19, 18
		};

		public int Size => size;

		public BitArray()
		{
			size = 0;
			bits = new int[1];
		}

		public BitArray(int size)
		{
			this.size = size;
			bits = MakeArray(size);
		}

		public int GetSize()
		{
			return size;
		}

		public int GetSizeInBytes()
		{
			return size + 7 >> 3;
		}

		private void EnsureCapacity(int size)
		{
			if (size > bits.Length << 5)
			{
				int[] destinationArray = MakeArray(size);
				Array.Copy(bits, 0, destinationArray, 0, bits.Length);
				bits = destinationArray;
			}
		}

		public bool Get(int i)
		{
			return (bits[i >> 5] & (1 << i)) != 0;
		}

		public bool GetValue(int i)
		{
			return Get(i);
		}

		public void Set(int i)
		{
			bits[i >> 5] |= 1 << i;
		}

		public void Flip(int i)
		{
			bits[i >> 5] ^= 1 << i;
		}

		public int GetNextSet(int from)
		{
			if (from >= size)
			{
				return size;
			}
			int num = from >> 5;
			int num2 = bits[num];
			for (num2 &= ~((1 << from) - 1); num2 == 0; num2 = bits[num])
			{
				if (++num == bits.Length)
				{
					return size;
				}
			}
			int num3 = (num << 5) + NumberOfTrailingZeros(num2);
			if (num3 <= size)
			{
				return num3;
			}
			return size;
		}

		public int GetNextUnset(int from)
		{
			if (from >= size)
			{
				return size;
			}
			int num = from >> 5;
			int num2 = ~bits[num];
			for (num2 &= ~((1 << from) - 1); num2 == 0; num2 = ~bits[num])
			{
				if (++num == bits.Length)
				{
					return size;
				}
			}
			int num3 = (num << 5) + NumberOfTrailingZeros(num2);
			if (num3 <= size)
			{
				return num3;
			}
			return size;
		}

		private static int NumberOfTrailingZeros(int num)
		{
			int num2 = (-num & num) % 37;
			if (num2 < 0)
			{
				num2 *= -1;
			}
			return Lookup[num2];
		}

		public void SetBulk(int i, int newBits)
		{
			bits[i >> 5] = newBits;
		}

		public void SetRange(int start, int end)
		{
			if (end < start)
			{
				throw new ArgumentException();
			}
			if (end == start)
			{
				return;
			}
			end--;
			int num = start >> 5;
			int num2 = end >> 5;
			for (int i = num; i <= num2; i++)
			{
				int num3 = ((i <= num) ? (start & 0x1F) : 0);
				int num4 = ((i < num2) ? 31 : (end & 0x1F));
				int num5;
				if (num3 == 0 && num4 == 31)
				{
					num5 = -1;
				}
				else
				{
					num5 = 0;
					for (int j = num3; j <= num4; j++)
					{
						num5 |= 1 << j;
					}
				}
				bits[i] |= num5;
			}
		}

		public void Clear()
		{
			int num = bits.Length;
			for (int i = 0; i < num; i++)
			{
				bits[i] = 0;
			}
		}

		public bool IsRange(int start, int end, bool val)
		{
			if (end < start)
			{
				throw new ArgumentException();
			}
			if (end == start)
			{
				return true;
			}
			end--;
			int num = start >> 5;
			int num2 = end >> 5;
			for (int i = num; i <= num2; i++)
			{
				int num3 = ((i <= num) ? (start & 0x1F) : 0);
				int num4 = ((i < num2) ? 31 : (end & 0x1F));
				int num5;
				if (num3 == 0 && num4 == 31)
				{
					num5 = -1;
				}
				else
				{
					num5 = 0;
					for (int j = num3; j <= num4; j++)
					{
						num5 |= 1 << j;
					}
				}
				if ((bits[i] & num5) != (val ? num5 : 0))
				{
					return false;
				}
			}
			return true;
		}

		public void AppendBit(bool bit)
		{
			EnsureCapacity(size + 1);
			if (bit)
			{
				bits[size >> 5] |= 1 << size;
			}
			size++;
		}

		public void AppendBits(int val, int numBits)
		{
			if (numBits < 0 || numBits > 32)
			{
				throw new ArgumentException("Num bits must be between 0 and 32");
			}
			EnsureCapacity(size + numBits);
			for (int num = numBits; num > 0; num--)
			{
				AppendBit(((val >> num - 1) & 1) == 1);
			}
		}

		public void AppendBitArray(BitArray other)
		{
			int num = other.size;
			EnsureCapacity(size + num);
			for (int i = 0; i < num; i++)
			{
				AppendBit(other.Get(i));
			}
		}

		public void Xor(BitArray other)
		{
			if (bits.Length != other.bits.Length)
			{
				throw new ArgumentException("Sizes don't match");
			}
			for (int i = 0; i < bits.Length; i++)
			{
				bits[i] ^= other.bits[i];
			}
		}

		public void ToBytes(int bitOffset, byte[] array, int offset, int numBytes)
		{
			for (int i = 0; i < numBytes; i++)
			{
				int num = 0;
				for (int j = 0; j < 8; j++)
				{
					if (Get(bitOffset))
					{
						num |= 1 << 7 - j;
					}
					bitOffset++;
				}
				array[offset + i] = (byte)num;
			}
		}

		public int[] GetBitArray()
		{
			return bits;
		}

		public void Reverse()
		{
			int[] array = new int[bits.Length];
			int num = size;
			for (int i = 0; i < num; i++)
			{
				if (Get(num - i - 1))
				{
					array[i >> 5] |= 1 << i;
				}
			}
			bits = array;
		}

		private static int[] MakeArray(int size)
		{
			return new int[size + 31 >> 5];
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(size);
			for (int i = 0; i < size; i++)
			{
				if ((i & 7) == 0)
				{
					stringBuilder.Append(' ');
				}
				stringBuilder.Append(Get(i) ? 'X' : '.');
			}
			return stringBuilder.ToString();
		}
	}
	public sealed class BitMatrix
	{
		private readonly int width;

		private readonly int height;

		private readonly int rowSize;

		private readonly int[] bits;

		public int Width => width;

		public int Height => height;

		public int LeftPadding { get; set; }

		public int TopPadding { get; set; }

		public int ActualWidth { get; set; }

		public int ActualHeight { get; set; }

		public BitMatrix(int dimension)
			: this(dimension, dimension)
		{
		}

		public BitMatrix(int width, int height)
		{
			if (width < 1 || height < 1)
			{
				throw new ArgumentException("Both dimensions must be greater than 0");
			}
			this.width = width;
			this.height = height;
			rowSize = width + 31 >> 5;
			bits = new int[rowSize * height];
			TopPadding = 0;
			LeftPadding = 0;
			ActualHeight = 0;
			ActualHeight = 0;
		}

		public bool Get(int x, int y)
		{
			int num = y * rowSize + (x >> 5);
			if (num >= bits.Length)
			{
				return false;
			}
			return ((bits[num] >>> x) & 1) != 0;
		}

		public bool GetValue(int x, int y)
		{
			return Get(x, y);
		}

		public void Set(int x, int y)
		{
			int num = y * rowSize + (x >> 5);
			bits[num] |= 1 << x;
		}

		public void SetValue(int x, int y)
		{
			Set(x, y);
		}

		public void Flip(int x, int y)
		{
			int num = y * rowSize + (x >> 5);
			bits[num] ^= 1 << x;
		}

		public void Clear()
		{
			int num = bits.Length;
			for (int i = 0; i < num; i++)
			{
				bits[i] = 0;
			}
		}

		public void SetRegion(int left, int top, int width_0, int height_1)
		{
			if (top < 0 || left < 0)
			{
				throw new ArgumentException("Left and top must be nonnegative");
			}
			if (height_1 < 1 || width_0 < 1)
			{
				throw new ArgumentException("Height and width must be at least 1");
			}
			int num = left + width_0;
			int num2 = top + height_1;
			if (num2 > height || num > width)
			{
				throw new ArgumentException("The region must fit inside the matrix");
			}
			for (int i = top; i < num2; i++)
			{
				int num3 = i * rowSize;
				for (int j = left; j < num; j++)
				{
					bits[num3 + (j >> 5)] |= 1 << j;
				}
			}
		}

		public BitArray GetRow(int y, BitArray row)
		{
			if (row == null || row.GetSize() < width)
			{
				row = new BitArray(width);
			}
			int num = y * rowSize;
			for (int i = 0; i < rowSize; i++)
			{
				row.SetBulk(i << 5, bits[num + i]);
			}
			return row;
		}

		public void SetRow(int y, BitArray row)
		{
			Array.Copy(row.GetBitArray(), 0, bits, y * rowSize, rowSize);
		}

		public int[] GetEnclosingRectangle()
		{
			int num = width;
			int num2 = height;
			int num3 = -1;
			int num4 = -1;
			for (int i = 0; i < height; i++)
			{
				for (int j = 0; j < rowSize; j++)
				{
					int num5 = bits[i * rowSize + j];
					if (num5 == 0)
					{
						continue;
					}
					if (i < num2)
					{
						num2 = i;
					}
					if (i > num4)
					{
						num4 = i;
					}
					if (j * 32 < num)
					{
						int k;
						for (k = 0; num5 << 31 - k == 0; k++)
						{
						}
						if (j * 32 + k < num)
						{
							num = j * 32 + k;
						}
					}
					if (j * 32 + 31 > num3)
					{
						int num6 = 31;
						while (num5 >>> num6 == 0)
						{
							num6--;
						}
						if (j * 32 + num6 > num3)
						{
							num3 = j * 32 + num6;
						}
					}
				}
			}
			int num7 = num3 - num;
			int num8 = num4 - num2;
			if (num7 < 0 || num8 < 0)
			{
				return null;
			}
			return new int[4] { num, num2, num7, num8 };
		}

		public int[] GetTopLeftOnBit()
		{
			int i;
			for (i = 0; i < bits.Length && bits[i] == 0; i++)
			{
			}
			if (i == bits.Length)
			{
				return null;
			}
			int num = i / rowSize;
			int num2 = i % rowSize << 5;
			int num3 = bits[i];
			int j;
			for (j = 0; num3 << 31 - j == 0; j++)
			{
			}
			num2 += j;
			return new int[2] { num2, num };
		}

		public int[] GetBottomRightOnBit()
		{
			int num = bits.Length - 1;
			while (num >= 0 && bits[num] == 0)
			{
				num--;
			}
			if (num < 0)
			{
				return null;
			}
			int num2 = num / rowSize;
			int num3 = num % rowSize << 5;
			int num4 = bits[num];
			int num5 = 31;
			while (num4 >>> num5 == 0)
			{
				num5--;
			}
			num3 += num5;
			return new int[2] { num3, num2 };
		}

		public int GetWidth()
		{
			return width;
		}

		public int GetHeight()
		{
			return height;
		}

		public override bool Equals(object o)
		{
			if (!(o is BitMatrix))
			{
				return false;
			}
			BitMatrix bitMatrix = (BitMatrix)o;
			if (width != bitMatrix.width || height != bitMatrix.height || rowSize != bitMatrix.rowSize || bits.Length != bitMatrix.bits.Length)
			{
				return false;
			}
			for (int i = 0; i < bits.Length; i++)
			{
				if (bits[i] != bitMatrix.bits[i])
				{
					return false;
				}
			}
			return true;
		}

		public override int GetHashCode()
		{
			int num = width;
			num = 31 * num + width;
			num = 31 * num + height;
			num = 31 * num + rowSize;
			int[] array = bits;
			foreach (int num2 in array)
			{
				num = 31 * num + num2;
			}
			return num;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(height * (width + 1));
			for (int i = 0; i < height; i++)
			{
				for (int j = 0; j < width; j++)
				{
					stringBuilder.Append(Get(j, i) ? "X " : "  ");
				}
				stringBuilder.Append('\n');
			}
			return stringBuilder.ToString();
		}
	}
	public sealed class BitSource
	{
		private readonly byte[] bytes;

		private int byteOffset;

		private int bitOffset;

		public int ByteOffset => byteOffset;

		public int BitOffset => bitOffset;

		public BitSource(byte[] bytes)
		{
			this.bytes = bytes;
		}

		public int ReadBits(int numBits)
		{
			if (numBits < 1 || numBits > 32)
			{
				throw new ArgumentException(numBits.ToString());
			}
			int num = 0;
			if (bitOffset > 0)
			{
				int num2 = 8 - bitOffset;
				int num3 = ((numBits < num2) ? numBits : num2);
				int num4 = num2 - num3;
				int num5 = 255 >> 8 - num3 << num4;
				num = (bytes[byteOffset] & num5) >> num4;
				numBits -= num3;
				bitOffset += num3;
				if (bitOffset == 8)
				{
					bitOffset = 0;
					byteOffset++;
				}
			}
			if (numBits > 0)
			{
				while (numBits >= 8)
				{
					num = (num << 8) | (bytes[byteOffset] & 0xFF);
					byteOffset++;
					numBits -= 8;
				}
				if (numBits > 0)
				{
					int num6 = 8 - numBits;
					int num7 = 255 >> num6 << num6;
					num = (num << numBits) | ((bytes[byteOffset] & num7) >> num6);
					bitOffset += numBits;
				}
			}
			return num;
		}

		public int Available()
		{
			return 8 * (bytes.Length - byteOffset) - bitOffset;
		}
	}
	public sealed class CharacterSetECI : ECI
	{
