		public static void InsertionSort<T>(List<T> vector, Comparator comparator)
		{
			int count = vector.Count;
			for (int i = 1; i < count; i++)
			{
				T val = vector[i];
				int num = i - 1;
				T value;
				while (num >= 0 && comparator.Compare(value = vector[num], val) > 0)
				{
					vector[num + 1] = value;
					num--;
				}
				vector[num + 1] = val;
			}
		}
	}
