	public class GlobalHistogramBinarizer : Binarizer
	{
		private const int LUMINANCE_BITS = 5;

		private const int LUMINANCE_SHIFT = 3;

		private const int LUMINANCE_BUCKETS = 32;

		private static readonly byte[] EMPTY = new byte[0];

		private byte[] luminances;

		private readonly int[] buckets;

		public override BitMatrix BlackMatrix
		{
			get
			{
				LuminanceSource luminanceSource = LuminanceSource;
				int width = luminanceSource.Width;
				int height = luminanceSource.Height;
				BitMatrix bitMatrix = new BitMatrix(width, height);
				InitArrays(width);
				int[] array = buckets;
				for (int i = 1; i < 5; i++)
				{
					int y = height * i / 5;
					byte[] row = luminanceSource.GetRow(y, luminances);
					int num = (width << 2) / 5;
					for (int j = width / 5; j < num; j++)
					{
						int num2 = row[j] & 0xFF;
						array[num2 >> 3]++;
					}
				}
				int num3 = EstimateBlackPoint(array);
				byte[] matrix = luminanceSource.Matrix;
				for (int k = 0; k < height; k++)
				{
					int num4 = k * width;
					for (int l = 0; l < width; l++)
					{
						if ((matrix[num4 + l] & 0xFF) < num3)
						{
							bitMatrix.Set(l, k);
						}
					}
				}
				return bitMatrix;
			}
		}

		public GlobalHistogramBinarizer(LuminanceSource source)
			: base(source)
		{
			luminances = EMPTY;
			buckets = new int[32];
		}

		public override BitArray GetBlackRow(int y, BitArray row)
		{
			LuminanceSource luminanceSource = LuminanceSource;
			int width = luminanceSource.Width;
			if (row == null || row.GetSize() < width)
			{
				row = new BitArray(width);
			}
			else
			{
				row.Clear();
			}
			InitArrays(width);
			byte[] row2 = luminanceSource.GetRow(y, luminances);
			int[] array = buckets;
			for (int i = 0; i < width; i++)
			{
				int num = row2[i] & 0xFF;
				array[num >> 3]++;
			}
			int num2 = EstimateBlackPoint(array);
			int num3 = row2[0] & 0xFF;
			int num4 = row2[1] & 0xFF;
			for (int j = 1; j < width - 1; j++)
			{
				int num5 = row2[j + 1] & 0xFF;
				if ((num4 << 2) - num3 - num5 >> 1 < num2)
				{
					row.Set(j);
				}
				num3 = num4;
				num4 = num5;
			}
			return row;
		}

		public override Binarizer CreateBinarizer(LuminanceSource source)
		{
			return new GlobalHistogramBinarizer(source);
		}

		private void InitArrays(int luminanceSize)
		{
			if (luminances.Length < luminanceSize)
			{
				luminances = new byte[luminanceSize];
			}
			for (int i = 0; i < 32; i++)
			{
				buckets[i] = 0;
			}
		}

		private static int EstimateBlackPoint(int[] buckets)
		{
			int num = buckets.Length;
			int num2 = 0;
			int num3 = 0;
			int num4 = 0;
			for (int i = 0; i < num; i++)
			{
				if (buckets[i] > num4)
				{
					num3 = i;
					num4 = buckets[i];
				}
				if (buckets[i] > num2)
				{
					num2 = buckets[i];
				}
			}
			int num5 = 0;
			int num6 = 0;
			for (int j = 0; j < num; j++)
			{
				int num7 = j - num3;
				int num8 = buckets[j] * num7 * num7;
				if (num8 > num6)
				{
					num5 = j;
					num6 = num8;
				}
			}
			if (num3 > num5)
			{
				int num9 = num3;
				num3 = num5;
				num5 = num9;
			}
			if (num5 - num3 <= num >> 4)
			{
				throw NotFoundException.Instance;
			}
			int num10 = num5 - 1;
			int num11 = -1;
			for (int num12 = num5 - 1; num12 > num3; num12--)
			{
				int num13 = num12 - num3;
				int num14 = num13 * num13 * (num5 - num12) * (num2 - buckets[num12]);
				if (num14 > num11)
				{
					num10 = num12;
					num11 = num14;
				}
			}
			return num10 << 3;
		}
	}
	public abstract class GridSampler
	{
		private static GridSampler gridSampler = new DefaultGridSampler();

		public static void SetGridSampler(GridSampler newGridSampler)
		{
			gridSampler = newGridSampler;
