		{
			return gridSampler;
		}

		public abstract BitMatrix SampleGrid(BitMatrix image, int dimensionX, int dimensionY, float p1ToX, float p1ToY, float p2ToX, float p2ToY, float p3ToX, float p3ToY, float p4ToX, float p4ToY, float p1FromX, float p1FromY, float p2FromX, float p2FromY, float p3FromX, float p3FromY, float p4FromX, float p4FromY);

		public abstract BitMatrix SampleGrid(BitMatrix image, int dimensionX, int dimensionY, PerspectiveTransform transform);

		protected internal static void CheckAndNudgePoints(BitMatrix image, float[] points)
		{
			int width = image.GetWidth();
			int height = image.GetHeight();
			bool flag = true;
			for (int i = 0; i < points.Length && flag; i += 2)
			{
				int num = (int)points[i];
				int num2 = (int)points[i + 1];
				if (num < -1 || num > width || num2 < -1 || num2 > height)
				{
					throw NotFoundException.Instance;
				}
				flag = false;
				if (num == -1)
				{
					points[i] = 0f;
					flag = true;
				}
				else if (num == width)
				{
					points[i] = width - 1;
					flag = true;
				}
				if (num2 == -1)
				{
					points[i + 1] = 0f;
					flag = true;
				}
				else if (num2 == height)
				{
					points[i + 1] = height - 1;
					flag = true;
				}
			}
			flag = true;
			int num3 = points.Length - 2;
			while (num3 >= 0 && flag)
			{
				int num4 = (int)points[num3];
				int num5 = (int)points[num3 + 1];
				if (num4 < -1 || num4 > width || num5 < -1 || num5 > height)
				{
					throw NotFoundException.Instance;
				}
				flag = false;
				if (num4 == -1)
				{
					points[num3] = 0f;
					flag = true;
				}
				else if (num4 == width)
				{
					points[num3] = width - 1;
					flag = true;
				}
				if (num5 == -1)
				{
					points[num3 + 1] = 0f;
					flag = true;
				}
				else if (num5 == height)
				{
					points[num3 + 1] = height - 1;
					flag = true;
				}
				num3 -= 2;
			}
		}
	}
	public class HybridBinarizer : GlobalHistogramBinarizer
	{
		private const int BLOCK_SIZE_POWER = 3;

		private const int BLOCK_SIZE = 8;

		private const int BLOCK_SIZE_MASK = 7;

		private const int MINIMUM_DIMENSION = 40;

		private const int MIN_DYNAMIC_RANGE = 24;

		private BitMatrix matrix;

		public override BitMatrix BlackMatrix
		{
			get
			{
				if (matrix != null)
				{
					return matrix;
				}
				LuminanceSource luminanceSource = LuminanceSource;
				int width = luminanceSource.Width;
				int height = luminanceSource.Height;
				if (width >= 40 && height >= 40)
				{
					byte[] array = luminanceSource.Matrix;
					int num = width >> 3;
					if (((uint)width & 7u) != 0)
					{
						num++;
					}
					int num2 = height >> 3;
					if (((uint)height & 7u) != 0)
					{
						num2++;
					}
					int[][] blackPoints = CalculateBlackPoints(array, num, num2, width, height);
					BitMatrix matrix_ = new BitMatrix(width, height);
					CalculateThresholdForBlock(array, num, num2, width, height, blackPoints, matrix_);
					matrix = matrix_;
				}
				else
				{
					matrix = base.BlackMatrix;
				}
				return matrix;
			}
		}

		public HybridBinarizer(LuminanceSource source)
			: base(source)
		{
		}

		public override Binarizer CreateBinarizer(LuminanceSource source)
		{
			return new HybridBinarizer(source);
		}

		private static void CalculateThresholdForBlock(byte[] luminances, int subWidth, int subHeight, int width, int height, int[][] blackPoints, BitMatrix matrix_0)
		{
			for (int i = 0; i < subHeight; i++)
			{
				int num = i << 3;
				int num2 = height - 8;
				if (num > num2)
				{
					num = num2;
				}
				for (int j = 0; j < subWidth; j++)
				{
					int num3 = j << 3;
					int num4 = width - 8;
					if (num3 > num4)
					{
						num3 = num4;
					}
					int num5 = Cap(j, 2, subWidth - 3);
					int num6 = Cap(i, 2, subHeight - 3);
					int num7 = 0;
					for (int k = -2; k <= 2; k++)
					{
						int[] array = blackPoints[num6 + k];
						num7 += array[num5 - 2] + array[num5 - 1] + array[num5] + array[num5 + 1] + array[num5 + 2];
					}
					int threshold = num7 / 25;
					ThresholdBlock(luminances, num3, num, threshold, width, matrix_0);
				}
			}
		}

		private static int Cap(int val, int min, int max)
		{
			if (val >= min)
			{
				if (val <= max)
				{
					return val;
				}
				return max;
			}
			return min;
		}

		private static void ThresholdBlock(byte[] luminances, int xoffset, int yoffset, int threshold, int stride, BitMatrix matrix_0)
		{
			int num = 0;
			int num2 = yoffset * stride + xoffset;
			while (num < 8)
			{
				for (int i = 0; i < 8; i++)
				{
					if ((luminances[num2 + i] & 0xFF) <= threshold)
					{
						matrix_0.Set(xoffset + i, yoffset + num);
					}
				}
				num++;
				num2 += stride;
			}
		}

		private static int[][] CalculateBlackPoints(byte[] luminances, int subWidth, int subHeight, int width, int height)
		{
			int[][] array = new int[subHeight][];
			for (int i = 0; i < subHeight; i++)
			{
				array[i] = new int[subWidth];
			}
			for (int j = 0; j < subHeight; j++)
			{
				int num = j << 3;
				int num2 = height - 8;
				if (num > num2)
				{
					num = num2;
				}
				for (int k = 0; k < subWidth; k++)
				{
					int num3 = k << 3;
					int num4 = width - 8;
					if (num3 > num4)
					{
						num3 = num4;
					}
					int num5 = 0;
					int num6 = 255;
					int num7 = 0;
					int num8 = 0;
					int num9 = num * width + num3;
					while (num8 < 8)
					{
						for (int l = 0; l < 8; l++)
						{
							int num10 = luminances[num9 + l] & 0xFF;
							num5 += num10;
							if (num10 < num6)
							{
								num6 = num10;
							}
							if (num10 > num7)
							{
								num7 = num10;
							}
						}
						if (num7 - num6 > 24)
						{
							num8++;
							num9 += width;
							while (num8 < 8)
							{
								for (int m = 0; m < 8; m++)
								{
									num5 += luminances[num9 + m] & 0xFF;
								}
								num8++;
								num9 += width;
							}
						}
						num8++;
						num9 += width;
					}
					int num11 = num5 >> 6;
					if (num7 - num6 <= 24)
					{
						num11 = num6 >> 1;
						if (j > 0 && k > 0)
						{
							int num12 = array[j - 1][k] + 2 * array[j][k - 1] + array[j - 1][k - 1] >> 2;
							if (num6 < num12)
							{
								num11 = num12;
							}
						}
					}
					array[j][k] = num11;
				}
			}
			return array;
		}
	}
