				throw new BigIntegerException("Cannot obtain the modular inverse of a number that is not coprime with the modulus.", null);
			}
			ExtendedEuclidGcd(n, a, out var _, out var v);
			if (v.sign == Sign.Negative)
			{
				return v + n;
			}
			return v;
		}

