namespace MessagingToolkit.Barcode.Common.Detector
{
	public sealed class MathUtils
	{
		private MathUtils()
		{
		}

		public static int Round(float d)
		{
			return (int)(d + 0.5f);
		}

		public static float Distance(float aX, float aY, float bX, float bY)
		{
			float num = aX - bX;
			float num2 = aY - bY;
			return (float)Math.Sqrt(num * num + num2 * num2);
		}

		public static float Distance(int aX, int aY, int bX, int bY)
		{
			int num = aX - bX;
			int num2 = aY - bY;
			return (float)Math.Sqrt(num * num + num2 * num2);
		}
	}
	public sealed class MonochromeRectangleDetector
	{
		private const int MaxModules = 32;

		private BitMatrix image;

		public MonochromeRectangleDetector(BitMatrix image)
		{
			this.image = image;
		}

		public ResultPoint[] Detect()
		{
			int height = image.Height;
			int width = image.Width;
			int num = height >> 1;
			int num2 = width >> 1;
			int num3 = Math.Max(1, height / 256);
			int num4 = Math.Max(1, width / 256);
			int top = 0;
			int bottom = height;
			int left = 0;
			int right = width;
			ResultPoint resultPoint = FindCornerFromCenter(num2, 0, left, right, num, -num3, top, bottom, num2 >> 1);
			top = (int)resultPoint.Y - 1;
			ResultPoint resultPoint2 = FindCornerFromCenter(num2, -num4, left, right, num, 0, top, bottom, num >> 1);
			left = (int)resultPoint2.X - 1;
			ResultPoint resultPoint3 = FindCornerFromCenter(num2, num4, left, right, num, 0, top, bottom, num >> 1);
			right = (int)resultPoint3.X + 1;
			ResultPoint resultPoint4 = FindCornerFromCenter(num2, 0, left, right, num, num3, top, bottom, num2 >> 1);
			bottom = (int)resultPoint4.Y + 1;
			resultPoint = FindCornerFromCenter(num2, 0, left, right, num, -num3, top, bottom, num2 >> 2);
			return new ResultPoint[4] { resultPoint, resultPoint2, resultPoint3, resultPoint4 };
		}

		private ResultPoint FindCornerFromCenter(int centerX, int deltaX, int left, int right, int centerY, int deltaY, int top, int bottom, int maxWhiteRun)
		{
			int[] array = null;
			int num = centerY;
			int num2 = centerX;
			while (num < bottom && num >= top && num2 < right && num2 >= left)
			{
				int[] array2 = ((deltaX != 0) ? BlackWhiteRange(num2, maxWhiteRun, top, bottom, horizontal: false) : BlackWhiteRange(num, maxWhiteRun, left, right, horizontal: true));
				if (array2 == null)
				{
					if (array == null)
					{
						throw NotFoundException.Instance;
					}
					if (deltaX == 0)
					{
						int num3 = num - deltaY;
						if (array[0] < centerX)
						{
							if (array[1] > centerX)
							{
								return new ResultPoint((deltaY > 0) ? array[0] : array[1], num3);
							}
							return new ResultPoint(array[0], num3);
						}
						return new ResultPoint(array[1], num3);
					}
					int num4 = num2 - deltaX;
					if (array[0] < centerY)
					{
						if (array[1] > centerY)
						{
							return new ResultPoint(num4, (deltaX < 0) ? array[0] : array[1]);
						}
						return new ResultPoint(num4, array[0]);
					}
					return new ResultPoint(num4, array[1]);
				}
				array = array2;
				num += deltaY;
				num2 += deltaX;
			}
			throw NotFoundException.Instance;
		}

		private int[] BlackWhiteRange(int fixedDimension, int maxWhiteRun, int minDim, int maxDim, bool horizontal)
		{
			int num = minDim + maxDim >> 1;
			int num2 = num;
			while (num2 >= minDim)
			{
				if (horizontal ? image.GetValue(num2, fixedDimension) : image.GetValue(fixedDimension, num2))
				{
					num2--;
					continue;
				}
				int num3 = num2;
				do
				{
					num2--;
				}
				while (num2 >= minDim && !(horizontal ? image.GetValue(num2, fixedDimension) : image.GetValue(fixedDimension, num2)));
				int num4 = num3 - num2;
				if (num2 >= minDim && num4 <= maxWhiteRun)
				{
					continue;
				}
				num2 = num3;
				break;
			}
			num2++;
			int num5 = num;
			while (num5 < maxDim)
			{
				if (horizontal ? image.GetValue(num5, fixedDimension) : image.GetValue(fixedDimension, num5))
				{
					num5++;
					continue;
				}
				int num6 = num5;
				do
				{
					num5++;
				}
				while (num5 < maxDim && !(horizontal ? image.GetValue(num5, fixedDimension) : image.GetValue(fixedDimension, num5)));
				int num7 = num5 - num6;
				if (num5 < maxDim && num7 <= maxWhiteRun)
				{
					continue;
				}
				num5 = num6;
				break;
			}
			num5--;
			if (num5 <= num2)
			{
				return null;
			}
			return new int[2] { num2, num5 };
		}
	}
	public sealed class WhiteRectangleDetector
	{
		private const int InitSize = 30;

		private const int Corr = 1;

		private readonly BitMatrix image;

		private readonly int height;

		private readonly int width;

		private readonly int leftInit;

		private readonly int rightInit;

		private readonly int downInit;

		private readonly int upInit;

		public WhiteRectangleDetector(BitMatrix img)
		{
			image = img;
			height = img.Height;
			width = img.Width;
			leftInit = width - 30 >> 1;
			rightInit = width + 30 >> 1;
			upInit = height - 30 >> 1;
			downInit = height + 30 >> 1;
			if (upInit < 0 || leftInit < 0 || downInit >= height || rightInit >= width)
			{
				throw NotFoundException.Instance;
			}
		}

		public WhiteRectangleDetector(BitMatrix img, int initSize, int x, int y)
		{
			image = img;
			height = img.Height;
			width = img.Width;
			int num = initSize >> 1;
			leftInit = x - num;
			rightInit = x + num;
			upInit = y - num;
			downInit = y + num;
			if (upInit < 0 || leftInit < 0 || downInit >= height || rightInit >= width)
			{
				throw NotFoundException.Instance;
			}
		}

		public ResultPoint[] Detect()
		{
			int num = leftInit;
			int num2 = rightInit;
			int num3 = upInit;
			int num4 = downInit;
			bool flag = false;
			bool flag2 = true;
			bool flag3 = false;
			while (flag2)
			{
				flag2 = false;
				bool flag4 = true;
				while (flag4 && num2 < width)
				{
					flag4 = ContainsBlackPoint(num3, num4, num2, horizontal: false);
					if (flag4)
					{
						num2++;
						flag2 = true;
					}
				}
				if (num2 >= width)
				{
					flag = true;
					break;
				}
				bool flag5 = true;
				while (flag5 && num4 < height)
				{
					flag5 = ContainsBlackPoint(num, num2, num4, horizontal: true);
					if (flag5)
					{
						num4++;
						flag2 = true;
					}
				}
				if (num4 >= height)
				{
					flag = true;
					break;
				}
				bool flag6 = true;
				while (flag6 && num >= 0)
				{
					flag6 = ContainsBlackPoint(num3, num4, num, horizontal: false);
					if (flag6)
					{
						num--;
						flag2 = true;
					}
				}
				if (num < 0)
				{
					flag = true;
					break;
				}
				bool flag7 = true;
				while (flag7 && num3 >= 0)
				{
					flag7 = ContainsBlackPoint(num, num2, num3, horizontal: true);
					if (flag7)
					{
						num3--;
						flag2 = true;
					}
				}
				if (num3 < 0)
				{
					flag = true;
					break;
				}
				if (flag2)
				{
					flag3 = true;
				}
			}
			if (!flag && flag3)
			{
				int num5 = num2 - num;
				ResultPoint resultPoint = null;
				for (int i = 1; i < num5; i++)
				{
					resultPoint = GetBlackPointOnSegment(num, num4 - i, num + i, num4);
					if (resultPoint != null)
					{
						break;
					}
				}
				if (resultPoint == null)
				{
					throw NotFoundException.Instance;
				}
				ResultPoint resultPoint2 = null;
				for (int j = 1; j < num5; j++)
				{
					resultPoint2 = GetBlackPointOnSegment(num, num3 + j, num + j, num3);
					if (resultPoint2 != null)
					{
						break;
					}
				}
				if (resultPoint2 == null)
				{
					throw NotFoundException.Instance;
				}
				ResultPoint resultPoint3 = null;
				for (int k = 1; k < num5; k++)
				{
					resultPoint3 = GetBlackPointOnSegment(num2, num3 + k, num2 - k, num3);
					if (resultPoint3 != null)
					{
						break;
					}
				}
				if (resultPoint3 == null)
				{
					throw NotFoundException.Instance;
				}
				ResultPoint resultPoint4 = null;
				for (int l = 1; l < num5; l++)
				{
					resultPoint4 = GetBlackPointOnSegment(num2, num4 - l, num2 - l, num4);
					if (resultPoint4 != null)
					{
						break;
					}
				}
				if (resultPoint4 == null)
				{
					throw NotFoundException.Instance;
				}
				return CenterEdges(resultPoint4, resultPoint, resultPoint3, resultPoint2);
			}
			throw NotFoundException.Instance;
		}

		private ResultPoint GetBlackPointOnSegment(float aX, float aY, float bX, float bY)
		{
			int num = MathUtils.Round(MathUtils.Distance(aX, aY, bX, bY));
			float num2 = (bX - aX) / (float)num;
			float num3 = (bY - aY) / (float)num;
			for (int i = 0; i < num; i++)
			{
				int num4 = MathUtils.Round(aX + (float)i * num2);
				int num5 = MathUtils.Round(aY + (float)i * num3);
				if (image.Get(num4, num5))
				{
					return new ResultPoint(num4, num5);
				}
			}
			return null;
		}

		private ResultPoint[] CenterEdges(ResultPoint y, ResultPoint z, ResultPoint x, ResultPoint t)
		{
			float x2 = y.X;
			float y2 = y.Y;
			float x3 = z.X;
			float y3 = z.Y;
			float x4 = x.X;
			float y4 = x.Y;
			float x5 = t.X;
			float y5 = t.Y;
			if (!(x2 < (float)width / 2f))
			{
				return new ResultPoint[4]
				{
					new ResultPoint(x5 + 1f, y5 + 1f),
					new ResultPoint(x3 + 1f, y3 - 1f),
					new ResultPoint(x4 - 1f, y4 + 1f),
					new ResultPoint(x2 - 1f, y2 - 1f)
				};
			}
			return new ResultPoint[4]
			{
				new ResultPoint(x5 - 1f, y5 + 1f),
				new ResultPoint(x3 + 1f, y3 + 1f),
				new ResultPoint(x4 - 1f, y4 - 1f),
				new ResultPoint(x2 + 1f, y2 - 1f)
			};
		}

		private bool ContainsBlackPoint(int a, int b, int fix, bool horizontal)
		{
			if (horizontal)
			{
				for (int i = a; i <= b; i++)
				{
					if (image.Get(i, fix))
					{
						return true;
					}
				}
			}
			else
			{
				for (int j = a; j <= b; j++)
				{
					if (image.Get(fix, j))
					{
						return true;
					}
				}
			}
			return false;
		}
	}
