namespace MessagingToolkit.Barcode.Client.Results
{
	public abstract class AbstractDoCoMoResultParser : ResultParser
	{
		internal static string[] MatchDoCoMoPrefixedField(string prefix, string rawText, bool trim)
		{
			return ResultParser.MatchPrefixedField(prefix, rawText, ';', trim);
		}

		internal static string MatchSingleDoCoMoPrefixedField(string prefix, string rawText, bool trim)
		{
			return ResultParser.MatchSinglePrefixedField(prefix, rawText, ';', trim);
		}
	}
	public sealed class AddressBookAUResultParser : ResultParser
	{
		public override ParsedResult Parse(Result result)
		{
			string massagedText = ResultParser.GetMassagedText(result);
			if (!massagedText.Contains("MEMORY") || !massagedText.Contains("\r\n"))
			{
				return null;
			}
			string value_ren = ResultParser.MatchSinglePrefixedField("NAME1:", massagedText, '\r', trim: true);
			string pronunciation = ResultParser.MatchSinglePrefixedField("NAME2:", massagedText, '\r', trim: true);
			string[] phoneNumbers = MatchMultipleValuePrefix("TEL", 3, massagedText, trim: true);
			string[] emails = MatchMultipleValuePrefix("MAIL", 3, massagedText, trim: true);
			string note = ResultParser.MatchSinglePrefixedField("MEMORY:", massagedText, '\r', trim: false);
			string text = ResultParser.MatchSinglePrefixedField("ADD:", massagedText, '\r', trim: true);
			string[] addresses = ((text == null) ? null : new string[1] { text });
			return new AddressBookParsedResult(ResultParser.MaybeWrap(value_ren), null, pronunciation, phoneNumbers, null, emails, null, null, note, addresses, null, null, null, null, null, null);
		}

		private static string[] MatchMultipleValuePrefix(string prefix, int max, string rawText, bool trim)
		{
			List<string> list = null;
			for (int i = 1; i <= max; i++)
			{
				string text = ResultParser.MatchSinglePrefixedField(prefix + i + ":", rawText, '\r', trim);
				if (text == null)
				{
					break;
				}
				if (list == null)
				{
					list = new List<string>(max);
				}
				list.Add(text);
			}
			if (list == null)
			{
				return null;
			}
			return ResultParser.ToStringArray(list);
		}
	}
	public sealed class AddressBookDoCoMoResultParser : AbstractDoCoMoResultParser
	{
		public override ParsedResult Parse(Result result)
		{
			string massagedText = ResultParser.GetMassagedText(result);
			if (!massagedText.StartsWith("MECARD:"))
			{
				return null;
			}
			string[] array = AbstractDoCoMoResultParser.MatchDoCoMoPrefixedField("N:", massagedText, trim: true);
			if (array == null)
			{
				return null;
			}
			string value_ren = ParseName(array[0]);
			string pronunciation = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("SOUND:", massagedText, trim: true);
			string[] phoneNumbers = AbstractDoCoMoResultParser.MatchDoCoMoPrefixedField("TEL:", massagedText, trim: true);
			string[] emails = AbstractDoCoMoResultParser.MatchDoCoMoPrefixedField("EMAIL:", massagedText, trim: true);
			string note = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("NOTE:", massagedText, trim: false);
			string[] addresses = AbstractDoCoMoResultParser.MatchDoCoMoPrefixedField("ADR:", massagedText, trim: true);
			string text = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("BDAY:", massagedText, trim: true);
			if (text != null && !ResultParser.IsStringOfDigits(text, 8))
			{
				text = null;
			}
			return new AddressBookParsedResult(urls: AbstractDoCoMoResultParser.MatchDoCoMoPrefixedField("URL:", massagedText, trim: true), org: AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("ORG:", massagedText, trim: true), names: ResultParser.MaybeWrap(value_ren), nicknames: null, pronunciation: pronunciation, phoneNumbers: phoneNumbers, phoneTypes: null, emails: emails, emailTypes: null, instantMessenger: null, note: note, addresses: addresses, addressTypes: null, birthday: text, title: null, geo: null);
		}

		private static string ParseName(string name)
		{
			int num = name.IndexOf(',');
			if (num >= 0)
			{
				return name.Substring(num + 1) + " " + name.Substring(0, num);
			}
			return name;
		}
	}
