	public sealed class BizcardResultParser : AbstractDoCoMoResultParser
	{
		public override ParsedResult Parse(Result result)
		{
			string massagedText = ResultParser.GetMassagedText(result);
			if (!massagedText.StartsWith("BIZCARD:"))
			{
				return null;
			}
			string firstName = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("N:", massagedText, trim: true);
			string lastName = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("X:", massagedText, trim: true);
			string value_ren = BuildName(firstName, lastName);
			string title = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("T:", massagedText, trim: true);
			string org = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("C:", massagedText, trim: true);
			string[] addresses = AbstractDoCoMoResultParser.MatchDoCoMoPrefixedField("A:", massagedText, trim: true);
			string number = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("B:", massagedText, trim: true);
			string number2 = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("M:", massagedText, trim: true);
			string number3 = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("F:", massagedText, trim: true);
			return new AddressBookParsedResult(emails: ResultParser.MaybeWrap(AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("E:", massagedText, trim: true)), names: ResultParser.MaybeWrap(value_ren), nicknames: null, pronunciation: null, phoneNumbers: BuildPhoneNumbers(number, number2, number3), phoneTypes: null, emailTypes: null, instantMessenger: null, note: null, addresses: addresses, addressTypes: null, org: org, birthday: null, title: title, urls: null, geo: null);
		}

		private static string[] BuildPhoneNumbers(string number1, string number2, string number3)
		{
			List<string> list = new List<string>(3);
			if (number1 != null)
			{
				list.Add(number1);
			}
			if (number2 != null)
			{
				list.Add(number2);
			}
			if (number3 != null)
			{
				list.Add(number3);
			}
			if (list.Count == 0)
			{
				return null;
			}
			return ResultParser.ToStringArray(list);
		}

		private static string BuildName(string firstName, string lastName)
		{
			if (firstName == null)
			{
				return lastName;
			}
			if (lastName != null)
			{
				return firstName + " " + lastName;
			}
			return firstName;
		}
