	public sealed class EmailAddressResultParser : ResultParser
	{
		public override ParsedResult Parse(Result result)
		{
			string massagedText = ResultParser.GetMassagedText(result);
			string text;
			if (massagedText.StartsWith("mailto:") || massagedText.StartsWith("MAILTO:"))
			{
				text = massagedText.Substring(7);
				int num = text.IndexOf('?');
				if (num >= 0)
				{
					text = text.Substring(0, num);
				}
				text = ResultParser.UrlDecode(text);
				IDictionary<string, string> dictionary = ResultParser.ParseNameValuePairs(massagedText);
				string subject_ = null;
				string body_ = null;
				if (dictionary != null)
				{
					if (string.IsNullOrEmpty(text))
					{
						text = dictionary["to"];
					}
					subject_ = dictionary["subject"];
					body_ = dictionary["body"];
				}
				return new EmailAddressParsedResult(text, subject_, body_, massagedText);
			}
			if (!EmailDoCoMoResultParser.IsBasicallyValidEmailAddress(massagedText))
			{
				return null;
			}
			text = massagedText;
			return new EmailAddressParsedResult(text, null, null, "mailto:" + text);
		}
	}
	public sealed class EmailDoCoMoResultParser : AbstractDoCoMoResultParser
	{
		private static Regex ATEXT_ALPHANUMERIC = new Regex("^[a-zA-Z0-9@.!#$%&'*+\\-/=?^_`{|}~]+$");

		public override ParsedResult Parse(Result result)
		{
			string massagedText = ResultParser.GetMassagedText(result);
			if (!massagedText.StartsWith("MATMSG:"))
			{
				return null;
			}
			string[] array = AbstractDoCoMoResultParser.MatchDoCoMoPrefixedField("TO:", massagedText, trim: true);
			if (array == null)
			{
				return null;
			}
			string text = array[0];
			if (!IsBasicallyValidEmailAddress(text))
			{
				return null;
			}
			string subject_ = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("SUB:", massagedText, trim: false);
			string body_ = AbstractDoCoMoResultParser.MatchSingleDoCoMoPrefixedField("BODY:", massagedText, trim: false);
			return new EmailAddressParsedResult(text, subject_, body_, "mailto:" + text);
		}

		internal static bool IsBasicallyValidEmailAddress(string email)
		{
			if (email != null && ATEXT_ALPHANUMERIC.Match(email).Success)
			{
				return email.IndexOf('@') >= 0;
			}
			return false;
		}
	}
