	public sealed class ExpandedProductResultParser : ResultParser
	{
		public override ParsedResult Parse(Result result)
		{
			if (result.BarcodeFormat != BarcodeFormat.RSSExpanded)
			{
				return null;
			}
			string massagedText = ResultParser.GetMassagedText(result);
			if (massagedText == null)
			{
				return null;
			}
			string productID = null;
			string sscc = null;
			string lotNumber = null;
			string productionDate = null;
			string packagingDate = null;
			string bestBeforeDate = null;
			string expirationDate = null;
			string weight = null;
			string weightType = null;
			string weightIncrement = null;
			string price = null;
			string priceIncrement = null;
			string priceCurrency = null;
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			int num = 0;
			while (num < massagedText.Length)
			{
				string text = FindAIvalue(num, massagedText);
				if (text == null)
				{
					return null;
				}
				num += text.Length + 2;
				string text2 = FindValue(num, massagedText);
				num += text2.Length;
				if ("00".Equals(text))
				{
					sscc = text2;
				}
				else if ("01".Equals(text))
				{
					productID = text2;
				}
				else if ("10".Equals(text))
				{
					lotNumber = text2;
				}
				else if ("11".Equals(text))
				{
					productionDate = text2;
				}
				else if ("13".Equals(text))
				{
					packagingDate = text2;
				}
				else if ("15".Equals(text))
				{
					bestBeforeDate = text2;
				}
				else if ("17".Equals(text))
				{
					expirationDate = text2;
				}
				else if ("3100".Equals(text) || "3101".Equals(text) || "3102".Equals(text) || "3103".Equals(text) || "3104".Equals(text) || "3105".Equals(text) || "3106".Equals(text) || "3107".Equals(text) || "3108".Equals(text) || "3109".Equals(text))
				{
					weight = text2;
					weightType = "KG";
					weightIncrement = text.Substring(3);
				}
				else if ("3200".Equals(text) || "3201".Equals(text) || "3202".Equals(text) || "3203".Equals(text) || "3204".Equals(text) || "3205".Equals(text) || "3206".Equals(text) || "3207".Equals(text) || "3208".Equals(text) || "3209".Equals(text))
				{
					weight = text2;
					weightType = "LB";
					weightIncrement = text.Substring(3);
				}
				else if ("3920".Equals(text) || "3921".Equals(text) || "3922".Equals(text) || "3923".Equals(text))
				{
					price = text2;
					priceIncrement = text.Substring(3);
				}
				else if ("3930".Equals(text) || "3931".Equals(text) || "3932".Equals(text) || "3933".Equals(text))
				{
					if (text2.Length < 4)
					{
						return null;
					}
					price = text2.Substring(3);
					priceCurrency = text2.Substring(0, 3);
					priceIncrement = text.Substring(3);
				}
				else
				{
					dictionary.Add(text, text2);
				}
			}
			return new ExpandedProductParsedResult(massagedText, productID, sscc, lotNumber, productionDate, packagingDate, bestBeforeDate, expirationDate, weight, weightType, weightIncrement, price, priceIncrement, priceCurrency, dictionary);
		}

		private static string FindAIvalue(int i, string rawText)
		{
			if (rawText[i] != '(')
			{
				return null;
			}
			string text = rawText.Substring(i + 1);
			StringBuilder stringBuilder = new StringBuilder();
			foreach (char c in text)
			{
				switch (c)
				{
				case ')':
					return stringBuilder.ToString();
				case '0':
				case '1':
				case '2':
				case '3':
				case '4':
				case '5':
				case '6':
				case '7':
				case '8':
				case '9':
					break;
				default:
					return null;
				}
				stringBuilder.Append(c);
			}
			return stringBuilder.ToString();
		}

		private static string FindValue(int i, string rawText)
		{
			StringBuilder stringBuilder = new StringBuilder();
			string text = rawText.Substring(i);
			for (int j = 0; j < text.Length; j++)
			{
				char c = text[j];
				if (c == '(')
				{
					if (FindAIvalue(j, text) != null)
					{
						break;
					}
					stringBuilder.Append('(');
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}
	}
