	public sealed class GeoResultParser : ResultParser
	{
		private static Regex GEO_URL_PATTERN = new Regex("geo:([\\-0-9.]+),([\\-0-9.]+)(?:,([\\-0-9.]+))?(?:\\?(.*))?", RegexOptions.IgnoreCase);

		public override ParsedResult Parse(Result result)
		{
			string massagedText = ResultParser.GetMassagedText(result);
			Match match = GEO_URL_PATTERN.Match(massagedText);
			if (!match.Success)
			{
				return null;
			}
			string value = match.Groups[4].Value;
			double num;
			double num2;
			double num3;
			try
			{
				num = double.Parse(match.Groups[1].Value, NumberStyles.Float, CultureInfo.InvariantCulture);
				if (num > 90.0 || num < -90.0)
				{
					return null;
				}
				num2 = double.Parse(match.Groups[2].Value, NumberStyles.Float, CultureInfo.InvariantCulture);
				if (num2 > 180.0 || num2 < -180.0)
				{
					return null;
				}
				if (string.IsNullOrEmpty(match.Groups[3].Value))
				{
					num3 = 0.0;
				}
				else
				{
					num3 = double.Parse(match.Groups[3].Value, NumberStyles.Float, CultureInfo.InvariantCulture);
					if (num3 < 0.0)
					{
						return null;
					}
				}
			}
			catch (Exception)
			{
				return null;
			}
			return new GeoParsedResult(num, num2, num3, value);
		}
	}
