	public sealed class ProductResultParser : ResultParser
	{
		public override ParsedResult Parse(Result result)
		{
			BarcodeFormat barcodeFormat = result.BarcodeFormat;
			if (barcodeFormat != BarcodeFormat.UPCA && barcodeFormat != BarcodeFormat.UPCE && barcodeFormat != BarcodeFormat.EAN8 && barcodeFormat != BarcodeFormat.EAN13)
			{
				return null;
			}
			string massagedText = ResultParser.GetMassagedText(result);
			int length = massagedText.Length;
			for (int i = 0; i < length; i++)
			{
				char c = massagedText[i];
				if (c < '0' || c > '9')
				{
					return null;
				}
			}
			string normalizedProductID = ((barcodeFormat != BarcodeFormat.UPCE) ? massagedText : UPCEDecoder.ConvertUPCEtoUPCA(massagedText));
			return new ProductParsedResult(massagedText, normalizedProductID);
		}
	}
	public abstract class ResultParser
	{
		private static readonly ResultParser[] PARSERS = new ResultParser[19]
		{
			new BookmarkDoCoMoResultParser(),
			new AddressBookDoCoMoResultParser(),
			new EmailDoCoMoResultParser(),
			new AddressBookAUResultParser(),
			new VCardResultParser(),
			new BizcardResultParser(),
			new VEventResultParser(),
			new EmailAddressResultParser(),
			new SMTPResultParser(),
			new TelResultParser(),
			new SMSMMSResultParser(),
			new SmsToMmsToResultParser(),
			new GeoResultParser(),
			new WifiResultParser(),
			new URLTOResultParser(),
			new URIResultParser(),
			new ISBNResultParser(),
			new ProductResultParser(),
			new ExpandedProductResultParser()
		};

		private static readonly Regex DIGITS = new Regex("\\d*", RegexOptions.Compiled);

		private static readonly Regex ALPHANUM = new Regex("[a-zA-Z0-9]*", RegexOptions.Compiled);

		private static readonly Regex AMPERSAND = new Regex("&", RegexOptions.Compiled);

		private static readonly Regex EQUALS = new Regex("=", RegexOptions.Compiled);

		private static readonly string BYTE_ORDER_MARK = "\ufeff";

		public abstract ParsedResult Parse(Result theResult);

		protected internal static string GetMassagedText(Result result)
		{
			string text = result.Text;
			if (text.StartsWith(BYTE_ORDER_MARK))
			{
				text = text.Substring(1);
			}
			return text;
		}

		public static ParsedResult ParseResult(Result theResult)
		{
			ResultParser[] pARSERS = PARSERS;
			for (int i = 0; i < pARSERS.Length; i++)
			{
				ParsedResult parsedResult = pARSERS[i].Parse(theResult);
				if (parsedResult != null)
				{
					return parsedResult;
				}
			}
			return new TextParsedResult(theResult.Text, null);
		}

		protected internal static void MaybeAppend(string val, StringBuilder result)
		{
			if (val != null)
			{
				result.Append('\n');
				result.Append(val);
			}
		}

		protected internal static void MaybeAppend(string[] val, StringBuilder result)
		{
			if (val != null)
			{
				foreach (string value in val)
				{
					result.Append('\n');
					result.Append(value);
				}
			}
		}

		protected internal static string[] MaybeWrap(string value_ren)
		{
			if (value_ren != null)
			{
				return new string[1] { value_ren };
			}
			return null;
		}

		protected internal static string UnescapeBackslash(string escaped)
		{
			int num = escaped.IndexOf('\\');
			if (num < 0)
			{
				return escaped;
			}
			int length = escaped.Length;
			StringBuilder stringBuilder = new StringBuilder(length - 1);
			stringBuilder.Append(escaped.ToCharArray(), 0, num);
			bool flag = false;
			for (int i = num; i < length; i++)
			{
				char c = escaped[i];
				if (flag || c != '\\')
				{
					stringBuilder.Append(c);
					flag = false;
				}
				else
				{
					flag = true;
				}
			}
			return stringBuilder.ToString();
		}

		protected internal static int ParseHexDigit(char c)
		{
			if (c >= '0' && c <= '9')
			{
				return c - 48;
			}
			if (c >= 'a' && c <= 'f')
			{
				return 10 + (c - 97);
			}
			if (c >= 'A' && c <= 'F')
			{
				return 10 + (c - 65);
			}
			return -1;
		}

		protected internal static bool IsStringOfDigits(string val, int length)
		{
			if (val != null && length == val.Length)
			{
				return DIGITS.Match(val).Success;
			}
			return false;
		}

		protected internal static bool IsSubstringOfDigits(string val, int offset, int length)
		{
			if (val == null)
			{
				return false;
			}
			int num = offset + length;
			if (val.Length >= num)
			{
				return DIGITS.Match(val.Substring(offset, length)).Success;
			}
			return false;
		}

		protected internal static bool IsSubstringOfAlphaNumeric(string val, int offset, int length)
		{
			if (val == null)
			{
				return false;
			}
			int num = offset + length;
			if (val.Length >= num)
			{
				return ALPHANUM.Match(val.Substring(offset, length)).Success;
			}
			return false;
		}

		internal static IDictionary<string, string> ParseNameValuePairs(string uri)
		{
			int num = uri.IndexOf('?');
			if (num < 0)
			{
				return null;
			}
			Dictionary<string, string> result = new Dictionary<string, string>(3);
			string[] array = AMPERSAND.Split(uri.Substring(num + 1));
			for (int i = 0; i < array.Length; i++)
			{
				AppendKeyValue(array[i], result);
			}
			return result;
		}

		private static void AppendKeyValue(string keyValue, IDictionary<string, string> result)
		{
			string[] array = EQUALS.Split(keyValue, 2);
			if (array.Length == 2)
			{
				string key = array[0];
				string escaped = array[1];
				try
				{
					escaped = UrlDecode(escaped);
					result.Add(key, escaped);
				}
				catch
				{
				}
			}
		}

		protected static string UrlDecode(string escaped)
		{
			if (escaped == null)
			{
				return null;
			}
			char[] array = escaped.ToCharArray();
			int num = FindFirstEscape(array);
			if (num < 0)
			{
				return escaped;
			}
			int num2 = array.Length;
			StringBuilder stringBuilder = new StringBuilder(num2 - 2);
			stringBuilder.Append(array, 0, num);
			for (int i = num; i < num2; i++)
			{
				char c = array[i];
				switch (c)
				{
				case '+':
					stringBuilder.Append(' ');
					break;
				case '%':
				{
					if (i >= num2 - 2)
					{
						stringBuilder.Append('%');
						break;
					}
					int num3 = ParseHexDigit(array[++i]);
					int num4 = ParseHexDigit(array[++i]);
					if (num3 < 0 || num4 < 0)
					{
						stringBuilder.Append('%');
						stringBuilder.Append(array[i - 1]);
						stringBuilder.Append(array[i]);
					}
					stringBuilder.Append((char)((num3 << 4) + num4));
					break;
				}
				default:
					stringBuilder.Append(c);
					break;
				}
			}
			return stringBuilder.ToString();
		}

		private static int FindFirstEscape(char[] escapedArray)
		{
			int num = escapedArray.Length;
			for (int i = 0; i < num; i++)
			{
				char c = escapedArray[i];
				if (c == '+' || c == '%')
				{
					return i;
				}
			}
			return -1;
		}

		internal static string[] MatchPrefixedField(string prefix, string rawText, char endChar, bool trim)
		{
			List<string> list = null;
			int num = 0;
			int length = rawText.Length;
			while (num < length)
			{
				num = rawText.IndexOf(prefix, num);
				if (num < 0)
				{
					break;
				}
				num += prefix.Length;
				int num2 = num;
				bool flag = true;
				while (flag)
				{
					num = rawText.IndexOf(endChar, num);
					if (num < 0)
					{
						num = rawText.Length;
						flag = false;
						continue;
					}
					if (rawText[num - 1] == '\\')
					{
						num++;
						continue;
					}
					if (list == null)
					{
						list = new List<string>(3);
					}
					string text = UnescapeBackslash(rawText.Substring(num2, num - num2));
					if (trim)
					{
						text = text.Trim();
					}
					if (!string.IsNullOrEmpty(text))
					{
						list.Add(text);
					}
					num++;
					flag = false;
				}
			}
			if (list == null || list.Count == 0)
			{
				return null;
			}
			return ToStringArray(list);
		}

		internal static string MatchSinglePrefixedField(string prefix, string rawText, char endChar, bool trim)
		{
			string[] array = MatchPrefixedField(prefix, rawText, endChar, trim);
			if (array != null)
			{
				return array[0];
			}
			return null;
		}

		internal static string[] ToStringArray(List<string> strings)
		{
			int count = strings.Count;
			string[] array = new string[count];
			for (int i = 0; i < count; i++)
			{
				array[i] = strings[i];
			}
			return array;
		}
	}
	public sealed class SMSMMSResultParser : ResultParser
	{
		public override ParsedResult Parse(Result result)
		{
			string massagedText = ResultParser.GetMassagedText(result);
			if (!massagedText.StartsWith("sms:") && !massagedText.StartsWith("SMS:") && !massagedText.StartsWith("mms:") && !massagedText.StartsWith("MMS:"))
			{
				return null;
			}
			IDictionary<string, string> dictionary = ResultParser.ParseNameValuePairs(massagedText);
			string subject = null;
			string body = null;
			bool flag = false;
			if (dictionary != null && dictionary.Count != 0)
			{
				subject = dictionary["subject"];
				body = dictionary["body"];
				flag = true;
			}
			int num = massagedText.IndexOf('?', 4);
			string text = ((num >= 0 && flag) ? massagedText.Substring(4, num - 4) : massagedText.Substring(4));
			int num2 = -1;
			List<string> list = new List<string>(1);
			List<string> list2 = new List<string>(1);
			int num3;
			while ((num3 = text.IndexOf(',', num2 + 1)) > num2)
			{
				string numberPart = text.Substring(num2 + 1, num3 - (num2 + 1));
				AddNumberVia(list, list2, numberPart);
				num2 = num3;
			}
			AddNumberVia(list, list2, text.Substring(num2 + 1));
			return new SMSParsedResult(ResultParser.ToStringArray(list), ResultParser.ToStringArray(list2), subject, body);
		}

		private static void AddNumberVia(ICollection<string> numbers, ICollection<string> vias, string numberPart)
		{
			int num = numberPart.IndexOf(';');
			if (num < 0)
			{
				numbers.Add(numberPart);
				vias.Add(null);
				return;
			}
			numbers.Add(numberPart.Substring(0, num));
			string text = numberPart.Substring(num + 1);
			string item = ((!text.StartsWith("via=")) ? null : text.Substring(4));
			vias.Add(item);
		}
	}
	public sealed class SMSParsedResult : ParsedResult
	{
		private readonly string[] numbers;

		private readonly string[] vias;

		private readonly string subject;

		private readonly string body;

		public override string DisplayResult
		{
			get
			{
				StringBuilder stringBuilder = new StringBuilder(100);
				ParsedResult.MaybeAppend(numbers, stringBuilder);
				ParsedResult.MaybeAppend(subject, stringBuilder);
				ParsedResult.MaybeAppend(body, stringBuilder);
				return stringBuilder.ToString();
			}
		}

		public SMSParsedResult(string number, string via, string subject, string body)
			: base(ParsedResultType.Sms)
		{
			numbers = new string[1] { number };
			vias = new string[1] { via };
			this.subject = subject;
			this.body = body;
		}

		public SMSParsedResult(string[] numbers, string[] vias, string subject, string body)
			: base(ParsedResultType.Sms)
		{
			this.numbers = numbers;
			this.vias = vias;
			this.subject = subject;
			this.body = body;
		}

		public string GetSMSURI()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("sms:");
			bool flag = true;
			for (int i = 0; i < numbers.Length; i++)
			{
				if (flag)
				{
					flag = false;
				}
				else
				{
					stringBuilder.Append(',');
				}
				stringBuilder.Append(numbers[i]);
				if (vias != null && vias[i] != null)
				{
					stringBuilder.Append(";via=");
					stringBuilder.Append(vias[i]);
				}
			}
			bool flag2 = body != null;
			bool flag3 = subject != null;
			if (flag2 || flag3)
			{
				stringBuilder.Append('?');
				if (flag2)
				{
					stringBuilder.Append("body=");
					stringBuilder.Append(body);
				}
				if (flag3)
				{
					if (flag2)
					{
						stringBuilder.Append('&');
					}
					stringBuilder.Append("subject=");
					stringBuilder.Append(subject);
				}
			}
			return stringBuilder.ToString();
		}

		public string[] GetNumbers()
		{
			return numbers;
		}

		public string[] GetVias()
		{
			return vias;
		}

		public string GetSubject()
		{
			return subject;
		}

		public string GetBody()
		{
			return body;
		}
	}
	public sealed class SmsToMmsToResultParser : ResultParser
	{
		public override ParsedResult Parse(Result result)
		{
			string massagedText = ResultParser.GetMassagedText(result);
			if (!massagedText.StartsWith("smsto:") && !massagedText.StartsWith("SMSTO:") && !massagedText.StartsWith("mmsto:") && !massagedText.StartsWith("MMSTO:"))
			{
				return null;
			}
			string text = massagedText.Substring(6);
			string body = null;
			int num = text.IndexOf(':');
			if (num >= 0)
			{
				body = text.Substring(num + 1);
				text = text.Substring(0, num);
			}
			return new SMSParsedResult(text, null, null, body);
		}
	}
	public sealed class SMTPResultParser : ResultParser
	{
		public override ParsedResult Parse(Result result)
		{
			string massagedText = ResultParser.GetMassagedText(result);
			if (!massagedText.StartsWith("smtp:") && !massagedText.StartsWith("SMTP:"))
			{
				return null;
			}
			string text = massagedText.Substring(5);
			string text2 = null;
			string body_ = null;
			int num = text.IndexOf(':');
			if (num >= 0)
			{
				text2 = text.Substring(num + 1);
				text = text.Substring(0, num);
				num = text2.IndexOf(':');
				if (num >= 0)
				{
					body_ = text2.Substring(num + 1);
					text2 = text2.Substring(0, num);
				}
			}
			string mailtoURI_ = "mailto:" + text;
			return new EmailAddressParsedResult(text, text2, body_, mailtoURI_);
		}
	}
