namespace MessagingToolkit.Barcode.Aztec
{
	public sealed class AztecDetectorResult : DetectorResult
	{
		private readonly bool compact;

		private readonly int nbDatablocks;

		private readonly int nbLayers;

		public AztecDetectorResult(BitMatrix bits, ResultPoint[] points, bool compact, int nbDatablocks, int nbLayers)
			: base(bits, points)
		{
			this.compact = compact;
			this.nbDatablocks = nbDatablocks;
			this.nbLayers = nbLayers;
		}

		public int GetNbLayers()
		{
			return nbLayers;
		}

		public int GetNbDatablocks()
		{
			return nbDatablocks;
		}

		public bool IsCompact()
		{
			return compact;
		}
	}
	public sealed class AztecDecoder : IDecoder
	{
		public Result Decode(BinaryBitmap image)
		{
			return Decode(image, null);
		}

		public Result Decode(BinaryBitmap image, Dictionary<DecodeOptions, object> decodingOptions)
		{
			AztecDetectorResult aztecDetectorResult = new MessagingToolkit.Barcode.Aztec.Detector.Detector(image.BlackMatrix).Detect();
			ResultPoint[] points = aztecDetectorResult.Points;
			if (decodingOptions != null)
			{
				ResultPointCallback resultPointCallback = ((decodingOptions == null) ? null : ((ResultPointCallback)BarcodeHelper.GetDecodeOptionType(decodingOptions, DecodeOptions.NeedResultPointCallback)));
				if (resultPointCallback != null)
				{
					ResultPoint[] array = points;
					foreach (ResultPoint point in array)
					{
						resultPointCallback.FoundPossibleResultPoint(point);
					}
				}
			}
			DecoderResult decoderResult = new MessagingToolkit.Barcode.Aztec.Decoder.Decoder().Decode(aztecDetectorResult);
			Result result = new Result(decoderResult.Text, decoderResult.RawBytes, points, BarcodeFormat.Aztec);
			List<byte[]> byteSegments = decoderResult.ByteSegments;
			if (byteSegments != null)
			{
				result.PutMetadata(ResultMetadataType.ByteSegments, byteSegments);
			}
			string eCLevel = decoderResult.ECLevel;
			if (eCLevel != null)
			{
				result.PutMetadata(ResultMetadataType.ErrorCorrectionLevel, eCLevel);
			}
			return result;
		}

		public void Reset()
		{
		}
	}
	public sealed class AztecEncoder : IEncoder
	{
		private static readonly Encoding DEFAULT_CHARSET = Encoding.GetEncoding("ISO-8859-1");

		private const int QUIET_ZONE_SIZE = 0;

		public BitMatrix Encode(string contents, BarcodeFormat format, int width, int height)
		{
			return Encode(contents, format, width, height, null);
		}

		public BitMatrix Encode(string contents, BarcodeFormat format, int width, int height, Dictionary<EncodeOptions, object> encodingOptions)
		{
			if (string.IsNullOrEmpty(contents))
			{
				throw new ArgumentException("Found empty contents");
			}
			if (format != BarcodeFormat.Aztec)
			{
				throw new ArgumentException("Can only encode Aztec, but got " + format);
			}
			if (width < 0 || height < 0)
			{
				throw new ArgumentException("Requested dimensions are too small: " + width + "x" + height);
			}
			int quietZone = 0;
			Encoding encoding = DEFAULT_CHARSET;
			int minECCPercent = 33;
			if (encodingOptions != null)
			{
				object encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.Margin);
				if (encodeOptionType != null)
				{
					quietZone = Convert.ToInt32(encodeOptionType);
				}
				string text = ((encodingOptions == null) ? null : ((string)BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.CharacterSet)));
				if (!string.IsNullOrEmpty(text))
				{
					encoding = Encoding.GetEncoding(text);
				}
				encodeOptionType = BarcodeHelper.GetEncodeOptionType(encodingOptions, EncodeOptions.ErrorCorrection);
				if (encodeOptionType != null)
				{
					minECCPercent = Convert.ToInt32(encodeOptionType);
				}
			}
			return RenderResult(MessagingToolkit.Barcode.Aztec.Encoder.Encoder.Encode(encoding.GetBytes(contents), minECCPercent).Matrix, width, height, quietZone);
		}

		private static BitMatrix RenderResult(BitMatrix input, int width, int height, int quietZone)
		{
			if (input == null)
			{
				throw new InvalidOperationException();
			}
			int width2 = input.Width;
			int height2 = input.Height;
			int num = width2 + (quietZone << 1);
			int num2 = height2 + (quietZone << 1);
			int num3 = Math.Max(width, num);
			int num4 = Math.Max(height, num2);
			int num5 = Math.Min(num3 / num, num4 / num2);
			int num6 = (num3 - width2 * num5) / 2;
			int num7 = (num4 - height2 * num5) / 2;
			BitMatrix bitMatrix = new BitMatrix(num3, num4);
			bitMatrix.LeftPadding = num6;
			bitMatrix.TopPadding = num7;
			bitMatrix.ActualHeight = num5 * height2;
			bitMatrix.ActualWidth = num5 * width2;
			int num8 = 0;
			int num9 = num7;
			while (num8 < height2)
			{
				int num10 = 0;
				int num11 = num6;
				while (num10 < width2)
				{
					if (input.Get(num10, num8))
					{
						bitMatrix.SetRegion(num11, num9, num5, num5);
					}
					num10++;
					num11 += num5;
				}
				num8++;
				num9 += num5;
			}
			return bitMatrix;
		}
	}
