	internal sealed class BinaryShiftToken : Token
	{
		private readonly short binaryShiftStart;

		private readonly short binaryShiftByteCount;

		internal BinaryShiftToken(Token previous, int totalBitCount, int binaryShiftStart, int binaryShiftByteCount)
			: base(previous, totalBitCount)
		{
			this.binaryShiftStart = (short)binaryShiftStart;
			this.binaryShiftByteCount = (short)binaryShiftByteCount;
		}

		public override void AppendTo(MessagingToolkit.Barcode.Common.BitArray bitArray, byte[] text)
		{
			for (int i = 0; i < binaryShiftByteCount; i++)
			{
				if (i == 0 || (i == 31 && binaryShiftByteCount <= 62))
				{
					bitArray.AppendBits(31, 5);
					if (binaryShiftByteCount > 62)
					{
						bitArray.AppendBits(binaryShiftByteCount - 31, 16);
					}
					else if (i == 0)
					{
						short val = 31;
						bitArray.AppendBits(Math.Min(binaryShiftByteCount, val), 5);
					}
					else
					{
						bitArray.AppendBits(binaryShiftByteCount - 31, 5);
					}
				}
				bitArray.AppendBits(text[binaryShiftStart + i], 8);
			}
		}

		public override string ToString()
		{
			return "<" + binaryShiftStart + "::" + (binaryShiftStart + binaryShiftByteCount - 1) + ">";
		}
	}
	public static class Encoder
	{
		public const int DEFAULT_EC_PERCENT = 33;

		private static readonly int[] NB_BITS;

		private static readonly int[] NB_BITS_COMPACT;

		private static readonly int[] WORD_SIZE;

		static Encoder()
		{
			WORD_SIZE = new int[33]
			{
				4, 6, 6, 8, 8, 8, 8, 8, 8, 10,
				10, 10, 10, 10, 10, 10, 10, 10, 10, 10,
				10, 10, 10, 12, 12, 12, 12, 12, 12, 12,
				12, 12, 12
			};
			NB_BITS_COMPACT = new int[5];
			for (int i = 1; i < NB_BITS_COMPACT.Length; i++)
			{
				NB_BITS_COMPACT[i] = (88 + 16 * i) * i;
			}
			NB_BITS = new int[33];
			for (int j = 1; j < NB_BITS.Length; j++)
			{
				NB_BITS[j] = (112 + 16 * j) * j;
			}
		}

		public static AztecCode Encode(byte[] data)
		{
			return Encode(data, 33);
		}

		public static AztecCode Encode(byte[] data, int minECCPercent)
		{
			MessagingToolkit.Barcode.Common.BitArray bitArray = new HighLevelEncoder(data).Encode();
			int num = bitArray.Size * minECCPercent / 100 + 11;
			int num2 = bitArray.Size + num;
			int num3 = 0;
			int num4 = 0;
			MessagingToolkit.Barcode.Common.BitArray bitArray2 = null;
			int i;
			for (i = 1; i < NB_BITS_COMPACT.Length; i++)
			{
				if (NB_BITS_COMPACT[i] >= num2)
				{
					if (num3 != WORD_SIZE[i])
					{
						num3 = WORD_SIZE[i];
						bitArray2 = StuffBits(bitArray, num3);
					}
					num4 = NB_BITS_COMPACT[i];
					if (bitArray2.Size + num <= NB_BITS_COMPACT[i])
					{
						break;
					}
				}
			}
			bool flag = true;
			if (i == NB_BITS_COMPACT.Length)
			{
				flag = false;
				for (i = 1; i < NB_BITS.Length; i++)
				{
					if (NB_BITS[i] >= num2)
					{
						if (num3 != WORD_SIZE[i])
						{
							num3 = WORD_SIZE[i];
							bitArray2 = StuffBits(bitArray, num3);
						}
						num4 = NB_BITS[i];
						if (bitArray2.Size + num <= NB_BITS[i])
						{
							break;
						}
					}
				}
			}
			if (i == NB_BITS.Length)
			{
				throw new ArgumentException("Data too large for an Aztec code");
			}
			int num5 = (bitArray2.Size + num3 - 1) / num3;
			for (int num6 = num5 * num3 - bitArray2.Size; num6 > 0; num6--)
			{
				bitArray2.AppendBit(bit: true);
			}
			ReedSolomonEncoder reedSolomonEncoder = new ReedSolomonEncoder(GetGF(num3));
			int num7 = num4 / num3;
			int[] array = BitsToWords(bitArray2, num3, num7);
			reedSolomonEncoder.Encode(array, num7 - num5);
			int numBits = num4 % num3;
			MessagingToolkit.Barcode.Common.BitArray bitArray3 = new MessagingToolkit.Barcode.Common.BitArray();
			bitArray3.AppendBits(0, numBits);
			int[] array2 = array;
			foreach (int val in array2)
			{
				bitArray3.AppendBits(val, num3);
			}
			MessagingToolkit.Barcode.Common.BitArray modeMessage = GenerateModeMessage(flag, i, num5);
			int num8 = (flag ? (11 + i * 4) : (14 + i * 4));
			int[] array3 = new int[num8];
			int num9;
			if (flag)
			{
				num9 = num8;
				for (int k = 0; k < array3.Length; k++)
				{
					array3[k] = k;
				}
			}
			else
			{
				num9 = num8 + 1 + 2 * ((num8 / 2 - 1) / 15);
				int num10 = num8 / 2;
				int num11 = num9 / 2;
				for (int l = 0; l < num10; l++)
				{
					int num12 = l + l / 15;
					array3[num10 - l - 1] = num11 - num12 - 1;
					array3[num10 + l] = num11 + num12 + 1;
				}
			}
			BitMatrix bitMatrix = new BitMatrix(num9);
			int m = 0;
			int num13 = 0;
			for (; m < i; m++)
			{
				int num14 = (flag ? ((i - m) * 4 + 9) : ((i - m) * 4 + 12));
				for (int n = 0; n < num14; n++)
				{
					int num15 = n * 2;
					for (int num16 = 0; num16 < 2; num16++)
					{
						if (bitArray3.Get(num13 + num15 + num16))
						{
							bitMatrix.Set(array3[m * 2 + num16], array3[m * 2 + n]);
						}
						if (bitArray3.Get(num13 + num14 * 2 + num15 + num16))
						{
							bitMatrix.Set(array3[m * 2 + n], array3[num8 - 1 - m * 2 - num16]);
						}
						if (bitArray3.Get(num13 + num14 * 4 + num15 + num16))
						{
							bitMatrix.Set(array3[num8 - 1 - m * 2 - num16], array3[num8 - 1 - m * 2 - n]);
						}
						if (bitArray3.Get(num13 + num14 * 6 + num15 + num16))
						{
							bitMatrix.Set(array3[num8 - 1 - m * 2 - n], array3[m * 2 + num16]);
						}
					}
				}
				num13 += num14 * 8;
			}
			DrawModeMessage(bitMatrix, flag, num9, modeMessage);
			if (flag)
			{
				DrawBullsEye(bitMatrix, num9 / 2, 5);
			}
			else
			{
				DrawBullsEye(bitMatrix, num9 / 2, 7);
				int num17 = 0;
				int num18 = 0;
				while (num17 < num8 / 2 - 1)
				{
					for (int num19 = (num9 / 2) & 1; num19 < num9; num19 += 2)
					{
						bitMatrix.Set(num9 / 2 - num18, num19);
						bitMatrix.Set(num9 / 2 + num18, num19);
						bitMatrix.Set(num19, num9 / 2 - num18);
						bitMatrix.Set(num19, num9 / 2 + num18);
					}
					num17 += 15;
					num18 += 16;
				}
			}
			return new AztecCode
			{
				Compact = flag,
				Size = num9,
				Layers = i,
				CodeWords = num5,
				Matrix = bitMatrix
			};
		}

		private static void DrawBullsEye(BitMatrix matrix, int center, int size)
		{
			for (int i = 0; i < size; i += 2)
			{
				for (int j = center - i; j <= center + i; j++)
				{
					matrix.Set(j, center - i);
					matrix.Set(j, center + i);
					matrix.Set(center - i, j);
					matrix.Set(center + i, j);
				}
			}
			matrix.Set(center - size, center - size);
			matrix.Set(center - size + 1, center - size);
			matrix.Set(center - size, center - size + 1);
			matrix.Set(center + size, center - size);
			matrix.Set(center + size, center - size + 1);
			matrix.Set(center + size, center + size - 1);
		}

		internal static MessagingToolkit.Barcode.Common.BitArray GenerateModeMessage(bool compact, int layers, int messageSizeInWords)
		{
			MessagingToolkit.Barcode.Common.BitArray bitArray = new MessagingToolkit.Barcode.Common.BitArray();
			if (compact)
			{
				bitArray.AppendBits(layers - 1, 2);
				bitArray.AppendBits(messageSizeInWords - 1, 6);
				return GenerateCheckWords(bitArray, 28, 4);
			}
			bitArray.AppendBits(layers - 1, 5);
			bitArray.AppendBits(messageSizeInWords - 1, 11);
			return GenerateCheckWords(bitArray, 40, 4);
		}

		private static void DrawModeMessage(BitMatrix matrix, bool compact, int matrixSize, MessagingToolkit.Barcode.Common.BitArray modeMessage)
		{
			if (compact)
			{
				for (int i = 0; i < 7; i++)
				{
					if (modeMessage.Get(i))
					{
						matrix.Set(matrixSize / 2 - 3 + i, matrixSize / 2 - 5);
					}
					if (modeMessage.Get(i + 7))
					{
						matrix.Set(matrixSize / 2 + 5, matrixSize / 2 - 3 + i);
					}
					if (modeMessage.Get(20 - i))
					{
						matrix.Set(matrixSize / 2 - 3 + i, matrixSize / 2 + 5);
					}
					if (modeMessage.Get(27 - i))
					{
						matrix.Set(matrixSize / 2 - 5, matrixSize / 2 - 3 + i);
					}
				}
				return;
			}
			for (int j = 0; j < 10; j++)
			{
				if (modeMessage.Get(j))
				{
					matrix.Set(matrixSize / 2 - 5 + j + j / 5, matrixSize / 2 - 7);
				}
				if (modeMessage.Get(j + 10))
				{
					matrix.Set(matrixSize / 2 + 7, matrixSize / 2 - 5 + j + j / 5);
				}
				if (modeMessage.Get(29 - j))
				{
					matrix.Set(matrixSize / 2 - 5 + j + j / 5, matrixSize / 2 + 7);
				}
				if (modeMessage.Get(39 - j))
				{
					matrix.Set(matrixSize / 2 - 7, matrixSize / 2 - 5 + j + j / 5);
				}
			}
		}

		private static MessagingToolkit.Barcode.Common.BitArray GenerateCheckWords(MessagingToolkit.Barcode.Common.BitArray stuffedBits, int totalSymbolBits, int wordSize)
		{
			int num = (stuffedBits.Size + wordSize - 1) / wordSize;
			for (int num2 = num * wordSize - stuffedBits.Size; num2 > 0; num2--)
			{
				stuffedBits.AppendBit(bit: true);
			}
			ReedSolomonEncoder reedSolomonEncoder = new ReedSolomonEncoder(GetGF(wordSize));
			int num3 = totalSymbolBits / wordSize;
			int[] array = BitsToWords(stuffedBits, wordSize, num3);
			reedSolomonEncoder.Encode(array, num3 - num);
			int numBits = totalSymbolBits % wordSize;
			MessagingToolkit.Barcode.Common.BitArray bitArray = new MessagingToolkit.Barcode.Common.BitArray();
			bitArray.AppendBits(0, numBits);
			int[] array2 = array;
			foreach (int val in array2)
			{
				bitArray.AppendBits(val, wordSize);
			}
			return bitArray;
		}

		private static int[] BitsToWords(MessagingToolkit.Barcode.Common.BitArray stuffedBits, int wordSize, int totalWords)
		{
			int[] array = new int[totalWords];
			int i = 0;
			for (int num = stuffedBits.Size / wordSize; i < num; i++)
			{
				int num2 = 0;
				for (int j = 0; j < wordSize; j++)
				{
					num2 |= (stuffedBits.Get(i * wordSize + j) ? (1 << wordSize - j - 1) : 0);
				}
				array[i] = num2;
			}
			return array;
		}

		private static GenericGF GetGF(int wordSize)
		{
			return wordSize switch
			{
				4 => GenericGF.AztecParam, 
				6 => GenericGF.AztecData6, 
				8 => GenericGF.AztecData8, 
				10 => GenericGF.AztecData10, 
				12 => GenericGF.AztecData12, 
				_ => null, 
			};
		}

		internal static MessagingToolkit.Barcode.Common.BitArray StuffBits(MessagingToolkit.Barcode.Common.BitArray bits, int wordSize)
		{
			MessagingToolkit.Barcode.Common.BitArray bitArray = new MessagingToolkit.Barcode.Common.BitArray();
			int size = bits.Size;
			int num = (1 << wordSize) - 2;
			for (int i = 0; i < size; i += wordSize)
			{
				int num2 = 0;
				for (int j = 0; j < wordSize; j++)
				{
					if (i + j >= size || bits.Get(i + j))
					{
						num2 |= 1 << wordSize - 1 - j;
					}
				}
				if ((num2 & num) == num)
				{
					bitArray.AppendBits(num2 & num, wordSize);
					i--;
				}
				else if ((num2 & num) == 0)
				{
					bitArray.AppendBits(num2 | 1, wordSize);
					i--;
				}
				else
				{
					bitArray.AppendBits(num2, wordSize);
				}
			}
			size = bitArray.Size;
			int num3 = size % wordSize;
			if (num3 != 0)
			{
				int num4 = 1;
				for (int k = 0; k < num3; k++)
				{
					if (!bitArray.Get(size - 1 - k))
					{
						num4 = 0;
					}
				}
				for (int l = num3; l < wordSize - 1; l++)
				{
					bitArray.AppendBit(bit: true);
				}
				bitArray.AppendBit(num4 == 0);
			}
			return bitArray;
		}
	}
	public sealed class HighLevelEncoder
	{
		internal static string[] MODE_NAMES;

		internal const int MODE_UPPER = 0;

		internal const int MODE_LOWER = 1;

		internal const int MODE_DIGIT = 2;

		internal const int MODE_MIXED = 3;

		internal const int MODE_PUNCT = 4;

		internal static readonly int[][] LATCH_TABLE;

		internal static readonly int[][] CHAR_MAP;

		internal static readonly int[][] SHIFT_TABLE;

		private readonly byte[] text;

		static HighLevelEncoder()
		{
