				new int[5] { 590318, 0, 327710, 327709, 656318 },
				new int[5] { 262158, 590300, 0, 590301, 932798 },
				new int[5] { 327709, 327708, 656318, 0, 327710 },
				new int[5] { 327711, 656380, 656382, 656381, 0 }
