					array3[num] = -1;
				}
			}
			SHIFT_TABLE[0][4] = 0;
			SHIFT_TABLE[1][4] = 0;
			SHIFT_TABLE[1][0] = 28;
			SHIFT_TABLE[3][4] = 0;
			SHIFT_TABLE[2][4] = 0;
